static volatile sig_atomic_t guest_signal_seen = 0;
static volatile sig_atomic_t guest_nested_signal_sequence = 0;
static volatile sig_atomic_t guest_timer_signal_seen = 0;
static volatile sig_atomic_t guest_timer_signal_code = 0;
static volatile sig_atomic_t guest_timer_signal_error = 0;
static volatile sig_atomic_t guest_timer_signal_id = -1;
static volatile sig_atomic_t guest_timer_signal_overrun = -1;
static volatile sig_atomic_t guest_timer_signal_value = 0;
static pid_t guest_signal_pid = 0;
static uid_t guest_signal_uid = 0;

static void guest_signal_handler(int signo, siginfo_t *info, void *context) {
        sigset_t mask;

        if (signo == SIGUSR1 &&
                        info &&
                        info->si_signo == SIGUSR1 &&
                        info->si_code == SI_TKILL &&
                        info->si_pid == guest_signal_pid &&
                        info->si_uid == guest_signal_uid &&
            context &&
            sigprocmask(SIG_SETMASK, NULL, &mask) >= 0 &&
            sigismember(&mask, SIGUSR1) > 0 &&
            sigismember(&mask, SIGUSR2) > 0)
                guest_signal_seen = 1;
}

static void guest_nested_signal_handler(int signo, siginfo_t *info, void *context) {
        if (signo == SIGUSR2 &&
            info && info->si_code == SI_TKILL &&
            context &&
            guest_nested_signal_sequence == 1)
                guest_nested_signal_sequence = 2;
}

static void guest_outer_signal_handler(int signo, siginfo_t *info, void *context) {
        if (signo != SIGUSR1 || !info || info->si_code != SI_TKILL || !context)
                return;

        guest_nested_signal_sequence = 1;
        if (raise(SIGUSR2) >= 0 && guest_nested_signal_sequence == 2)
                guest_nested_signal_sequence = 3;
}

static void guest_timer_signal_handler(int signo, siginfo_t *info, void *context) {
        if (signo != SIGRTMIN || !info || !context)
                return;

        guest_timer_signal_code = info->si_code;
        guest_timer_signal_error = info->si_errno;
        guest_timer_signal_id = info->si_timerid;
        guest_timer_signal_overrun = info->si_overrun;
        guest_timer_signal_value = info->si_value.sival_int;
        guest_timer_signal_seen = 1;
}

static int test_guest_timer_signal(void) {
        static const int expected_value = 0x51a7;
        struct sigaction action = {
                .sa_sigaction = guest_timer_signal_handler,
                .sa_flags = SA_SIGINFO,
        };
        struct sigevent event = {
                .sigev_notify = SIGEV_SIGNAL,
                .sigev_signo = SIGRTMIN,
                .sigev_value.sival_int = expected_value,
        };
        struct itimerspec timer_value = {
                .it_value.tv_nsec = 1,
        };
        struct timespec deadline;
        timer_t timer;

        if (sigemptyset(&action.sa_mask) < 0 ||
            sigaction(SIGRTMIN, &action, NULL) < 0 ||
            timer_create(CLOCK_MONOTONIC, &event, &timer) < 0 ||
            timer_settime(timer, 0, &timer_value, NULL) < 0 ||
            clock_gettime(CLOCK_MONOTONIC, &deadline) < 0)
                return -errno;

        deadline.tv_sec += 2;
        while (!guest_timer_signal_seen) {
                struct timespec now;

                if (clock_gettime(CLOCK_MONOTONIC, &now) < 0)
                        return -errno;
                if (now.tv_sec > deadline.tv_sec ||
                    (now.tv_sec == deadline.tv_sec && now.tv_nsec >= deadline.tv_nsec))
                        return -ETIMEDOUT;
                (void) syscall(SYS_sched_yield);
        }

        if (timer_delete(timer) < 0)
                return -errno;
        if (guest_timer_signal_code != SI_TIMER ||
            guest_timer_signal_error != 0 ||
            guest_timer_signal_id < 0 ||
            guest_timer_signal_overrun < 0 ||
            guest_timer_signal_value != expected_value)
                return -EPROTO;

        return 0;
}

