static struct rseq *guest_rseq_area(void) {
        return (struct rseq *) ((uint8_t *) __builtin_thread_pointer() + __rseq_offset);
}

static int validate_guest_rseq_registration(void) {
        struct rseq *rseq = guest_rseq_area();
        unsigned int registration_size;
        bool getcpu_consistent = false;
        long result;

        if (__rseq_size != 28 || __rseq_flags != 0 || (uintptr_t) rseq % 32 != 0 ||
            (int32_t) rseq->cpu_id_start < 0 || rseq->cpu_id != rseq->cpu_id_start || rseq->node_id != 0 ||
            (int32_t) rseq->mm_cid < 0)
                return -EPROTO;

        registration_size = __rseq_size < 32 ? 32 : __rseq_size;
        errno = 0;
        if (syscall(SYS_rseq, rseq, registration_size, 0, RSEQ_SIG) >= 0 || errno != EBUSY)
                return -EPROTO;

        for (unsigned attempt = 0; attempt < 128; attempt++) {
                unsigned int cpu, cpu_before, node, node_before;

                cpu_before = rseq->cpu_id;
                node_before = rseq->node_id;
                if (syscall(SYS_getcpu, &cpu, &node, NULL) < 0)
                        return -errno;
                if (cpu_before != rseq->cpu_id || node_before != rseq->node_id)
                        continue;
                if (cpu != cpu_before || node != node_before)
                        return -EPROTO;

                getcpu_consistent = true;
                break;
        }
        if (!getcpu_consistent)
                return -EAGAIN;
        unsigned int copied_node = UINT_MAX;
        errno = 0;
        if (syscall(SYS_getcpu, (void*) 1, &copied_node, (void*) 1) >= 0 || errno != EFAULT ||
            copied_node != rseq->node_id)
                return -EPROTO;
        errno = 0;
        result = syscall(SYS_rseq_slice_yield);
        if (result < 0 && errno != ENOSYS)
                return -errno;
        if (result > 0)
                return -EPROTO;

        errno = 0;
        result = prctl(PR_RSEQ_SLICE_EXTENSION, PR_RSEQ_SLICE_EXTENSION_GET, 0, 0, 0);
        if (result < 0) {
                if (errno != EINVAL)
                        return -errno;
        } else {
                if (result != 0)
                        return -EPROTO;
                errno = 0;
                result = prctl(
                                PR_RSEQ_SLICE_EXTENSION,
                                PR_RSEQ_SLICE_EXTENSION_SET,
                                PR_RSEQ_SLICE_EXT_ENABLE,
                                0,
                                0);
                if (getauxval(AT_RSEQ_FEATURE_SIZE) < 33 && (result >= 0 || errno != EOPNOTSUPP))
                        return -EPROTO;
        }

        return 0;
}

static int test_guest_rseq_unregister(void) {
        struct rseq *rseq = guest_rseq_area();
        unsigned int registration_size = __rseq_size < 32 ? 32 : __rseq_size;

        if (syscall(SYS_rseq, rseq, registration_size, RSEQ_FLAG_UNREGISTER, RSEQ_SIG) < 0)
                return -errno;
        if (rseq->cpu_id_start != 0 || rseq->cpu_id != UINT32_MAX || rseq->node_id != 0 || rseq->mm_cid != 0)
                return -EPROTO;
        if (syscall(SYS_rseq, rseq, registration_size, 0, RSEQ_SIG) < 0)
                return -errno;

        return validate_guest_rseq_registration();
}

