static int test_guest_rseq_malformed_signal(void) {
        int status;
        pid_t child;

        child = fork();
        if (child < 0)
                return -errno;
        if (child == 0) {
                struct sigaction action = {
                        .sa_handler = guest_rseq_malformed_signal_handler,
                };
                struct rseq *rseq = guest_rseq_area();

                if (sigemptyset(&action.sa_mask) < 0 || sigaction(SIGUSR1, &action, NULL) < 0)
                        _exit(109);
                __atomic_store_n(&rseq->rseq_cs, UINTPTR_MAX, __ATOMIC_RELEASE);
                if (raise(SIGUSR1) < 0)
                        _exit(110);
                _exit(111);
        }

        if (waitpid(child, &status, 0) != child || !WIFSIGNALED(status) || WTERMSIG(status) != SIGSEGV)
                return -EPROTO;
        return 0;
}

