static bool guest_has_avx512(void) {
        unsigned eax, ebx, ecx, edx;

        __cpuid_count(7, 0, eax, ebx, ecx, edx);
        return (ebx & bit_AVX512F) != 0;
}

static uint32_t guest_signal_xsave_size(uint64_t xfeatures) {
        uint32_t size = (xfeatures & UINT64_C(0xe0)) != 0 ? 2432U : 832U;
        unsigned eax, ebx, ecx, edx;

        for (unsigned component = 17; component <= 18; component++) {
                uint32_t end;

                if (!(xfeatures & (UINT64_C(1) << component)))
                        continue;
                __cpuid_count(0x0d, component, eax, ebx, ecx, edx);
                end = ebx + eax;
                if (eax == 0 || end < ebx)
                        return 0;
                size = end > size ? end : size;
        }
        return size;
}

static void guest_fpu_signal_handler(int signo, siginfo_t *info, void *context) {
        ucontext_t *ucontext = context;
        struct _libc_fpstate *fpstate;
        uint8_t *xstate;
        uint64_t xfeatures, supported_xfeatures;
        uint32_t extended_size, magic1, magic2, xstate_size;

        if (signo != SIGUSR1 || !info || !ucontext)
                return;

        fpstate = ucontext->uc_mcontext.fpregs;
        if (!fpstate)
                return;

        xstate = (uint8_t*) fpstate;
        memcpy(&magic1, xstate + 464, sizeof(magic1));
        memcpy(&extended_size, xstate + 468, sizeof(extended_size));
        memcpy(&supported_xfeatures, xstate + 472, sizeof(supported_xfeatures));
        memcpy(&xstate_size, xstate + 480, sizeof(xstate_size));
        memcpy(&xfeatures, xstate + 512, sizeof(xfeatures));
        if (xstate_size > 16U * 1024U)
                return;
        memcpy(&magic2, xstate + xstate_size, sizeof(magic2));
        memcpy(guest_fpu_handler_ymm, fpstate->_xmm[15].element, 16);
        memcpy(guest_fpu_handler_ymm + 4, xstate + 576 + 15 * 16, 16);
        guest_fpu_handler_mxcsr = fpstate->mxcsr;
        guest_fpu_handler_fcw = fpstate->cwd;
                if (magic1 != UINT32_C(0x46505853) ||
                        ((supported_xfeatures & ~((UINT64_C(1) << 17)|(UINT64_C(1) << 18))) != UINT64_C(7) &&
                         (supported_xfeatures & ~((UINT64_C(1) << 17)|(UINT64_C(1) << 18))) != UINT64_C(0xe7)) ||
                        xstate_size != guest_signal_xsave_size(supported_xfeatures) ||
                        extended_size != xstate_size + sizeof(uint32_t) ||
                            (xfeatures & ~supported_xfeatures) != 0 ||
                            (xfeatures & UINT64_C(7)) != UINT64_C(7) ||
            magic2 != UINT32_C(0x46505845) ||
            memcmp(guest_fpu_handler_ymm, guest_fpu_initial_ymm, sizeof(guest_fpu_initial_ymm)) != 0 ||
            fpstate->mxcsr != guest_fpu_initial_mxcsr ||
            fpstate->cwd != guest_fpu_initial_fcw)
                return;

        memcpy(fpstate->_xmm[15].element, guest_fpu_replacement_ymm, 16);
        memcpy(xstate + 576 + 15 * 16, guest_fpu_replacement_ymm + 4, 16);
        xfeatures |= UINT64_C(1) << 2;
        memcpy(xstate + 512, &xfeatures, sizeof(xfeatures));
        fpstate->mxcsr = UINT32_C(0x5f80);
        fpstate->cwd = guest_fpu_replacement_fcw;
        guest_fpu_signal_seen = 1;
}

static void guest_fpu_avx512_signal_handler(int signo, siginfo_t *info, void *context) {
        ucontext_t *ucontext = context;
        struct _libc_fpstate *fpstate;
        uint8_t *xstate;
        uint64_t k7, supported_xfeatures, xfeatures;
        uint32_t extended_size, magic1, magic2, xstate_size;

        if (signo != SIGUSR2 || !info || !ucontext)
                return;

        fpstate = ucontext->uc_mcontext.fpregs;
        if (!fpstate)
                return;

        xstate = (uint8_t*) fpstate;
        memcpy(&magic1, xstate + 464, sizeof(magic1));
        memcpy(&extended_size, xstate + 468, sizeof(extended_size));
        memcpy(&supported_xfeatures, xstate + 472, sizeof(supported_xfeatures));
        memcpy(&xstate_size, xstate + 480, sizeof(xstate_size));
        memcpy(&xfeatures, xstate + 512, sizeof(xfeatures));
        if (xstate_size > 16U * 1024U)
                return;
        memcpy(&magic2, xstate + xstate_size, sizeof(magic2));
        memcpy(&k7, xstate + 832 + 7 * sizeof(uint64_t), sizeof(k7));
        memcpy(guest_fpu_handler_zmm, xstate + 1408 + 15 * 64, sizeof(guest_fpu_handler_zmm));
        guest_fpu_handler_k7 = k7;

        if (magic1 != UINT32_C(0x46505853) ||
                        extended_size != xstate_size + sizeof(uint32_t) ||
                        (supported_xfeatures & ~((UINT64_C(1) << 17)|(UINT64_C(1) << 18))) != UINT64_C(0xe7) ||
                        xstate_size != guest_signal_xsave_size(supported_xfeatures) ||
            (xfeatures & ~supported_xfeatures) != 0 ||
            magic2 != UINT32_C(0x46505845) ||
            k7 != guest_fpu_initial_k7 ||
            memcmp(guest_fpu_handler_zmm, guest_fpu_initial_zmm, sizeof(guest_fpu_initial_zmm)) != 0)
                return;

        memcpy(xstate + 832 + 7 * sizeof(uint64_t), &guest_fpu_replacement_k7, sizeof(guest_fpu_replacement_k7));
        memcpy(xstate + 1408 + 15 * 64, guest_fpu_replacement_zmm, sizeof(guest_fpu_replacement_zmm));
        xfeatures |= UINT64_C(0xe0);
        memcpy(xstate + 512, &xfeatures, sizeof(xfeatures));
        guest_fpu_avx512_seen = 1;
}

static void guest_fpu_amx_signal_handler(int signo, siginfo_t *info, void *context) {
        ucontext_t *ucontext = context;
        struct _libc_fpstate *fpstate;
        unsigned eax, ebx, ecx, edx;
        uint8_t *xstate;
        uint64_t supported_xfeatures, xfeatures;
        uint32_t extended_size, magic1, magic2, xstate_size;

        if (signo != SIGUSR2 || !info || !ucontext)
                return;
        fpstate = ucontext->uc_mcontext.fpregs;
        if (!fpstate)
                return;

        xstate = (uint8_t*) fpstate;
        memcpy(&magic1, xstate + 464, sizeof(magic1));
        memcpy(&extended_size, xstate + 468, sizeof(extended_size));
        memcpy(&supported_xfeatures, xstate + 472, sizeof(supported_xfeatures));
        memcpy(&xstate_size, xstate + 480, sizeof(xstate_size));
        memcpy(&xfeatures, xstate + 512, sizeof(xfeatures));
        if (xstate_size > 16U * 1024U)
                return;
        memcpy(&magic2, xstate + xstate_size, sizeof(magic2));
        __cpuid_count(0x0d, 18, eax, ebx, ecx, edx);
        if (eax < sizeof(guest_fpu_handler_tile) || ebx > xstate_size ||
            sizeof(guest_fpu_handler_tile) > xstate_size - ebx)
                return;
        memcpy(guest_fpu_handler_tile, xstate + ebx, sizeof(guest_fpu_handler_tile));

        if (magic1 != UINT32_C(0x46505853) ||
            extended_size != xstate_size + sizeof(uint32_t) ||
            xstate_size != guest_signal_xsave_size(supported_xfeatures) ||
            (supported_xfeatures & ((UINT64_C(1) << 17)|(UINT64_C(1) << 18))) !=
                    ((UINT64_C(1) << 17)|(UINT64_C(1) << 18)) ||
            (xfeatures & (UINT64_C(1) << 18)) == 0 ||
            (xfeatures & ~supported_xfeatures) != 0 ||
            magic2 != UINT32_C(0x46505845) ||
            memcmp(guest_fpu_handler_tile, guest_fpu_initial_tile, sizeof(guest_fpu_handler_tile)) != 0)
                return;

        memcpy(xstate + ebx, guest_fpu_replacement_tile, sizeof(guest_fpu_replacement_tile));
        xfeatures |= UINT64_C(1) << 18;
        memcpy(xstate + 512, &xfeatures, sizeof(xfeatures));
        guest_fpu_amx_seen = 1;
}

__attribute__((target("avx512f"), noinline))
static int test_guest_signal_avx512(void) {
        struct sigaction action = {
                .sa_sigaction = guest_fpu_avx512_signal_handler,
                .sa_flags = SA_SIGINFO,
        };
        _Alignas(64) uint32_t observed_zmm[16], original_zmm[16];
        uint64_t observed_k7, original_k7;
        unsigned eax, ebx, ecx, edx;
        long result;
        pid_t pid = getpid(), tid = gettid();

        __cpuid_count(7, 0, eax, ebx, ecx, edx);
        if (!(ebx & bit_AVX512F))
                return 0;
        if (sigemptyset(&action.sa_mask) < 0 || sigaction(SIGUSR2, &action, NULL) < 0)
                return -errno;

        asm volatile (
                "vmovdqu64 %%zmm31, %0\n\t"
                "kmovq %%k7, %1"
                : "=m" (original_zmm), "=m" (original_k7));

        guest_fpu_avx512_seen = 0;
        memset(guest_fpu_handler_zmm, 0, sizeof(guest_fpu_handler_zmm));
        guest_fpu_handler_k7 = 0;
        asm volatile (
                "vmovdqu64 %[initial_zmm], %%zmm31\n\t"
                "kmovq %[initial_k7], %%k7\n\t"
                "mov %[syscall_number], %%eax\n\t"
                "syscall\n\t"
                "vmovdqu64 %%zmm31, %[observed_zmm]\n\t"
                "kmovq %%k7, %[observed_k7]"
                : "=a" (result),
                  [observed_zmm] "=m" (observed_zmm),
                  [observed_k7] "=m" (observed_k7)
                : "D" ((long) pid),
                  "S" ((long) tid),
                  "d" ((long) SIGUSR2),
                  [syscall_number] "i" (SYS_tgkill),
                  [initial_zmm] "m" (guest_fpu_initial_zmm),
                  [initial_k7] "m" (guest_fpu_initial_k7)
                : "rcx", "r11", "zmm31", "k7", "memory");

        asm volatile (
                "vmovdqu64 %0, %%zmm31\n\t"
                "kmovq %1, %%k7"
                :
                : "m" (original_zmm), "m" (original_k7)
                : "zmm31", "k7", "memory");

        if (result < 0)
                return (int) result;
        if (!guest_fpu_avx512_seen ||
            observed_k7 != guest_fpu_replacement_k7 ||
            memcmp(observed_zmm, guest_fpu_replacement_zmm, sizeof(observed_zmm)) != 0) {
                fprintf(stderr,
                        "AVX-512 FPU mismatch: seen=%d frame-k7=%016" PRIx64 " returned-k7=%016" PRIx64 "\n",
                        guest_fpu_avx512_seen,
                        guest_fpu_handler_k7,
                        observed_k7);
                return -EPROTO;
        }

        return 0;
}

__attribute__((target("amx-tile"), noinline))
static int test_guest_signal_amx(void) {
        struct sigaction action = {
                .sa_sigaction = guest_fpu_amx_signal_handler,
                .sa_flags = SA_SIGINFO,
        }, old_action;
        _Alignas(64) GuestAmxTileConfig configuration = {
                .palette_id = 1,
                .columns[0] = 64,
                .rows[0] = 16,
        };
        _Alignas(64) uint8_t output[1024] = {};
        unsigned eax, ebx, ecx, edx;
        long result;

        __cpuid_count(7, 0, eax, ebx, ecx, edx);
        if (!(edx & bit_AMX_TILE))
                return 0;
        if (syscall(SYS_arch_prctl, ARCH_REQ_XCOMP_PERM, ARCH_XCOMP_TILEDATA) < 0)
                return -errno;
        if (sigemptyset(&action.sa_mask) < 0 || sigaction(SIGUSR2, &action, &old_action) < 0)
                return -errno;

        for (size_t i = 0; i < sizeof(guest_fpu_initial_tile); i++) {
                guest_fpu_initial_tile[i] = (uint8_t) (i * 29U + 7U);
                guest_fpu_replacement_tile[i] = (uint8_t) (i * 43U + 19U);
        }
        memset(guest_fpu_handler_tile, 0, sizeof(guest_fpu_handler_tile));
        guest_fpu_amx_seen = 0;

        _tile_loadconfig(&configuration);
        _tile_loadd(0, guest_fpu_initial_tile, 64);
        result = syscall(SYS_tgkill, getpid(), gettid(), SIGUSR2);
        _tile_stored(0, output, 64);
        _tile_release();

        if (sigaction(SIGUSR2, &old_action, NULL) < 0)
                return -errno;
        if (result < 0)
                return (int) result;
        if (!guest_fpu_amx_seen ||
            memcmp(guest_fpu_handler_tile, guest_fpu_initial_tile, sizeof(guest_fpu_handler_tile)) != 0 ||
            memcmp(output, guest_fpu_replacement_tile, sizeof(output)) != 0)
                return -EPROTO;
        return 0;
}

static int test_guest_signal_fpu(void) {
        struct sigaction action = {
                .sa_sigaction = guest_fpu_signal_handler,
                .sa_flags = SA_SIGINFO,
        };
        _Alignas(32) uint32_t original_ymm[8], observed_ymm[8];
        uint32_t original_mxcsr, observed_mxcsr;
        uint16_t original_fcw, observed_fcw;
        long result;
        pid_t pid = getpid(), tid = gettid();

        if (sigemptyset(&action.sa_mask) < 0 || sigaction(SIGUSR1, &action, NULL) < 0)
                return -errno;

        asm volatile (
                "vmovdqu %%ymm15, %0\n\t"
                "stmxcsr %1\n\t"
                "fnstcw %2"
                : "=m" (original_ymm), "=m" (original_mxcsr), "=m" (original_fcw));

        guest_fpu_signal_seen = 0;
        memset(guest_fpu_handler_ymm, 0, sizeof(guest_fpu_handler_ymm));
        guest_fpu_handler_mxcsr = 0;
        guest_fpu_handler_fcw = 0;
        asm volatile (
                "vmovdqu %[initial_ymm], %%ymm15\n\t"
                "ldmxcsr %[initial_mxcsr]\n\t"
                "fldcw %[initial_fcw]\n\t"
                "mov %[syscall_number], %%eax\n\t"
                "syscall\n\t"
                "vmovdqu %%ymm15, %[observed_ymm]\n\t"
                "stmxcsr %[observed_mxcsr]\n\t"
                "fnstcw %[observed_fcw]"
                : "=a" (result),
                                                                        [observed_ymm] "=m" (observed_ymm),
                  [observed_mxcsr] "=m" (observed_mxcsr),
                  [observed_fcw] "=m" (observed_fcw)
                : "D" ((long) pid),
                  "S" ((long) tid),
                  "d" ((long) SIGUSR1),
                  [syscall_number] "i" (SYS_tgkill),
                  [initial_ymm] "m" (guest_fpu_initial_ymm),
                  [initial_mxcsr] "m" (guest_fpu_initial_mxcsr),
                  [initial_fcw] "m" (guest_fpu_initial_fcw)
                : "rcx", "r11", "ymm15", "memory");

        asm volatile (
                "vmovdqu %0, %%ymm15\n\t"
                "ldmxcsr %1\n\t"
                "fldcw %2"
                :
                : "m" (original_ymm), "m" (original_mxcsr), "m" (original_fcw)
                : "ymm15", "memory");

        if (result < 0)
                return (int) result;
        if (!guest_fpu_signal_seen ||
            memcmp(observed_ymm, guest_fpu_replacement_ymm, sizeof(observed_ymm)) != 0 ||
                        observed_mxcsr != UINT32_C(0x5f80) ||
                        observed_fcw != guest_fpu_replacement_fcw) {
                                fprintf(stderr,
                        "AVX FPU mismatch: seen=%d frame=%08x,%08x,%08x,%08x,%08x,%08x,%08x,%08x/%08x/%04x returned=%08x,%08x,%08x,%08x,%08x,%08x,%08x,%08x/%08x/%04x\n",
                                                guest_fpu_signal_seen,
                        guest_fpu_handler_ymm[0],
                        guest_fpu_handler_ymm[1],
                        guest_fpu_handler_ymm[2],
                        guest_fpu_handler_ymm[3],
                        guest_fpu_handler_ymm[4],
                        guest_fpu_handler_ymm[5],
                        guest_fpu_handler_ymm[6],
                        guest_fpu_handler_ymm[7],
                                                guest_fpu_handler_mxcsr,
                                                guest_fpu_handler_fcw,
                        observed_ymm[0],
                        observed_ymm[1],
                        observed_ymm[2],
                        observed_ymm[3],
                        observed_ymm[4],
                        observed_ymm[5],
                        observed_ymm[6],
                        observed_ymm[7],
                                                observed_mxcsr,
                                                observed_fcw);
                return -EPROTO;
        }

        int r = test_guest_signal_avx512();
        if (r < 0)
                return r;

        r = test_guest_signal_amx();
        if (r < 0)
                return r;

        return 0;
}

