typedef struct GuestSignalWriteRestartContext {
        pthread_t target;
        int control_fd;
        int drain_fd;
        size_t drain_size;
} GuestSignalWriteRestartContext;

static void *guest_signal_write_restart_worker(void *userdata) {
        const struct timespec delay = {
                .tv_nsec = 20 * 1000 * 1000,
        };
        GuestSignalWriteRestartContext *context = userdata;
        size_t drained = 0;
        char buffer[4096], byte;

        if (read(context->control_fd, &byte, 1) != 1)
                return (void*) (uintptr_t) 1;
        (void) nanosleep(&delay, NULL);
        if (pthread_kill(context->target, SIGUSR1) != 0)
                return (void*) (uintptr_t) 2;
        (void) nanosleep(&delay, NULL);

        while (drained < context->drain_size) {
                size_t remaining = context->drain_size - drained;
                ssize_t n = read(context->drain_fd, buffer, remaining < sizeof(buffer) ? remaining : sizeof(buffer));

                if (n <= 0)
                        return (void*) (uintptr_t) 3;
                drained += n;
        }

        return NULL;
}

static int fill_nonblocking_fd(int fd, size_t *ret_size) {
        char buffer[4096] = {};
        size_t size = 0;
        int flags;

        flags = fcntl(fd, F_GETFL);
        if (flags < 0 || fcntl(fd, F_SETFL, flags | O_NONBLOCK) < 0)
                return -errno;
        for (;;) {
                ssize_t n = write(fd, buffer, sizeof(buffer));

                if (n < 0) {
                        if (errno != EAGAIN)
                                return -errno;
                        break;
                }
                size += n;
        }
        if (fcntl(fd, F_SETFL, flags) < 0)
                return -errno;

        *ret_size = size;
        return 0;
}

