static int run_guest_signal_open_restart_round(bool restart, unsigned call) {
        struct sigaction action = {
                .sa_handler = guest_restart_signal_handler,
                .sa_flags = restart ? SA_RESTART : 0,
        };
        char path[PATH_MAX];
        GuestSignalOpenRestartContext context;
        int control_pipe[2], fd, release_pipe[2], saved_errno;
        pthread_t worker;
        void *worker_result;
        struct open_how how = {
                .flags = O_RDONLY | O_CLOEXEC,
        };
        int result = 0, r;

        if (snprintf(path, sizeof(path), "/tmp/kvm-restart-fifo-%ld-%d", (long) getpid(), restart) >=
            (int) sizeof(path))
                return -ENAMETOOLONG;
        if (mkfifo(path, 0600) < 0 || pipe(control_pipe) < 0 || pipe(release_pipe) < 0 ||
            sigemptyset(&action.sa_mask) < 0 || sigaction(SIGUSR1, &action, NULL) < 0)
                return -errno;
        context = (GuestSignalOpenRestartContext) {
                .target = pthread_self(),
                .control_fd = control_pipe[0],
                .release_fd = release_pipe[0],
                .path = path,
        };
        r = pthread_create(&worker, NULL, guest_signal_open_restart_worker, &context);
        if (r != 0)
                return -r;
        if (write(control_pipe[1], "g", 1) != 1)
                return -errno;

        errno = 0;
        if (call == 0)
                fd = syscall(SYS_open, path, O_RDONLY | O_CLOEXEC, 0);
        else if (call == 1)
                fd = syscall(SYS_openat, AT_FDCWD, path, O_RDONLY | O_CLOEXEC, 0);
        else
                fd = syscall(SYS_openat2, AT_FDCWD, path, &how, sizeof(how));
        saved_errno = errno;
        if (restart) {
                if (fd < 0)
                        result = -EINTR;
        } else {
                if (fd >= 0 || saved_errno != EINTR)
                        result = -EPROTO;
                else
                        if (call == 0)
                                fd = syscall(SYS_open, path, O_RDONLY | O_CLOEXEC, 0);
                        else if (call == 1)
                                fd = syscall(SYS_openat, AT_FDCWD, path, O_RDONLY | O_CLOEXEC, 0);
                        else
                                fd = syscall(SYS_openat2, AT_FDCWD, path, &how, sizeof(how));
        }
        if (fd < 0 && result == 0)
                result = -errno;
        if (write(release_pipe[1], "x", 1) != 1 && result == 0)
                result = -errno;
        r = pthread_join(worker, &worker_result);
        if (r != 0 && result == 0)
                result = -r;
        if (worker_result && result == 0)
                result = -EIO;
        if (fd >= 0)
                close(fd);
        close(control_pipe[0]);
        close(control_pipe[1]);
        close(release_pipe[0]);
        close(release_pipe[1]);
        if (unlink(path) < 0 && result == 0)
                result = -errno;
        return result;
}

static int run_guest_signal_fcntl_restart_round(bool restart, bool ofd) {
        struct sigaction action = {
                .sa_handler = guest_restart_signal_handler,
                .sa_flags = restart ? SA_RESTART : 0,
        };
        struct flock lock = {
                .l_type = F_WRLCK,
                .l_whence = SEEK_SET,
                .l_len = 1,
        };
        char proc_path[64], byte;
        GuestSignalRestartContext context;
        int control_pipe[2], fd, ready_pipe[2], release_pipe[2], saved_errno, status;
        pthread_t worker;
        void *worker_result;
        pid_t child;
        int result = 0, r;

        fd = memfd_create("kvm-restart-fcntl", MFD_CLOEXEC);
        if (fd < 0 || pipe(control_pipe) < 0 || pipe(ready_pipe) < 0 || pipe(release_pipe) < 0 ||
            sigemptyset(&action.sa_mask) < 0 || sigaction(SIGUSR1, &action, NULL) < 0)
                return -errno;
        if (snprintf(proc_path, sizeof(proc_path), "/proc/self/fd/%d", fd) >= (int) sizeof(proc_path))
                return -ENAMETOOLONG;

        child = fork();
        if (child < 0)
                return -errno;
        if (child == 0) {
                int lock_fd = fd;

                if (ofd) {
                        lock_fd = open(proc_path, O_RDWR | O_CLOEXEC);
                        if (lock_fd < 0)
                                _exit(119);
                }
                if (fcntl(lock_fd, ofd ? F_OFD_SETLK : F_SETLK, &lock) < 0 ||
                    write(ready_pipe[1], "r", 1) != 1 || read(release_pipe[0], &byte, 1) != 1)
                        _exit(120);
                _exit(66);
        }
        if (read(ready_pipe[0], &byte, 1) != 1)
                return -EIO;

        context = (GuestSignalRestartContext) {
                .target = pthread_self(),
                .control_fd = control_pipe[0],
                .data_fd = release_pipe[1],
        };
        r = pthread_create(&worker, NULL, guest_signal_restart_worker, &context);
        if (r != 0)
                return -r;
        if (write(control_pipe[1], "g", 1) != 1)
                return -errno;

        errno = 0;
        r = fcntl(fd, ofd ? F_OFD_SETLKW : F_SETLKW, &lock);
        saved_errno = errno;
        if (restart) {
                if (r < 0)
                        result = -EINTR;
        } else if (r >= 0 || saved_errno != EINTR)
                result = -EPROTO;
        if (pthread_join(worker, &worker_result) != 0 && result == 0)
                result = -EIO;
        if (worker_result && result == 0)
                result = -EIO;
        if (waitpid(child, &status, 0) != child || !WIFEXITED(status) || WEXITSTATUS(status) != 66) {
                if (result == 0)
                        result = -ECHILD;
        }
        if (!restart && r < 0) {
                r = fcntl(fd, ofd ? F_OFD_SETLKW : F_SETLKW, &lock);
                if (r < 0 && result == 0)
                        result = -errno;
        }
        lock.l_type = F_UNLCK;
        if (r >= 0 && fcntl(fd, ofd ? F_OFD_SETLK : F_SETLK, &lock) < 0 && result == 0)
                result = -errno;

        close(control_pipe[0]);
        close(control_pipe[1]);
        close(ready_pipe[0]);
        close(ready_pipe[1]);
        close(release_pipe[0]);
        close(release_pipe[1]);
        close(fd);
        return result;
}

