static void* guest_thread_main(void *userdata) {
        GuestThreadContext *context = userdata;
        int r;

        context->child_tid = gettid();
        context->mxcsr = guest_read_mxcsr();
        context->rseq_error = validate_guest_rseq_registration();
        context->shared_value = 42 + context->index;

        r = pthread_barrier_wait(&context->shared->barrier);
        if (r != 0 && r != PTHREAD_BARRIER_SERIAL_THREAD)
                return (void*) (uintptr_t) 1;
        for (unsigned i = 0; i < 1000; i++) {
                if (pthread_mutex_lock(&context->shared->mutex) != 0)
                        return (void*) (uintptr_t) 2;
                context->shared->counter++;
                if (pthread_mutex_unlock(&context->shared->mutex) != 0)
                        return (void*) (uintptr_t) 3;
        }

        if (context->index == 0) {
                pthread_t nested;
                void *result;
                int r;

                r = pthread_create(&nested, NULL, guest_nested_thread_main, context);
                if (r != 0) {
                        context->nested_error = r;
                        return (void*) (uintptr_t) 4;
                }
                r = pthread_join(nested, &result);
                if (r != 0) {
                        context->nested_error = r;
                        return (void*) (uintptr_t) 5;
                }
                if (context->nested_tid <= 0 ||
                    context->nested_tid == context->child_tid ||
                                        context->nested_mxcsr != guest_fpu_initial_mxcsr ||
                    (uintptr_t) result != 31)
                        return (void*) (uintptr_t) 6;
        }

        return (void*) (uintptr_t) (23 + context->index);
}

