static int test_guest_robust_futex_unlock(void) {
        static const struct {
                int operation;
                uint32_t bitset;
        } variants[] = {
                { FUTEX_WAKE, 0 },
                { FUTEX_WAKE_BITSET, FUTEX_BITSET_MATCH_ANY },
                { FUTEX_UNLOCK_PI, 0 },
        };
        struct {
                uint32_t futex;
                struct robust_list list;
        } lock = {};
        struct robust_list_head *original_head;
        struct robust_list_head head = {};
        size_t original_length;

        if (syscall(SYS_get_robust_list, 0, &original_head, &original_length) < 0)
                return -errno;
        if (original_length != sizeof(head))
                return -EPROTO;
        head.list.next = &head.list;
        lock.list.next = &head.list;
        if (syscall(SYS_set_robust_list, &head, sizeof(head)) < 0)
                return -errno;

        for (size_t i = 0; i < sizeof(variants) / sizeof(variants[0]); i++) {
                const typeof(variants[0]) *variant = variants + i;
                int error = 0;
                long result;

                lock.futex = (uint32_t) gettid() | FUTEX_WAITERS;
                head.list_op_pending = &lock.list;
                errno = 0;
                result = syscall(SYS_futex,
                                 &lock.futex,
                                 variant->operation | FUTEX_ROBUST_UNLOCK,
                                 gettid(),
                                 NULL,
                                 &head.list_op_pending,
                                 variant->bitset);
                if (result < 0)
                        error = errno;
                if (result == 0) {
                        if (lock.futex != 0 || head.list_op_pending != NULL)
                                error = EPROTO;
                } else if (error != ENOSYS ||
                           lock.futex != ((uint32_t) gettid() | FUTEX_WAITERS) ||
                           head.list_op_pending != &lock.list)
                        error = error ?: EPROTO;

                if (error != 0 && error != ENOSYS) {
                        (void) syscall(SYS_set_robust_list, original_head, original_length);
                        return -error;
                }
        }

        if (syscall(SYS_set_robust_list, original_head, original_length) < 0)
                return -errno;
        return 0;
}

static volatile sig_atomic_t guest_thread_signal_ready = 0;
static volatile sig_atomic_t guest_thread_signal_seen = 0;
static volatile sig_atomic_t guest_thread_signal_tid = 0;

static void guest_thread_signal_handler(int signo, siginfo_t *info, void *context) {
        pid_t tid = gettid();

        if (signo == SIGUSR2 &&
            info && info->si_code == SI_TKILL &&
            context &&
            tid == guest_thread_signal_tid)
                guest_thread_signal_seen = tid;
}

static void* guest_thread_signal_target(void *userdata) {
        (void) userdata;

        guest_thread_signal_tid = gettid();
        guest_thread_signal_ready = 1;
        while (guest_thread_signal_seen == 0)
                (void) syscall(SYS_sched_yield);

        return NULL;
}

