static void* guest_thread_async_cancel_target(void *userdata) {
        GuestThreadCancelContext *context = userdata;
        int r;

        pthread_cleanup_push(guest_thread_cancel_cleanup, context);
        r = pthread_setcanceltype(PTHREAD_CANCEL_ASYNCHRONOUS, NULL);
        context->ready = r == 0 ? 1 : -1;
        while (r == 0)
                asm volatile ("pause" ::: "memory");
        pthread_cleanup_pop(/* execute= */ 0);
        return (void*) (uintptr_t) r;
}

static void* guest_thread_setxid_target(void *userdata) {
        GuestThreadSetxidContext *context = userdata;

        context->ready = 1;
        while (!context->release)
                (void) syscall(SYS_sched_yield);

        if (getresuid(&context->ruid, &context->euid, &context->suid) < 0 ||
            getresgid(&context->rgid, &context->egid, &context->sgid) < 0)
                context->error = errno;
        return NULL;
}

