static int prepare_guest_worker_exec_state(void) {
        struct sched_param parameter = {};
        unsigned long allowed_nodes[16] = {}, preferred_nodes[16] = {};
        unsigned long execution_personality;
        cpu_set_t affinity;
        sigset_t mask;
        int cpu, r;

        cpu = sched_getcpu();
        if (cpu < 0)
                return -errno;
        CPU_ZERO(&affinity);
        CPU_SET(cpu, &affinity);
        if (sigemptyset(&mask) < 0 || sigaddset(&mask, SIGUSR1) < 0 ||
            pthread_sigmask(SIG_BLOCK, &mask, NULL) != 0 ||
            prctl(PR_SET_TIMERSLACK, 123456789UL, 0, 0, 0) < 0 ||
            sched_setscheduler(0, SCHED_BATCH, &parameter) < 0 ||
            setpriority(PRIO_PROCESS, 0, 5) < 0 ||
                        sched_setaffinity(0, sizeof(affinity), &affinity) < 0 ||
                        syscall(SYS_ioprio_set,
                                        IOPRIO_WHO_PROCESS,
                                        0,
                                        IOPRIO_PRIO_VALUE(IOPRIO_CLASS_BE, 6)) < 0)
                return -errno;
        r = syscall(SYS_get_mempolicy, NULL, allowed_nodes, 1024, NULL, MPOL_F_MEMS_ALLOWED);
        if (r < 0) {
                if (errno != ENOSYS)
                        return -errno;
        } else {
                unsigned node;

                for (node = 0; node < 1024; node++)
                        if (allowed_nodes[node / (8 * sizeof(unsigned long))] &
                            (1UL << (node % (8 * sizeof(unsigned long)))))
                                break;
                if (node >= 1024)
                        return -ENXIO;
                preferred_nodes[node / (8 * sizeof(unsigned long))] |=
                        1UL << (node % (8 * sizeof(unsigned long)));
                if (syscall(SYS_set_mempolicy, MPOL_PREFERRED, preferred_nodes, 1024) < 0)
                        return -errno;
        }
        execution_personality = personality(UINT_MAX);
        if (execution_personality == ULONG_MAX || personality(execution_personality | UNAME26) < 0 ||
            prctl(PR_SET_PDEATHSIG, SIGUSR2, 0, 0, 0) < 0 ||
            prctl(PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0) < 0 ||
            prctl(PR_MCE_KILL, PR_MCE_KILL_SET, PR_MCE_KILL_EARLY, 0, 0) < 0)
                return -errno;

        return 0;
}

