typedef struct GuestLandlockRulesetAttrV10 {
        uint64_t handled_access_fs;
        uint64_t handled_access_net;
        uint64_t scoped;
        uint64_t quiet_access_fs;
        uint64_t quiet_access_net;
        uint64_t quiet_scoped;
} GuestLandlockRulesetAttrV10;

static int install_guest_landlock_exec_domain(bool *ret_udp) {
        long abi;
        int ruleset_fd;

        abi = syscall(SYS_landlock_create_ruleset, NULL, 0, LANDLOCK_CREATE_RULESET_VERSION);
        if (abi < 0)
                return -errno;

        if (abi >= 10) {
                const GuestLandlockRulesetAttrV10 ruleset = {
                        .handled_access_fs = LANDLOCK_ACCESS_FS_MAKE_REG,
                        .handled_access_net = LANDLOCK_ACCESS_NET_BIND_UDP |
                                LANDLOCK_ACCESS_NET_CONNECT_SEND_UDP,
                        .quiet_access_net = LANDLOCK_ACCESS_NET_BIND_UDP,
                };
                const struct landlock_net_port_attr ephemeral_rule = {
                        .allowed_access = LANDLOCK_ACCESS_NET_BIND_UDP,
                        .port = 0,
                };
                const struct landlock_net_port_attr quiet_rule = {
                        .port = 1,
                };

                ruleset_fd = syscall(SYS_landlock_create_ruleset, &ruleset, sizeof(ruleset), 0);
                if (ruleset_fd < 0)
                        return -errno;
                if (syscall(SYS_landlock_add_rule,
                            ruleset_fd,
                            LANDLOCK_RULE_NET_PORT,
                            &ephemeral_rule,
                            0) < 0 ||
                    syscall(SYS_landlock_add_rule,
                            ruleset_fd,
                            LANDLOCK_RULE_NET_PORT,
                            &quiet_rule,
                            LANDLOCK_ADD_RULE_QUIET) < 0) {
                        int error = errno;

                        close(ruleset_fd);
                        return -error;
                }
                *ret_udp = true;
        } else {
                const struct landlock_ruleset_attr ruleset = {
                        .handled_access_fs = LANDLOCK_ACCESS_FS_MAKE_REG,
                };

                ruleset_fd = syscall(SYS_landlock_create_ruleset, &ruleset, sizeof(ruleset), 0);
                if (ruleset_fd < 0)
                        return -errno;
                *ret_udp = false;
        }

        if (prctl(PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0) < 0 ||
            syscall(SYS_landlock_restrict_self, ruleset_fd, 0) < 0 ||
            close(ruleset_fd) < 0)
                return -errno;
        return 0;
}

static int validate_guest_landlock_udp(void) {
        struct sockaddr_in address = {
                .sin_family = AF_INET,
                .sin_addr.s_addr = htonl(INADDR_LOOPBACK),
        };
        int fd;

        fd = socket(AF_INET, SOCK_DGRAM | SOCK_CLOEXEC, 0);
        if (fd < 0 || bind(fd, (struct sockaddr*) &address, sizeof(address)) < 0 || close(fd) < 0)
                return EXIT_FAILURE;

        fd = socket(AF_INET, SOCK_DGRAM | SOCK_CLOEXEC, 0);
        if (fd < 0)
                return EXIT_FAILURE;
        address.sin_port = htons(1);
        errno = 0;
        if (bind(fd, (struct sockaddr*) &address, sizeof(address)) >= 0 || errno != EACCES) {
                close(fd);
                return EXIT_FAILURE;
        }
        close(fd);

        fd = socket(AF_INET, SOCK_DGRAM | SOCK_CLOEXEC, 0);
        if (fd < 0)
                return EXIT_FAILURE;
        address.sin_port = htons(9);
        errno = 0;
        if (connect(fd, (struct sockaddr*) &address, sizeof(address)) >= 0 || errno != EACCES) {
                close(fd);
                return EXIT_FAILURE;
        }
        close(fd);
        return EXIT_SUCCESS;
}

static int install_guest_getppid_filter(void) {
        const struct sock_filter instructions[] = {
                BPF_STMT(BPF_LD | BPF_W | BPF_ABS, offsetof(struct seccomp_data, nr)),
                BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, SYS_getppid, 0, 1),
                BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_ERRNO | EPERM),
                BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_ALLOW),
        };
        const struct sock_fprog program = {
                .len = sizeof(instructions) / sizeof(instructions[0]),
                .filter = (struct sock_filter*) instructions,
        };

        if (prctl(PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0) < 0 ||
            syscall(SYS_seccomp, SECCOMP_SET_MODE_FILTER, 0, &program) < 0)
                return -errno;

        return 0;
}

