static int guest_core_sched_get(uint64_t *ret_cookie) {
        uint64_t cookie = 0;

        errno = 0;
        if (prctl(PR_SCHED_CORE,
                  PR_SCHED_CORE_GET,
                  0,
                  PR_SCHED_CORE_SCOPE_THREAD,
                  &cookie) < 0)
                return errno == EINVAL || errno == ENODEV ? 0 : -errno;
        *ret_cookie = cookie;
        return 1;
}

