        if (prepare_guest_worker_exec_state() < 0)
                return (void*) (uintptr_t) errno;
        if (context->create_cookie &&
            prctl(PR_SCHED_CORE,
                  PR_SCHED_CORE_CREATE,
                  0,
                  PR_SCHED_CORE_SCOPE_THREAD,
                  0) < 0)
                return (void*) (uintptr_t) errno;
        if (guest_core_sched_get(&cookie) != 1 ||
            (context->create_cookie ? cookie == 0 : cookie != 0) ||
            write(context->ready_fd, "r", 1) != 1 ||
            read(context->release_fd, &byte, 1) != 1)
                return (void*) (uintptr_t) EPROTO;

        snprintf(pid, sizeof(pid), "%ld", (long) getpid());
        execl(context->self,
              context->self,
              "--guest-thread-exec-target",
              pid,
              context->create_cookie ? "--expect-core-sched-nonzero" : "--expect-core-sched-zero",
              NULL);
        return (void*) (uintptr_t) errno;
