static int run_guest_thread_core_sched_exec(const char *self, bool worker_creates_cookie) {
        int status;
        pid_t process;

        process = fork();
        if (process < 0)
                return EXIT_FAILURE;
        if (process == 0) {
                GuestCoreSchedExecContext context;
                int ready_pipe[2], release_pipe[2], r;
                pthread_t worker;
                void *result;
                uint64_t cookie;
                char byte;

                r = guest_core_sched_get(&cookie);
                if (r == 0)
                        _exit(0);
                if (r < 0 || cookie != 0 ||
                    pipe2(ready_pipe, O_CLOEXEC) < 0 || pipe2(release_pipe, O_CLOEXEC) < 0)
                        _exit(88);
                context = (GuestCoreSchedExecContext) {
                        .self = self,
                        .ready_fd = ready_pipe[1],
                        .release_fd = release_pipe[0],
                        .create_cookie = worker_creates_cookie,
                };
                r = pthread_create(&worker, NULL, guest_worker_core_sched_exec, &context);
                if (r != 0 || read(ready_pipe[0], &byte, 1) != 1 || byte != 'r')
                        _exit(89);
                if (!worker_creates_cookie &&
                    prctl(PR_SCHED_CORE,
                          PR_SCHED_CORE_CREATE,
                          0,
                          PR_SCHED_CORE_SCOPE_THREAD,
                          0) < 0)
                        _exit(90);
                if (write(release_pipe[1], "x", 1) != 1)
                        _exit(91);
                r = pthread_join(worker, &result);
                if (r == 0)
                        r = (int) (uintptr_t) result;
                _exit(r == 0 ? 0 : 92);
        }

        if (waitpid(process, &status, 0) != process ||
            !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                return EXIT_FAILURE;
        return EXIT_SUCCESS;
}

