typedef struct GuestSpeculationThreadContext {
        pthread_mutex_t mutex;
        pthread_cond_t condition;
        bool ready;
        bool release;
        bool test_store_bypass;
        bool test_indirect_branch;
        int error;
} GuestSpeculationThreadContext;

static int guest_speculation_verify_mode(
                const GuestSpeculationThreadContext *context,
                unsigned long mode) {

        if (context->test_store_bypass &&
            prctl(PR_GET_SPECULATION_CTRL, PR_SPEC_STORE_BYPASS, 0, 0, 0) !=
                    (int) (PR_SPEC_PRCTL | mode))
                return -EPROTO;
        if (context->test_indirect_branch &&
            prctl(PR_GET_SPECULATION_CTRL, PR_SPEC_INDIRECT_BRANCH, 0, 0, 0) !=
                    (int) (PR_SPEC_PRCTL | mode))
                return -EPROTO;

        return 0;
}

static int guest_speculation_set_mode(
                const GuestSpeculationThreadContext *context,
                unsigned long mode) {

        if (context->test_store_bypass &&
            prctl(PR_SET_SPECULATION_CTRL, PR_SPEC_STORE_BYPASS, mode, 0, 0) < 0)
                return -errno;
        if (context->test_indirect_branch &&
            prctl(PR_SET_SPECULATION_CTRL, PR_SPEC_INDIRECT_BRANCH, mode, 0, 0) < 0)
                return -errno;

        return 0;
}

static void* guest_speculation_nested_thread(void *userdata) {
        GuestSpeculationThreadContext *context = userdata;

        context->error = guest_speculation_verify_mode(context, PR_SPEC_DISABLE);
        if (context->error >= 0)
                context->error = guest_speculation_set_mode(context, PR_SPEC_ENABLE);
        if (context->error >= 0)
                context->error = guest_speculation_verify_mode(context, PR_SPEC_ENABLE);
        return NULL;
}

static void* guest_speculation_worker_thread(void *userdata) {
        GuestSpeculationThreadContext *context = userdata;
        pthread_t nested_thread;
        int child_status, result;
        pid_t child;

        context->error = guest_speculation_verify_mode(context, PR_SPEC_ENABLE);
        if (context->error >= 0)
                context->error = guest_speculation_set_mode(context, PR_SPEC_DISABLE);
        if (context->error >= 0)
                context->error = pthread_create(&nested_thread, NULL, guest_speculation_nested_thread, context);
        if (context->error == 0)
                context->error = pthread_join(nested_thread, NULL);
        if (context->error >= 0)
                context->error = guest_speculation_verify_mode(context, PR_SPEC_DISABLE);
        if (context->error >= 0) {
                child = fork();
                if (child < 0)
                        context->error = -errno;
                else if (child == 0) {
                        if (guest_speculation_verify_mode(context, PR_SPEC_DISABLE) < 0 ||
                            guest_speculation_set_mode(context, PR_SPEC_ENABLE) < 0 ||
                            guest_speculation_verify_mode(context, PR_SPEC_ENABLE) < 0)
                                _exit(112);
                        _exit(0);
                } else if (waitpid(child, &child_status, 0) != child ||
                           !WIFEXITED(child_status) || WEXITSTATUS(child_status) != 0)
                        context->error = -ECHILD;
        }
        if (context->error >= 0)
                context->error = guest_speculation_verify_mode(context, PR_SPEC_DISABLE);

        result = pthread_mutex_lock(&context->mutex);
        if (result != 0)
                context->error = -result;
        context->ready = true;
        result = pthread_cond_signal(&context->condition);
        if (result != 0)
                context->error = -result;
        while (!context->release) {
                result = pthread_cond_wait(&context->condition, &context->mutex);
                if (result != 0) {
                        context->error = -result;
                        break;
                }
        }
        result = pthread_mutex_unlock(&context->mutex);
        if (result != 0)
                context->error = -result;
        return NULL;
}

static void* guest_speculation_reused_thread(void *userdata) {
        GuestSpeculationThreadContext *context = userdata;

        context->error = guest_speculation_verify_mode(context, PR_SPEC_ENABLE);
        return NULL;
}

static int guest_speculation_verify_force_disabled(const GuestSpeculationThreadContext *context) {
        static const unsigned long selectors[] = {
                PR_SPEC_STORE_BYPASS,
                PR_SPEC_INDIRECT_BRANCH,
        };

                for (size_t i = 0; i < sizeof(selectors) / sizeof(selectors[0]); i++) {
                                unsigned long selector = selectors[i];

                                if ((selector == PR_SPEC_STORE_BYPASS && !context->test_store_bypass) ||
                                        (selector == PR_SPEC_INDIRECT_BRANCH && !context->test_indirect_branch))
                        continue;
                                if (prctl(PR_GET_SPECULATION_CTRL, selector, 0, 0, 0) !=
                    (PR_SPEC_PRCTL | PR_SPEC_FORCE_DISABLE))
                        return -EPROTO;
                errno = 0;
                                if (prctl(PR_SET_SPECULATION_CTRL, selector, PR_SPEC_ENABLE, 0, 0) >= 0 ||
                    errno != EPERM)
                        return -EPROTO;
                                if (prctl(PR_SET_SPECULATION_CTRL, selector, PR_SPEC_DISABLE, 0, 0) < 0 ||
                                        prctl(PR_GET_SPECULATION_CTRL, selector, 0, 0, 0) !=
                            (PR_SPEC_PRCTL | PR_SPEC_FORCE_DISABLE))
                        return -EPROTO;
        }

        return 0;
}

static void* guest_speculation_force_disabled_thread(void *userdata) {
        GuestSpeculationThreadContext *context = userdata;
        int child_status;
        pid_t child;

        context->error = guest_speculation_verify_force_disabled(context);
        if (context->error < 0)
                return NULL;

        child = fork();
        if (child < 0) {
                context->error = -errno;
                return NULL;
        }
        if (child == 0)
                _exit(guest_speculation_verify_force_disabled(context) < 0 ? 114 : 0);
        if (waitpid(child, &child_status, 0) != child ||
            !WIFEXITED(child_status) || WEXITSTATUS(child_status) != 0)
                context->error = -ECHILD;
        return NULL;
}

static int test_guest_speculation_force_disabled_inheritance(
                GuestSpeculationThreadContext *context) {

        int child_status;
        pid_t child;

        child = fork();
        if (child < 0)
                return -errno;
        if (child == 0) {
                pthread_t thread;
                pid_t vfork_child;

                if (guest_speculation_set_mode(context, PR_SPEC_FORCE_DISABLE) < 0 ||
                    guest_speculation_verify_force_disabled(context) < 0)
                        _exit(115);
                context->error = 0;
                if (pthread_create(
                                    &thread,
                                    NULL,
                                    guest_speculation_force_disabled_thread,
                                    context) != 0 ||
                    pthread_join(thread, NULL) != 0 || context->error < 0 ||
                    guest_speculation_verify_force_disabled(context) < 0)
                        _exit(116);

                vfork_child = vfork();
                if (vfork_child < 0)
                        _exit(117);
                if (vfork_child == 0)
                        _exit(guest_speculation_verify_force_disabled(context) < 0 ? 118 : 0);
                if (waitpid(vfork_child, &child_status, 0) != vfork_child ||
                    !WIFEXITED(child_status) || WEXITSTATUS(child_status) != 0 ||
                    guest_speculation_verify_force_disabled(context) < 0)
                        _exit(119);
                _exit(0);
        }

        if (waitpid(child, &child_status, 0) != child ||
            !WIFEXITED(child_status) || WEXITSTATUS(child_status) != 0 ||
            guest_speculation_verify_mode(context, PR_SPEC_ENABLE) < 0)
                return -EPROTO;
        return 0;
}

typedef struct GuestSpeculationTsyncContext {
        pthread_mutex_t mutex;
        pthread_cond_t ready_condition;
        pthread_cond_t release_condition;
        GuestSpeculationThreadContext speculation;
        unsigned ready;
        bool release;
        int errors[2];
} GuestSpeculationTsyncContext;

typedef struct GuestSpeculationTsyncWorker {
        GuestSpeculationTsyncContext *context;
        unsigned index;
} GuestSpeculationTsyncWorker;

static int guest_speculation_verify_tsync_policy(const GuestSpeculationThreadContext *context) {
        int expected, status;

        if (context->test_store_bypass) {
                status = prctl(PR_GET_SPECULATION_CTRL, PR_SPEC_STORE_BYPASS, 0, 0, 0);
                expected = guest_seccomp_forces_store_bypass ?
                        PR_SPEC_PRCTL | PR_SPEC_FORCE_DISABLE :
                        PR_SPEC_PRCTL | PR_SPEC_ENABLE;
                if (status != expected)
                        return -EPROTO;
        }

        if (context->test_indirect_branch) {
                status = prctl(PR_GET_SPECULATION_CTRL, PR_SPEC_INDIRECT_BRANCH, 0, 0, 0);
                expected = guest_seccomp_forces_indirect_branch ?
                        PR_SPEC_PRCTL | PR_SPEC_FORCE_DISABLE :
                        PR_SPEC_PRCTL | PR_SPEC_ENABLE;
                if (status != expected)
                        return -EPROTO;
        }

        return 0;
}

static void* guest_speculation_tsync_worker(void *userdata) {
        GuestSpeculationTsyncWorker *worker = userdata;
        GuestSpeculationTsyncContext *context = worker->context;
        int result;

        result = pthread_mutex_lock(&context->mutex);
        if (result != 0) {
                context->errors[worker->index] = -result;
                return NULL;
        }
        context->ready++;
        result = pthread_cond_signal(&context->ready_condition);
        if (result != 0)
                context->errors[worker->index] = -result;
        while (!context->release) {
                result = pthread_cond_wait(&context->release_condition, &context->mutex);
                if (result != 0) {
                        context->errors[worker->index] = -result;
                        break;
                }
        }
        result = pthread_mutex_unlock(&context->mutex);
        if (result != 0)
                context->errors[worker->index] = -result;
        if (context->errors[worker->index] >= 0)
                context->errors[worker->index] = guest_speculation_verify_tsync_policy(&context->speculation);
        return NULL;
}

static int install_guest_allow_all_seccomp(unsigned long flags) {
        static const struct sock_filter instructions[] = {
                BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_ALLOW),
        };
        const struct sock_fprog program = {
                .len = sizeof(instructions) / sizeof(instructions[0]),
                .filter = (struct sock_filter*) instructions,
        };

        return syscall(SYS_seccomp, SECCOMP_SET_MODE_FILTER, flags, &program) < 0 ? -errno : 0;
}

typedef struct GuestSpeculationTsyncFailureContext {
        pthread_mutex_t mutex;
        pthread_cond_t ready_condition;
        pthread_cond_t release_condition;
        GuestSpeculationThreadContext speculation;
        pid_t tid;
        bool ready;
        bool release;
        int error;
} GuestSpeculationTsyncFailureContext;

static void* guest_speculation_tsync_failure_worker(void *userdata) {
        GuestSpeculationTsyncFailureContext *context = userdata;
        int result;

        context->tid = gettid();
        context->error = install_guest_allow_all_seccomp(SECCOMP_FILTER_FLAG_SPEC_ALLOW);
        if (context->error >= 0)
                context->error = guest_speculation_verify_mode(&context->speculation, PR_SPEC_ENABLE);

        result = pthread_mutex_lock(&context->mutex);
        if (result != 0) {
                context->error = -result;
                return NULL;
        }
        context->ready = true;
        result = pthread_cond_signal(&context->ready_condition);
        if (result != 0)
                context->error = -result;
        while (!context->release) {
                result = pthread_cond_wait(&context->release_condition, &context->mutex);
                if (result != 0) {
                        context->error = -result;
                        break;
                }
        }
        result = pthread_mutex_unlock(&context->mutex);
        if (result != 0)
                context->error = -result;
        if (context->error >= 0)
                context->error = guest_speculation_verify_mode(&context->speculation, PR_SPEC_ENABLE);
        return NULL;
}

static int test_guest_speculation_tsync_failure(const GuestSpeculationThreadContext *speculation) {
        static const struct sock_filter instructions[] = {
                BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_ALLOW),
        };
        const struct sock_fprog program = {
                .len = sizeof(instructions) / sizeof(instructions[0]),
                .filter = (struct sock_filter*) instructions,
        };
        GuestSpeculationTsyncFailureContext context = {
                .speculation = {
                        .test_store_bypass = speculation->test_store_bypass,
                        .test_indirect_branch = speculation->test_indirect_branch,
                },
        };
        pthread_t thread;
        int result;
        long failed_tid;

        result = pthread_mutex_init(&context.mutex, NULL);
        if (result != 0)
                return -result;
        result = pthread_cond_init(&context.ready_condition, NULL);
        if (result != 0)
                return -result;
        result = pthread_cond_init(&context.release_condition, NULL);
        if (result != 0)
                return -result;
        result = pthread_create(&thread, NULL, guest_speculation_tsync_failure_worker, &context);
        if (result != 0)
                return -result;

        result = pthread_mutex_lock(&context.mutex);
        if (result != 0)
                return -result;
        while (!context.ready) {
                result = pthread_cond_wait(&context.ready_condition, &context.mutex);
                if (result != 0)
                        return -result;
        }
        failed_tid = syscall(
                        SYS_seccomp,
                        SECCOMP_SET_MODE_FILTER,
                        SECCOMP_FILTER_FLAG_TSYNC,
                        &program);
        if (failed_tid != context.tid ||
            guest_speculation_verify_mode(&context.speculation, PR_SPEC_ENABLE) < 0)
                context.error = -EPROTO;
        context.release = true;
        result = pthread_cond_signal(&context.release_condition);
        if (result != 0)
                context.error = -result;
        result = pthread_mutex_unlock(&context.mutex);
        if (result != 0)
                return -result;
        result = pthread_join(thread, NULL);
        if (result != 0 || context.error < 0)
                return result != 0 ? -result : context.error;
        if (pthread_cond_destroy(&context.release_condition) != 0 ||
            pthread_cond_destroy(&context.ready_condition) != 0 ||
            pthread_mutex_destroy(&context.mutex) != 0)
                return -EPROTO;
        return 0;
}

static int test_guest_speculation_tsync_lifecycle(const GuestSpeculationThreadContext *speculation) {
        GuestSpeculationTsyncContext context = {};
        GuestSpeculationTsyncWorker workers[2];
        pthread_t threads[2];
        int result;

        context.speculation.test_store_bypass = speculation->test_store_bypass;
        context.speculation.test_indirect_branch = speculation->test_indirect_branch;

        result = pthread_mutex_init(&context.mutex, NULL);
        if (result != 0)
                return -result;
        result = pthread_cond_init(&context.ready_condition, NULL);
        if (result != 0)
                return -result;
        result = pthread_cond_init(&context.release_condition, NULL);
        if (result != 0)
                return -result;

        for (unsigned i = 0; i < 2; i++) {
                workers[i] = (GuestSpeculationTsyncWorker) {
                        .context = &context,
                        .index = i,
                };
                result = pthread_create(threads + i, NULL, guest_speculation_tsync_worker, workers + i);
                if (result != 0)
                        return -result;
        }

        result = pthread_mutex_lock(&context.mutex);
        if (result != 0)
                return -result;
        while (context.ready < 2) {
                result = pthread_cond_wait(&context.ready_condition, &context.mutex);
                if (result != 0)
                        return -result;
        }
        if (install_guest_allow_all_seccomp(
                            SECCOMP_FILTER_FLAG_TSYNC | SECCOMP_FILTER_FLAG_SPEC_ALLOW) < 0 ||
            guest_speculation_verify_mode(&context.speculation, PR_SPEC_ENABLE) < 0 ||
            install_guest_allow_all_seccomp(SECCOMP_FILTER_FLAG_TSYNC) < 0)
                return -EPROTO;
        context.release = true;
        result = pthread_cond_broadcast(&context.release_condition);
        if (result != 0)
                return -result;
        result = pthread_mutex_unlock(&context.mutex);
        if (result != 0)
                return -result;

        for (unsigned i = 0; i < 2; i++) {
                result = pthread_join(threads[i], NULL);
                if (result != 0 || context.errors[i] < 0)
                        return result != 0 ? -result : context.errors[i];
        }
        result = guest_speculation_verify_tsync_policy(&context.speculation);
        if (result < 0)
                return result;
        if (pthread_cond_destroy(&context.release_condition) != 0 ||
            pthread_cond_destroy(&context.ready_condition) != 0 ||
            pthread_mutex_destroy(&context.mutex) != 0)
                return -EPROTO;
        return 0;
}

static int test_guest_speculation_creation_lifecycle(void) {
        GuestSpeculationThreadContext context = {};
        int initial_indirect_branch, initial_store_bypass;
        pthread_t worker;
        int child_status, result;
        pid_t child;

        initial_store_bypass = prctl(PR_GET_SPECULATION_CTRL, PR_SPEC_STORE_BYPASS, 0, 0, 0);
        initial_indirect_branch = prctl(PR_GET_SPECULATION_CTRL, PR_SPEC_INDIRECT_BRANCH, 0, 0, 0);
        if (initial_store_bypass < 0 || initial_indirect_branch < 0)
                return EXIT_FAILURE;
        context.test_store_bypass = (initial_store_bypass & PR_SPEC_PRCTL) != 0 &&
                (initial_store_bypass & PR_SPEC_FORCE_DISABLE) == 0;
        context.test_indirect_branch = (initial_indirect_branch & PR_SPEC_PRCTL) != 0 &&
                (initial_indirect_branch & PR_SPEC_FORCE_DISABLE) == 0;
        if (!context.test_store_bypass && !context.test_indirect_branch)
                return EXIT_SUCCESS;
        if (test_guest_seccomp_speculation_profile() != EXIT_SUCCESS)
                return EXIT_FAILURE;

        result = pthread_mutex_init(&context.mutex, NULL);
        if (result != 0)
                return EXIT_FAILURE;
        result = pthread_cond_init(&context.condition, NULL);
        if (result != 0)
                return EXIT_FAILURE;
        if (guest_speculation_set_mode(&context, PR_SPEC_ENABLE) < 0 ||
            pthread_create(&worker, NULL, guest_speculation_worker_thread, &context) != 0)
                return EXIT_FAILURE;

        result = pthread_mutex_lock(&context.mutex);
        if (result != 0)
                return EXIT_FAILURE;
        while (!context.ready) {
                result = pthread_cond_wait(&context.condition, &context.mutex);
                if (result != 0)
                        return EXIT_FAILURE;
        }
        if (guest_speculation_verify_mode(&context, PR_SPEC_ENABLE) < 0)
                context.error = -EPROTO;
        context.release = true;
        result = pthread_cond_signal(&context.condition);
        if (result != 0)
                context.error = -result;
        result = pthread_mutex_unlock(&context.mutex);
        if (result != 0)
                return EXIT_FAILURE;
        if (pthread_join(worker, NULL) != 0 || context.error < 0 ||
            guest_speculation_verify_mode(&context, PR_SPEC_ENABLE) < 0)
                return EXIT_FAILURE;

        context.error = 0;
        if (pthread_create(&worker, NULL, guest_speculation_reused_thread, &context) != 0 ||
            pthread_join(worker, NULL) != 0 || context.error < 0)
                return EXIT_FAILURE;

        errno = 0;
        if (syscall(SYS_clone, CLONE_THREAD | SIGCHLD, NULL, NULL, NULL, 0) >= 0 || errno != EINVAL ||
            guest_speculation_verify_mode(&context, PR_SPEC_ENABLE) < 0)
                return EXIT_FAILURE;

        if (guest_speculation_set_mode(&context, PR_SPEC_DISABLE) < 0)
                return EXIT_FAILURE;
        child = vfork();
        if (child < 0)
                return EXIT_FAILURE;
        if (child == 0) {
                if (guest_speculation_verify_mode(&context, PR_SPEC_DISABLE) < 0 ||
                    guest_speculation_set_mode(&context, PR_SPEC_ENABLE) < 0 ||
                    guest_speculation_verify_mode(&context, PR_SPEC_ENABLE) < 0)
                        _exit(113);
                _exit(0);
        }
        if (waitpid(child, &child_status, 0) != child ||
            !WIFEXITED(child_status) || WEXITSTATUS(child_status) != 0 ||
            guest_speculation_verify_mode(&context, PR_SPEC_DISABLE) < 0)
                return EXIT_FAILURE;

        if (context.test_store_bypass &&
            prctl(PR_SET_SPECULATION_CTRL,
                  PR_SPEC_STORE_BYPASS,
                  initial_store_bypass & ~PR_SPEC_PRCTL,
                  0,
                  0) < 0)
                return EXIT_FAILURE;
        if (context.test_indirect_branch &&
            prctl(PR_SET_SPECULATION_CTRL,
                  PR_SPEC_INDIRECT_BRANCH,
                  initial_indirect_branch & ~PR_SPEC_PRCTL,
                  0,
                  0) < 0)
                return EXIT_FAILURE;
                                if (guest_speculation_set_mode(&context, PR_SPEC_ENABLE) < 0 ||
                                        test_guest_speculation_force_disabled_inheritance(&context) < 0 ||
                                                prctl(PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0) < 0 ||
                                        test_guest_speculation_tsync_failure(&context) < 0 ||
                                        test_guest_speculation_tsync_lifecycle(&context) < 0)
                                                                return EXIT_FAILURE;
        if (pthread_cond_destroy(&context.condition) != 0 ||
            pthread_mutex_destroy(&context.mutex) != 0)
                return EXIT_FAILURE;
        return EXIT_SUCCESS;
}

static int test_guest_thread(void) {
        enum { N_THREADS = 4 };
        GuestThreadContext contexts[N_THREADS] = {};
        GuestThreadShared shared;
        pthread_t threads[N_THREADS];
        pid_t parent_tid = gettid();
        uint32_t original_mxcsr;
        unsigned futex_hash_slots;
        int futex_hash_supported;
        int r;

        if (!guest_amx_state_works() || !guest_amx_thread_state_works()) {
                fprintf(stderr, "Guest AMX thread lifecycle failed\n");
                return EXIT_FAILURE;
        }

        if (test_guest_speculation_creation_lifecycle() != EXIT_SUCCESS) {
                fprintf(stderr, "Guest speculation creation lifecycle failed\n");
                return EXIT_FAILURE;
        }

        futex_hash_supported = guest_futex_hash_get_slots(&futex_hash_slots);
        if (futex_hash_supported < 0 || (futex_hash_supported > 0 && futex_hash_slots != 0)) {
                fprintf(stderr, "Guest futex hash did not start empty\n");
                return EXIT_FAILURE;
        }
        r = test_guest_robust_futex_unlock();
        if (r < 0) {
                fprintf(stderr, "Guest robust futex unlock failed: %s\n", strerror(-r));
                return EXIT_FAILURE;
        }

        r = validate_guest_rseq_registration();
        if (r < 0) {
                fprintf(stderr, "Guest main-thread rseq registration failed: %s\n", strerror(-r));
                return EXIT_FAILURE;
        }

        original_mxcsr = guest_read_mxcsr();
        guest_write_mxcsr(guest_fpu_initial_mxcsr);

        r = pthread_barrier_init(&shared.barrier, NULL, N_THREADS + 1);
        if (r != 0 || (r = pthread_mutex_init(&shared.mutex, NULL)) != 0) {
                fprintf(stderr, "Failed to initialize guest thread synchronization: %s\n", strerror(r));
                return EXIT_FAILURE;
        }
        shared.counter = 0;

        for (unsigned i = 0; i < N_THREADS; i++) {
                contexts[i] = (GuestThreadContext) {
                        .shared = &shared,
                        .parent_tid = parent_tid,
                        .index = i,
                };
                r = pthread_create(threads + i, NULL, guest_thread_main, contexts + i);
                if (r != 0) {
                        fprintf(stderr, "Failed to create guest thread: %s\n", strerror(r));
                        return EXIT_FAILURE;
                }
        }

        if (futex_hash_supported > 0 &&
            (guest_futex_hash_get_slots(&futex_hash_slots) != 1 || futex_hash_slots != 16)) {
                fprintf(stderr, "Guest thread creation did not allocate the default futex hash\n");
                return EXIT_FAILURE;
        }

        r = pthread_barrier_wait(&shared.barrier);
        if (r != 0 && r != PTHREAD_BARRIER_SERIAL_THREAD) {
                fprintf(stderr, "Failed to release guest thread barrier: %s\n", strerror(r));
                return EXIT_FAILURE;
        }

        for (unsigned i = 0; i < N_THREADS; i++) {
                void *result;

                r = pthread_join(threads[i], &result);
                if (r != 0) {
                        fprintf(stderr, "Failed to join guest thread: %s\n", strerror(r));
                        return EXIT_FAILURE;
                }
                if (contexts[i].child_tid <= 0 || contexts[i].child_tid == parent_tid ||
                                        contexts[i].mxcsr != guest_fpu_initial_mxcsr ||
                                        contexts[i].rseq_error != 0 ||
                    contexts[i].shared_value != (int) (42 + i) || (uintptr_t) result != 23 + i) {
                        fprintf(stderr,
                                "Guest thread %u returned inconsistent state: tid=%ld nested=%ld error=%d value=%d result=%lu\n",
                                i,
                                (long) contexts[i].child_tid,
                                (long) contexts[i].nested_tid,
                                contexts[i].nested_error,
                                contexts[i].shared_value,
                                (unsigned long) (uintptr_t) result);
                        return EXIT_FAILURE;
                }
                for (unsigned j = 0; j < i; j++)
                        if (contexts[j].child_tid == contexts[i].child_tid) {
                                fprintf(stderr, "Guest threads did not receive distinct TIDs\n");
                                return EXIT_FAILURE;
                        }
        }
        if (shared.counter != N_THREADS * 1000) {
                fprintf(stderr, "Guest mutex lost shared counter updates\n");
                return EXIT_FAILURE;
        }
        if ((r = pthread_mutex_destroy(&shared.mutex)) != 0 ||
            (r = pthread_barrier_destroy(&shared.barrier)) != 0) {
                fprintf(stderr, "Failed to destroy guest thread synchronization: %s\n", strerror(r));
                return EXIT_FAILURE;
        }

        pthread_mutexattr_t robust_attributes;
        pthread_mutex_t robust_mutex;
        pthread_t robust_owner;
        void *robust_result;

        if ((r = pthread_mutexattr_init(&robust_attributes)) != 0 ||
            (r = pthread_mutexattr_setrobust(&robust_attributes, PTHREAD_MUTEX_ROBUST)) != 0 ||
            (r = pthread_mutex_init(&robust_mutex, &robust_attributes)) != 0 ||
            (r = pthread_mutexattr_destroy(&robust_attributes)) != 0 ||
            (r = pthread_create(&robust_owner, NULL, guest_robust_mutex_owner, &robust_mutex)) != 0 ||
            (r = pthread_join(robust_owner, &robust_result)) != 0) {
                fprintf(stderr, "Failed to run robust guest mutex owner: %s\n", strerror(r));
                return EXIT_FAILURE;
        }
        if ((uintptr_t) robust_result != 0 || (r = pthread_mutex_lock(&robust_mutex)) != EOWNERDEAD ||
            (r = pthread_mutex_consistent(&robust_mutex)) != 0 ||
            (r = pthread_mutex_unlock(&robust_mutex)) != 0 || (r = pthread_mutex_destroy(&robust_mutex)) != 0) {
                fprintf(stderr, "Guest robust mutex recovery failed: %s\n", strerror(r));
                return EXIT_FAILURE;
        }

        GuestThreadCancelContext cancel_context = {};
        int cancel_pipe[2];
        pthread_t cancel_target;
        void *cancel_result;

        if (pipe(cancel_pipe) < 0)
                return EXIT_FAILURE;
        cancel_context.fd = cancel_pipe[0];
        if ((r = pthread_create(&cancel_target, NULL, guest_thread_cancel_target, &cancel_context)) != 0) {
                fprintf(stderr, "Failed to create cancellable guest thread: %s\n", strerror(r));
                return EXIT_FAILURE;
        }
        while (!cancel_context.ready)
                (void) syscall(SYS_sched_yield);
        if ((r = pthread_cancel(cancel_target)) != 0 ||
            (r = pthread_join(cancel_target, &cancel_result)) != 0 ||
            cancel_result != PTHREAD_CANCELED ||
            cancel_context.cleaned != 1) {
                fprintf(stderr, "Guest pthread cancellation failed: %s\n", strerror(r));
                return EXIT_FAILURE;
        }
        close(cancel_pipe[0]);
        close(cancel_pipe[1]);

        cancel_context = (GuestThreadCancelContext) {};
        if ((r = pthread_create(&cancel_target, NULL, guest_thread_async_cancel_target, &cancel_context)) != 0) {
                fprintf(stderr, "Failed to create asynchronously cancellable guest thread: %s\n", strerror(r));
                return EXIT_FAILURE;
        }
        while (cancel_context.ready == 0)
                (void) syscall(SYS_sched_yield);
        if (cancel_context.ready < 0 ||
            (r = pthread_cancel(cancel_target)) != 0 ||
            (r = pthread_join(cancel_target, &cancel_result)) != 0 ||
            cancel_result != PTHREAD_CANCELED ||
            cancel_context.cleaned != 1) {
                fprintf(stderr, "Guest asynchronous pthread cancellation failed: %s\n", strerror(r));
                return EXIT_FAILURE;
        }

        GuestThreadSetxidContext setxid_context = {};
        pthread_t setxid_target;
        uid_t ruid, euid, suid;
        gid_t rgid, egid, sgid;

        if (getresuid(&ruid, &euid, &suid) < 0 || getresgid(&rgid, &egid, &sgid) < 0) {
                fprintf(stderr, "Failed to query guest credentials: %m\n");
                return EXIT_FAILURE;
        }
        if ((r = pthread_create(&setxid_target, NULL, guest_thread_setxid_target, &setxid_context)) != 0) {
                fprintf(stderr, "Failed to prepare guest setxid synchronization: %s\n", strerror(r));
                return EXIT_FAILURE;
        }
        while (!setxid_context.ready)
                (void) syscall(SYS_sched_yield);
        if (setresgid(rgid, egid, sgid) < 0 || setresuid(ruid, euid, suid) < 0) {
                fprintf(stderr, "Guest setxid synchronization failed: %m\n");
                return EXIT_FAILURE;
        }
        setxid_context.release = 1;
        if ((r = pthread_join(setxid_target, NULL)) != 0 ||
            setxid_context.error != 0 ||
            setxid_context.ruid != ruid || setxid_context.euid != euid || setxid_context.suid != suid ||
            setxid_context.rgid != rgid || setxid_context.egid != egid || setxid_context.sgid != sgid) {
                fprintf(stderr, "Guest sibling credentials are inconsistent after setxid: %s\n", strerror(r));
                return EXIT_FAILURE;
        }

        struct sigaction thread_signal_action = {
                .sa_sigaction = guest_thread_signal_handler,
                .sa_flags = SA_SIGINFO,
        };
        pthread_t signal_target;

        if (sigemptyset(&thread_signal_action.sa_mask) < 0 ||
            sigaction(SIGUSR2, &thread_signal_action, NULL) < 0 ||
            (r = pthread_create(&signal_target, NULL, guest_thread_signal_target, NULL)) != 0) {
                fprintf(stderr, "Failed to prepare guest thread signal: %s\n", strerror(r));
                return EXIT_FAILURE;
        }
        while (!guest_thread_signal_ready)
                (void) syscall(SYS_sched_yield);
        if ((r = pthread_kill(signal_target, SIGUSR2)) != 0 || (r = pthread_join(signal_target, NULL)) != 0 ||
            guest_thread_signal_seen != guest_thread_signal_tid) {
                fprintf(stderr, "Targeted guest thread signal failed: %s\n", strerror(r));
                return EXIT_FAILURE;
        }

        GuestThreadForkContext fork_context;
        int fork_pipe[2], fork_status;
        pthread_t fork_sibling;
        pid_t fork_child;
        void *fork_sibling_result;

        if (pipe(fork_pipe) < 0)
                return EXIT_FAILURE;
        fork_context = (GuestThreadForkContext) {
                .fd = fork_pipe[0],
        };
        if ((r = pthread_create(&fork_sibling, NULL, guest_thread_fork_sibling, &fork_context)) != 0) {
                fprintf(stderr, "Failed to create guest fork sibling: %s\n", strerror(r));
                return EXIT_FAILURE;
        }
        while (!fork_context.ready)
                (void) syscall(SYS_sched_yield);

        fork_child = fork();
        if (fork_child < 0) {
                fprintf(stderr, "Failed to fork multithreaded guest: %m\n");
                return EXIT_FAILURE;
        }
        if (fork_child == 0)
                _exit(46);

        if (write(fork_pipe[1], "x", 1) != 1 || (r = pthread_join(fork_sibling, &fork_sibling_result)) != 0 ||
            fork_sibling_result || waitpid(fork_child, &fork_status, 0) != fork_child ||
            !WIFEXITED(fork_status) || WEXITSTATUS(fork_status) != 46) {
                fprintf(stderr, "Multithreaded guest fork lifecycle failed\n");
                return EXIT_FAILURE;
        }
        close(fork_pipe[0]);
        close(fork_pipe[1]);

                pthread_t worker_fork;
                void *worker_fork_result;

                if ((r = pthread_create(&worker_fork, NULL, guest_worker_fork, NULL)) != 0 ||
                        (r = pthread_join(worker_fork, &worker_fork_result)) != 0 ||
                        worker_fork_result) {
                                fprintf(stderr, "Guest worker-thread fork promotion failed: %s\n", strerror(r));
                                return EXIT_FAILURE;
                }

        r = test_guest_thread_mprotect();
        if (r < 0) {
                fprintf(stderr, "Cross-vCPU guest mprotect failed: %s\n", strerror(-r));
                return EXIT_FAILURE;
        }

        guest_write_mxcsr(original_mxcsr);

        printf("KVM_THREAD_OK parent=%ld children=%ld,%ld,%ld,%ld\n",
               (long) parent_tid,
               (long) contexts[0].child_tid,
               (long) contexts[1].child_tid,
               (long) contexts[2].child_tid,
               (long) contexts[3].child_tid);
        return EXIT_SUCCESS;
}

static int test_guest_vfork_mlockall(void) {
        int status;
        pid_t process;

        process = fork();
        if (process < 0)
                return EXIT_FAILURE;
        if (process == 0) {
                long page_size = sysconf(_SC_PAGESIZE);
                void *memory;
                pid_t child;

                if (page_size <= 0)
                        _exit(45);
                memory = mmap(NULL,
                              page_size,
                              PROT_READ | PROT_WRITE,
                              MAP_PRIVATE | MAP_ANONYMOUS,
                              -1,
                              0);
                if (memory == MAP_FAILED)
                        _exit(46);
                errno = 0;
                if (mlock(memory, page_size) == 0) {
                        child = vfork();
                        if (child < 0) {
                                if (errno != EOPNOTSUPP)
                                        _exit(47);
                        } else {
                                if (child == 0)
                                        _exit(0);
                                if (waitpid(child, &status, 0) != child ||
                                    !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                                        _exit(48);
                        }
                        if (munlockall() < 0)
                                _exit(49);
                } else if (errno != ENOMEM && errno != EPERM)
                        _exit(50);

                errno = 0;
                if (mlockall(MCL_FUTURE) < 0)
                        _exit(errno == ENOMEM || errno == EPERM ? 0 : 42);
                child = vfork();
                if (child < 0)
                        _exit(errno == EOPNOTSUPP ? 0 : 43);
                if (child == 0)
                        _exit(0);
                if (waitpid(child, &status, 0) != child ||
                    !WIFEXITED(status) || WEXITSTATUS(status) != 0 ||
                    munlockall() < 0)
                        _exit(44);
                _exit(0);
        }

        if (waitpid(process, &status, 0) != process ||
            !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                return EXIT_FAILURE;

        return EXIT_SUCCESS;
}

static int test_guest_vfork_futex_hash(void) {
        unsigned slots;
        int status, supported;
        pid_t child;

        supported = guest_futex_hash_get_slots(&slots);
        if (supported < 0 || (supported > 0 && slots != 0))
                return EXIT_FAILURE;
        if (supported == 0)
                return EXIT_SUCCESS;
        if (prctl(PR_FUTEX_HASH, PR_FUTEX_HASH_SET_SLOTS, 16, 0, 0) < 0)
                return errno == EINVAL ? EXIT_SUCCESS : EXIT_FAILURE;

        child = vfork();
        if (child < 0)
                return EXIT_FAILURE;
        if (child == 0) {
                if (guest_futex_hash_get_slots(&slots) != 1 || slots != 16)
                        _exit(51);
                errno = 0;
                if (prctl(PR_FUTEX_HASH, PR_FUTEX_HASH_SET_SLOTS, 32, 0, 0) >= 0 || errno != EOPNOTSUPP)
                        _exit(52);
                _exit(0);
        }

        if (waitpid(child, &status, 0) != child || !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                return EXIT_FAILURE;
        if (guest_futex_hash_get_slots(&slots) != 1 || slots != 16)
                return EXIT_FAILURE;

        return EXIT_SUCCESS;
}

__attribute__((target("amx-tile"), noinline))
static int test_guest_vfork_amx(void) {
        _Alignas(64) GuestAmxTileConfig configuration = {
                .palette_id = 1,
                .columns[0] = 64,
                .rows[0] = 16,
        };
        _Alignas(64) uint8_t parent_input[1024], parent_output[1024] = {}, child_output[1024] = {}, zero[1024] = {};
        unsigned eax, ebx, ecx, edx;
        int status;
        pid_t child;

        __cpuid_count(7, 0, eax, ebx, ecx, edx);
        if (!(edx & bit_AMX_TILE))
                return EXIT_SUCCESS;
        if (syscall(SYS_arch_prctl, ARCH_REQ_XCOMP_PERM, ARCH_XCOMP_TILEDATA) < 0)
                return EXIT_FAILURE;

        for (size_t i = 0; i < sizeof(parent_input); i++)
                parent_input[i] = (uint8_t) (i * 61U + 37U);
        _tile_loadconfig(&configuration);
        _tile_loadd(0, parent_input, 64);
        child = vfork();
        if (child < 0) {
                _tile_release();
                return EXIT_FAILURE;
        }
        if (child == 0) {
                uint64_t permissions = 0;

                _tile_loadconfig(&configuration);
                _tile_stored(0, child_output, 64);
                _tile_release();
                if (syscall(SYS_arch_prctl, ARCH_GET_XCOMP_PERM, &permissions) < 0 ||
                    !(permissions & (UINT64_C(1) << ARCH_XCOMP_TILEDATA)) ||
                    memcmp(child_output, zero, sizeof(child_output)) != 0)
                        _exit(124);
                _exit(0);
        }

        _tile_stored(0, parent_output, 64);
        _tile_release();
        if (waitpid(child, &status, 0) != child || !WIFEXITED(status) || WEXITSTATUS(status) != 0 ||
            memcmp(parent_output, parent_input, sizeof(parent_output)) != 0)
                return EXIT_FAILURE;
        return EXIT_SUCCESS;
}

static int test_guest_vfork(void) {
        int status;
        pid_t child;
        _Alignas(64) uint32_t original_zmm[16];
        _Alignas(32) uint32_t original_ymm[8];
        struct rseq *rseq;
        unsigned int registration_size;
        uint32_t original_mxcsr;
        uint64_t original_k7 = 0;
        bool avx512, invalid;

        if (test_guest_vfork_mlockall() != EXIT_SUCCESS) {
                fprintf(stderr, "Guest MCL_FUTURE vfork boundary failed\n");
                return EXIT_FAILURE;
        }
        if (test_guest_vfork_futex_hash() != EXIT_SUCCESS) {
                fprintf(stderr, "Guest futex hash vfork boundary failed\n");
                return EXIT_FAILURE;
        }
        if (test_guest_vfork_amx() != EXIT_SUCCESS) {
                fprintf(stderr, "Guest AMX vfork lifecycle failed\n");
                return EXIT_FAILURE;
        }

        avx512 = guest_has_avx512();
        rseq = guest_rseq_area();
        registration_size = __rseq_size < 32 ? 32 : __rseq_size;
        original_mxcsr = guest_read_mxcsr();
        if (avx512) {
                guest_save_avx512(original_zmm, &original_k7);
                child = guest_raw_vfork_with_avx512(rseq, registration_size);
                guest_restore_avx512(original_zmm, &original_k7);
        } else {
                asm volatile ("vmovdqu %%ymm15, %0" : "=m" (original_ymm));
                child = guest_raw_vfork_with_fpu(rseq, registration_size);
                asm volatile ("vmovdqu %0, %%ymm15" : : "m" (original_ymm) : "ymm15", "memory");
        }
        guest_write_mxcsr(original_mxcsr);
        if (child < 0) {
                fprintf(stderr, "Failed to vfork guest child: %m\n");
                return EXIT_FAILURE;
        }

        invalid = guest_vfork_child_mxcsr != guest_fpu_initial_mxcsr ||
                guest_vfork_parent_mxcsr != guest_fpu_initial_mxcsr;
        if (avx512)
                invalid = invalid ||
                        memcmp(guest_vfork_child_zmm, guest_fpu_initial_zmm, sizeof(guest_vfork_child_zmm)) != 0 ||
                        memcmp(guest_vfork_parent_zmm, guest_fpu_initial_zmm, sizeof(guest_vfork_parent_zmm)) != 0 ||
                        guest_vfork_child_k7 != guest_fpu_initial_k7 ||
                        guest_vfork_parent_k7 != guest_fpu_initial_k7;
        else
                invalid = invalid ||
                        memcmp(guest_vfork_child_ymm, guest_fpu_initial_ymm, sizeof(guest_vfork_child_ymm)) != 0 ||
                        memcmp(guest_vfork_parent_ymm, guest_fpu_initial_ymm, sizeof(guest_vfork_parent_ymm)) != 0;
        if (invalid) {
                fprintf(stderr, "Guest vfork did not preserve child/parent xstate\n");
                return EXIT_FAILURE;
        }

        if (waitpid(child, &status, 0) != child) {
                fprintf(stderr, "Failed to wait for guest child: %m\n");
                return EXIT_FAILURE;
        }
        if (!WIFEXITED(status) || WEXITSTATUS(status) != 42) {
                fprintf(stderr, "Guest child returned unexpected status %#x\n", status);
                return EXIT_FAILURE;
        }

        printf("KVM_VFORK_OK child=%ld\n", (long) child);
        return EXIT_SUCCESS;
}

static volatile int guest_fork_value = 0;

static int test_guest_fork_madvise(void) {
        long page_size;
        uint8_t *memory;
        int status;
        pid_t child;

        page_size = sysconf(_SC_PAGESIZE);
        if (page_size <= 0)
                return EXIT_FAILURE;
        memory = mmap(
                        NULL,
                        page_size * 4,
                        PROT_READ | PROT_WRITE,
                        MAP_PRIVATE | MAP_ANONYMOUS,
                        -1,
                        0);
        if (memory == MAP_FAILED)
                return EXIT_FAILURE;
        for (size_t i = 0; i < 4; i++)
                memory[i * page_size] = 0x31 + i;
        if (madvise(memory, page_size, MADV_WIPEONFORK) < 0 ||
            madvise(memory, page_size, MADV_KEEPONFORK) < 0 ||
                        madvise(memory + page_size, page_size, MADV_WIPEONFORK) < 0 ||
            madvise(memory + page_size, page_size, MADV_DONTFORK) < 0 ||
            madvise(memory + page_size * 2, page_size, MADV_WIPEONFORK) < 0 ||
            madvise(memory + page_size * 3, page_size, MADV_DONTFORK) < 0 ||
            madvise(memory + page_size * 3, page_size, MADV_DOFORK) < 0)
                return EXIT_FAILURE;

        child = fork();
        if (child < 0)
                return EXIT_FAILURE;
        if (child == 0) {
                pid_t grandchild = vfork();

                if (grandchild < 0)
                        _exit(169);
                if (grandchild == 0)
                        _exit(75);
                if (waitpid(grandchild, &status, 0) != grandchild ||
                    !WIFEXITED(status) || WEXITSTATUS(status) != 75)
                        _exit(170);
                errno = 0;
                if (mprotect(memory + page_size, page_size, PROT_READ) >= 0 || errno != ENOMEM)
                        _exit(130);
                if (mmap(
                                    memory + page_size,
                                    page_size,
                                    PROT_READ | PROT_WRITE,
                                    MAP_PRIVATE | MAP_ANONYMOUS | MAP_FIXED_NOREPLACE,
                                    -1,
                                    0) != memory + page_size)
                        _exit(131);
                memory[page_size] = 0x41;
                if (memory[0] != 0x31 || memory[page_size] != 0x41 ||
                    memory[page_size * 2] != 0 || memory[page_size * 3] != 0x34)
                        _exit(132);
                _exit(74);
        }

        if (waitpid(child, &status, 0) != child || !WIFEXITED(status) || WEXITSTATUS(status) != 74)
                return EXIT_FAILURE;
        for (size_t i = 0; i < 4; i++)
                if (memory[i * page_size] != 0x31 + i)
                        return EXIT_FAILURE;
        if (munmap(memory, page_size * 4) < 0)
                return EXIT_FAILURE;

        return EXIT_SUCCESS;
}

