static int test_guest_fork(void) {
        int status;
        pid_t child;
        _Alignas(64) uint32_t observed_zmm[16], original_zmm[16];
        _Alignas(32) uint32_t observed_ymm[8], original_ymm[8];
        uint32_t observed_mxcsr, original_mxcsr;
        uint64_t observed_k7, original_k7;
        unsigned futex_hash_slots;
        int futex_hash_supported;
        bool avx512;

        if (test_guest_tsc_fork_inheritance() != EXIT_SUCCESS) {
                fprintf(stderr, "Guest TSC mode fork inheritance failed\n");
                return EXIT_FAILURE;
        }
        if (test_guest_fork_madvise() != EXIT_SUCCESS) {
                fprintf(stderr, "Guest fork madvise inheritance failed\n");
                return EXIT_FAILURE;
        }

        futex_hash_supported = guest_futex_hash_get_slots(&futex_hash_slots);
        if (futex_hash_supported < 0 || (futex_hash_supported > 0 && futex_hash_slots != 0))
                return EXIT_FAILURE;
        if (futex_hash_supported > 0 &&
            prctl(PR_FUTEX_HASH, PR_FUTEX_HASH_SET_SLOTS, 16, 0, 0) < 0) {
                if (errno != EINVAL)
                        return EXIT_FAILURE;
                futex_hash_supported = 0;
        }

        guest_fork_value = 1;
        avx512 = guest_has_avx512();
        asm volatile ("vmovdqu %%ymm15, %0" : "=m" (original_ymm));
        original_mxcsr = guest_read_mxcsr();
        if (avx512) {
                guest_save_avx512(original_zmm, &original_k7);
                child = guest_process_create_with_avx512(
                                SYS_fork,
                                observed_zmm,
                                &observed_k7,
                                &observed_mxcsr);
                guest_restore_avx512(original_zmm, &original_k7);
                memcpy(observed_ymm, guest_fpu_initial_ymm, sizeof(observed_ymm));
        } else
                child = guest_process_create_with_fpu(SYS_fork, observed_ymm, &observed_mxcsr);
        asm volatile ("vmovdqu %0, %%ymm15" : : "m" (original_ymm) : "ymm15", "memory");
        guest_write_mxcsr(original_mxcsr);
        if (child < 0) {
                fprintf(stderr, "Failed to fork guest child: %m\n");
                return EXIT_FAILURE;
        }
        if (child == 0) {
                if (memcmp(observed_ymm, guest_fpu_initial_ymm, sizeof(observed_ymm)) != 0 ||
                                        observed_mxcsr != guest_fpu_initial_mxcsr ||
                                        (avx512 &&
                                         (memcmp(observed_zmm, guest_fpu_initial_zmm, sizeof(observed_zmm)) != 0 ||
                                          observed_k7 != guest_fpu_initial_k7)))
                        _exit(98);
                                if (futex_hash_supported > 0 &&
                                        (guest_futex_hash_get_slots(&futex_hash_slots) != 1 || futex_hash_slots != 0))
                                                _exit(96);
                                                                if (validate_guest_rseq_registration() < 0)
                                                                                                _exit(97);
                guest_fork_value = 2;
                _exit(42);
        }

        if (memcmp(observed_ymm, guest_fpu_initial_ymm, sizeof(observed_ymm)) != 0 ||
            observed_mxcsr != guest_fpu_initial_mxcsr ||
                        (avx512 &&
                         (memcmp(observed_zmm, guest_fpu_initial_zmm, sizeof(observed_zmm)) != 0 ||
                          observed_k7 != guest_fpu_initial_k7)) ||
            guest_fork_value != 1) {
                fprintf(stderr, "Guest fork did not preserve AVX/COW state\n");
                return EXIT_FAILURE;
        }
        if (waitpid(child, &status, 0) != child) {
                fprintf(stderr, "Failed to wait for fork guest child: %m\n");
                return EXIT_FAILURE;
        }
        if (!WIFEXITED(status) || WEXITSTATUS(status) != 42) {
                fprintf(stderr, "Fork guest child returned unexpected status %#x\n", status);
                return EXIT_FAILURE;
        }
        if (futex_hash_supported > 0 &&
            (guest_futex_hash_get_slots(&futex_hash_slots) != 1 || futex_hash_slots != 16)) {
                fprintf(stderr, "Guest fork changed the parent futex hash\n");
                return EXIT_FAILURE;
        }
        if (test_guest_fork_amx() != EXIT_SUCCESS) {
                fprintf(stderr, "Guest fork AMX state lifecycle failed\n");
                return EXIT_FAILURE;
        }

        printf("KVM_FORK_OK child=%ld\n", (long) child);
        return EXIT_SUCCESS;
}

static int test_guest_ioctl_denied(void) {
        int fd;

        fd = open("/dev/null", O_RDONLY|O_CLOEXEC);
        if (fd < 0) {
                fprintf(stderr, "Failed to open ioctl test target: %m\n");
                return EXIT_FAILURE;
        }

        errno = 0;
        if (ioctl(fd, _IO(KVMIO, 0xff), 0) >= 0 || errno != EPERM) {
                fprintf(stderr, "Guest KVM-typed ioctl was not denied: %m\n");
                return EXIT_FAILURE;
        }

        close(fd);
        printf("KVM_IOCTL_FILTER_OK\n");
        return EXIT_SUCCESS;
}

