static int test_guest_libc_fork(void) {
        int status;
        pid_t child;

        guest_fork_value = 1;
        child = fork();
        if (child < 0) {
                fprintf(stderr, "Failed to libc-fork guest child: %m\n");
                return EXIT_FAILURE;
        }
        if (child == 0) {
                guest_fork_value = 2;
                _exit(43);
        }

        if (guest_fork_value != 1) {
                fprintf(stderr, "Guest libc fork did not preserve COW memory\n");
                return EXIT_FAILURE;
        }
        if (waitpid(child, &status, 0) != child ||
            !WIFEXITED(status) ||
            WEXITSTATUS(status) != 43) {
                fprintf(stderr, "Libc-fork guest child returned unexpected status %#x\n", status);
                return EXIT_FAILURE;
        }

        printf("KVM_LIBC_FORK_OK child=%ld\n", (long) child);
        return EXIT_SUCCESS;
}

static int test_guest_vfork_exec(const char *self) {
        int status;
        pid_t child;

        child = vfork();
        if (child < 0) {
                fprintf(stderr, "Failed to vfork exec guest child: %m\n");
                return EXIT_FAILURE;
        }
        if (child == 0) {
                execl(self, self, "--guest-vfork-exec-child", NULL);
                _exit(127);
        }

        if (waitpid(child, &status, 0) != child) {
                fprintf(stderr, "Failed to wait for exec guest child: %m\n");
                return EXIT_FAILURE;
        }
        if (!WIFEXITED(status) || WEXITSTATUS(status) != 23) {
                fprintf(stderr, "Exec guest child returned unexpected status %#x\n", status);
                return EXIT_FAILURE;
        }

        printf("KVM_VFORK_EXEC_OK child=%ld\n", (long) child);
        return EXIT_SUCCESS;
}

