        static const uint64_t openat2_user_data = UINT64_C(0x4b564d494f464f50);
        static const char payload[] = "KVM_IO_URING_PAYLOAD";
        static const uint64_t buffer_update_user_data = UINT64_C(0x4b564d494f554255);
        static const uint64_t cancel_target_user_data = UINT64_C(0x4b564d494f554354);
        static const uint64_t cancel_user_data = UINT64_C(0x4b564d494f554343);
        static const char multishot_payloads[2][16] = { "KVM_MULTI_ONE", "KVM_MULTI_TWO" };
        static const uint16_t multishot_buffer_group = 8;
        static const uint16_t multishot_buffer_id = 30;
        static const uint64_t multishot_provide_user_data = UINT64_C(0x4b564d494f4d5042);
        static const uint64_t multishot_receive_user_data = UINT64_C(0x4b564d494f4d5256);
        static const uint64_t nop_user_data = UINT64_C(0x4b564d494f554e50);
        static const uint16_t pbuf_buffer_group = 9;
        static const uint16_t pbuf_buffer_id = 41;
        static const uint64_t pbuf_receive_user_data = UINT64_C(0x4b564d494f505252);
        static const uint64_t poll_remove_user_data = UINT64_C(0x4b564d494f50524d);
        static const uint64_t poll_user_data = UINT64_C(0x4b564d494f504f4c);
        static const uint64_t provide_user_data = UINT64_C(0x4b564d494f555042);
        static const uint64_t read_user_data = UINT64_C(0x4b564d494f555252);
        static const uint64_t registered_ring_user_data = UINT64_C(0x4b564d494f555247);
        static const uint64_t remove_user_data = UINT64_C(0x4b564d494f555242);
        static const char socket_payload[] = "KVM_IO_URING_SOCKET";
        static const uint16_t provided_buffer_group = 7;
        static const uint16_t provided_buffer_id = 19;
        static const uint64_t socket_receive_user_data = UINT64_C(0x4b564d494f555352);
        static const uint64_t socket_send_user_data = UINT64_C(0x4b564d494f555353);
