static int guest_clone_thread_main(void *userdata) {
        GuestCloneThreadContext *context = userdata;
        struct sched_param parameter;

        context->tid_matches = context->child_tid == syscall(SYS_gettid);
        context->tls_matches = __builtin_thread_pointer() == context->expected_tls;
        context->scheduler_matches = sched_getscheduler(0) == context->expected_scheduler;
        context->priority_matches = sched_getparam(0, &parameter) >= 0 &&
                                    parameter.sched_priority == context->expected_priority;
        parameter = (struct sched_param) {};
        context->scheduler_change_matches = sched_setscheduler(0, SCHED_BATCH, &parameter) >= 0 &&
                                            sched_getscheduler(0) == SCHED_BATCH;
        __atomic_store_n(&context->done, 1, __ATOMIC_RELEASE);
        return 0;
}
