static int validate_guest_file_lease_exec(void) {
        char path[PATH_MAX];

        if (snprintf(path, sizeof(path), "/tmp/kvm-lease-exec-%ld", (long) getpid()) >= (int) sizeof(path) ||
            fcntl(GUEST_LEASE_FD, F_GETLEASE) != F_WRLCK ||
            fcntl(GUEST_LEASE_FD, F_SETLEASE, F_UNLCK) < 0 || close(GUEST_LEASE_FD) < 0 ||
            unlink(path) < 0)
                return EXIT_FAILURE;

        printf("KVM_FILE_LEASE_OK\n");
        return EXIT_SUCCESS;
}

static int run_guest_file_lease_exec(const char *self) {
        char path[PATH_MAX];
        int fd = -1, status;
        pid_t child;

        if (snprintf(path, sizeof(path), "/tmp/kvm-lease-exec-%ld", (long) getpid()) >= (int) sizeof(path))
                return -EOVERFLOW;
        fd = open(path, O_CREAT | O_EXCL | O_RDWR, 0600);
        if (fd < 0)
                goto fail;
        if (fd != GUEST_LEASE_FD) {
                if (dup2(fd, GUEST_LEASE_FD) != GUEST_LEASE_FD || close(fd) < 0)
                        goto fail;
                fd = GUEST_LEASE_FD;
        }
        errno = 0;
        if (fcntl(fd, F_SETLEASE, INT_MAX) >= 0 || errno != EINVAL ||
            fcntl(fd, F_SETLEASE, F_WRLCK) < 0 || fcntl(fd, F_GETLEASE) != F_WRLCK)
                goto fail;

        child = fork();
        if (child < 0)
                goto fail;
        if (child == 0)
                _exit(fcntl(fd, F_GETLEASE) == F_WRLCK ? 0 : 145);
        if (waitpid(child, &status, 0) != child ||
            !WIFEXITED(status) || WEXITSTATUS(status) != 0 || fcntl(fd, F_GETLEASE) != F_WRLCK)
                goto fail;

        execl(self, self, "--guest-exec-target", "--expect-file-lease", NULL);
fail:
        if (fd >= 0) {
                (void) fcntl(fd, F_SETLEASE, F_UNLCK);
                close(fd);
        }
        unlink(path);
        return -EPROTO;
}

static int wait_guest_dnotify_signal(void) {
        const struct timespec timeout = {
                .tv_sec = 5,
        };
        sigset_t mask;
        siginfo_t info;

        if (sigemptyset(&mask) < 0 || sigaddset(&mask, SIGUSR1) < 0)
                return -errno;
        if (sigtimedwait(&mask, &info, &timeout) != SIGUSR1 ||
            info.si_code != POLL_MSG || info.si_fd != GUEST_DNOTIFY_FD)
                return -EPROTO;
        return 0;
}

static int create_guest_dnotify_file(const char *path, const char *name) {
        char file_path[PATH_MAX];
        int fd;

        if (snprintf(file_path, sizeof(file_path), "%s/%s", path, name) >= (int) sizeof(file_path))
                return -EOVERFLOW;
        fd = open(file_path, O_CREAT | O_EXCL | O_WRONLY, 0600);
        if (fd < 0)
                return -errno;
        return close(fd) < 0 ? -errno : 0;
}

static int cleanup_guest_dnotify_path(const char *path) {
        static const char *const names[] = { "fork", "exec" };
        char file_path[PATH_MAX];

        for (size_t i = 0; i < sizeof(names) / sizeof(names[0]); i++) {
                if (snprintf(file_path, sizeof(file_path), "%s/%s", path, names[i]) >=
                    (int) sizeof(file_path))
                        return -EOVERFLOW;
                if (unlink(file_path) < 0 && errno != ENOENT)
                        return -errno;
        }
        return rmdir(path) < 0 ? -errno : 0;
}

static int validate_guest_dnotify_exec(void) {
        char path[PATH_MAX];
        sigset_t mask;

        if (snprintf(path, sizeof(path), "/tmp/kvm-dnotify-exec-%ld", (long) getpid()) >= (int) sizeof(path) ||
            create_guest_dnotify_file(path, "exec") < 0 || wait_guest_dnotify_signal() < 0 ||
            fcntl(GUEST_DNOTIFY_FD, F_NOTIFY, 0) < 0 || close(GUEST_DNOTIFY_FD) < 0 ||
            sigemptyset(&mask) < 0 || sigaddset(&mask, SIGUSR1) < 0 ||
            pthread_sigmask(SIG_UNBLOCK, &mask, NULL) != 0 || cleanup_guest_dnotify_path(path) < 0)
                return EXIT_FAILURE;

        printf("KVM_DNOTIFY_OK\n");
        return EXIT_SUCCESS;
}

static int run_guest_dnotify_exec(const char *self) {
        char path[PATH_MAX];
        sigset_t mask, old_mask;
        int fd = -1, status;
        bool mask_set = false;
        pid_t child;

        if (snprintf(path, sizeof(path), "/tmp/kvm-dnotify-exec-%ld", (long) getpid()) >= (int) sizeof(path) ||
            mkdir(path, 0700) < 0 || sigemptyset(&mask) < 0 || sigaddset(&mask, SIGUSR1) < 0 ||
            pthread_sigmask(SIG_BLOCK, &mask, &old_mask) != 0)
                goto fail;
        mask_set = true;
        fd = open(path, O_RDONLY | O_DIRECTORY);
        if (fd < 0)
                goto fail;
        if (fd != GUEST_DNOTIFY_FD) {
                if (dup2(fd, GUEST_DNOTIFY_FD) != GUEST_DNOTIFY_FD || close(fd) < 0)
                        goto fail;
                fd = GUEST_DNOTIFY_FD;
        }
        if (fcntl(fd, F_SETOWN, getpid()) < 0 || fcntl(fd, F_SETSIG, SIGUSR1) < 0 ||
            fcntl(fd, F_NOTIFY, DN_CREATE | DN_MULTISHOT) < 0)
                goto fail;

        child = fork();
        if (child < 0)
                goto fail;
        if (child == 0)
                _exit(create_guest_dnotify_file(path, "fork") < 0 ? 146 : 0);
        if (wait_guest_dnotify_signal() < 0 || waitpid(child, &status, 0) != child ||
            !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                goto fail;

        execl(self, self, "--guest-exec-target", "--expect-dnotify", NULL);
fail:
        if (fd >= 0) {
                (void) fcntl(fd, F_NOTIFY, 0);
                close(fd);
        }
        if (mask_set)
                pthread_sigmask(SIG_SETMASK, &old_mask, NULL);
        cleanup_guest_dnotify_path(path);
        return -EPROTO;
}

static int test_guest_fcntl_notification_exec(const char *self) {
        int status;

        for (unsigned test = 0; test < 2; test++) {
                pid_t child = fork();

                if (child < 0)
                        return EXIT_FAILURE;
                if (child == 0)
                        _exit((test == 0 ?
                                       run_guest_file_lease_exec(self) :
                                       run_guest_dnotify_exec(self)) < 0 ? 147 : 0);
                if (waitpid(child, &status, 0) != child ||
                    !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                        return EXIT_FAILURE;
        }

        return EXIT_SUCCESS;
}

static int wait_guest_async_io_signal(void) {
        const struct timespec timeout = {
                .tv_sec = 5,
        };
        sigset_t mask;
        siginfo_t info;

        if (sigemptyset(&mask) < 0 || sigaddset(&mask, SIGUSR2) < 0)
                return -errno;
        if (sigtimedwait(&mask, &info, &timeout) != SIGUSR2 ||
            info.si_code != POLL_IN || info.si_fd != GUEST_ASYNC_READ_FD ||
            (info.si_band & POLLIN) == 0)
                return -EPROTO;
        return 0;
}

static int validate_guest_async_io_exec(void) {
        struct f_owner_ex owner = {};
        char byte;
        sigset_t mask;
        int flags;

        flags = fcntl(GUEST_ASYNC_READ_FD, F_GETFL);
        if (flags < 0 || (flags & (O_ASYNC | O_NONBLOCK)) != (O_ASYNC | O_NONBLOCK) ||
            (fcntl(GUEST_ASYNC_READ_FD, F_GETFD) & FD_CLOEXEC) != 0 ||
            (fcntl(GUEST_ASYNC_WRITE_FD, F_GETFD) & FD_CLOEXEC) != 0 ||
            fcntl(GUEST_ASYNC_READ_FD, F_GETOWN) != getpid() ||
            fcntl(GUEST_ASYNC_READ_FD, F_GETOWN_EX, &owner) < 0 ||
            owner.type != F_OWNER_PID || owner.pid != getpid() ||
            fcntl(GUEST_ASYNC_READ_FD, F_GETSIG) != SIGUSR2 ||
            write(GUEST_ASYNC_WRITE_FD, "e", 1) != 1 || wait_guest_async_io_signal() < 0 ||
            read(GUEST_ASYNC_READ_FD, &byte, 1) != 1 || byte != 'e' ||
            fcntl(GUEST_ASYNC_READ_FD, F_SETFL, flags & ~O_ASYNC) < 0 ||
            fcntl(GUEST_ASYNC_READ_FD, F_SETOWN, 0) < 0 || close(GUEST_ASYNC_READ_FD) < 0 ||
            close(GUEST_ASYNC_WRITE_FD) < 0 || sigemptyset(&mask) < 0 || sigaddset(&mask, SIGUSR2) < 0 ||
            pthread_sigmask(SIG_UNBLOCK, &mask, NULL) != 0)
                return EXIT_FAILURE;

        printf("KVM_ASYNC_IO_OK\n");
        return EXIT_SUCCESS;
}

static int run_guest_async_io_exec(const char *self) {
        struct f_owner_ex invalid_owner = {
                .type = INT_MAX,
                .pid = getpid(),
        };
        struct f_owner_ex owner = {
                .type = F_OWNER_PID,
                .pid = getpid(),
        };
        struct f_owner_ex inherited_owner = {};
        int pipe_fds[2] = { -1, -1 };
        sigset_t mask, old_mask;
        bool fixed_fds = false, mask_set = false;
        char byte;
        int flags, status;
        pid_t child;

        if (sigemptyset(&mask) < 0 || sigaddset(&mask, SIGUSR2) < 0 ||
            pthread_sigmask(SIG_BLOCK, &mask, &old_mask) != 0)
                goto fail;
        mask_set = true;
        if (pipe2(pipe_fds, O_NONBLOCK) < 0 ||
            dup2(pipe_fds[0], GUEST_ASYNC_READ_FD) != GUEST_ASYNC_READ_FD ||
            dup2(pipe_fds[1], GUEST_ASYNC_WRITE_FD) != GUEST_ASYNC_WRITE_FD)
                goto fail;
        fixed_fds = true;
        if (close(pipe_fds[0]) < 0 || close(pipe_fds[1]) < 0)
                goto fail;
        pipe_fds[0] = pipe_fds[1] = -1;

        errno = 0;
        if (fcntl(GUEST_ASYNC_READ_FD, F_SETOWN_EX, &invalid_owner) >= 0 || errno != EINVAL)
                goto fail;
        errno = 0;
        if (fcntl(GUEST_ASYNC_READ_FD, F_SETSIG, NSIG) >= 0 || errno != EINVAL ||
            fcntl(GUEST_ASYNC_READ_FD, F_SETOWN, getpid()) < 0 ||
            fcntl(GUEST_ASYNC_READ_FD, F_GETOWN) != getpid() ||
            fcntl(GUEST_ASYNC_READ_FD, F_SETOWN_EX, &owner) < 0 ||
            fcntl(GUEST_ASYNC_READ_FD, F_SETSIG, SIGUSR2) < 0 ||
            fcntl(GUEST_ASYNC_READ_FD, F_GETSIG) != SIGUSR2)
                goto fail;
        flags = fcntl(GUEST_ASYNC_READ_FD, F_GETFL);
        if (flags < 0 || fcntl(GUEST_ASYNC_READ_FD, F_SETFL, flags | O_ASYNC | O_NONBLOCK) < 0)
                goto fail;

        child = fork();
        if (child < 0)
                goto fail;
        if (child == 0) {
                int child_flags = fcntl(GUEST_ASYNC_READ_FD, F_GETFL);

                if (fcntl(GUEST_ASYNC_READ_FD, F_GETOWN_EX, &inherited_owner) < 0 ||
                    inherited_owner.type != F_OWNER_PID || inherited_owner.pid != getppid() ||
                    fcntl(GUEST_ASYNC_READ_FD, F_GETSIG) != SIGUSR2 ||
                    child_flags < 0 ||
                    (child_flags & (O_ASYNC | O_NONBLOCK)) != (O_ASYNC | O_NONBLOCK) ||
                    write(GUEST_ASYNC_WRITE_FD, "f", 1) != 1)
                        _exit(152);
                _exit(0);
        }
        if (wait_guest_async_io_signal() < 0 || waitpid(child, &status, 0) != child ||
            !WIFEXITED(status) || WEXITSTATUS(status) != 0 ||
            read(GUEST_ASYNC_READ_FD, &byte, 1) != 1 || byte != 'f')
                goto fail;

        execl(self, self, "--guest-exec-target", "--expect-async-io", NULL);
fail:
        if (fixed_fds) {
                flags = fcntl(GUEST_ASYNC_READ_FD, F_GETFL);
                if (flags >= 0)
                        (void) fcntl(GUEST_ASYNC_READ_FD, F_SETFL, flags & ~O_ASYNC);
                close(GUEST_ASYNC_READ_FD);
                close(GUEST_ASYNC_WRITE_FD);
        }
        if (pipe_fds[0] >= 0)
                close(pipe_fds[0]);
        if (pipe_fds[1] >= 0)
                close(pipe_fds[1]);
        if (mask_set)
                pthread_sigmask(SIG_SETMASK, &old_mask, NULL);
        return -EPROTO;
}

static int test_guest_async_io_exec(const char *self) {
        int status;
        pid_t child;

        child = fork();
        if (child < 0)
                return EXIT_FAILURE;
        if (child == 0)
                _exit(run_guest_async_io_exec(self) < 0 ? 153 : 0);
        if (waitpid(child, &status, 0) != child ||
            !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                return EXIT_FAILURE;
        return EXIT_SUCCESS;
}

static int make_guest_rw_hint_path(char path[static PATH_MAX]) {
        return snprintf(path, PATH_MAX, "/tmp/kvm-rw-hint-%ld", (long) getpid()) < PATH_MAX ?
                0 : -EOVERFLOW;
}

static int validate_guest_pipe_rw_hint_exec(void) {
        char path[PATH_MAX], byte, *buffer = NULL;
        uint64_t hint = RWH_WRITE_LIFE_NOT_SET;
        int available, independent_fd = -1, result = EXIT_FAILURE;
        long page_size;

        page_size = sysconf(_SC_PAGESIZE);
        if (page_size <= 0 || page_size > INT_MAX || make_guest_rw_hint_path(path) < 0)
                goto finish;
        buffer = malloc((size_t) page_size);
        if (!buffer)
                goto finish;

        if ((fcntl(GUEST_PIPE_READ_FD, F_GETFD) & FD_CLOEXEC) != 0 ||
            (fcntl(GUEST_PIPE_WRITE_FD, F_GETFD) & FD_CLOEXEC) != 0 ||
            (fcntl(GUEST_RW_HINT_FD, F_GETFD) & FD_CLOEXEC) != 0 ||
            fcntl(GUEST_PIPE_READ_FD, F_GETPIPE_SZ) != page_size ||
            fcntl(GUEST_PIPE_WRITE_FD, F_GETPIPE_SZ) != page_size ||
            ioctl(GUEST_PIPE_READ_FD, FIONREAD, &available) < 0 || available != page_size ||
            read(GUEST_PIPE_READ_FD, buffer, (size_t) page_size) != page_size)
                goto finish;
        for (long i = 0; i < page_size; i++)
                if (buffer[i] != 'p')
                        goto finish;
        if (write(GUEST_PIPE_WRITE_FD, "e", 1) != 1 ||
            read(GUEST_PIPE_READ_FD, &byte, 1) != 1 || byte != 'e' ||
            fcntl(GUEST_RW_HINT_FD, F_GET_RW_HINT, &hint) < 0 || hint != RWH_WRITE_LIFE_SHORT)
                goto finish;

        independent_fd = open(path, O_RDONLY);
        hint = RWH_WRITE_LIFE_NOT_SET;
        if (independent_fd < 0 || fcntl(independent_fd, F_GET_RW_HINT, &hint) < 0 ||
            hint != RWH_WRITE_LIFE_SHORT)
                goto finish;

        hint = RWH_WRITE_LIFE_NOT_SET;
        if (fcntl(GUEST_RW_HINT_FD, F_SET_RW_HINT, &hint) < 0)
                goto finish;
        result = EXIT_SUCCESS;

finish:
        if (independent_fd >= 0 && close(independent_fd) < 0)
                result = EXIT_FAILURE;
        if (close(GUEST_PIPE_READ_FD) < 0 || close(GUEST_PIPE_WRITE_FD) < 0 ||
            close(GUEST_RW_HINT_FD) < 0)
                result = EXIT_FAILURE;
        if (make_guest_rw_hint_path(path) < 0 || (unlink(path) < 0 && errno != ENOENT))
                result = EXIT_FAILURE;
        free(buffer);
        if (result == EXIT_SUCCESS)
                printf("KVM_PIPE_RW_HINT_OK\n");
        return result;
}

static int run_guest_pipe_rw_hint_exec(const char *self) {
        char path[PATH_MAX] = {}, *buffer = NULL;
        uint64_t hint, invalid_hint = RWH_WRITE_LIFE_EXTREME + 1;
        int available, file_fd = -1, pipe_fds[2] = { -1, -1 }, status;
        bool fixed_file = false, fixed_pipe = false;
        long page_size;
        pid_t child;

        page_size = sysconf(_SC_PAGESIZE);
        if (page_size <= 0 || page_size > INT_MAX || make_guest_rw_hint_path(path) < 0)
                goto fail;
        buffer = malloc((size_t) page_size);
        if (!buffer)
                goto fail;
        memset(buffer, 'p', (size_t) page_size);

        if (pipe2(pipe_fds, O_NONBLOCK) < 0 ||
            dup2(pipe_fds[0], GUEST_PIPE_READ_FD) != GUEST_PIPE_READ_FD ||
            dup2(pipe_fds[1], GUEST_PIPE_WRITE_FD) != GUEST_PIPE_WRITE_FD)
                goto fail;
        fixed_pipe = true;
        if (close(pipe_fds[0]) < 0 || close(pipe_fds[1]) < 0)
                goto fail;
        pipe_fds[0] = pipe_fds[1] = -1;

        errno = 0;
        if (fcntl(GUEST_PIPE_READ_FD, F_SETPIPE_SZ, -1) >= 0 || errno != EINVAL ||
            fcntl(GUEST_PIPE_READ_FD, F_SETPIPE_SZ, (int) page_size) != page_size ||
            fcntl(GUEST_PIPE_READ_FD, F_GETPIPE_SZ) != page_size ||
            fcntl(GUEST_PIPE_WRITE_FD, F_GETPIPE_SZ) != page_size ||
            write(GUEST_PIPE_WRITE_FD, buffer, (size_t) page_size) != page_size)
                goto fail;
        errno = 0;
        if (write(GUEST_PIPE_WRITE_FD, "x", 1) >= 0 || errno != EAGAIN ||
            ioctl(GUEST_PIPE_READ_FD, FIONREAD, &available) < 0 || available != page_size)
                goto fail;

        file_fd = open(path, O_CREAT | O_EXCL | O_RDWR, 0600);
        if (file_fd < 0)
                goto fail;
        if (file_fd != GUEST_RW_HINT_FD) {
                if (dup2(file_fd, GUEST_RW_HINT_FD) != GUEST_RW_HINT_FD || close(file_fd) < 0)
                        goto fail;
                file_fd = GUEST_RW_HINT_FD;
        }
        fixed_file = true;

        hint = UINT64_MAX;
        if (fcntl(file_fd, F_GET_RW_HINT, &hint) < 0 || hint != RWH_WRITE_LIFE_NOT_SET)
                goto fail;
        errno = 0;
        if (fcntl(file_fd, F_SET_RW_HINT, &invalid_hint) >= 0 || errno != EINVAL)
                goto fail;
        errno = 0;
        if (fcntl(file_fd, F_GET_FILE_RW_HINT, &hint) >= 0 || errno != EINVAL)
                goto fail;
        errno = 0;
        if (fcntl(file_fd, F_SET_FILE_RW_HINT, &hint) >= 0 || errno != EINVAL)
                goto fail;
        hint = RWH_WRITE_LIFE_SHORT;
        if (fcntl(file_fd, F_SET_RW_HINT, &hint) < 0 ||
            fcntl(file_fd, F_GET_RW_HINT, &hint) < 0 || hint != RWH_WRITE_LIFE_SHORT)
                goto fail;

        child = fork();
        if (child < 0)
                goto fail;
        if (child == 0) {
                uint64_t child_hint = RWH_WRITE_LIFE_NOT_SET;
                int child_available, child_fd;

                if (fcntl(GUEST_PIPE_READ_FD, F_GETPIPE_SZ) != page_size ||
                    fcntl(GUEST_PIPE_WRITE_FD, F_GETPIPE_SZ) != page_size ||
                    ioctl(GUEST_PIPE_READ_FD, FIONREAD, &child_available) < 0 ||
                    child_available != page_size ||
                    fcntl(GUEST_RW_HINT_FD, F_GET_RW_HINT, &child_hint) < 0 ||
                    child_hint != RWH_WRITE_LIFE_SHORT)
                        _exit(154);
                child_fd = open(path, O_RDONLY);
                child_hint = RWH_WRITE_LIFE_NOT_SET;
                if (child_fd < 0 || fcntl(child_fd, F_GET_RW_HINT, &child_hint) < 0 ||
                    child_hint != RWH_WRITE_LIFE_SHORT || close(child_fd) < 0)
                        _exit(154);
                _exit(0);
        }
        if (waitpid(child, &status, 0) != child ||
            !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                goto fail;

        free(buffer);
        buffer = NULL;
        execl(self, self, "--guest-exec-target", "--expect-pipe-rw-hint", NULL);
fail:
        if (fixed_pipe) {
                close(GUEST_PIPE_READ_FD);
                close(GUEST_PIPE_WRITE_FD);
        }
        if (pipe_fds[0] >= 0)
                close(pipe_fds[0]);
        if (pipe_fds[1] >= 0)
                close(pipe_fds[1]);
        if (fixed_file)
                close(GUEST_RW_HINT_FD);
        else if (file_fd >= 0)
                close(file_fd);
        if (path[0] != 0)
                unlink(path);
        free(buffer);
        return -EPROTO;
}

static int test_guest_pipe_rw_hint_exec(const char *self) {
        int status;
        pid_t child;

        child = fork();
        if (child < 0)
                return EXIT_FAILURE;
        if (child == 0)
                _exit(run_guest_pipe_rw_hint_exec(self) < 0 ? 155 : 0);
        if (waitpid(child, &status, 0) != child ||
            !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                return EXIT_FAILURE;
        return EXIT_SUCCESS;
}

static int make_guest_fcntl_metadata_path(char path[static PATH_MAX]) {
        return snprintf(path, PATH_MAX, "/tmp/kvm-fcntl-metadata-%ld", (long) getpid()) < PATH_MAX ?
                0 : -EOVERFLOW;
}

static int check_guest_fcntl_metadata(pid_t owner_pid) {
        uid_t owner_uids[2] = { (uid_t) -1, (uid_t) -1 };
        int r;

        errno = 0;
        r = fcntl(GUEST_CREATED_FD, F_CREATED_QUERY, 0);
        if (r < 0) {
                if (errno != EINVAL)
                        return -EPROTO;
                errno = 0;
                if (fcntl(GUEST_DUPLICATE_FD, F_CREATED_QUERY, 0) >= 0 || errno != EINVAL)
                        return -EPROTO;
                errno = 0;
                if (fcntl(GUEST_REOPENED_FD, F_CREATED_QUERY, 0) >= 0 || errno != EINVAL)
                        return -EPROTO;
        } else if (r != 1 || fcntl(GUEST_DUPLICATE_FD, F_CREATED_QUERY, 0) != 1 ||
                   fcntl(GUEST_REOPENED_FD, F_CREATED_QUERY, 0) != 0)
                return -EPROTO;

        errno = 0;
        r = fcntl(GUEST_CREATED_FD, F_DUPFD_QUERY, GUEST_DUPLICATE_FD);
        if (r < 0) {
                if (errno != EINVAL)
                        return -EPROTO;
                errno = 0;
                if (fcntl(GUEST_CREATED_FD, F_DUPFD_QUERY, GUEST_REOPENED_FD) >= 0 || errno != EINVAL)
                        return -EPROTO;
        } else {
                if (r != 1 || fcntl(GUEST_CREATED_FD, F_DUPFD_QUERY, GUEST_REOPENED_FD) != 0)
                        return -EPROTO;
                errno = 0;
                if (fcntl(GUEST_CREATED_FD, F_DUPFD_QUERY, INT_MAX) >= 0 || errno != EBADF)
                        return -EPROTO;
        }

        errno = 0;
        r = fcntl(GUEST_CREATED_FD, F_GETOWNER_UIDS, owner_uids);
        if (r < 0) {
                if (errno != EINVAL)
                        return -EPROTO;
                errno = 0;
                if (fcntl(GUEST_DUPLICATE_FD, F_GETOWNER_UIDS, owner_uids) >= 0 || errno != EINVAL)
                        return -EPROTO;
        } else {
                if (r != 0 || owner_uids[0] != getuid() || owner_uids[1] != geteuid())
                        return -EPROTO;
                owner_uids[0] = owner_uids[1] = (uid_t) -1;
                if (fcntl(GUEST_DUPLICATE_FD, F_GETOWNER_UIDS, owner_uids) < 0 ||
                    owner_uids[0] != getuid() || owner_uids[1] != geteuid())
                        return -EPROTO;
                owner_uids[0] = owner_uids[1] = (uid_t) -1;
                if (fcntl(GUEST_REOPENED_FD, F_GETOWNER_UIDS, owner_uids) < 0 ||
                    owner_uids[0] != 0 || owner_uids[1] != 0)
                        return -EPROTO;
        }

        if (fcntl(GUEST_CREATED_FD, F_GETOWN) != owner_pid ||
            fcntl(GUEST_DUPLICATE_FD, F_GETOWN) != owner_pid ||
            fcntl(GUEST_REOPENED_FD, F_GETOWN) != 0)
                return -EPROTO;
        return 0;
}

static int cleanup_guest_fcntl_metadata(void) {
        char path[PATH_MAX];
        int result = 0;

        if (close(GUEST_CREATED_FD) < 0)
                result = -errno;
        if (close(GUEST_DUPLICATE_FD) < 0)
                result = -errno;
        if (close(GUEST_REOPENED_FD) < 0)
                result = -errno;
        if (make_guest_fcntl_metadata_path(path) < 0)
                result = -EOVERFLOW;
        else if (unlink(path) < 0 && errno != ENOENT)
                result = -errno;
        return result;
}

static int validate_guest_fcntl_metadata_exec(void) {
        int result = EXIT_FAILURE;

        if ((fcntl(GUEST_CREATED_FD, F_GETFD) & FD_CLOEXEC) != 0 ||
            (fcntl(GUEST_DUPLICATE_FD, F_GETFD) & FD_CLOEXEC) != 0 ||
            (fcntl(GUEST_REOPENED_FD, F_GETFD) & FD_CLOEXEC) != 0 ||
            check_guest_fcntl_metadata(getpid()) < 0 ||
            fcntl(GUEST_CREATED_FD, F_SETOWN, 0) < 0)
                goto finish;
        result = EXIT_SUCCESS;

finish:
        if (cleanup_guest_fcntl_metadata() < 0)
                result = EXIT_FAILURE;
        if (result == EXIT_SUCCESS)
                printf("KVM_FCNTL_METADATA_OK\n");
        return result;
}

static int run_guest_fcntl_metadata_exec(const char *self) {
        char path[PATH_MAX] = {};
        int fd = -1, reopened_fd = -1, status;
        bool fixed_fds = false;
        pid_t child;

        if (make_guest_fcntl_metadata_path(path) < 0)
                goto fail;
        fd = open(path, O_CREAT | O_EXCL | O_RDWR, 0600);
        if (fd < 0)
                goto fail;
        if (fd != GUEST_CREATED_FD) {
                if (dup2(fd, GUEST_CREATED_FD) != GUEST_CREATED_FD || close(fd) < 0)
                        goto fail;
                fd = GUEST_CREATED_FD;
        }
        if (dup2(fd, GUEST_DUPLICATE_FD) != GUEST_DUPLICATE_FD)
                goto fail;
        reopened_fd = open(path, O_RDWR);
        if (reopened_fd < 0)
                goto fail;
        if (reopened_fd != GUEST_REOPENED_FD) {
                if (dup2(reopened_fd, GUEST_REOPENED_FD) != GUEST_REOPENED_FD || close(reopened_fd) < 0)
                        goto fail;
                reopened_fd = GUEST_REOPENED_FD;
        }
        fixed_fds = true;

        if (fcntl(GUEST_CREATED_FD, F_SETOWN, getpid()) < 0 ||
            check_guest_fcntl_metadata(getpid()) < 0)
                goto fail;

        child = fork();
        if (child < 0)
                goto fail;
        if (child == 0)
                _exit(check_guest_fcntl_metadata(getppid()) < 0 ? 156 : 0);
        if (waitpid(child, &status, 0) != child ||
            !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                goto fail;

        execl(self, self, "--guest-exec-target", "--expect-fcntl-metadata", NULL);
fail:
        if (fixed_fds)
                cleanup_guest_fcntl_metadata();
        else {
                if (fd >= 0)
                        close(fd);
                if (reopened_fd >= 0)
                        close(reopened_fd);
                if (path[0] != 0)
                        unlink(path);
        }
        return -EPROTO;
}

static int test_guest_fcntl_metadata_exec(const char *self) {
        int status;
        pid_t child;

        child = fork();
        if (child < 0)
                return EXIT_FAILURE;
        if (child == 0)
                _exit(run_guest_fcntl_metadata_exec(self) < 0 ? 157 : 0);
        if (waitpid(child, &status, 0) != child ||
            !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                return EXIT_FAILURE;
        return EXIT_SUCCESS;
}

enum {
        GUEST_OFD_CONCURRENT_WRITES = 64,
};

static int make_guest_open_description_path(char path[static PATH_MAX]) {
        return snprintf(path, PATH_MAX, "/tmp/kvm-open-description-%ld", (long) getpid()) < PATH_MAX ?
                0 : -EOVERFLOW;
}

static int check_guest_open_description(off_t shared_offset, off_t reopened_offset, int expected_flags) {
        static const int shared_fds[] = {
                GUEST_OFD_ORIGINAL_FD,
                GUEST_OFD_DUPLICATE_FD,
                GUEST_OFD_SCM_FD,
        };
        struct stat expected_stat, reopened_stat;
        int flags, r;

        if (fstat(GUEST_OFD_ORIGINAL_FD, &expected_stat) < 0)
                return -errno;
        for (size_t i = 0; i < sizeof(shared_fds) / sizeof(shared_fds[0]); i++) {
                struct stat stat_buffer;
                int flags;

                if (lseek(shared_fds[i], 0, SEEK_CUR) != shared_offset ||
                    fstat(shared_fds[i], &stat_buffer) < 0 ||
                    stat_buffer.st_dev != expected_stat.st_dev || stat_buffer.st_ino != expected_stat.st_ino)
                        return -EPROTO;
                flags = fcntl(shared_fds[i], F_GETFL);
                if (flags < 0 || (flags & (O_APPEND | O_NONBLOCK)) != expected_flags)
                        return -EPROTO;
        }

        flags = fcntl(GUEST_OFD_REOPENED_FD, F_GETFL);
        if (flags < 0 || (flags & (O_APPEND | O_NONBLOCK)) != 0 ||
            lseek(GUEST_OFD_REOPENED_FD, 0, SEEK_CUR) != reopened_offset ||
            fstat(GUEST_OFD_REOPENED_FD, &reopened_stat) < 0 ||
            reopened_stat.st_dev != expected_stat.st_dev || reopened_stat.st_ino != expected_stat.st_ino)
                return -EPROTO;

        errno = 0;
        r = fcntl(GUEST_OFD_ORIGINAL_FD, F_DUPFD_QUERY, GUEST_OFD_DUPLICATE_FD);
        if (r < 0) {
                if (errno != EINVAL)
                        return -EPROTO;
                errno = 0;
                if (fcntl(GUEST_OFD_ORIGINAL_FD, F_DUPFD_QUERY, GUEST_OFD_SCM_FD) >= 0 || errno != EINVAL)
                        return -EPROTO;
        } else if (r != 1 || fcntl(GUEST_OFD_ORIGINAL_FD, F_DUPFD_QUERY, GUEST_OFD_SCM_FD) != 1 ||
                   fcntl(GUEST_OFD_ORIGINAL_FD, F_DUPFD_QUERY, GUEST_OFD_REOPENED_FD) != 0)
                return -EPROTO;
        return 0;
}

static int cleanup_guest_open_description(void) {
        static const int fds[] = {
                GUEST_OFD_ORIGINAL_FD,
                GUEST_OFD_DUPLICATE_FD,
                GUEST_OFD_REOPENED_FD,
                GUEST_OFD_SCM_FD,
                GUEST_OFD_CLOEXEC_FD,
        };
        char path[PATH_MAX];
        int result = 0;

        for (size_t i = 0; i < sizeof(fds) / sizeof(fds[0]); i++)
                if (close(fds[i]) < 0 && errno != EBADF)
                        result = -errno;
        if (make_guest_open_description_path(path) < 0)
                result = -EOVERFLOW;
        else if (unlink(path) < 0 && errno != ENOENT)
                result = -errno;
        return result;
}

static int validate_guest_open_description_exec(void) {
        static const char initial[] = "abcdef";
        const off_t concurrent_size = sizeof(initial) - 1 + 2 * GUEST_OFD_CONCURRENT_WRITES;
        char appended, byte;
        struct stat stat_buffer;
        int flags, result = EXIT_FAILURE;

        if ((fcntl(GUEST_OFD_ORIGINAL_FD, F_GETFD) & FD_CLOEXEC) != 0 ||
            (fcntl(GUEST_OFD_DUPLICATE_FD, F_GETFD) & FD_CLOEXEC) != 0 ||
            (fcntl(GUEST_OFD_REOPENED_FD, F_GETFD) & FD_CLOEXEC) != 0 ||
            (fcntl(GUEST_OFD_SCM_FD, F_GETFD) & FD_CLOEXEC) != 0)
                goto finish;
        errno = 0;
        if (fcntl(GUEST_OFD_CLOEXEC_FD, F_GETFD) >= 0 || errno != EBADF ||
            check_guest_open_description(4, 1, O_APPEND | O_NONBLOCK) < 0 ||
            read(GUEST_OFD_ORIGINAL_FD, &byte, 1) != 1 || byte != 'e' ||
            check_guest_open_description(5, 1, O_APPEND | O_NONBLOCK) < 0 ||
            fstat(GUEST_OFD_ORIGINAL_FD, &stat_buffer) < 0 || stat_buffer.st_size != concurrent_size ||
            write(GUEST_OFD_SCM_FD, "e", 1) != 1 ||
            fstat(GUEST_OFD_ORIGINAL_FD, &stat_buffer) < 0 || stat_buffer.st_size != concurrent_size + 1 ||
            lseek(GUEST_OFD_DUPLICATE_FD, 0, SEEK_CUR) != concurrent_size + 1 ||
            lseek(GUEST_OFD_REOPENED_FD, 0, SEEK_CUR) != 1 ||
            pread(GUEST_OFD_REOPENED_FD, &appended, 1, concurrent_size) != 1 || appended != 'e')
                goto finish;

        flags = fcntl(GUEST_OFD_DUPLICATE_FD, F_GETFL);
        if (flags < 0 || fcntl(GUEST_OFD_DUPLICATE_FD, F_SETFL, flags & ~(O_APPEND | O_NONBLOCK)) < 0 ||
            check_guest_open_description(concurrent_size + 1, 1, 0) < 0)
                goto finish;
        result = EXIT_SUCCESS;

finish:
        if (cleanup_guest_open_description() < 0)
                result = EXIT_FAILURE;
        if (result == EXIT_SUCCESS)
                printf("KVM_OPEN_DESCRIPTION_OK\n");
        return result;
}

static int run_guest_open_description_exec(const char *self) {
        static const char initial[] = "abcdef";
        char content[sizeof(initial) - 1 + 2 * GUEST_OFD_CONCURRENT_WRITES], path[PATH_MAX] = {};
        int fd = -1, flags, go_pipe[2] = { -1, -1 }, ready_pipe[2] = { -1, -1 };
        int received_fd = -1, reopened_fd = -1, sockets[2] = { -1, -1 }, status;
        bool fixed_fds = false, parent_writes_ok = true;
        pid_t child;

        if (make_guest_open_description_path(path) < 0)
                goto fail;
        fd = open(path, O_CREAT | O_EXCL | O_RDWR, 0600);
        if (fd < 0)
                goto fail;
        if (fd != GUEST_OFD_ORIGINAL_FD) {
                if (dup2(fd, GUEST_OFD_ORIGINAL_FD) != GUEST_OFD_ORIGINAL_FD || close(fd) < 0)
                        goto fail;
                fd = GUEST_OFD_ORIGINAL_FD;
        }
        if (dup2(fd, GUEST_OFD_DUPLICATE_FD) != GUEST_OFD_DUPLICATE_FD)
                goto fail;
        reopened_fd = open(path, O_RDWR);
        if (reopened_fd < 0)
                goto fail;
        if (reopened_fd != GUEST_OFD_REOPENED_FD) {
                if (dup2(reopened_fd, GUEST_OFD_REOPENED_FD) != GUEST_OFD_REOPENED_FD ||
                    close(reopened_fd) < 0)
                        goto fail;
                reopened_fd = GUEST_OFD_REOPENED_FD;
        }
        if (dup3(fd, GUEST_OFD_CLOEXEC_FD, O_CLOEXEC) != GUEST_OFD_CLOEXEC_FD ||
            socketpair(AF_UNIX, SOCK_DGRAM | SOCK_CLOEXEC, 0, sockets) < 0 ||
            send_guest_scm_rights(sockets[0], &fd, 1, 'o') < 0 ||
            receive_guest_scm_rights(sockets[1], 0, 'o', &received_fd) < 0)
                goto fail;
        if (received_fd != GUEST_OFD_SCM_FD) {
                if (dup2(received_fd, GUEST_OFD_SCM_FD) != GUEST_OFD_SCM_FD || close(received_fd) < 0)
                        goto fail;
                received_fd = GUEST_OFD_SCM_FD;
        }
        fixed_fds = true;
        if (close(sockets[0]) < 0 || close(sockets[1]) < 0)
                goto fail;
        sockets[0] = sockets[1] = -1;

        if (write(fd, initial, sizeof(initial) - 1) != (ssize_t) sizeof(initial) - 1 ||
            lseek(GUEST_OFD_DUPLICATE_FD, 2, SEEK_SET) != 2)
                goto fail;
        flags = fcntl(fd, F_GETFL);
        if (flags < 0 || fcntl(fd, F_SETFL, flags | O_APPEND | O_NONBLOCK) < 0 ||
            check_guest_open_description(2, 0, O_APPEND | O_NONBLOCK) < 0 ||
            (fcntl(GUEST_OFD_CLOEXEC_FD, F_GETFD) & FD_CLOEXEC) == 0 ||
            lseek(GUEST_OFD_CLOEXEC_FD, 0, SEEK_CUR) != 2 ||
            (fcntl(GUEST_OFD_CLOEXEC_FD, F_GETFL) & (O_APPEND | O_NONBLOCK)) !=
            (O_APPEND | O_NONBLOCK) ||
            pipe2(ready_pipe, O_CLOEXEC) < 0 || pipe2(go_pipe, O_CLOEXEC) < 0)
                goto fail;

        child = fork();
        if (child < 0)
                goto fail;
        if (child == 0) {
                close(ready_pipe[0]);
                close(go_pipe[1]);
                if (check_guest_open_description(2, 0, O_APPEND | O_NONBLOCK) < 0 ||
                    write(ready_pipe[1], "r", 1) != 1 || read(go_pipe[0], content, 1) != 1)
                        _exit(158);
                for (unsigned i = 0; i < GUEST_OFD_CONCURRENT_WRITES; i++)
                        if (write(GUEST_OFD_SCM_FD, "c", 1) != 1)
                                _exit(158);
                _exit(0);
        }

        close(ready_pipe[1]);
        ready_pipe[1] = -1;
        close(go_pipe[0]);
        go_pipe[0] = -1;
        if (read(ready_pipe[0], content, 1) != 1 || write(go_pipe[1], "g", 1) != 1) {
                parent_writes_ok = false;
                close(go_pipe[1]);
                go_pipe[1] = -1;
        }
        if (parent_writes_ok)
                for (unsigned i = 0; i < GUEST_OFD_CONCURRENT_WRITES; i++)
                        if (write(GUEST_OFD_ORIGINAL_FD, "p", 1) != 1) {
                                parent_writes_ok = false;
                                break;
                        }
        if (waitpid(child, &status, 0) != child ||
            !WIFEXITED(status) || WEXITSTATUS(status) != 0 || !parent_writes_ok)
                goto fail;
        close(ready_pipe[0]);
        ready_pipe[0] = -1;
        close(go_pipe[1]);
        go_pipe[1] = -1;

        if (check_guest_open_description(sizeof(content), 0, O_APPEND | O_NONBLOCK) < 0 ||
            lseek(GUEST_OFD_CLOEXEC_FD, 0, SEEK_CUR) != (off_t) sizeof(content) ||
            pread(GUEST_OFD_REOPENED_FD, content, sizeof(content), 0) != (ssize_t) sizeof(content) ||
            memcmp(content, initial, sizeof(initial) - 1) != 0)
                goto fail;
        size_t child_bytes = 0, parent_bytes = 0;
        for (size_t i = sizeof(initial) - 1; i < sizeof(content); i++) {
                if (content[i] == 'c')
                        child_bytes++;
                else if (content[i] == 'p')
                        parent_bytes++;
                else
                        goto fail;
        }
        if (child_bytes != GUEST_OFD_CONCURRENT_WRITES || parent_bytes != GUEST_OFD_CONCURRENT_WRITES ||
            lseek(GUEST_OFD_ORIGINAL_FD, 4, SEEK_SET) != 4 ||
            lseek(GUEST_OFD_REOPENED_FD, 1, SEEK_SET) != 1 ||
            check_guest_open_description(4, 1, O_APPEND | O_NONBLOCK) < 0)
                goto fail;

        execl(self, self, "--guest-exec-target", "--expect-open-description", NULL);
fail:
        for (size_t i = 0; i < 2; i++) {
                if (sockets[i] >= 0)
                        close(sockets[i]);
                if (ready_pipe[i] >= 0)
                        close(ready_pipe[i]);
                if (go_pipe[i] >= 0)
                        close(go_pipe[i]);
        }
        if (fixed_fds)
                cleanup_guest_open_description();
        else {
                if (fd >= 0)
                        close(fd);
                if (reopened_fd >= 0)
                        close(reopened_fd);
                if (received_fd >= 0)
                        close(received_fd);
                if (path[0] != 0)
                        unlink(path);
        }
        return -EPROTO;
}

static int test_guest_open_description_exec(const char *self) {
        int status;
        pid_t child;

        child = fork();
        if (child < 0)
                return EXIT_FAILURE;
        if (child == 0)
                _exit(run_guest_open_description_exec(self) < 0 ? 159 : 0);
        if (waitpid(child, &status, 0) != child ||
            !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                return EXIT_FAILURE;
        return EXIT_SUCCESS;
}

enum {
        GUEST_MEMFD_CAP_NOEXEC = 1U << 0,
        GUEST_MEMFD_CAP_EXEC = 1U << 1,
};

static int check_guest_memfd_seals(unsigned expected_seals) {
        static const int fds[] = {
                GUEST_MEMFD_FD,
                GUEST_MEMFD_DUPLICATE_FD,
                GUEST_MEMFD_SCM_FD,
        };
        struct stat expected_stat;

        if (fstat(GUEST_MEMFD_FD, &expected_stat) < 0)
                return -errno;
        for (size_t i = 0; i < sizeof(fds) / sizeof(fds[0]); i++) {
                struct stat stat_buffer;

                if (fcntl(fds[i], F_GET_SEALS) != (int) expected_seals ||
                    fstat(fds[i], &stat_buffer) < 0 || stat_buffer.st_dev != expected_stat.st_dev ||
                    stat_buffer.st_ino != expected_stat.st_ino)
                        return -EPROTO;
        }
        return 0;
}

static int cleanup_guest_memfd_seals(void) {
        static const int fds[] = {
                GUEST_MEMFD_FD,
                GUEST_MEMFD_DUPLICATE_FD,
                GUEST_MEMFD_SCM_FD,
                GUEST_MEMFD_CLOEXEC_FD,
                GUEST_MEMFD_EXEC_FD,
        };
        int result = 0;

        for (size_t i = 0; i < sizeof(fds) / sizeof(fds[0]); i++)
                if (close(fds[i]) < 0 && errno != EBADF)
                        result = -errno;
        return result;
}

static int validate_guest_memfd_seals_exec(const char *capabilities_string) {
        char *end = NULL;
        struct stat stat_buffer;
        void *private_mapping = MAP_FAILED, *shared_mapping = MAP_FAILED;
        unsigned expected_seals, capabilities;
        long page_size, parsed_capabilities;
        int result = EXIT_FAILURE;

        errno = 0;
        parsed_capabilities = strtol(capabilities_string, &end, 10);
        if (errno != 0 || !end || *end != '\0' || parsed_capabilities < 0 ||
            parsed_capabilities > (GUEST_MEMFD_CAP_NOEXEC | GUEST_MEMFD_CAP_EXEC))
                goto finish;
        capabilities = (unsigned) parsed_capabilities;
        expected_seals = F_SEAL_SHRINK | F_SEAL_GROW | F_SEAL_WRITE | F_SEAL_FUTURE_WRITE | F_SEAL_SEAL;
        if (capabilities & GUEST_MEMFD_CAP_NOEXEC)
                expected_seals |= F_SEAL_EXEC;
        page_size = sysconf(_SC_PAGESIZE);
        if (page_size <= 0 ||
            (fcntl(GUEST_MEMFD_FD, F_GETFD) & FD_CLOEXEC) != 0 ||
            (fcntl(GUEST_MEMFD_DUPLICATE_FD, F_GETFD) & FD_CLOEXEC) != 0 ||
            (fcntl(GUEST_MEMFD_SCM_FD, F_GETFD) & FD_CLOEXEC) != 0 ||
            check_guest_memfd_seals(expected_seals) < 0 ||
            fstat(GUEST_MEMFD_FD, &stat_buffer) < 0 || stat_buffer.st_size != 3 * page_size)
                goto finish;
        errno = 0;
        if (fcntl(GUEST_MEMFD_CLOEXEC_FD, F_GETFD) >= 0 || errno != EBADF)
                goto finish;

        shared_mapping = mmap(NULL, (size_t) page_size * 3, PROT_READ, MAP_SHARED, GUEST_MEMFD_FD, 0);
        private_mapping = mmap(
                        NULL,
                        (size_t) page_size * 3,
                        PROT_READ | PROT_WRITE,
                        MAP_PRIVATE,
                        GUEST_MEMFD_FD,
                        0);
        if (shared_mapping == MAP_FAILED || private_mapping == MAP_FAILED ||
            ((uint8_t *) shared_mapping)[0] != 0x11 || ((uint8_t *) shared_mapping)[page_size] != 0x22)
                goto finish;
        ((uint8_t *) private_mapping)[0] = 0x33;
        if (((uint8_t *) shared_mapping)[0] != 0x11)
                goto finish;

        errno = 0;
        if (pwrite(GUEST_MEMFD_DUPLICATE_FD, "x", 1, 0) >= 0 || errno != EPERM)
                goto finish;
        errno = 0;
        if (ftruncate(GUEST_MEMFD_FD, page_size) >= 0 || errno != EPERM)
                goto finish;
        errno = 0;
        if (ftruncate(GUEST_MEMFD_FD, page_size * 4) >= 0 || errno != EPERM)
                goto finish;
        errno = 0;
        void *denied_mapping = mmap(
                        NULL,
                        (size_t) page_size,
                        PROT_READ | PROT_WRITE,
                        MAP_SHARED,
                        GUEST_MEMFD_FD,
                        0);
        if (denied_mapping != MAP_FAILED || errno != EPERM) {
                if (denied_mapping != MAP_FAILED)
                        munmap(denied_mapping, (size_t) page_size);
                goto finish;
        }
        errno = 0;
        if (fcntl(GUEST_MEMFD_FD, F_ADD_SEALS, 0) >= 0 || errno != EPERM)
                goto finish;

        if (capabilities & GUEST_MEMFD_CAP_NOEXEC) {
                if (fstat(GUEST_MEMFD_FD, &stat_buffer) < 0 || (stat_buffer.st_mode & 0777) != 0600)
                        goto finish;
                errno = 0;
                if (fchmod(GUEST_MEMFD_FD, 0700) >= 0 || errno != EPERM)
                        goto finish;
        }

        if (capabilities & GUEST_MEMFD_CAP_EXEC) {
                if ((fcntl(GUEST_MEMFD_EXEC_FD, F_GETFD) & FD_CLOEXEC) != 0 ||
                    fcntl(GUEST_MEMFD_EXEC_FD, F_GET_SEALS) != F_SEAL_EXEC ||
                    fstat(GUEST_MEMFD_EXEC_FD, &stat_buffer) < 0 || (stat_buffer.st_mode & 0777) != 0600)
                        goto finish;
                errno = 0;
                if (fchmod(GUEST_MEMFD_EXEC_FD, 0700) >= 0 || errno != EPERM ||
                    write(GUEST_MEMFD_EXEC_FD, "e", 1) != 1)
                        goto finish;
        } else {
                errno = 0;
                if (fcntl(GUEST_MEMFD_EXEC_FD, F_GETFD) >= 0 || errno != EBADF)
                        goto finish;
        }
        result = EXIT_SUCCESS;

finish:
        if (private_mapping != MAP_FAILED && munmap(private_mapping, (size_t) page_size * 3) < 0)
                result = EXIT_FAILURE;
        if (shared_mapping != MAP_FAILED && munmap(shared_mapping, (size_t) page_size * 3) < 0)
                result = EXIT_FAILURE;
        if (cleanup_guest_memfd_seals() < 0)
                result = EXIT_FAILURE;
        if (result == EXIT_SUCCESS)
                printf("KVM_MEMFD_SEALS_OK\n");
        return result;
}

static int run_guest_memfd_seals_exec(const char *self) {
        char capabilities_string[16];
        struct stat stat_buffer;
        void *mapping = MAP_FAILED;
        unsigned capabilities = 0, expected_seals;
        int exec_fd = -1, fd = -1, received_fd = -1, sockets[2] = { -1, -1 }, status;
        bool fixed_fds = false;
        long page_size;
        pid_t child;

        page_size = sysconf(_SC_PAGESIZE);
        if (page_size <= 0)
                goto fail;
        errno = 0;
        fd = memfd_create("kvm-invalid-exec-mode", MFD_EXEC | MFD_NOEXEC_SEAL);
        if (fd >= 0 || errno != EINVAL) {
                if (fd >= 0)
                        close(fd);
                goto fail;
        }

        fd = memfd_create("kvm-seal-lifecycle", MFD_ALLOW_SEALING | MFD_NOEXEC_SEAL);
        if (fd < 0 && errno == EINVAL)
                fd = memfd_create("kvm-seal-lifecycle", MFD_ALLOW_SEALING);
        else if (fd >= 0)
                capabilities |= GUEST_MEMFD_CAP_NOEXEC;
        if (fd < 0)
                goto fail;
        if (fd != GUEST_MEMFD_FD) {
                if (dup2(fd, GUEST_MEMFD_FD) != GUEST_MEMFD_FD || close(fd) < 0)
                        goto fail;
                fd = GUEST_MEMFD_FD;
        }
        if (dup2(fd, GUEST_MEMFD_DUPLICATE_FD) != GUEST_MEMFD_DUPLICATE_FD ||
            dup3(fd, GUEST_MEMFD_CLOEXEC_FD, O_CLOEXEC) != GUEST_MEMFD_CLOEXEC_FD ||
            socketpair(AF_UNIX, SOCK_DGRAM | SOCK_CLOEXEC, 0, sockets) < 0 ||
            send_guest_scm_rights(sockets[0], &fd, 1, 's') < 0 ||
            receive_guest_scm_rights(sockets[1], 0, 's', &received_fd) < 0)
                goto fail;
        if (received_fd != GUEST_MEMFD_SCM_FD) {
                if (dup2(received_fd, GUEST_MEMFD_SCM_FD) != GUEST_MEMFD_SCM_FD || close(received_fd) < 0)
                        goto fail;
                received_fd = GUEST_MEMFD_SCM_FD;
        }
        fixed_fds = true;
        if (close(sockets[0]) < 0 || close(sockets[1]) < 0)
                goto fail;
        sockets[0] = sockets[1] = -1;

        expected_seals = capabilities & GUEST_MEMFD_CAP_NOEXEC ? F_SEAL_EXEC : 0;
        if (check_guest_memfd_seals(expected_seals) < 0 ||
            ftruncate(fd, page_size * 2) < 0 || fstat(fd, &stat_buffer) < 0)
                goto fail;
        if (capabilities & GUEST_MEMFD_CAP_NOEXEC) {
                if ((stat_buffer.st_mode & 0777) != 0666)
                        goto fail;
                errno = 0;
                if (fchmod(fd, 0777) >= 0 || errno != EPERM || fchmod(fd, 0600) < 0)
                        goto fail;
        }

        errno = 0;
        if (fcntl(fd, F_ADD_SEALS, INT_MIN) >= 0 || errno != EINVAL)
                goto fail;
        mapping = mmap(NULL, (size_t) page_size * 2, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
        if (mapping == MAP_FAILED)
                goto fail;
        ((uint8_t *) mapping)[0] = 0x11;
        if (fcntl(fd, F_ADD_SEALS, F_SEAL_SHRINK) < 0)
                goto fail;
        expected_seals |= F_SEAL_SHRINK;
        errno = 0;
        if (ftruncate(fd, page_size) >= 0 || errno != EPERM || ftruncate(fd, page_size * 3) < 0 ||
            fcntl(fd, F_ADD_SEALS, F_SEAL_GROW) < 0)
                goto fail;
        expected_seals |= F_SEAL_GROW;
        errno = 0;
        if (ftruncate(fd, page_size * 4) >= 0 || errno != EPERM)
                goto fail;
        errno = 0;
        if (fcntl(fd, F_ADD_SEALS, F_SEAL_WRITE) >= 0 || errno != EBUSY ||
            fcntl(fd, F_ADD_SEALS, F_SEAL_FUTURE_WRITE) < 0)
                goto fail;
        expected_seals |= F_SEAL_FUTURE_WRITE;
        errno = 0;
        if (pwrite(fd, "x", 1, 0) >= 0 || errno != EPERM)
                goto fail;
        errno = 0;
        void *denied_mapping = mmap(
                        NULL,
                        (size_t) page_size,
                        PROT_READ | PROT_WRITE,
                        MAP_SHARED,
                        fd,
                        0);
        if (denied_mapping != MAP_FAILED || errno != EPERM) {
                if (denied_mapping != MAP_FAILED)
                        munmap(denied_mapping, (size_t) page_size);
                goto fail;
        }
        ((uint8_t *) mapping)[page_size] = 0x21;

        child = fork();
        if (child < 0)
                goto fail;
        if (child == 0) {
                if (check_guest_memfd_seals(expected_seals) < 0)
                        _exit(160);
                ((uint8_t *) mapping)[page_size] = 0x22;
                errno = 0;
                if (ftruncate(GUEST_MEMFD_DUPLICATE_FD, page_size) >= 0 || errno != EPERM)
                        _exit(160);
                errno = 0;
                if (pwrite(GUEST_MEMFD_SCM_FD, "x", 1, 0) >= 0 || errno != EPERM)
                        _exit(160);
                _exit(0);
        }
        if (waitpid(child, &status, 0) != child ||
            !WIFEXITED(status) || WEXITSTATUS(status) != 0 ||
            ((uint8_t *) mapping)[page_size] != 0x22 || munmap(mapping, (size_t) page_size * 2) < 0)
                goto fail;
        mapping = MAP_FAILED;

        if (fcntl(fd, F_ADD_SEALS, F_SEAL_WRITE) < 0)
                goto fail;
        expected_seals |= F_SEAL_WRITE;
        if (fcntl(fd, F_ADD_SEALS, F_SEAL_SEAL) < 0)
                goto fail;
        expected_seals |= F_SEAL_SEAL;
        if (check_guest_memfd_seals(expected_seals) < 0)
                goto fail;
        errno = 0;
        if (fcntl(fd, F_ADD_SEALS, 0) >= 0 || errno != EPERM)
                goto fail;

        errno = 0;
        exec_fd = memfd_create("kvm-exec-seal", MFD_ALLOW_SEALING | MFD_EXEC);
        if (exec_fd < 0) {
                if (errno != EACCES && errno != EINVAL)
                        goto fail;
                close(GUEST_MEMFD_EXEC_FD);
        } else {
                capabilities |= GUEST_MEMFD_CAP_EXEC;
                if (exec_fd != GUEST_MEMFD_EXEC_FD) {
                        if (dup2(exec_fd, GUEST_MEMFD_EXEC_FD) != GUEST_MEMFD_EXEC_FD || close(exec_fd) < 0)
                                goto fail;
                        exec_fd = GUEST_MEMFD_EXEC_FD;
                }
                if (ftruncate(exec_fd, page_size) < 0 || fstat(exec_fd, &stat_buffer) < 0 ||
                    (stat_buffer.st_mode & 0777) != 0777 || fchmod(exec_fd, 0644) < 0 ||
                    fcntl(exec_fd, F_GET_SEALS) != 0 || fcntl(exec_fd, F_ADD_SEALS, F_SEAL_EXEC) < 0 ||
                    fcntl(exec_fd, F_GET_SEALS) != F_SEAL_EXEC || fchmod(exec_fd, 0600) < 0)
                        goto fail;
                errno = 0;
                if (fchmod(exec_fd, 0700) >= 0 || errno != EPERM || write(exec_fd, "e", 1) != 1)
                        goto fail;
        }

        if (snprintf(capabilities_string, sizeof(capabilities_string), "%u", capabilities) >=
            (int) sizeof(capabilities_string))
                goto fail;
        execl(self, self, "--guest-exec-target", "--expect-memfd-seals", capabilities_string, NULL);
fail:
        if (mapping != MAP_FAILED)
                munmap(mapping, (size_t) page_size * 2);
        for (size_t i = 0; i < 2; i++)
                if (sockets[i] >= 0)
                        close(sockets[i]);
        if (fixed_fds)
                cleanup_guest_memfd_seals();
        else {
                if (fd >= 0)
                        close(fd);
                if (received_fd >= 0)
                        close(received_fd);
                if (exec_fd >= 0)
                        close(exec_fd);
        }
        return -EPROTO;
}

static int test_guest_memfd_seals_exec(const char *self) {
        int status;
        pid_t child;

        child = fork();
        if (child < 0)
                return EXIT_FAILURE;
        if (child == 0)
                _exit(run_guest_memfd_seals_exec(self) < 0 ? 161 : 0);
        if (waitpid(child, &status, 0) != child ||
            !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                return EXIT_FAILURE;
        return EXIT_SUCCESS;
}

static int make_guest_delegation_path(char path[static PATH_MAX]) {
        return snprintf(path, PATH_MAX, "/tmp/kvm-delegation-%ld", (long) getpid()) < PATH_MAX ?
                0 : -EOVERFLOW;
}

static int check_guest_delegation_unsupported(void) {
        static const int fds[] = {
                GUEST_DELEGATION_FD,
                GUEST_DELEGATION_DUPLICATE_FD,
        };
        struct delegation delegation = {
                .d_type = F_WRLCK,
        };

        for (size_t i = 0; i < sizeof(fds) / sizeof(fds[0]); i++) {
                struct delegation query = {};

                errno = 0;
                if (fcntl(fds[i], F_GETDELEG, &query) >= 0 || errno != EINVAL)
                        return -EPROTO;
                errno = 0;
                if (fcntl(fds[i], F_SETDELEG, &delegation) >= 0 || errno != EINVAL)
                        return -EPROTO;
        }
        return 0;
}

static int check_guest_delegation_type(uint16_t expected_type) {
        static const int fds[] = {
                GUEST_DELEGATION_FD,
                GUEST_DELEGATION_DUPLICATE_FD,
        };

        for (size_t i = 0; i < sizeof(fds) / sizeof(fds[0]); i++) {
                struct delegation delegation = {};

                if (fcntl(fds[i], F_GETDELEG, &delegation) < 0 || delegation.d_flags != 0 ||
                    delegation.__pad != 0 || delegation.d_type != expected_type)
                        return -EPROTO;
        }
        return 0;
}

static int wait_guest_delegation_signal(void) {
        const struct timespec timeout = {
                .tv_sec = 5,
        };
        sigset_t mask;
        siginfo_t info;

        if (sigemptyset(&mask) < 0 || sigaddset(&mask, SIGUSR1) < 0)
                return -errno;
        if (sigtimedwait(&mask, &info, &timeout) != SIGUSR1 ||
            info.si_code != POLL_MSG || info.si_fd != GUEST_DELEGATION_FD)
                return -EPROTO;
        return 0;
}

static int cleanup_guest_delegation(void) {
        char path[PATH_MAX];
        int result = 0;

        if (close(GUEST_DELEGATION_FD) < 0 && errno != EBADF)
                result = -errno;
        if (close(GUEST_DELEGATION_DUPLICATE_FD) < 0 && errno != EBADF)
                result = -errno;
        if (make_guest_delegation_path(path) < 0)
                result = -EOVERFLOW;
        else if (unlink(path) < 0 && errno != ENOENT)
                result = -errno;
        return result;
}

static int validate_guest_file_delegation_exec(const char *support_string) {
        char path[PATH_MAX];
        struct delegation delegation = {};
        char *end = NULL;
        sigset_t mask;
        long support = -1;
        int contender_fd = -1, result = EXIT_FAILURE, status;
        pid_t child;

        errno = 0;
        support = strtol(support_string, &end, 10);
        if (errno != 0 || !end || *end != '\0' || support < 0 || support > 1 ||
            make_guest_delegation_path(path) < 0 ||
            (fcntl(GUEST_DELEGATION_FD, F_GETFD) & FD_CLOEXEC) != 0 ||
            (fcntl(GUEST_DELEGATION_DUPLICATE_FD, F_GETFD) & FD_CLOEXEC) != 0)
                goto finish;
        if (support == 0) {
                if (check_guest_delegation_unsupported() < 0)
                        goto finish;
                result = EXIT_SUCCESS;
                goto finish;
        }

        if (check_guest_delegation_type(F_WRLCK) < 0 ||
            sigemptyset(&mask) < 0 || sigaddset(&mask, SIGUSR1) < 0 ||
            pthread_sigmask(SIG_SETMASK, NULL, &mask) != 0 || sigismember(&mask, SIGUSR1) != 1)
                goto finish;
        child = fork();
        if (child < 0)
                goto finish;
        if (child == 0) {
                close(GUEST_DELEGATION_FD);
                close(GUEST_DELEGATION_DUPLICATE_FD);
                errno = 0;
                int fd = open(path, O_RDONLY | O_NONBLOCK);
                if (fd >= 0) {
                        close(fd);
                        _exit(162);
                }
                _exit(errno == EAGAIN || errno == EWOULDBLOCK ? 0 : 162);
        }
        if (wait_guest_delegation_signal() < 0 || waitpid(child, &status, 0) != child ||
            !WIFEXITED(status) || WEXITSTATUS(status) != 0 || check_guest_delegation_type(F_RDLCK) < 0)
                goto finish;
        delegation.d_type = F_UNLCK;
        if (fcntl(GUEST_DELEGATION_FD, F_SETDELEG, &delegation) < 0 ||
            check_guest_delegation_type(F_UNLCK) < 0)
                goto finish;
        contender_fd = open(path, O_RDWR | O_NONBLOCK);
        if (contender_fd < 0 || close(contender_fd) < 0)
                goto finish;
        contender_fd = -1;
        if (pthread_sigmask(SIG_UNBLOCK, &mask, NULL) != 0)
                goto finish;
        result = EXIT_SUCCESS;

finish:
        if (contender_fd >= 0)
                close(contender_fd);
        if (support == 1) {
                sigemptyset(&mask);
                sigaddset(&mask, SIGUSR1);
                pthread_sigmask(SIG_UNBLOCK, &mask, NULL);
        }
        if (cleanup_guest_delegation() < 0)
                result = EXIT_FAILURE;
        if (result == EXIT_SUCCESS)
                printf(support == 1 ? "KVM_FILE_DELEGATION_OK\n" : "KVM_FILE_DELEGATION_UNSUPPORTED\n");
        return result;
}

static int run_guest_file_delegation_exec(const char *self) {
        char path[PATH_MAX] = {}, support_string[2];
        struct delegation delegation = {};
        sigset_t mask, old_mask;
        int fd = -1, permission_fd = -1, status;
        bool fixed_fds = false, mask_set = false;
        long support = 0;
        pid_t child;

        if (make_guest_delegation_path(path) < 0)
                goto fail;
        fd = open(path, O_CREAT | O_EXCL | O_RDWR, 0600);
        if (fd < 0)
                goto fail;
        if (fd != GUEST_DELEGATION_FD) {
                if (dup2(fd, GUEST_DELEGATION_FD) != GUEST_DELEGATION_FD || close(fd) < 0)
                        goto fail;
                fd = GUEST_DELEGATION_FD;
        }
        if (dup2(fd, GUEST_DELEGATION_DUPLICATE_FD) != GUEST_DELEGATION_DUPLICATE_FD)
                goto fail;
        fixed_fds = true;

        errno = 0;
        if (fcntl(fd, F_GETDELEG, &delegation) < 0) {
                if (errno != EINVAL || check_guest_delegation_unsupported() < 0)
                        goto fail;
        } else {
                if (delegation.d_flags != 0 || delegation.__pad != 0 || delegation.d_type != F_UNLCK)
                        goto fail;
                support = 1;

                delegation = (struct delegation) {
                        .d_flags = 1,
                };
                errno = 0;
                if (fcntl(fd, F_GETDELEG, &delegation) >= 0 || errno != EINVAL)
                        goto fail;
                delegation = (struct delegation) {
                        .__pad = 1,
                        .d_type = F_WRLCK,
                };
                errno = 0;
                if (fcntl(fd, F_SETDELEG, &delegation) >= 0 || errno != EINVAL)
                        goto fail;
                delegation = (struct delegation) {
                        .d_type = UINT16_MAX,
                };
                errno = 0;
                if (fcntl(fd, F_SETDELEG, &delegation) >= 0 || errno != EINVAL)
                        goto fail;

                if (geteuid() != 0) {
                        permission_fd = open("/etc/passwd", O_RDONLY | O_CLOEXEC);
                        delegation = (struct delegation) {
                                .d_type = F_RDLCK,
                        };
                        errno = 0;
                        if (permission_fd < 0 || fcntl(permission_fd, F_SETDELEG, &delegation) >= 0 ||
                            errno != EACCES || close(permission_fd) < 0)
                                goto fail;
                        permission_fd = -1;
                }

                if (sigemptyset(&mask) < 0 || sigaddset(&mask, SIGUSR1) < 0 ||
                    pthread_sigmask(SIG_BLOCK, &mask, &old_mask) != 0)
                        goto fail;
                mask_set = true;
                delegation = (struct delegation) {
                        .d_type = F_WRLCK,
                };
                if (fcntl(fd, F_SETOWN, getpid()) < 0 || fcntl(fd, F_SETSIG, SIGUSR1) < 0 ||
                    fcntl(fd, F_SETDELEG, &delegation) < 0 || check_guest_delegation_type(F_WRLCK) < 0)
                        goto fail;

                child = fork();
                if (child < 0)
                        goto fail;
                if (child == 0)
                        _exit(check_guest_delegation_type(F_WRLCK) < 0 ? 163 : 0);
                if (waitpid(child, &status, 0) != child ||
                    !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                        goto fail;
        }

        support_string[0] = support ? '1' : '0';
        support_string[1] = '\0';
        execl(self, self, "--guest-exec-target", "--expect-file-delegation", support_string, NULL);
fail:
        if (permission_fd >= 0)
                close(permission_fd);
        if (mask_set)
                pthread_sigmask(SIG_SETMASK, &old_mask, NULL);
        if (fixed_fds)
                cleanup_guest_delegation();
        else {
                if (fd >= 0)
                        close(fd);
                if (path[0] != 0)
                        unlink(path);
        }
        return -EPROTO;
}

static int test_guest_file_delegation_exec(const char *self) {
        int status;
        pid_t child;

        child = fork();
        if (child < 0)
                return EXIT_FAILURE;
        if (child == 0)
                _exit(run_guest_file_delegation_exec(self) < 0 ? 164 : 0);
        if (waitpid(child, &status, 0) != child ||
            !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                return EXIT_FAILURE;
        return EXIT_SUCCESS;
}

static int submit_guest_aio(aio_context_t context, struct iocb *iocb) {
        struct iocb *iocbs[] = { iocb };

        return syscall(SYS_io_submit, context, 1, iocbs) == 1 ? 0 : -errno;
}

static int get_guest_aio_event(
                aio_context_t context,
                const struct iocb *iocb,
                uint64_t expected_data,
                int64_t expected_result) {

        const struct timespec timeout = {
                .tv_sec = 5,
        };
        struct io_event event = {};

        if (syscall(SYS_io_getevents, context, 1, 1, &event, &timeout) != 1 ||
            event.data != expected_data || event.obj != (uintptr_t) iocb ||
            event.res != expected_result || event.res2 != 0)
                return -EPROTO;
        return 0;
}

static int guest_mapping_has_vm_flag(uintptr_t address, const char *flag, bool *ret) {
        FILE *smaps;
        char *line = NULL;
        size_t allocated = 0;
        bool target = false;
        int result = -ENOENT;

        if (!flag || !ret)
                return -EINVAL;
        smaps = fopen("/proc/self/smaps", "re");
        if (!smaps)
                return -errno;
        while (getline(&line, &allocated, smaps) >= 0) {
                unsigned long end, start;

                if (sscanf(line, "%lx-%lx", &start, &end) == 2) {
                        target = address >= start && address < end;
                        continue;
                }
                if (!target || strncmp(line, "VmFlags:", strlen("VmFlags:")) != 0)
                        continue;

                char *saveptr = NULL;
                for (char *word = strtok_r(line + strlen("VmFlags:"), " \n", &saveptr);
                     word;
                     word = strtok_r(NULL, " \n", &saveptr))
                        if (strcmp(word, flag) == 0) {
                                *ret = true;
                                result = 0;
                                goto finish;
                        }
                *ret = false;
                result = 0;
                goto finish;
        }
        if (ferror(smaps))
                result = errno > 0 ? -errno : -EIO;

finish:
        free(line);
        if (fclose(smaps) < 0 && result >= 0)
                result = -errno;
        return result;
}

static int check_guest_aio_context_invalid(aio_context_t context) {
        const struct timespec timeout = {};
        struct io_event event;

        errno = 0;
        if (syscall(SYS_io_getevents, context, 0, 1, &event, &timeout) >= 0 || errno != EINVAL)
                return -EPROTO;
        errno = 0;
        if (syscall(SYS_io_destroy, context) >= 0 || errno != EINVAL)
                return -EPROTO;
        return 0;
}

static int check_guest_aio_stale(aio_context_t context, long page_size) {
        unsigned char residency;

        errno = 0;
        if (mincore((void*) context, (size_t) page_size, &residency) >= 0 || errno != ENOMEM ||
            check_guest_aio_context_invalid(context) < 0)
                return -EPROTO;
        return 0;
}

static int validate_guest_legacy_aio_exec(const char *context_string) {
        char *end = NULL, byte;
        aio_context_t context;
        unsigned long parsed_context;
        long page_size;
        int result = EXIT_FAILURE;

        errno = 0;
        parsed_context = strtoul(context_string, &end, 10);
        if (errno != 0 || !end || *end != '\0' || parsed_context == 0)
                goto finish;
        context = parsed_context;
        page_size = sysconf(_SC_PAGESIZE);
        if (page_size <= 0 ||
            (fcntl(GUEST_AIO_FILE_FD, F_GETFD) & FD_CLOEXEC) != 0 ||
            (fcntl(GUEST_AIO_PIPE_READ_FD, F_GETFD) & FD_CLOEXEC) != 0 ||
            (fcntl(GUEST_AIO_PIPE_WRITE_FD, F_GETFD) & FD_CLOEXEC) != 0 ||
            check_guest_aio_stale(context, page_size) < 0 ||
            write(GUEST_AIO_PIPE_WRITE_FD, "e", 1) != 1 ||
            read(GUEST_AIO_PIPE_READ_FD, &byte, 1) != 1 || byte != 'e')
                goto finish;
        result = EXIT_SUCCESS;

finish:
        if (close(GUEST_AIO_FILE_FD) < 0)
                result = EXIT_FAILURE;
        if (close(GUEST_AIO_PIPE_READ_FD) < 0)
                result = EXIT_FAILURE;
        if (close(GUEST_AIO_PIPE_WRITE_FD) < 0)
                result = EXIT_FAILURE;
        if (result == EXIT_SUCCESS)
                printf("KVM_LEGACY_AIO_OK\n");
        return result;
}

static int run_guest_legacy_aio_exec(const char *self) {
        const struct timespec zero_timeout = {};
        char context_string[32], read_buffer[8] = {}, write_buffer[] = "legacy";
        aio_context_t context = 0, exec_context = 0, invalid_context = 1, old_exec_context;
        struct io_event event = {};
        struct iocb poll_iocb = {
                .aio_data = 0x33,
                .aio_lio_opcode = IOCB_CMD_POLL,
                .aio_fildes = GUEST_AIO_PIPE_READ_FD,
                .aio_buf = POLLIN,
        };
        struct iocb read_iocb = {
                .aio_data = 0x22,
                .aio_lio_opcode = IOCB_CMD_PREAD,
                .aio_fildes = GUEST_AIO_FILE_FD,
                .aio_buf = (uintptr_t) read_buffer,
                .aio_nbytes = sizeof(write_buffer) - 1,
        };
        struct iocb write_iocb = {
                .aio_data = 0x11,
                .aio_lio_opcode = IOCB_CMD_PWRITE,
                .aio_fildes = GUEST_AIO_FILE_FD,
                .aio_buf = (uintptr_t) write_buffer,
                .aio_nbytes = sizeof(write_buffer) - 1,
        };
        struct iocb exec_poll_iocb = poll_iocb;
        int file_fd = -1, pipe_fds[2] = { -1, -1 }, status;
        bool dontfork = false, fixed_fds = false;
        unsigned char residency;
        void *moved, *reservation = MAP_FAILED;
        long page_size;
        pid_t child;

        page_size = sysconf(_SC_PAGESIZE);
        if (page_size <= 0)
                goto fail;
        errno = 0;
        if (syscall(SYS_io_setup, 8, (void*) 1) >= 0 || errno != EFAULT)
                goto fail;
        errno = 0;
        if (syscall(SYS_io_setup, 0, &context) >= 0 || errno != EINVAL)
                goto fail;
        errno = 0;
        if (syscall(SYS_io_setup, 8, &invalid_context) >= 0 || errno != EINVAL)
                goto fail;

        file_fd = memfd_create("kvm-legacy-aio", 0);
        if (file_fd < 0)
                goto fail;
        if (file_fd != GUEST_AIO_FILE_FD) {
                if (dup2(file_fd, GUEST_AIO_FILE_FD) != GUEST_AIO_FILE_FD || close(file_fd) < 0)
                        goto fail;
                file_fd = GUEST_AIO_FILE_FD;
        }
        if (pipe2(pipe_fds, O_NONBLOCK) < 0 ||
            dup2(pipe_fds[0], GUEST_AIO_PIPE_READ_FD) != GUEST_AIO_PIPE_READ_FD ||
            dup2(pipe_fds[1], GUEST_AIO_PIPE_WRITE_FD) != GUEST_AIO_PIPE_WRITE_FD)
                goto fail;
        fixed_fds = true;
        if (close(pipe_fds[0]) < 0 || close(pipe_fds[1]) < 0)
                goto fail;
        pipe_fds[0] = pipe_fds[1] = -1;

        if (syscall(SYS_io_setup, 16, &context) < 0 || context == 0 ||
            mincore((void*) context, (size_t) page_size, &residency) < 0 ||
            submit_guest_aio(context, &write_iocb) < 0 ||
            get_guest_aio_event(context, &write_iocb, write_iocb.aio_data, sizeof(write_buffer) - 1) < 0 ||
            submit_guest_aio(context, &read_iocb) < 0 ||
            get_guest_aio_event(context, &read_iocb, read_iocb.aio_data, sizeof(write_buffer) - 1) < 0 ||
            memcmp(read_buffer, write_buffer, sizeof(write_buffer) - 1) != 0 ||
            syscall(SYS_io_getevents, context, 0, 1, &event, &zero_timeout) != 0)
                goto fail;
        errno = 0;
        if (syscall(SYS_io_getevents, context, 2, 1, &event, &zero_timeout) >= 0 || errno != EINVAL)
                goto fail;
        errno = 0;
        if (syscall(SYS_io_getevents, invalid_context, 0, 1, &event, &zero_timeout) >= 0 || errno != EINVAL)
                goto fail;
        errno = 0;
        if (syscall(SYS_io_cancel, context, &write_iocb, &event) >= 0 || errno != EINVAL)
                goto fail;

        if (submit_guest_aio(context, &poll_iocb) < 0)
                goto fail;
        errno = 0;
        if (syscall(SYS_io_cancel, context, &poll_iocb, &event) >= 0 || errno != EINPROGRESS ||
            get_guest_aio_event(context, &poll_iocb, poll_iocb.aio_data, 0) < 0 ||
            syscall(SYS_io_destroy, context) < 0 || check_guest_aio_stale(context, page_size) < 0)
                goto fail;
        context = 0;

        if (syscall(SYS_io_setup, 16, &exec_context) < 0 || exec_context == 0 ||
            mincore((void*) exec_context, (size_t) page_size, &residency) < 0)
                goto fail;
        old_exec_context = exec_context;
        reservation = mmap(NULL, (size_t) page_size, PROT_NONE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (reservation == MAP_FAILED || munmap(reservation, (size_t) page_size) < 0)
                goto fail;
        moved = mremap(
                        (void*) exec_context,
                        (size_t) page_size,
                        (size_t) page_size,
                        MREMAP_MAYMOVE | MREMAP_FIXED,
                        reservation);
        if (moved != reservation)
                goto fail;
        reservation = MAP_FAILED;
        exec_context = (uintptr_t) moved;
        if (check_guest_aio_stale(old_exec_context, page_size) < 0 ||
            mincore((void*) exec_context, (size_t) page_size, &residency) < 0 ||
            guest_mapping_has_vm_flag(exec_context, "dc", &dontfork) < 0)
                goto fail;
        child = fork();
        if (child < 0)
                goto fail;
        if (child == 0) {
                errno = 0;
                int mapped = mincore((void*) exec_context, (size_t) page_size, &residency);

                if (check_guest_aio_context_invalid(exec_context) < 0 ||
                    (dontfork && (mapped >= 0 || errno != ENOMEM)) || (!dontfork && mapped < 0))
                        _exit(165);
                _exit(0);
        }
        if (waitpid(child, &status, 0) != child ||
            !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                goto fail;

        exec_poll_iocb.aio_data = 0x44;
        if (submit_guest_aio(exec_context, &exec_poll_iocb) < 0 ||
            snprintf(context_string, sizeof(context_string), "%lu", (unsigned long) exec_context) >=
                            (int) sizeof(context_string))
                goto fail;
        execl(self, self, "--guest-exec-target", "--expect-legacy-aio", context_string, NULL);
fail:
        if (reservation != MAP_FAILED)
                munmap(reservation, (size_t) page_size);
        if (context != 0)
                syscall(SYS_io_destroy, context);
        if (exec_context != 0)
                syscall(SYS_io_destroy, exec_context);
        if (fixed_fds) {
                close(GUEST_AIO_FILE_FD);
                close(GUEST_AIO_PIPE_READ_FD);
                close(GUEST_AIO_PIPE_WRITE_FD);
        } else {
                if (file_fd >= 0)
                        close(file_fd);
                if (pipe_fds[0] >= 0)
                        close(pipe_fds[0]);
                if (pipe_fds[1] >= 0)
                        close(pipe_fds[1]);
        }
        return -EPROTO;
}

static int test_guest_legacy_aio_exec(const char *self) {
        int status;
        pid_t child;

        child = fork();
        if (child < 0)
                return EXIT_FAILURE;
        if (child == 0)
                _exit(run_guest_legacy_aio_exec(self) < 0 ? 166 : 0);
        if (waitpid(child, &status, 0) != child ||
            !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                return EXIT_FAILURE;
        return EXIT_SUCCESS;
}

enum {
        GUEST_MOUNT_CAP_OPEN_TREE_ATTR = 1U << 0,
        GUEST_MOUNT_CAP_STATMOUNT_BY_FD = 1U << 1,
};

typedef union GuestStatmountBuffer {
        struct statmount statmount;
        uint8_t bytes[4096];
} GuestStatmountBuffer;

static int make_guest_mount_api_paths(
                char base[static PATH_MAX],
                char target[static PATH_MAX],
                char clone[static PATH_MAX],
                pid_t owner) {

        if (snprintf(base, PATH_MAX, "/tmp/kvm-mount-api-%ld", (long) owner) >= PATH_MAX ||
            snprintf(target, PATH_MAX, "%s/target", base) >= PATH_MAX ||
            snprintf(clone, PATH_MAX, "%s/clone", base) >= PATH_MAX)
                return -EOVERFLOW;
        return 0;
}

static int move_guest_mount_fd(int fd, int target, bool cloexec) {
        int flags;

        if (fd < 0)
                return -EBADF;
        if (fd != target) {
                int r = cloexec ? dup3(fd, target, O_CLOEXEC) : dup2(fd, target);

                if (r != target)
                        return -errno;
                if (close(fd) < 0)
                        return -errno;
                return target;
        }

        flags = fcntl(fd, F_GETFD);
        if (flags < 0 || fcntl(fd, F_SETFD, cloexec ? flags | FD_CLOEXEC : flags & ~FD_CLOEXEC) < 0)
                return -errno;
        return target;
}

static int guest_mount_unique_id(const char *path, uint64_t *ret_id) {
        struct statx statx_buffer = {};

        if (syscall(SYS_statx, AT_FDCWD, path, AT_SYMLINK_NOFOLLOW, STATX_MNT_ID_UNIQUE, &statx_buffer) < 0)
                return -errno;
        if ((statx_buffer.stx_mask & STATX_MNT_ID_UNIQUE) == 0 || statx_buffer.stx_mnt_id == 0)
                return -EPROTO;
        *ret_id = statx_buffer.stx_mnt_id;
        return 0;
}

static int guest_listmount_contains(uint64_t mount_id) {
        uint64_t ids[128];
        struct mnt_id_req request = {
                .size = MNT_ID_REQ_SIZE_VER0,
                .mnt_id = LSMT_ROOT,
        };

        for (unsigned iteration = 0; iteration < 1024; iteration++) {
                long n = syscall(SYS_listmount, &request, ids, sizeof(ids) / sizeof(ids[0]), 0);

                if (n < 0)
                        return -errno;
                if (n == 0)
                        return 0;
                for (long i = 0; i < n; i++)
                        if (ids[i] == mount_id)
                                return 1;
                request.param = ids[n - 1];
        }
        return -ELOOP;
}

static int guest_statmount_verify(
                uint64_t mount_id,
                const char *mount_point,
                uint64_t expected_attributes,
                uint64_t *ret_namespace_id) {

        const uint64_t mask = STATMOUNT_SB_BASIC | STATMOUNT_MNT_BASIC | STATMOUNT_MNT_POINT |
                              STATMOUNT_FS_TYPE | STATMOUNT_MNT_NS_ID;
        struct mnt_id_req request = {
                .size = MNT_ID_REQ_SIZE_VER0,
                .mnt_id = mount_id,
                .param = mask,
        };
        GuestStatmountBuffer buffer = {};
        struct statmount *statmount = &buffer.statmount;

        if (syscall(SYS_statmount, &request, statmount, sizeof(buffer), 0) < 0)
                return -errno;
        if (statmount->size > sizeof(buffer) || statmount->size < sizeof(*statmount) ||
            (statmount->mask & mask) != mask || statmount->mnt_id != mount_id ||
            statmount->mnt_ns_id == 0 || (statmount->mnt_attr & expected_attributes) != expected_attributes ||
            statmount->fs_type >= statmount->size - sizeof(*statmount) ||
            statmount->mnt_point >= statmount->size - sizeof(*statmount) ||
            strcmp(statmount->str + statmount->fs_type, "tmpfs") != 0 ||
            strcmp(statmount->str + statmount->mnt_point, mount_point) != 0)
                return -EPROTO;
        if (ret_namespace_id)
                *ret_namespace_id = statmount->mnt_ns_id;
        return 0;
}

static int guest_statmount_by_fd(int fd, uint64_t expected_mount_id) {
        const uint64_t mask = STATMOUNT_MNT_BASIC | STATMOUNT_FS_TYPE;
        struct mnt_id_req request = {
                .size = MNT_ID_REQ_SIZE_VER0,
                .mnt_ns_fd = fd,
                .param = mask,
        };
        GuestStatmountBuffer buffer = {};

        errno = 0;
        if (syscall(SYS_statmount, &request, &buffer.statmount, sizeof(buffer), STATMOUNT_BY_FD) < 0)
                return errno == EINVAL ? 0 : -errno;
        if ((buffer.statmount.mask & mask) != mask || buffer.statmount.mnt_id != expected_mount_id ||
            buffer.statmount.fs_type >= buffer.statmount.size - sizeof(buffer.statmount) ||
            strcmp(buffer.statmount.str + buffer.statmount.fs_type, "tmpfs") != 0)
                return -EPROTO;
        return 1;
}

static int read_guest_mount_sentinel(int directory_fd, const char *path) {
        char buffer[16] = {};
        int fd;

        fd = openat(directory_fd, path, O_RDONLY | O_CLOEXEC);
        if (fd < 0)
                return -errno;
        ssize_t n = read(fd, buffer, sizeof(buffer));
        int error = n < 0 ? -errno : 0;

        if (close(fd) < 0 && error >= 0)
                error = -errno;
        if (error < 0)
                return error;
        return n == 9 && memcmp(buffer, "mount-api", 9) == 0 ? 0 : -EPROTO;
}

static int check_guest_mount_api(
                unsigned capabilities,
                uint64_t expected_mount_namespace_inode,
                uint64_t expected_user_namespace_inode,
                uint64_t target_id,
                uint64_t clone_id,
                bool exec_completed,
                pid_t owner) {

        char base[PATH_MAX], clone[PATH_MAX], target[PATH_MAX];
        struct stat namespace_stat;
        uint64_t clone_namespace_id, target_namespace_id;
        int fd, r;

        if (make_guest_mount_api_paths(base, target, clone, owner) < 0 ||
            stat("/proc/self/ns/mnt", &namespace_stat) < 0 ||
            (uint64_t) namespace_stat.st_ino != expected_mount_namespace_inode ||
            stat("/proc/self/ns/user", &namespace_stat) < 0 ||
            (uint64_t) namespace_stat.st_ino != expected_user_namespace_inode ||
            getuid() != 0 || geteuid() != 0 || getgid() != 0 || getegid() != 0)
                return -EPROTO;
        static const int persistent_fds[] = {
                GUEST_MOUNT_CONTEXT_FD,
                GUEST_MOUNT_FD,
                GUEST_MOUNT_TREE_FD,
                GUEST_MOUNT_PICK_FD,
        };
        for (size_t i = 0; i < sizeof(persistent_fds) / sizeof(persistent_fds[0]); i++)
                if ((fcntl(persistent_fds[i], F_GETFD) & FD_CLOEXEC) != 0)
                        return -EPROTO;
        errno = 0;
        r = fcntl(GUEST_MOUNT_CLOEXEC_FD, F_GETFD);
        if ((exec_completed && (r >= 0 || errno != EBADF)) ||
            (!exec_completed && (r < 0 || (r & FD_CLOEXEC) == 0)) ||
            guest_mount_unique_id(target, &target_namespace_id) < 0 || target_namespace_id != target_id ||
            guest_mount_unique_id(clone, &clone_namespace_id) < 0 || clone_namespace_id != clone_id ||
            guest_listmount_contains(target_id) != 1 || guest_listmount_contains(clone_id) != 1 ||
            guest_statmount_verify(
                            target_id,
                            target,
                            MOUNT_ATTR_NODEV | MOUNT_ATTR_NOSUID,
                            &target_namespace_id) < 0 ||
            guest_statmount_verify(
                            clone_id,
                            clone,
                            MOUNT_ATTR_NODEV | MOUNT_ATTR_NOSUID | MOUNT_ATTR_RDONLY | MOUNT_ATTR_NOEXEC,
                            &clone_namespace_id) < 0 ||
            target_namespace_id != clone_namespace_id ||
            read_guest_mount_sentinel(GUEST_MOUNT_FD, "sub/sentinel") < 0 ||
            read_guest_mount_sentinel(GUEST_MOUNT_TREE_FD, "sentinel") < 0)
                return -EPROTO;

        r = guest_statmount_by_fd(GUEST_MOUNT_FD, target_id);
        if (r < 0 || (!!(capabilities & GUEST_MOUNT_CAP_STATMOUNT_BY_FD) != (r > 0)))
                return -EPROTO;
        if (capabilities & GUEST_MOUNT_CAP_OPEN_TREE_ATTR) {
                if ((fcntl(GUEST_MOUNT_ATTR_FD, F_GETFD) & FD_CLOEXEC) != 0 ||
                    read_guest_mount_sentinel(GUEST_MOUNT_ATTR_FD, "sentinel") < 0)
                        return -EPROTO;
                errno = 0;
                fd = openat(GUEST_MOUNT_ATTR_FD, "denied", O_CREAT | O_WRONLY | O_CLOEXEC, 0600);
                if (fd >= 0 || errno != EROFS) {
                        if (fd >= 0)
                                close(fd);
                        return -EPROTO;
                }
        } else {
                errno = 0;
                if (fcntl(GUEST_MOUNT_ATTR_FD, F_GETFD) >= 0 || errno != EBADF)
                        return -EPROTO;
        }
        return 0;
}

static int cleanup_guest_mount_api(void) {
        static const int fds[] = {
                GUEST_MOUNT_CONTEXT_FD,
                GUEST_MOUNT_FD,
                GUEST_MOUNT_TREE_FD,
                GUEST_MOUNT_PICK_FD,
                GUEST_MOUNT_CLOEXEC_FD,
                GUEST_MOUNT_ATTR_FD,
        };
        char base[PATH_MAX], clone[PATH_MAX], target[PATH_MAX];
        int result = 0;

        if (make_guest_mount_api_paths(base, target, clone, getpid()) < 0)
                return -EOVERFLOW;
        if (umount2(clone, MNT_DETACH) < 0 && errno != EINVAL && errno != ENOENT)
                result = -errno;
        if (umount2(target, MNT_DETACH) < 0 && errno != EINVAL && errno != ENOENT)
                result = -errno;
        for (size_t i = 0; i < sizeof(fds) / sizeof(fds[0]); i++)
                if (close(fds[i]) < 0 && errno != EBADF)
                        result = -errno;
        if (rmdir(clone) < 0 && errno != ENOENT)
                result = -errno;
        if (rmdir(target) < 0 && errno != ENOENT)
                result = -errno;
        if (rmdir(base) < 0 && errno != ENOENT)
                result = -errno;
        return result;
}

static int validate_guest_mount_api_exec(
                const char *capabilities_string,
                const char *mount_namespace_string,
                const char *user_namespace_string,
                const char *target_id_string,
                const char *clone_id_string) {

        const char *strings[] = {
                capabilities_string,
                mount_namespace_string,
                user_namespace_string,
                target_id_string,
                clone_id_string,
        };
        uint64_t values[5];
        int result = EXIT_FAILURE;

        for (size_t i = 0; i < sizeof(strings) / sizeof(strings[0]); i++) {
                char *end = NULL;

                errno = 0;
                values[i] = strtoull(strings[i], &end, 10);
                if (errno != 0 || !end || *end != '\0')
                        goto finish;
        }
                if (values[0] > (GUEST_MOUNT_CAP_OPEN_TREE_ATTR | GUEST_MOUNT_CAP_STATMOUNT_BY_FD) ||
                        check_guest_mount_api(
                                                        (unsigned) values[0],
                                                        values[1],
                                                        values[2],
                                                        values[3],
                                                        values[4],
                                                        true,
                                                        getpid()) < 0)
                goto finish;

        char base[PATH_MAX], clone[PATH_MAX], target[PATH_MAX];
        if (make_guest_mount_api_paths(base, target, clone, getpid()) < 0)
                goto finish;
        int fd = openat(GUEST_MOUNT_FD, "post-exec", O_CREAT | O_WRONLY | O_CLOEXEC, 0600);
        if (fd < 0 || close(fd) < 0 || unlinkat(GUEST_MOUNT_FD, "post-exec", 0) < 0)
                goto finish;
        result = EXIT_SUCCESS;

finish:
        if (cleanup_guest_mount_api() < 0)
                result = EXIT_FAILURE;
        if (result == EXIT_SUCCESS)
                printf("KVM_MOUNT_API_OK\n");
        return result;
}

static int run_guest_mount_api_exec(const char *self) {
        char base[PATH_MAX], capabilities_string[16], clone[PATH_MAX], clone_id_string[32];
        char mount_namespace_string[32], target[PATH_MAX], target_id_string[32], user_namespace_string[32];
        struct mount_attr readonly_attr = {
                .attr_set = MOUNT_ATTR_RDONLY | MOUNT_ATTR_NOEXEC,
        };
        struct stat namespace_stat;
        unsigned capabilities = 0;
        uint64_t clone_id, target_id;
        int attr_fd = -1, clone_fd = -1, context_fd = -1, fd = -1, mount_fd = -1, pick_fd = -1;
        bool fixed_fds = false;
        pid_t child;
        int r, status;

        if (make_guest_mount_api_paths(base, target, clone, getpid()) < 0 ||
            mount(NULL, "/", NULL, MS_REC | MS_PRIVATE, NULL) < 0 ||
            mkdir(base, 0700) < 0 || mkdir(target, 0700) < 0 || mkdir(clone, 0700) < 0)
                goto fail;

        errno = 0;
        if (syscall(SYS_fsopen, "tmpfs", UINT_MAX) >= 0 || errno != EINVAL)
                goto fail;
        errno = 0;
        if (syscall(SYS_fsopen, "kvm-no-such-filesystem", 0) >= 0 || errno != ENODEV)
                goto fail;
        errno = 0;
        if (syscall(SYS_fsconfig, -1, FSCONFIG_CMD_CREATE, NULL, NULL, 0) >= 0 || errno != EINVAL)
                goto fail;
        errno = 0;
        if (syscall(SYS_open_tree, AT_FDCWD, "/", UINT_MAX) >= 0 || errno != EINVAL)
                goto fail;
        errno = 0;
        if (syscall(SYS_move_mount, AT_FDCWD, "/", AT_FDCWD, target, UINT_MAX) >= 0 || errno != EINVAL)
                goto fail;
        errno = 0;
        if (syscall(SYS_mount_setattr, AT_FDCWD, target, 0, &readonly_attr, 0) >= 0 || errno != EINVAL)
                goto fail;

        context_fd = syscall(SYS_fsopen, "tmpfs", 0);
        if (context_fd < 0 || move_guest_mount_fd(context_fd, GUEST_MOUNT_CONTEXT_FD, false) < 0)
                goto fail;
        context_fd = GUEST_MOUNT_CONTEXT_FD;
        if (syscall(SYS_fsconfig, context_fd, FSCONFIG_SET_STRING, "size", "64k", 0) < 0 ||
            syscall(SYS_fsconfig, context_fd, FSCONFIG_SET_STRING, "mode", "0700", 0) < 0 ||
            syscall(SYS_fsconfig, context_fd, FSCONFIG_CMD_CREATE, NULL, NULL, 0) < 0)
                goto fail;
        mount_fd = syscall(SYS_fsmount, context_fd, 0, MOUNT_ATTR_NODEV | MOUNT_ATTR_NOSUID);
        if (mount_fd < 0 || move_guest_mount_fd(mount_fd, GUEST_MOUNT_FD, false) < 0)
                goto fail;
        mount_fd = GUEST_MOUNT_FD;
        if (mkdirat(mount_fd, "sub", 0700) < 0)
                goto fail;
        fd = openat(mount_fd, "sub/sentinel", O_CREAT | O_WRONLY | O_CLOEXEC, 0600);
        if (fd < 0 || write(fd, "mount-api", 9) != 9 || close(fd) < 0)
                goto fail;
        fd = -1;
        if (syscall(SYS_move_mount, mount_fd, "", AT_FDCWD, target, MOVE_MOUNT_F_EMPTY_PATH) < 0)
                goto fail;

        clone_fd = syscall(SYS_open_tree, mount_fd, "sub", OPEN_TREE_CLONE);
        if (clone_fd < 0 || move_guest_mount_fd(clone_fd, GUEST_MOUNT_TREE_FD, false) < 0)
                goto fail;
        clone_fd = GUEST_MOUNT_TREE_FD;
        if (syscall(
                            SYS_mount_setattr,
                            clone_fd,
                            "",
                            AT_EMPTY_PATH,
                            &readonly_attr,
                            sizeof(readonly_attr)) < 0 ||
            syscall(SYS_move_mount, clone_fd, "", AT_FDCWD, clone, MOVE_MOUNT_F_EMPTY_PATH) < 0)
                goto fail;

        pick_fd = syscall(SYS_fspick, AT_FDCWD, target, 0);
        if (pick_fd < 0 || move_guest_mount_fd(pick_fd, GUEST_MOUNT_PICK_FD, false) < 0)
                goto fail;
        pick_fd = GUEST_MOUNT_PICK_FD;
        fd = syscall(SYS_open_tree, AT_FDCWD, target, OPEN_TREE_CLOEXEC);
        if (fd < 0 || move_guest_mount_fd(fd, GUEST_MOUNT_CLOEXEC_FD, true) < 0)
                goto fail;
        fd = -1;
        fixed_fds = true;

        attr_fd = syscall(
                        SYS_open_tree_attr,
                        mount_fd,
                        "sub",
                        OPEN_TREE_CLONE,
                        &readonly_attr,
                        sizeof(readonly_attr));
        if (attr_fd < 0) {
                if (errno != ENOSYS)
                        goto fail;
                close(GUEST_MOUNT_ATTR_FD);
        } else {
                capabilities |= GUEST_MOUNT_CAP_OPEN_TREE_ATTR;
                if (move_guest_mount_fd(attr_fd, GUEST_MOUNT_ATTR_FD, false) < 0)
                        goto fail;
                attr_fd = GUEST_MOUNT_ATTR_FD;
        }

        if (guest_mount_unique_id(target, &target_id) < 0 || guest_mount_unique_id(clone, &clone_id) < 0 ||
            stat("/proc/self/ns/mnt", &namespace_stat) < 0 ||
            snprintf(mount_namespace_string, sizeof(mount_namespace_string), "%llu",
                     (unsigned long long) namespace_stat.st_ino) >= (int) sizeof(mount_namespace_string) ||
            stat("/proc/self/ns/user", &namespace_stat) < 0 ||
            snprintf(user_namespace_string, sizeof(user_namespace_string), "%llu",
                     (unsigned long long) namespace_stat.st_ino) >= (int) sizeof(user_namespace_string))
                goto fail;
        r = guest_statmount_by_fd(mount_fd, target_id);
        if (r < 0)
                goto fail;
        if (r > 0)
                capabilities |= GUEST_MOUNT_CAP_STATMOUNT_BY_FD;
        if (check_guest_mount_api(
                            capabilities,
                            strtoull(mount_namespace_string, NULL, 10),
                            strtoull(user_namespace_string, NULL, 10),
                            target_id,
                            clone_id,
                            false,
                            getpid()) < 0)
                goto fail;

        child = fork();
        if (child < 0)
                goto fail;
        if (child == 0)
                _exit(check_guest_mount_api(
                                      capabilities,
                                      strtoull(mount_namespace_string, NULL, 10),
                                      strtoull(user_namespace_string, NULL, 10),
                                      target_id,
                                      clone_id,
                                      false,
                                      getppid()) < 0 ? 167 : 0);
        if (waitpid(child, &status, 0) != child ||
            !WIFEXITED(status) || WEXITSTATUS(status) != 0 ||
            snprintf(capabilities_string, sizeof(capabilities_string), "%u", capabilities) >=
                            (int) sizeof(capabilities_string) ||
            snprintf(target_id_string, sizeof(target_id_string), "%llu", (unsigned long long) target_id) >=
                            (int) sizeof(target_id_string) ||
            snprintf(clone_id_string, sizeof(clone_id_string), "%llu", (unsigned long long) clone_id) >=
                            (int) sizeof(clone_id_string))
                goto fail;

        execl(self,
              self,
              "--guest-exec-target",
              "--expect-mount-api",
              capabilities_string,
              mount_namespace_string,
              user_namespace_string,
              target_id_string,
              clone_id_string,
              NULL);
fail:
        if (fd >= 0)
                close(fd);
        if (!fixed_fds) {
                if (attr_fd >= 0)
                        close(attr_fd);
                if (clone_fd >= 0)
                        close(clone_fd);
                if (context_fd >= 0)
                        close(context_fd);
                if (mount_fd >= 0)
                        close(mount_fd);
                if (pick_fd >= 0)
                        close(pick_fd);
        }
        cleanup_guest_mount_api();
        return -EPROTO;
}

static int write_guest_namespace_file(pid_t pid, const char *name, const char *value) {
        char path[PATH_MAX];
        size_t length = strlen(value), written = 0;
        int fd;

        if (snprintf(path, sizeof(path), "/proc/%ld/%s", (long) pid, name) >= (int) sizeof(path))
                return -EOVERFLOW;
        fd = open(path, O_WRONLY | O_CLOEXEC);
        if (fd < 0)
                return -errno;
        while (written < length) {
                ssize_t n = write(fd, value + written, length - written);

                if (n < 0) {
                        int error = -errno;

                        close(fd);
                        return error;
                }
                written += n;
        }
        return close(fd) < 0 ? -errno : 0;
}

static int map_guest_user_namespace(pid_t pid, uid_t uid, gid_t gid) {
        char map[64];
        int r;

        r = write_guest_namespace_file(pid, "setgroups", "deny\n");
        if (r < 0 && r != -ENOENT)
                return r;
        if (snprintf(map, sizeof(map), "0 %u 1\n", uid) >= (int) sizeof(map))
                return -EOVERFLOW;
        r = write_guest_namespace_file(pid, "uid_map", map);
        if (r < 0)
                return r;
        if (snprintf(map, sizeof(map), "0 %u 1\n", gid) >= (int) sizeof(map))
                return -EOVERFLOW;
        return write_guest_namespace_file(pid, "gid_map", map);
}

static int test_guest_mount_api_exec(const char *self) {
        int go_pipe[2] = { -1, -1 }, ready_pipe[2] = { -1, -1 }, status;
        uid_t uid = getuid();
        gid_t gid = getgid();
        pid_t child;
        char byte;
        int fd;

        errno = 0;
        fd = syscall(SYS_fsopen, "tmpfs", 0);
        if (fd >= 0 || errno != EPERM) {
                if (fd >= 0)
                        close(fd);
                return EXIT_FAILURE;
        }
        if (pipe2(ready_pipe, O_CLOEXEC) < 0 || pipe2(go_pipe, O_CLOEXEC) < 0)
                return EXIT_FAILURE;
        child = syscall(SYS_clone, CLONE_NEWUSER | SIGCHLD, NULL, NULL, NULL, 0);
        if (child < 0)
                goto fail;
        if (child == 0) {
                close(ready_pipe[0]);
                close(go_pipe[1]);
                if (write(ready_pipe[1], "r", 1) != 1 ||
                    read(go_pipe[0], &byte, 1) != 1 || byte != 'g' ||
                    setresgid(0, 0, 0) < 0 || setresuid(0, 0, 0) < 0 || unshare(CLONE_NEWNS) < 0)
                        _exit(168);
                close(ready_pipe[1]);
                close(go_pipe[0]);
                _exit(run_guest_mount_api_exec(self) < 0 ? 169 : 0);
        }
        close(ready_pipe[1]);
        ready_pipe[1] = -1;
        close(go_pipe[0]);
        go_pipe[0] = -1;
        if (read(ready_pipe[0], &byte, 1) != 1 || byte != 'r' ||
            map_guest_user_namespace(child, uid, gid) < 0 || write(go_pipe[1], "g", 1) != 1)
                goto fail_child;
        close(ready_pipe[0]);
        ready_pipe[0] = -1;
        close(go_pipe[1]);
        go_pipe[1] = -1;
        if (waitpid(child, &status, 0) != child ||
            !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                return EXIT_FAILURE;
        return EXIT_SUCCESS;

fail_child:
        close(go_pipe[1]);
        go_pipe[1] = -1;
        waitpid(child, &status, 0);
fail:
        for (size_t i = 0; i < 2; i++) {
                if (ready_pipe[i] >= 0)
                        close(ready_pipe[i]);
                if (go_pipe[i] >= 0)
                        close(go_pipe[i]);
        }
        return EXIT_FAILURE;
}

static int move_guest_socket_fd(int fd, int target, bool cloexec) {
        int flags;

        if (fd < 0)
                return -EBADF;
        if (fd != target) {
                int r = cloexec ? dup3(fd, target, O_CLOEXEC) : dup2(fd, target);

                if (r != target)
                        return -errno;
                if (close(fd) < 0)
                        return -errno;
                return target;
        }

        flags = fcntl(fd, F_GETFD);
        if (flags < 0 || fcntl(fd, F_SETFD, cloexec ? flags | FD_CLOEXEC : flags & ~FD_CLOEXEC) < 0)
                return -errno;
        return target;
}

static int make_guest_unix_socket_address(
                struct sockaddr_un *ret_address,
                socklen_t *ret_size,
                pid_t owner) {

        struct sockaddr_un address = {
                .sun_family = AF_UNIX,
        };
        int n;

        n = snprintf(address.sun_path + 1, sizeof(address.sun_path) - 1, "kvm-socket-state-%ld", (long) owner);
        if (n <= 0 || (size_t) n >= sizeof(address.sun_path) - 1)
                return -EOVERFLOW;
        *ret_address = address;
        *ret_size = offsetof(struct sockaddr_un, sun_path) + 1 + n;
        return 0;
}

static int check_guest_socket_int_option(int fd, int level, int option, int expected) {
        int value = INT_MIN;
        socklen_t size = sizeof(value);

        if (getsockopt(fd, level, option, &value, &size) < 0)
                return -errno;
        return size == sizeof(value) && value == expected ? 0 : -EPROTO;
}

static int check_guest_socket_timeout(int fd, int option, const struct timeval *expected) {
        struct timeval value = {};
        socklen_t size = sizeof(value);

        if (getsockopt(fd, SOL_SOCKET, option, &value, &size) < 0)
                return -errno;
        return size == sizeof(value) && value.tv_sec == expected->tv_sec &&
                       value.tv_usec == expected->tv_usec ? 0 : -EPROTO;
}

static int check_guest_socket_state(bool exec_completed, pid_t owner) {
        static const int persistent_fds[] = {
                GUEST_UNIX_LISTENER_FD,
                GUEST_UNIX_SERVER_FD,
                GUEST_UNIX_CLIENT_FD,
                GUEST_UNIX_DUPLICATE_FD,
                GUEST_UNIX_PENDING_FD,
                GUEST_TCP_LISTENER_FD,
                GUEST_TCP_SERVER_FD,
                GUEST_TCP_CLIENT_FD,
                GUEST_TCP_PENDING_FD,
                GUEST_UDP_LEFT_FD,
                GUEST_UDP_RIGHT_FD,
                GUEST_SOCKET_ERROR_FD,
        };
        const struct timeval timeout = {
                .tv_sec = 2,
                .tv_usec = 500000,
        };
        struct sockaddr_in address, peer, udp_left, udp_right;
        struct sockaddr_un expected_unix, unix_address;
        struct ucred credentials;
        socklen_t expected_unix_size, size;
        int r;

        for (size_t i = 0; i < sizeof(persistent_fds) / sizeof(persistent_fds[0]); i++)
                if ((fcntl(persistent_fds[i], F_GETFD) & FD_CLOEXEC) != 0)
                        return -EPROTO;
        errno = 0;
        r = fcntl(GUEST_SOCKET_CLOEXEC_FD, F_GETFD);
        if ((exec_completed && (r >= 0 || errno != EBADF)) ||
            (!exec_completed && (r < 0 || (r & FD_CLOEXEC) == 0)))
                return -EPROTO;

        if (make_guest_unix_socket_address(&expected_unix, &expected_unix_size, owner) < 0)
                return -EPROTO;
        size = sizeof(unix_address);
        if (getsockname(GUEST_UNIX_LISTENER_FD, (struct sockaddr*) &unix_address, &size) < 0 ||
            size != expected_unix_size || memcmp(&unix_address, &expected_unix, size) != 0)
                return -EPROTO;
        size = sizeof(unix_address);
        if (getpeername(GUEST_UNIX_CLIENT_FD, (struct sockaddr*) &unix_address, &size) < 0 ||
            size != expected_unix_size || memcmp(&unix_address, &expected_unix, size) != 0 ||
            check_guest_socket_int_option(GUEST_UNIX_LISTENER_FD, SOL_SOCKET, SO_ACCEPTCONN, 1) < 0 ||
            check_guest_socket_int_option(GUEST_UNIX_SERVER_FD, SOL_SOCKET, SO_PASSCRED, 1) < 0 ||
            check_guest_socket_int_option(GUEST_UNIX_DUPLICATE_FD, SOL_SOCKET, SO_KEEPALIVE, 1) < 0 ||
            check_guest_socket_timeout(GUEST_UNIX_SERVER_FD, SO_RCVTIMEO, &timeout) < 0 ||
            check_guest_socket_timeout(GUEST_UNIX_DUPLICATE_FD, SO_SNDTIMEO, &timeout) < 0)
                return -EPROTO;
        size = sizeof(credentials);
        if (getsockopt(GUEST_UNIX_SERVER_FD, SOL_SOCKET, SO_PEERCRED, &credentials, &size) < 0 ||
            size != sizeof(credentials) || credentials.pid != owner || credentials.uid != getuid() ||
            credentials.gid != getgid())
                return -EPROTO;

        size = sizeof(address);
        if (getsockname(GUEST_TCP_LISTENER_FD, (struct sockaddr*) &address, &size) < 0 ||
            size != sizeof(address) || address.sin_family != AF_INET || address.sin_port == 0 ||
            address.sin_addr.s_addr != htonl(INADDR_LOOPBACK) ||
            check_guest_socket_int_option(GUEST_TCP_LISTENER_FD, SOL_SOCKET, SO_ACCEPTCONN, 1) < 0 ||
            check_guest_socket_int_option(GUEST_TCP_SERVER_FD, IPPROTO_TCP, TCP_NODELAY, 1) < 0 ||
            check_guest_socket_int_option(GUEST_TCP_CLIENT_FD, IPPROTO_TCP, TCP_NODELAY, 1) < 0 ||
            check_guest_socket_int_option(GUEST_TCP_SERVER_FD, SOL_SOCKET, SO_KEEPALIVE, 1) < 0 ||
            check_guest_socket_timeout(GUEST_TCP_SERVER_FD, SO_RCVTIMEO, &timeout) < 0)
                return -EPROTO;
        size = sizeof(peer);
        if (getpeername(GUEST_TCP_CLIENT_FD, (struct sockaddr*) &peer, &size) < 0 ||
            size != sizeof(peer) || peer.sin_port != address.sin_port ||
            peer.sin_addr.s_addr != address.sin_addr.s_addr)
                return -EPROTO;
        size = sizeof(peer);
        if (getsockname(GUEST_TCP_SERVER_FD, (struct sockaddr*) &peer, &size) < 0 ||
            size != sizeof(peer) || peer.sin_port != address.sin_port ||
            peer.sin_addr.s_addr != address.sin_addr.s_addr)
                return -EPROTO;

        size = sizeof(udp_left);
        if (getsockname(GUEST_UDP_LEFT_FD, (struct sockaddr*) &udp_left, &size) < 0 ||
            size != sizeof(udp_left) || udp_left.sin_port == 0)
                return -EPROTO;
        size = sizeof(udp_right);
        if (getsockname(GUEST_UDP_RIGHT_FD, (struct sockaddr*) &udp_right, &size) < 0 ||
            size != sizeof(udp_right) || udp_right.sin_port == 0)
                return -EPROTO;
        size = sizeof(peer);
        if (getpeername(GUEST_UDP_LEFT_FD, (struct sockaddr*) &peer, &size) < 0 ||
            size != sizeof(peer) || peer.sin_port != udp_right.sin_port ||
            getpeername(GUEST_UDP_RIGHT_FD, (struct sockaddr*) &peer, &size) < 0 ||
            peer.sin_port != udp_left.sin_port ||
            check_guest_socket_int_option(GUEST_UDP_LEFT_FD, IPPROTO_IP, IP_TTL, 42) < 0 ||
            check_guest_socket_timeout(GUEST_UDP_RIGHT_FD, SO_RCVTIMEO, &timeout) < 0)
                return -EPROTO;
        return 0;
}

static int cleanup_guest_socket_state(void) {
        int result = 0;

        for (int fd = GUEST_UNIX_LISTENER_FD; fd <= GUEST_SOCKET_CLOEXEC_FD; fd++)
                if (close(fd) < 0 && errno != EBADF)
                        result = -errno;
        return result;
}

static int receive_guest_unix_credentials(pid_t owner) {
        _Alignas(struct cmsghdr) unsigned char control[CMSG_SPACE(sizeof(struct ucred))] = {};
        char payload[16] = {};
        struct iovec iov = {
                .iov_base = payload,
                .iov_len = sizeof(payload),
        };
        struct msghdr message = {
                .msg_iov = &iov,
                .msg_iovlen = 1,
                .msg_control = control,
                .msg_controllen = sizeof(control),
        };
        struct cmsghdr *cmsg;
        struct ucred credentials;

        if (recvmsg(GUEST_UNIX_SERVER_FD, &message, 0) != 9 || memcmp(payload, "unix-exec", 9) != 0)
                return -EPROTO;
        cmsg = CMSG_FIRSTHDR(&message);
        if (!cmsg || cmsg->cmsg_level != SOL_SOCKET || cmsg->cmsg_type != SCM_CREDENTIALS ||
            cmsg->cmsg_len != CMSG_LEN(sizeof(credentials)))
                return -EPROTO;
        memcpy(&credentials, CMSG_DATA(cmsg), sizeof(credentials));
        return credentials.pid == owner && credentials.uid == getuid() && credentials.gid == getgid() ?
                0 : -EPROTO;
}

static int make_guest_notify_address(
                const char *path,
                struct sockaddr_un *ret_address,
                socklen_t *ret_size) {

        struct sockaddr_un address = {
                .sun_family = AF_UNIX,
        };
        size_t length;

        if (!path || !path[0])
                return -EINVAL;
        length = strlen(path);
        if (path[0] == '@') {
                if (length > sizeof(address.sun_path))
                        return -ENAMETOOLONG;
                memcpy(address.sun_path + 1, path + 1, length - 1);
                *ret_size = offsetof(struct sockaddr_un, sun_path) + length;
        } else {
                if (length >= sizeof(address.sun_path))
                        return -ENAMETOOLONG;
                memcpy(address.sun_path, path, length + 1);
                *ret_size = offsetof(struct sockaddr_un, sun_path) + length + 1;
        }
        *ret_address = address;
        return 0;
}

static int send_guest_notification(const struct sockaddr_un *address, socklen_t address_size, const char *payload) {
        struct iovec iov = {
                .iov_base = (char*) payload,
                .iov_len = strlen(payload),
        };
        struct msghdr message = {
                .msg_name = (struct sockaddr*) address,
                .msg_namelen = address_size,
                .msg_iov = &iov,
                .msg_iovlen = 1,
        };
        int fd;
        ssize_t n;

        fd = socket(AF_UNIX, SOCK_DGRAM | SOCK_CLOEXEC, 0);
        if (fd < 0)
                return -errno;
        n = sendmsg(fd, &message, MSG_NOSIGNAL);
        if (close(fd) < 0 && n >= 0)
                return -errno;
        return n == (ssize_t) iov.iov_len ? 0 : n < 0 ? -errno : -EIO;
}

static int receive_guest_notification(int fd, const char *payload, pid_t sender) {
        _Alignas(struct cmsghdr) unsigned char control[CMSG_SPACE(sizeof(struct ucred))] = {};
        char buffer[128] = {};
        struct iovec iov = {
                .iov_base = buffer,
                .iov_len = sizeof(buffer),
        };
        struct msghdr message = {
                .msg_iov = &iov,
                .msg_iovlen = 1,
                .msg_control = control,
                .msg_controllen = sizeof(control),
        };
        struct pollfd pollfd = {
                .fd = fd,
                .events = POLLIN,
        };
        struct cmsghdr *cmsg;
        struct ucred credentials;
        ssize_t n;

        if (poll(&pollfd, 1, 5000) != 1 || pollfd.revents != POLLIN)
                return -ETIMEDOUT;
        n = recvmsg(fd, &message, 0);
        if (n != (ssize_t) strlen(payload) || memcmp(buffer, payload, (size_t) n) != 0 ||
            (message.msg_flags & (MSG_TRUNC | MSG_CTRUNC)) != 0)
                return -EPROTO;
        cmsg = CMSG_FIRSTHDR(&message);
        if (!cmsg || cmsg->cmsg_level != SOL_SOCKET || cmsg->cmsg_type != SCM_CREDENTIALS ||
            cmsg->cmsg_len != CMSG_LEN(sizeof(credentials)) || CMSG_NXTHDR(&message, cmsg))
                return -EPROTO;
        memcpy(&credentials, CMSG_DATA(cmsg), sizeof(credentials));
        return credentials.pid == sender && credentials.uid == getuid() && credentials.gid == getgid() ?
                0 : -EPROTO;
}

static uint64_t guest_timespec_usec(const struct timespec *value) {
        return (uint64_t) value->tv_sec * UINT64_C(1000000) + (uint64_t) value->tv_nsec / UINT64_C(1000);
}

static int guest_sleep_usec(uint64_t usec) {
        struct timespec delay = {
                .tv_sec = usec / UINT64_C(1000000),
                .tv_nsec = (long) ((usec % UINT64_C(1000000)) * UINT64_C(1000)),
        };
        int r;

        do
                r = clock_nanosleep(CLOCK_MONOTONIC, 0, &delay, &delay);
        while (r == EINTR);
        return r == 0 ? 0 : -r;
}

static int parse_guest_notify_environment(
                struct sockaddr_un *ret_address,
                socklen_t *ret_address_size,
                uint64_t *ret_watchdog_usec) {

        const char *notify_socket = getenv("NOTIFY_SOCKET"), *watchdog_pid = getenv("WATCHDOG_PID");
        const char *watchdog_usec = getenv("WATCHDOG_USEC");
        unsigned long long parsed_pid, parsed_usec;
        char *end;

        errno = 0;
        parsed_pid = watchdog_pid ? strtoull(watchdog_pid, &end, 10) : 0;
        if (!watchdog_pid || errno != 0 || *end || parsed_pid != (unsigned long long) getpid())
                return -EINVAL;
        errno = 0;
        parsed_usec = watchdog_usec ? strtoull(watchdog_usec, &end, 10) : 0;
        if (!watchdog_usec || errno != 0 || *end || parsed_usec < 100000 || parsed_usec > 10000000)
                return -EINVAL;
        if (make_guest_notify_address(notify_socket, ret_address, ret_address_size) < 0)
                return -EINVAL;
        *ret_watchdog_usec = parsed_usec;
        return 0;
}

static int test_guest_notify(void) {
        static const char child_payload[] = "STATUS=child-notification";
        static const char ready_payload[] = "READY=1\nSTATUS=guest-ready";
        static const char watchdog_payload[] = "WATCHDOG=1";
        struct sockaddr_un address;
        const char *notify_socket = getenv("NOTIFY_SOCKET");
        struct timespec before, after;
        socklen_t address_size;
        uint64_t parsed_usec;
        int fd = -1, result = EXIT_FAILURE, status, value = 1;
        pid_t child, waited;
        int source_kvm;

        if (parse_guest_notify_environment(&address, &address_size, &parsed_usec) < 0)
                goto finish;
        if (notify_socket[0] != '@')
                (void) unlink(notify_socket);
        fd = socket(AF_UNIX, SOCK_DGRAM | SOCK_CLOEXEC, 0);
        if (fd < 0 || setsockopt(fd, SOL_SOCKET, SO_PASSCRED, &value, sizeof(value)) < 0 ||
            bind(fd, (struct sockaddr*) &address, address_size) < 0)
                goto finish;

        if (send_guest_notification(&address, address_size, ready_payload) < 0 ||
            receive_guest_notification(fd, ready_payload, getpid()) < 0)
                goto finish;

        child = fork();
        if (child < 0)
                goto finish;
        if (child == 0)
                _exit(send_guest_notification(&address, address_size, child_payload) < 0 ? 1 : 0);
        if (receive_guest_notification(fd, child_payload, child) < 0)
                goto finish_child;
        do
                waited = waitpid(child, &status, 0);
        while (waited < 0 && errno == EINTR);
        if (waited != child || !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                goto finish;

        for (unsigned i = 0; i < 2; i++) {
                if (clock_gettime(CLOCK_MONOTONIC, &before) < 0)
                        goto finish;
                if (guest_sleep_usec(parsed_usec / 4) < 0 ||
                    send_guest_notification(&address, address_size, watchdog_payload) < 0 ||
                    receive_guest_notification(fd, watchdog_payload, getpid()) < 0 ||
                    clock_gettime(CLOCK_MONOTONIC, &after) < 0)
                        goto finish;
                uint64_t elapsed = guest_timespec_usec(&after) - guest_timespec_usec(&before);
                if (elapsed < parsed_usec / 4 || elapsed >= parsed_usec)
                        goto finish;
        }

        source_kvm = guest_process_has_kvm_fd();
        if (source_kvm < 0)
                goto finish;
        printf(
                        "KVM_NOTIFY_OK source_kvm=%d main_pid=%ld child_pid=%ld watchdog_usec=%llu\n",
                        source_kvm,
                        (long) getpid(),
                        (long) child,
                        (unsigned long long) parsed_usec);
        result = EXIT_SUCCESS;
        goto finish;

finish_child:
        kill(child, SIGKILL);
        (void) waitpid(child, NULL, 0);
finish:
        if (fd >= 0)
                close(fd);
        if (notify_socket && notify_socket[0] != '@')
                (void) unlink(notify_socket);
        return result;
}

static int test_guest_notify_service(const char *behavior) {
        static const char child_ready[] = "READY=1\nSTATUS=child-ready";
        static const char main_ready[] = "READY=1\nSTATUS=main-ready";
        static const char watchdog[] = "WATCHDOG=1";
        struct sockaddr_un address;
        socklen_t address_size;
        uint64_t watchdog_usec;
        pid_t child, waited;
        int source_kvm, status;

        if (parse_guest_notify_environment(&address, &address_size, &watchdog_usec) < 0)
                return EXIT_FAILURE;
        source_kvm = guest_process_has_kvm_fd();
        if (source_kvm < 0)
                return EXIT_FAILURE;

        if (strcmp(behavior, "ready") == 0) {
                if (send_guest_notification(&address, address_size, main_ready) < 0)
                        return EXIT_FAILURE;
                for (unsigned i = 0; i < 2; i++)
                        if (guest_sleep_usec(watchdog_usec / 4) < 0 ||
                            send_guest_notification(&address, address_size, watchdog) < 0)
                                return EXIT_FAILURE;
                printf("KVM_NOTIFY_SERVICE_READY source_kvm=%d pid=%ld\n", source_kvm, (long) getpid());
                return EXIT_SUCCESS;
        }

        if (strcmp(behavior, "child-ready") == 0) {
                child = fork();
                if (child < 0)
                        return EXIT_FAILURE;
                if (child == 0) {
                        if (send_guest_notification(&address, address_size, child_ready) < 0)
                                _exit(EXIT_FAILURE);
                        _exit(guest_sleep_usec(watchdog_usec / 8) < 0 ? EXIT_FAILURE : EXIT_SUCCESS);
                }
                do
                        waited = waitpid(child, &status, 0);
                while (waited < 0 && errno == EINTR);
                if (waited != child || !WIFEXITED(status) || WEXITSTATUS(status) != EXIT_SUCCESS)
                        return EXIT_FAILURE;
                printf(
                                "KVM_NOTIFY_SERVICE_CHILD_READY source_kvm=%d main_pid=%ld child_pid=%ld\n",
                                source_kvm,
                                (long) getpid(),
                                (long) child);
                return EXIT_SUCCESS;
        }

        if (strcmp(behavior, "watchdog-timeout") == 0) {
                if (send_guest_notification(&address, address_size, main_ready) < 0)
                        return EXIT_FAILURE;
                printf("KVM_NOTIFY_SERVICE_WATCHDOG_ARMED source_kvm=%d pid=%ld\n", source_kvm, (long) getpid());
                fflush(stdout);
                return guest_sleep_usec(watchdog_usec * 3) < 0 ? EXIT_FAILURE : 125;
        }

        if (strcmp(behavior, "readiness-timeout") == 0) {
                printf("KVM_NOTIFY_SERVICE_READINESS_PENDING source_kvm=%d pid=%ld\n", source_kvm, (long) getpid());
                fflush(stdout);
                return guest_sleep_usec(watchdog_usec * 3) < 0 ? EXIT_FAILURE : 125;
        }

        return EXIT_FAILURE;
}

static volatile sig_atomic_t guest_lifecycle_terminate = 0;
static volatile sig_atomic_t guest_lifecycle_restart = 0;
static volatile sig_atomic_t guest_lifecycle_reload = 0;

static void guest_lifecycle_term_handler(int signo) {
        (void) signo;
        guest_lifecycle_terminate = 1;
}

static void guest_lifecycle_restart_handler(int signo) {
        (void) signo;
        guest_lifecycle_restart = 1;
}

static void guest_lifecycle_reload_handler(int signo) {
        (void) signo;
        guest_lifecycle_reload = 1;
}

static int make_guest_lifecycle_path(const char *prefix, const char *suffix, char path[static PATH_MAX]) {
        if (!prefix || !prefix[0] || snprintf(path, PATH_MAX, "%s.%s", prefix, suffix) >= PATH_MAX)
                return -EOVERFLOW;
        return 0;
}

static int write_guest_lifecycle_file(const char *prefix, const char *suffix, const char *value, bool append) {
        char path[PATH_MAX];
        size_t length = strlen(value), offset = 0;
        int fd;

        if (make_guest_lifecycle_path(prefix, suffix, path) < 0)
                return -EOVERFLOW;
        fd = open(path, O_WRONLY | O_CREAT | O_CLOEXEC | (append ? O_APPEND : O_TRUNC), 0600);
        if (fd < 0)
                return -errno;
        while (offset < length) {
                ssize_t n = write(fd, value + offset, length - offset);

                if (n < 0) {
                        int error = -errno;

                        close(fd);
                        return error;
                }
                offset += (size_t) n;
        }
        return close(fd) < 0 ? -errno : 0;
}

static int notify_guest_lifecycle(const char *payload) {
        struct sockaddr_un address;
        const char *notify_socket = getenv("NOTIFY_SOCKET");
        socklen_t address_size;

        if (make_guest_notify_address(notify_socket, &address, &address_size) < 0)
                return -EINVAL;
        return send_guest_notification(&address, address_size, payload);
}

static int notify_guest_lifecycle_ready(void) {
        return notify_guest_lifecycle("READY=1\nSTATUS=lifecycle-ready");
}

static int record_guest_lifecycle_state(const char *prefix, pid_t child, int *ret_source_kvm) {
        char cgroup[PATH_MAX], state[PATH_MAX + 160];
        int source_kvm;

        source_kvm = guest_process_has_kvm_fd();
        if (source_kvm < 0 || read_current_cgroup(cgroup, sizeof(cgroup)) < 0 ||
            snprintf(
                            state,
                            sizeof(state),
                            "pid=%ld\nsource_kvm=%d\ncgroup=%s\nchild=%ld\n",
                            (long) getpid(),
                            source_kvm,
                            cgroup,
                            (long) child) >= (int) sizeof(state) ||
            write_guest_lifecycle_file(prefix, "ready", state, false) < 0)
                return -EIO;

        if (ret_source_kvm)
                *ret_source_kvm = source_kvm;
        return 0;
}

static int wait_guest_lifecycle_term_full(
                const char *prefix,
                pid_t child,
                bool notify,
                int ready_fd,
                bool restartable) {

        struct sigaction action = {
                .sa_handler = guest_lifecycle_term_handler,
        };
        struct sigaction restart_action = {
                .sa_handler = guest_lifecycle_restart_handler,
        };
        char state[128];
        int source_kvm;

        guest_lifecycle_terminate = 0;
        guest_lifecycle_restart = 0;
        if (sigemptyset(&action.sa_mask) < 0 || sigaction(SIGTERM, &action, NULL) < 0 ||
            (restartable &&
             (sigemptyset(&restart_action.sa_mask) < 0 || sigaction(SIGUSR1, &restart_action, NULL) < 0)) ||
            record_guest_lifecycle_state(prefix, child, &source_kvm) < 0 ||
            (notify && notify_guest_lifecycle_ready() < 0) ||
            (ready_fd >= 0 && write(ready_fd, "1", 1) != 1))
                return EXIT_FAILURE;
        if (ready_fd >= 0)
                close(ready_fd);

        printf(
                        "KVM_SERVICE_LIFECYCLE_READY source_kvm=%d pid=%ld child=%ld\n",
                        source_kvm,
                        (long) getpid(),
                        (long) child);
        fflush(stdout);
        while (!guest_lifecycle_terminate && !guest_lifecycle_restart)
                (void) pause();

        if (guest_lifecycle_restart) {
                if (snprintf(state, sizeof(state), "pid=%ld\n", (long) getpid()) >= (int) sizeof(state) ||
                    write_guest_lifecycle_file(prefix, "restart", state, true) < 0)
                        return EXIT_FAILURE;
                return 42;
        }

        if (snprintf(state, sizeof(state), "pid=%ld\n", (long) getpid()) >= (int) sizeof(state) ||
            write_guest_lifecycle_file(prefix, "term", state, false) < 0)
                return EXIT_FAILURE;
        return EXIT_SUCCESS;
}

static int wait_guest_lifecycle_term(const char *prefix, pid_t child) {
        return wait_guest_lifecycle_term_full(prefix, child, true, -EBADF, false);
}

static int record_guest_lifecycle_forking_run(const char *prefix) {
        char count_path[PATH_MAX], count_string[32], run[128];
        unsigned long count = 0;
        int r, source_kvm;

        if (make_guest_lifecycle_path(prefix, "count", count_path) < 0)
                return -EOVERFLOW;
        r = read_guest_text_file(count_path, count_string, sizeof(count_string));
        if (r >= 0) {
                char *end;

                errno = 0;
                count = strtoul(count_string, &end, 10);
                if (errno != 0 || end == count_string || *end || count == ULONG_MAX)
                        return -EINVAL;
        } else if (r != -ENOENT)
                return r;

        count++;
        source_kvm = guest_process_has_kvm_fd();
        if (source_kvm < 0 ||
            snprintf(count_string, sizeof(count_string), "%lu\n", count) >= (int) sizeof(count_string) ||
            write_guest_lifecycle_file(prefix, "count", count_string, false) < 0 ||
            snprintf(
                            run,
                            sizeof(run),
                            "run=%lu pid=%ld source_kvm=%d\n",
                            count,
                            (long) getpid(),
                            source_kvm) >= (int) sizeof(run) ||
            write_guest_lifecycle_file(prefix, "runs", run, true) < 0)
                return -EIO;
        return 0;
}

static int run_guest_lifecycle_forking(const char *prefix, bool write_pid_file, bool restartable) {
        char marker, pid_string[32];
        int pipe_fds[2], status;
        pid_t child;

        if (pipe2(pipe_fds, O_CLOEXEC) < 0)
                return EXIT_FAILURE;

        child = fork();
        if (child < 0)
                return EXIT_FAILURE;
        if (child == 0) {
                pid_t daemon;

                close(pipe_fds[0]);
                if (setsid() < 0)
                        _exit(EXIT_FAILURE);
                daemon = fork();
                if (daemon < 0)
                        _exit(EXIT_FAILURE);
                if (daemon > 0)
                        _exit(EXIT_SUCCESS);

                if ((write_pid_file &&
                     (snprintf(pid_string, sizeof(pid_string), "%ld\n", (long) getpid()) >= (int) sizeof(pid_string) ||
                      write_guest_lifecycle_file(prefix, "pid", pid_string, false) < 0)) ||
                    (restartable && record_guest_lifecycle_forking_run(prefix) < 0))
                        _exit(EXIT_FAILURE);
                return wait_guest_lifecycle_term_full(prefix, 0, false, pipe_fds[1], restartable);
        }

        close(pipe_fds[1]);
        ssize_t n;
        do
                n = read(pipe_fds[0], &marker, 1);
        while (n < 0 && errno == EINTR);
        close(pipe_fds[0]);
        if (waitpid(child, &status, 0) != child || n != 1 || marker != '1' ||
            !WIFEXITED(status) || WEXITSTATUS(status) != EXIT_SUCCESS)
                return EXIT_FAILURE;
        return EXIT_SUCCESS;
}

static int run_guest_lifecycle_restart(const char *prefix) {
        char count_path[PATH_MAX], count_string[32], run[128];
        unsigned long count = 0;
        int r, source_kvm;

        if (make_guest_lifecycle_path(prefix, "count", count_path) < 0)
                return EXIT_FAILURE;
        r = read_guest_text_file(count_path, count_string, sizeof(count_string));
        if (r >= 0) {
                char *end;

                errno = 0;
                count = strtoul(count_string, &end, 10);
                if (errno != 0 || end == count_string || *end || count == ULONG_MAX)
                        return EXIT_FAILURE;
        } else if (r != -ENOENT)
                return EXIT_FAILURE;

        count++;
        if (snprintf(count_string, sizeof(count_string), "%lu\n", count) >= (int) sizeof(count_string) ||
            write_guest_lifecycle_file(prefix, "count", count_string, false) < 0)
                return EXIT_FAILURE;
        source_kvm = guest_process_has_kvm_fd();
        if (source_kvm < 0 ||
            snprintf(
                            run,
                            sizeof(run),
                            "run=%lu pid=%ld source_kvm=%d\n",
                            count,
                            (long) getpid(),
                            source_kvm) >= (int) sizeof(run) ||
            write_guest_lifecycle_file(prefix, "runs", run, true) < 0)
                return EXIT_FAILURE;

        if (count < 3)
                return 42;
        return wait_guest_lifecycle_term(prefix, 0);
}

static int run_guest_lifecycle_oom(const char *prefix) {
        const size_t allocation = 4U * 1024U * 1024U;
        int source_kvm;

        if (record_guest_lifecycle_state(prefix, 0, &source_kvm) < 0 || notify_guest_lifecycle_ready() < 0)
                return EXIT_FAILURE;
        printf("KVM_SERVICE_LIFECYCLE_OOM source_kvm=%d pid=%ld\n", source_kvm, (long) getpid());
        fflush(stdout);

        for (;;) {
                void *memory = mmap(NULL, allocation, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

                if (memory == MAP_FAILED)
                        return EXIT_FAILURE;
                for (size_t offset = 0; offset < allocation; offset += 4096)
                        ((volatile uint8_t*) memory)[offset] = 0xa5;
        }
}

static int run_guest_lifecycle_activation(const char *prefix) {
        char response[] = "pong", request[sizeof(response)] = {};
        const char *listen_fds = getenv("LISTEN_FDS"), *listen_names = getenv("LISTEN_FDNAMES");
        const char *listen_pid = getenv("LISTEN_PID");
        uint64_t parsed_pid;
        socklen_t size;
        int accepted = -1, flags, source_kvm, type;

        if (parse_guest_uint64(listen_pid, &parsed_pid) < 0 || parsed_pid != (uint64_t) getpid() ||
            !listen_fds || strcmp(listen_fds, "1") != 0 ||
            !listen_names || strcmp(listen_names, "lifecycle") != 0)
                goto fail;
        flags = fcntl(3, F_GETFD);
        size = sizeof(type);
        if (flags < 0 || (flags & FD_CLOEXEC) != 0 ||
            getsockopt(3, SOL_SOCKET, SO_TYPE, &type, &size) < 0 || size != sizeof(type) || type != SOCK_STREAM)
                goto fail;
        accepted = accept4(3, NULL, NULL, SOCK_CLOEXEC);
        if (accepted < 0 || recv(accepted, request, sizeof(request) - 1, MSG_WAITALL) != 4 ||
            memcmp(request, "ping", 4) != 0 || record_guest_lifecycle_state(prefix, 0, &source_kvm) < 0 ||
            send(accepted, response, sizeof(response) - 1, MSG_NOSIGNAL) != (ssize_t) sizeof(response) - 1)
                goto fail;
        close(accepted);
        printf("KVM_SERVICE_LIFECYCLE_ACTIVATION source_kvm=%d pid=%ld fd=3\n", source_kvm, (long) getpid());
        return EXIT_SUCCESS;

fail:
        if (accepted >= 0)
                close(accepted);
        return EXIT_FAILURE;
}

static int test_guest_service_command(const char *phase, const char *prefix, const char *behavior) {
        struct sigaction action = {
                .sa_handler = guest_lifecycle_term_handler,
        };
        char cgroup[PATH_MAX], event[PATH_MAX + 160];
        int source_kvm;

        source_kvm = guest_process_has_kvm_fd();
        if (source_kvm < 0 || read_current_cgroup(cgroup, sizeof(cgroup)) < 0 ||
            snprintf(
                            event,
                            sizeof(event),
                            "phase=%s pid=%ld source_kvm=%d behavior=%s cgroup=%s\n",
                            phase,
                            (long) getpid(),
                            source_kvm,
                            behavior,
                            cgroup) >= (int) sizeof(event) ||
            write_guest_lifecycle_file(prefix, "events", event, true) < 0)
                return EXIT_FAILURE;

        if (strcmp(behavior, "success") == 0)
                return EXIT_SUCCESS;
        if (strcmp(behavior, "skip") == 0)
                return 1;
        if (strcmp(behavior, "condition-fail") == 0)
                return 255;
        if (strcmp(behavior, "fail") == 0)
                return 42;
        if (strcmp(behavior, "hold") != 0)
                return EXIT_FAILURE;

        guest_lifecycle_terminate = 0;
        if (sigemptyset(&action.sa_mask) < 0 || sigaction(SIGTERM, &action, NULL) < 0)
                return EXIT_FAILURE;
        while (!guest_lifecycle_terminate)
                (void) pause();
        return EXIT_SUCCESS;
}

static int write_guest_lsm_attr(const char *prefix, const char *suffix, const char *path) {
        char value[4096];
        ssize_t n;
        int fd;

        fd = open(path, O_RDONLY | O_CLOEXEC | O_NOCTTY);
        if (fd < 0) {
                if (errno == ENOENT)
                        strcpy(value, "<unavailable>\n");
                else if (errno == EACCES || errno == EPERM)
                        strcpy(value, "<inaccessible>\n");
                else
                        return -1;
        } else {
                do
                        n = read(fd, value, sizeof(value) - 2);
                while (n < 0 && errno == EINTR);
                int error = errno;
                close(fd);
                if (n < 0 && (error == EINVAL || error == ENODATA))
                        strcpy(value, "<unset>\n");
                else if (n < 0 && (error == EACCES || error == EPERM))
                        strcpy(value, "<inaccessible>\n");
                else if (n < 0)
                        return -1;
                else if (n == 0)
                        strcpy(value, "<unset>\n");
                else {
                        while (n > 0 && value[n - 1] == '\0')
                                n--;
                        if (n == 0 || value[n - 1] != '\n')
                                value[n++] = '\n';
                        value[n] = '\0';
                }
        }

        return write_guest_lifecycle_file(prefix, suffix, value, false);
}

static int test_guest_lsm_state(const char *prefix) {
        char event[160];
        int source_kvm;

        source_kvm = guest_process_has_kvm_fd();
        if (source_kvm < 0 ||
            snprintf(event, sizeof(event), "source_kvm=%d secure=%lu pid=%ld\n",
                     source_kvm, getauxval(AT_SECURE), (long) getpid()) >= (int) sizeof(event) ||
            write_guest_lifecycle_file(prefix, "events", event, false) < 0)
                return EXIT_FAILURE;

        static const struct {
                const char *suffix;
                const char *path;
        } attributes[] = {
                { "attr-current", "/proc/self/attr/current" },
                { "attr-prev", "/proc/self/attr/prev" },
                { "apparmor-current", "/proc/self/attr/apparmor/current" },
                { "apparmor-prev", "/proc/self/attr/apparmor/prev" },
                { "selinux-current", "/proc/self/attr/selinux/current" },
                { "selinux-prev", "/proc/self/attr/selinux/prev" },
                { "selinux-exec", "/proc/self/attr/selinux/exec" },
                { "selinux-fscreate", "/proc/self/attr/selinux/fscreate" },
                { "selinux-keycreate", "/proc/self/attr/selinux/keycreate" },
                { "selinux-sockcreate", "/proc/self/attr/selinux/sockcreate" },
        };

        for (size_t i = 0; i < sizeof(attributes) / sizeof(attributes[0]); i++)
                if (write_guest_lsm_attr(prefix, attributes[i].suffix, attributes[i].path) < 0)
                        return EXIT_FAILURE;

        return EXIT_SUCCESS;
}

static int test_guest_service_dbus(const char *name, const char *prefix) {
        typedef struct sd_bus sd_bus;
        int (*bus_open_user)(sd_bus **ret);
        int (*bus_request_name)(sd_bus *bus, const char *requested_name, uint64_t flags);
        sd_bus* (*bus_flush_close_unref)(sd_bus *bus);
        struct sigaction action = {
                .sa_handler = guest_lifecycle_term_handler,
        };
        sd_bus *bus = NULL;
        void *library;
        int result = EXIT_FAILURE;

        library = dlopen("libsystemd.so.0", RTLD_NOW | RTLD_LOCAL);
        if (!library)
                return EXIT_FAILURE;
        bus_open_user = dlsym(library, "sd_bus_open_user");
        bus_request_name = dlsym(library, "sd_bus_request_name");
        bus_flush_close_unref = dlsym(library, "sd_bus_flush_close_unref");
        if (!bus_open_user || !bus_request_name || !bus_flush_close_unref ||
            bus_open_user(&bus) < 0 || bus_request_name(bus, name, 0) < 0 ||
            test_guest_service_command("dbus", prefix, "success") != EXIT_SUCCESS)
                goto finish;

        guest_lifecycle_terminate = 0;
        if (sigemptyset(&action.sa_mask) < 0 || sigaction(SIGTERM, &action, NULL) < 0)
                goto finish;
        while (!guest_lifecycle_terminate)
                (void) pause();
        result = EXIT_SUCCESS;

finish:
        if (bus)
                bus = bus_flush_close_unref(bus);
        if (dlclose(library) < 0)
                result = EXIT_FAILURE;
        return result;
}

static int test_guest_service_notify_reload(const char *prefix) {
        struct sigaction action = {
                .sa_handler = guest_lifecycle_term_handler,
        };
        struct sigaction reload_action = {
                .sa_handler = guest_lifecycle_reload_handler,
        };

        guest_lifecycle_terminate = 0;
        guest_lifecycle_reload = 0;
        if (sigemptyset(&action.sa_mask) < 0 || sigaction(SIGTERM, &action, NULL) < 0 ||
            sigemptyset(&reload_action.sa_mask) < 0 || sigaction(SIGHUP, &reload_action, NULL) < 0 ||
            test_guest_service_command("notify-reload", prefix, "success") != EXIT_SUCCESS ||
            notify_guest_lifecycle_ready() < 0)
                return EXIT_FAILURE;

        while (!guest_lifecycle_terminate) {
                while (!guest_lifecycle_reload && !guest_lifecycle_terminate)
                        (void) pause();
                if (guest_lifecycle_terminate)
                        break;

                struct timespec now;
                char notification[128];
                uint64_t monotonic_usec;

                guest_lifecycle_reload = 0;
                if (clock_gettime(CLOCK_MONOTONIC, &now) < 0)
                        return EXIT_FAILURE;
                monotonic_usec = (uint64_t) now.tv_sec * UINT64_C(1000000) + (uint64_t) now.tv_nsec / 1000;
                if (snprintf(
                                    notification,
                                    sizeof(notification),
                                    "RELOADING=1\nMONOTONIC_USEC=%" PRIu64 "\nSTATUS=lifecycle-reloading",
                                    monotonic_usec) >= (int) sizeof(notification) ||
                    notify_guest_lifecycle(notification) < 0 ||
                    test_guest_service_command("notify-reload-sighup", prefix, "success") != EXIT_SUCCESS ||
                    notify_guest_lifecycle_ready() < 0)
                        return EXIT_FAILURE;
        }
        return EXIT_SUCCESS;
}

static int test_guest_service_lifecycle(const char *behavior, const char *prefix) {
        if (strcmp(behavior, "hold") == 0)
                return wait_guest_lifecycle_term(prefix, 0);

        if (strcmp(behavior, "forking") == 0)
                return run_guest_lifecycle_forking(prefix, true, false);

        if (strcmp(behavior, "forking-restart") == 0)
                return run_guest_lifecycle_forking(prefix, true, true);

        if (strcmp(behavior, "forking-no-pidfile") == 0)
                return run_guest_lifecycle_forking(prefix, false, false);

        if (strcmp(behavior, "forking-fail") == 0) {
                char state[64];
                int source_kvm = guest_process_has_kvm_fd();

                if (source_kvm < 0 ||
                    snprintf(state, sizeof(state), "pid=%ld\nsource_kvm=%d\n", (long) getpid(), source_kvm) >=
                            (int) sizeof(state) ||
                    write_guest_lifecycle_file(prefix, "fail", state, false) < 0)
                        return EXIT_FAILURE;
                return 42;
        }

        if (strcmp(behavior, "ignore-term") == 0) {
                int source_kvm;

                if (signal(SIGTERM, SIG_IGN) == SIG_ERR ||
                    record_guest_lifecycle_state(prefix, 0, &source_kvm) < 0 || notify_guest_lifecycle_ready() < 0)
                        return EXIT_FAILURE;
                printf("KVM_SERVICE_LIFECYCLE_IGNORE_TERM source_kvm=%d pid=%ld\n", source_kvm, (long) getpid());
                fflush(stdout);
                for (;;)
                        (void) pause();
        }

        if (strcmp(behavior, "restart") == 0)
                return run_guest_lifecycle_restart(prefix);

        if (strcmp(behavior, "oom") == 0)
                return run_guest_lifecycle_oom(prefix);

        if (strcmp(behavior, "mixed-child") == 0) {
                pid_t child = fork();

                if (child < 0)
                        return EXIT_FAILURE;
                if (child == 0) {
                        if (signal(SIGTERM, SIG_IGN) == SIG_ERR)
                                _exit(EXIT_FAILURE);
                        for (;;)
                                (void) pause();
                }
                return wait_guest_lifecycle_term(prefix, child);
        }

        if (strcmp(behavior, "activation") == 0)
                return run_guest_lifecycle_activation(prefix);

        return EXIT_FAILURE;
}

static int validate_guest_socket_state_exec(void) {
        char buffer[32] = {}, datagram[16] = {};
        int accepted = -1, error = 0, result = EXIT_FAILURE;
        socklen_t size = sizeof(error);

        if (check_guest_socket_state(true, getpid()) < 0 || receive_guest_unix_credentials(getpid()) < 0 ||
            recv(GUEST_UNIX_SERVER_FD, buffer, 1, 0) != 0 ||
            send(GUEST_UNIX_DUPLICATE_FD, "reply", 5, 0) != 5 ||
            recv(GUEST_UNIX_CLIENT_FD, buffer, 5, MSG_WAITALL) != 5 || memcmp(buffer, "reply", 5) != 0)
                goto finish;
        accepted = accept4(GUEST_UNIX_LISTENER_FD, NULL, NULL, SOCK_CLOEXEC);
        if (accepted < 0 || send(GUEST_UNIX_PENDING_FD, "u", 1, 0) != 1 ||
            recv(accepted, buffer, 1, 0) != 1 || buffer[0] != 'u' || close(accepted) < 0)
                goto finish;
        accepted = -1;

        if (recv(GUEST_TCP_SERVER_FD, buffer, 16, MSG_WAITALL) != 16 ||
            memcmp(buffer, "tcp-exectcp-fork", 16) != 0)
                goto finish;
        accepted = accept4(GUEST_TCP_LISTENER_FD, NULL, NULL, SOCK_CLOEXEC);
        if (accepted < 0 || send(GUEST_TCP_PENDING_FD, "t", 1, 0) != 1 ||
            recv(accepted, buffer, 1, 0) != 1 || buffer[0] != 't' || close(accepted) < 0)
                goto finish;
        accepted = -1;

        if (recv(GUEST_UDP_RIGHT_FD, datagram, sizeof(datagram), 0) != 8 ||
            memcmp(datagram, "udp-exec", 8) != 0 ||
            recv(GUEST_UDP_RIGHT_FD, datagram, sizeof(datagram), 0) != 8 ||
            memcmp(datagram, "udp-fork", 8) != 0 ||
            send(GUEST_UDP_RIGHT_FD, "response", 8, 0) != 8 ||
            recv(GUEST_UDP_LEFT_FD, datagram, sizeof(datagram), 0) != 8 ||
            memcmp(datagram, "response", 8) != 0 ||
            getsockopt(GUEST_SOCKET_ERROR_FD, SOL_SOCKET, SO_ERROR, &error, &size) < 0 ||
            size != sizeof(error) || error != ECONNREFUSED)
                goto finish;
        error = INT_MIN;
        size = sizeof(error);
        if (getsockopt(GUEST_SOCKET_ERROR_FD, SOL_SOCKET, SO_ERROR, &error, &size) < 0 || error != 0)
                goto finish;
        result = EXIT_SUCCESS;

finish:
        if (accepted >= 0)
                close(accepted);
        if (cleanup_guest_socket_state() < 0)
                result = EXIT_FAILURE;
        if (result == EXIT_SUCCESS)
                printf("KVM_SOCKET_STATE_OK\n");
        return result;
}

static int run_guest_socket_state_exec(const char *self) {
        const struct timeval timeout = {
                .tv_sec = 2,
                .tv_usec = 500000,
        };
        struct sockaddr_in address = {
                .sin_family = AF_INET,
                .sin_addr.s_addr = htonl(INADDR_LOOPBACK),
        };
        struct sockaddr_in left_address, right_address;
        struct sockaddr_un unix_address;
        socklen_t address_size, unix_address_size;
        int accepted = -1, client = -1, error_fd = -1, listener = -1, pending = -1;
        int udp_left = -1, udp_right = -1, value = 1, status;
        bool fixed_fds = false;
        struct pollfd pollfd;
        char byte;
        pid_t child;

        if (make_guest_unix_socket_address(&unix_address, &unix_address_size, getpid()) < 0)
                goto fail;
        listener = socket(AF_UNIX, SOCK_STREAM, 0);
        if (listener < 0 || bind(listener, (struct sockaddr*) &unix_address, unix_address_size) < 0 ||
            listen(listener, 2) < 0 || move_guest_socket_fd(listener, GUEST_UNIX_LISTENER_FD, false) < 0)
                goto fail;
        listener = GUEST_UNIX_LISTENER_FD;
        client = socket(AF_UNIX, SOCK_STREAM, 0);
        if (client < 0 || connect(client, (struct sockaddr*) &unix_address, unix_address_size) < 0)
                goto fail;
        accepted = accept(listener, NULL, NULL);
        if (accepted < 0 || move_guest_socket_fd(accepted, GUEST_UNIX_SERVER_FD, false) < 0 ||
            move_guest_socket_fd(client, GUEST_UNIX_CLIENT_FD, false) < 0)
                goto fail;
        accepted = GUEST_UNIX_SERVER_FD;
        client = GUEST_UNIX_CLIENT_FD;
        if (dup2(accepted, GUEST_UNIX_DUPLICATE_FD) != GUEST_UNIX_DUPLICATE_FD ||
            setsockopt(accepted, SOL_SOCKET, SO_PASSCRED, &value, sizeof(value)) < 0 ||
            setsockopt(accepted, SOL_SOCKET, SO_KEEPALIVE, &value, sizeof(value)) < 0 ||
            setsockopt(accepted, SOL_SOCKET, SO_RCVTIMEO, &timeout, sizeof(timeout)) < 0 ||
            setsockopt(accepted, SOL_SOCKET, SO_SNDTIMEO, &timeout, sizeof(timeout)) < 0 ||
            send(client, "unix-exec", 9, 0) != 9 || shutdown(client, SHUT_WR) < 0)
                goto fail;
        pending = socket(AF_UNIX, SOCK_STREAM, 0);
        if (pending < 0 || connect(pending, (struct sockaddr*) &unix_address, unix_address_size) < 0 ||
            move_guest_socket_fd(pending, GUEST_UNIX_PENDING_FD, false) < 0)
                goto fail;
        pending = GUEST_UNIX_PENDING_FD;

        listener = socket(AF_INET, SOCK_STREAM, 0);
        if (listener < 0 || setsockopt(listener, SOL_SOCKET, SO_REUSEADDR, &value, sizeof(value)) < 0 ||
            bind(listener, (struct sockaddr*) &address, sizeof(address)) < 0 || listen(listener, 2) < 0)
                goto fail;
        address_size = sizeof(address);
        if (getsockname(listener, (struct sockaddr*) &address, &address_size) < 0 ||
            move_guest_socket_fd(listener, GUEST_TCP_LISTENER_FD, false) < 0)
                goto fail;
        listener = GUEST_TCP_LISTENER_FD;
        client = socket(AF_INET, SOCK_STREAM, 0);
        if (client < 0 || connect(client, (struct sockaddr*) &address, sizeof(address)) < 0)
                goto fail;
        accepted = accept(listener, NULL, NULL);
        if (accepted < 0 || move_guest_socket_fd(accepted, GUEST_TCP_SERVER_FD, false) < 0 ||
            move_guest_socket_fd(client, GUEST_TCP_CLIENT_FD, false) < 0)
                goto fail;
        accepted = GUEST_TCP_SERVER_FD;
        client = GUEST_TCP_CLIENT_FD;
        if (setsockopt(accepted, IPPROTO_TCP, TCP_NODELAY, &value, sizeof(value)) < 0 ||
            setsockopt(client, IPPROTO_TCP, TCP_NODELAY, &value, sizeof(value)) < 0 ||
            setsockopt(accepted, SOL_SOCKET, SO_KEEPALIVE, &value, sizeof(value)) < 0 ||
            setsockopt(accepted, SOL_SOCKET, SO_RCVTIMEO, &timeout, sizeof(timeout)) < 0 ||
            send(client, "tcp-exec", 8, 0) != 8)
                goto fail;
        pending = socket(AF_INET, SOCK_STREAM, 0);
        if (pending < 0 || connect(pending, (struct sockaddr*) &address, sizeof(address)) < 0 ||
            move_guest_socket_fd(pending, GUEST_TCP_PENDING_FD, false) < 0)
                goto fail;
        pending = GUEST_TCP_PENDING_FD;

        udp_left = socket(AF_INET, SOCK_DGRAM, 0);
        udp_right = socket(AF_INET, SOCK_DGRAM, 0);
        if (udp_left < 0 || udp_right < 0)
                goto fail;
        left_address = (struct sockaddr_in) {
                .sin_family = AF_INET,
                .sin_addr.s_addr = htonl(INADDR_LOOPBACK),
        };
        right_address = left_address;
        if (bind(udp_left, (struct sockaddr*) &left_address, sizeof(left_address)) < 0 ||
            bind(udp_right, (struct sockaddr*) &right_address, sizeof(right_address)) < 0)
                goto fail;
        address_size = sizeof(left_address);
        if (getsockname(udp_left, (struct sockaddr*) &left_address, &address_size) < 0)
                goto fail;
        address_size = sizeof(right_address);
        if (getsockname(udp_right, (struct sockaddr*) &right_address, &address_size) < 0 ||
            connect(udp_left, (struct sockaddr*) &right_address, sizeof(right_address)) < 0 ||
            connect(udp_right, (struct sockaddr*) &left_address, sizeof(left_address)) < 0 ||
            setsockopt(udp_left, IPPROTO_IP, IP_TTL, &(int) { 42 }, sizeof(int)) < 0 ||
            setsockopt(udp_right, SOL_SOCKET, SO_RCVTIMEO, &timeout, sizeof(timeout)) < 0 ||
            send(udp_left, "udp-exec", 8, 0) != 8 ||
            move_guest_socket_fd(udp_left, GUEST_UDP_LEFT_FD, false) < 0 ||
            move_guest_socket_fd(udp_right, GUEST_UDP_RIGHT_FD, false) < 0)
                goto fail;
        udp_left = GUEST_UDP_LEFT_FD;
        udp_right = GUEST_UDP_RIGHT_FD;

        listener = socket(AF_INET, SOCK_STREAM, 0);
        address = (struct sockaddr_in) {
                .sin_family = AF_INET,
                .sin_addr.s_addr = htonl(INADDR_LOOPBACK),
        };
        if (listener < 0 || bind(listener, (struct sockaddr*) &address, sizeof(address)) < 0)
                goto fail;
        address_size = sizeof(address);
        if (getsockname(listener, (struct sockaddr*) &address, &address_size) < 0 || close(listener) < 0)
                goto fail;
        listener = -1;
        error_fd = socket(AF_INET, SOCK_STREAM | SOCK_NONBLOCK, 0);
        errno = 0;
        if (error_fd < 0 || connect(error_fd, (struct sockaddr*) &address, sizeof(address)) >= 0 ||
            errno != EINPROGRESS)
                goto fail;
        pollfd = (struct pollfd) {
                .fd = error_fd,
                .events = POLLOUT | POLLERR,
        };
        if (poll(&pollfd, 1, 5000) != 1 || (pollfd.revents & (POLLOUT | POLLERR)) == 0 ||
            move_guest_socket_fd(error_fd, GUEST_SOCKET_ERROR_FD, false) < 0 ||
            dup3(GUEST_UDP_LEFT_FD, GUEST_SOCKET_CLOEXEC_FD, O_CLOEXEC) != GUEST_SOCKET_CLOEXEC_FD)
                goto fail;
        error_fd = GUEST_SOCKET_ERROR_FD;
        fixed_fds = true;

        if (check_guest_socket_state(false, getpid()) < 0)
                goto fail;
        child = fork();
        if (child < 0)
                goto fail;
        if (child == 0) {
                if (check_guest_socket_state(false, getppid()) < 0 ||
                    send(GUEST_UNIX_DUPLICATE_FD, "f", 1, 0) != 1 ||
                    send(GUEST_TCP_CLIENT_FD, "tcp-fork", 8, 0) != 8 ||
                    send(GUEST_UDP_LEFT_FD, "udp-fork", 8, 0) != 8)
                        _exit(170);
                _exit(0);
        }
        if (waitpid(child, &status, 0) != child ||
            !WIFEXITED(status) || WEXITSTATUS(status) != 0 ||
            recv(GUEST_UNIX_CLIENT_FD, &byte, 1, 0) != 1 || byte != 'f')
                goto fail;

        execl(self, self, "--guest-exec-target", "--expect-socket-state", NULL);
fail:
        if (!fixed_fds) {
                if (accepted >= 0)
                        close(accepted);
                if (client >= 0)
                        close(client);
                if (error_fd >= 0)
                        close(error_fd);
                if (listener >= 0)
                        close(listener);
                if (pending >= 0)
                        close(pending);
                if (udp_left >= 0)
                        close(udp_left);
                if (udp_right >= 0)
                        close(udp_right);
        }
        cleanup_guest_socket_state();
        return -EPROTO;
}

static int test_guest_socket_state_exec(const char *self) {
        int status;
        pid_t child;

        child = fork();
        if (child < 0)
                return EXIT_FAILURE;
        if (child == 0)
                _exit(run_guest_socket_state_exec(self) < 0 ? 171 : 0);
        if (waitpid(child, &status, 0) != child ||
            !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                return EXIT_FAILURE;
        return EXIT_SUCCESS;
}

static const char guest_zero_file_payload[] = "0123456789abcdef";
static const char guest_zero_vmsplice_payload[] = "vmsplice-page";
static const char guest_zero_fork_payload[] = "fork-page";

static int move_guest_zero_copy_fd(int fd, int target, bool cloexec) {
        int flags;

        if (fd < 0)
                return -EBADF;
        if (fd != target) {
                int r = cloexec ? dup3(fd, target, O_CLOEXEC) : dup2(fd, target);

                if (r != target)
                        return -errno;
                if (close(fd) < 0)
                        return -errno;
                return target;
        }

        flags = fcntl(fd, F_GETFD);
        if (flags < 0 || fcntl(fd, F_SETFD, cloexec ? flags | FD_CLOEXEC : flags & ~FD_CLOEXEC) < 0)
                return -errno;
        return target;
}

static int cleanup_guest_zero_copy(void) {
        int result = 0;

        for (int fd = GUEST_ZERO_SOURCE_FD; fd <= GUEST_ZERO_CLOEXEC_FD; fd++)
                if (close(fd) < 0 && errno != EBADF)
                        result = -errno;
        return result;
}

static int check_guest_zero_copy_fds(bool exec_completed) {
        static const int persistent_fds[] = {
                GUEST_ZERO_SOURCE_FD,
                GUEST_ZERO_OUTPUT_FD,
                GUEST_ZERO_COPY_FD,
                GUEST_ZERO_PIPE_READ_FD,
                GUEST_ZERO_PIPE_WRITE_FD,
                GUEST_ZERO_TEE_READ_FD,
                GUEST_ZERO_TEE_WRITE_FD,
                GUEST_ZERO_SOCKET_SEND_FD,
                GUEST_ZERO_SOCKET_RECEIVE_FD,
        };
        int r;

        for (size_t i = 0; i < sizeof(persistent_fds) / sizeof(persistent_fds[0]); i++)
                if ((fcntl(persistent_fds[i], F_GETFD) & FD_CLOEXEC) != 0)
                        return -EPROTO;
        errno = 0;
        r = fcntl(GUEST_ZERO_CLOEXEC_FD, F_GETFD);
        if ((exec_completed && (r >= 0 || errno != EBADF)) ||
            (!exec_completed && (r < 0 || (r & FD_CLOEXEC) == 0)))
                return -EPROTO;
        return 0;
}

static int validate_guest_zero_copy_exec(void) {
        static const char expected_pipe[] = "vmsplice-pageabcdeffork-page";
        char buffer[sizeof(expected_pipe)] = {}, copy_buffer[5] = {}, socket_buffer[4] = {};
        struct iovec iov = {
                .iov_base = buffer,
                .iov_len = sizeof(guest_zero_vmsplice_payload) - 1,
        };
        loff_t output_offset = 0;
        int available, result = EXIT_FAILURE;
        size_t transferred = 0;

        if (check_guest_zero_copy_fds(true) < 0 ||
            lseek(GUEST_ZERO_SOURCE_FD, 0, SEEK_CUR) != 0 ||
                        lseek(GUEST_ZERO_OUTPUT_FD, 0, SEEK_CUR) != 0 ||
            lseek(GUEST_ZERO_COPY_FD, 0, SEEK_CUR) != 0 ||
            pread(GUEST_ZERO_COPY_FD, copy_buffer, sizeof(copy_buffer), 0) != sizeof(copy_buffer) ||
            copy_buffer[0] != 0 || memcmp(copy_buffer + 1, "2345", 4) != 0 ||
            recv(GUEST_ZERO_SOCKET_RECEIVE_FD, socket_buffer, sizeof(socket_buffer), MSG_WAITALL) !=
                            sizeof(socket_buffer) ||
            memcmp(socket_buffer, "6789", sizeof(socket_buffer)) != 0 ||
            ioctl(GUEST_ZERO_PIPE_READ_FD, FIONREAD, &available) < 0 ||
            available != (int) sizeof(expected_pipe) - 1 ||
            ioctl(GUEST_ZERO_TEE_READ_FD, FIONREAD, &available) < 0 ||
            available != (int) sizeof(guest_zero_vmsplice_payload) - 1)
                goto finish;

        while (transferred < sizeof(expected_pipe) - 1) {
                ssize_t n = splice(
                                GUEST_ZERO_PIPE_READ_FD,
                                NULL,
                                GUEST_ZERO_OUTPUT_FD,
                                &output_offset,
                                sizeof(expected_pipe) - 1 - transferred,
                                0);

                if (n <= 0)
                        goto finish;
                transferred += n;
        }
        if (output_offset != (loff_t) sizeof(expected_pipe) - 1 ||
                        lseek(GUEST_ZERO_OUTPUT_FD, 0, SEEK_CUR) != 0 ||
            pread(GUEST_ZERO_OUTPUT_FD, buffer, sizeof(expected_pipe) - 1, 0) != sizeof(expected_pipe) - 1 ||
            memcmp(buffer, expected_pipe, sizeof(expected_pipe) - 1) != 0)
                goto finish;
        errno = 0;
        if (splice(
                            GUEST_ZERO_PIPE_READ_FD,
                            NULL,
                            GUEST_ZERO_OUTPUT_FD,
                            NULL,
                            1,
                            SPLICE_F_NONBLOCK) >= 0 ||
            errno != EAGAIN)
                goto finish;

        memset(buffer, 0, sizeof(buffer));
        if (vmsplice(GUEST_ZERO_TEE_READ_FD, &iov, 1, SPLICE_F_NONBLOCK) !=
                            (ssize_t) sizeof(guest_zero_vmsplice_payload) - 1 ||
            memcmp(buffer, guest_zero_vmsplice_payload, sizeof(guest_zero_vmsplice_payload) - 1) != 0)
                goto finish;
        errno = 0;
        if (tee(
                            GUEST_ZERO_TEE_READ_FD,
                            GUEST_ZERO_PIPE_WRITE_FD,
                            1,
                            SPLICE_F_NONBLOCK) >= 0 ||
            errno != EAGAIN)
                goto finish;
        result = EXIT_SUCCESS;

finish:
        if (cleanup_guest_zero_copy() < 0)
                result = EXIT_FAILURE;
        if (result == EXIT_SUCCESS)
                printf("KVM_ZERO_COPY_OK\n");
        return result;
}

static int run_guest_zero_copy_exec(const char *self) {
        loff_t copy_input_offset = 2, copy_output_offset = 1, send_offset = 6, splice_offset = 10;
        int copy_fd = -1, output_fd = -1, pipe_fds[2] = { -1, -1 }, socket_fds[2] = { -1, -1 };
        int source_fd = -1, tee_fds[2] = { -1, -1 }, status;
        void *memory = MAP_FAILED;
        bool fixed_fds = false;
        struct iovec iov;
        long page_size;
        pid_t child;

        page_size = sysconf(_SC_PAGESIZE);
        if (page_size <= 0)
                goto fail;
        source_fd = memfd_create("kvm-zero-source", 0);
        output_fd = memfd_create("kvm-zero-output", 0);
        copy_fd = memfd_create("kvm-zero-copy", 0);
        if (source_fd < 0 || output_fd < 0 || copy_fd < 0 ||
            write(source_fd, guest_zero_file_payload, sizeof(guest_zero_file_payload) - 1) !=
                            sizeof(guest_zero_file_payload) - 1 ||
            lseek(source_fd, 0, SEEK_SET) != 0 || pipe2(pipe_fds, O_NONBLOCK) < 0 ||
            pipe2(tee_fds, O_NONBLOCK) < 0 || socketpair(AF_UNIX, SOCK_STREAM, 0, socket_fds) < 0)
                goto fail;
        if (move_guest_zero_copy_fd(source_fd, GUEST_ZERO_SOURCE_FD, false) < 0 ||
            move_guest_zero_copy_fd(output_fd, GUEST_ZERO_OUTPUT_FD, false) < 0 ||
            move_guest_zero_copy_fd(copy_fd, GUEST_ZERO_COPY_FD, false) < 0 ||
            move_guest_zero_copy_fd(pipe_fds[0], GUEST_ZERO_PIPE_READ_FD, false) < 0 ||
            move_guest_zero_copy_fd(pipe_fds[1], GUEST_ZERO_PIPE_WRITE_FD, false) < 0 ||
            move_guest_zero_copy_fd(tee_fds[0], GUEST_ZERO_TEE_READ_FD, false) < 0 ||
            move_guest_zero_copy_fd(tee_fds[1], GUEST_ZERO_TEE_WRITE_FD, false) < 0 ||
            move_guest_zero_copy_fd(socket_fds[0], GUEST_ZERO_SOCKET_SEND_FD, false) < 0 ||
            move_guest_zero_copy_fd(socket_fds[1], GUEST_ZERO_SOCKET_RECEIVE_FD, false) < 0 ||
            dup3(GUEST_ZERO_PIPE_WRITE_FD, GUEST_ZERO_CLOEXEC_FD, O_CLOEXEC) != GUEST_ZERO_CLOEXEC_FD)
                goto fail;
        source_fd = GUEST_ZERO_SOURCE_FD;
        output_fd = GUEST_ZERO_OUTPUT_FD;
        copy_fd = GUEST_ZERO_COPY_FD;
        for (size_t i = 0; i < 2; i++) {
                pipe_fds[i] = -1;
                tee_fds[i] = -1;
                socket_fds[i] = -1;
        }
        fixed_fds = true;

        int capacity = fcntl(GUEST_ZERO_TEE_WRITE_FD, F_GETPIPE_SZ);
        char *fill = capacity > 0 ? malloc((size_t) capacity) : NULL;
        if (!fill)
                goto fail;
        memset(fill, 0x5a, (size_t) capacity);
        if (write(GUEST_ZERO_TEE_WRITE_FD, fill, (size_t) capacity) != capacity) {
                free(fill);
                goto fail;
        }
        errno = 0;
        if (write(GUEST_ZERO_TEE_WRITE_FD, "x", 1) >= 0 || errno != EAGAIN ||
            read(GUEST_ZERO_TEE_READ_FD, fill, (size_t) capacity) != capacity) {
                free(fill);
                goto fail;
        }
        free(fill);

        errno = 0;
        if (vmsplice(GUEST_ZERO_PIPE_WRITE_FD, &(struct iovec) {}, 0, UINT_MAX) >= 0 || errno != EINVAL)
                goto fail;
        errno = 0;
        if (splice(
                            GUEST_ZERO_PIPE_READ_FD,
                            &splice_offset,
                            GUEST_ZERO_OUTPUT_FD,
                            NULL,
                            1,
                            SPLICE_F_NONBLOCK) >= 0 ||
            errno != ESPIPE)
                goto fail;
        splice_offset = 10;
        errno = 0;
        if (tee(
                            GUEST_ZERO_PIPE_READ_FD,
                            GUEST_ZERO_PIPE_WRITE_FD,
                            1,
                            SPLICE_F_NONBLOCK) >= 0 ||
            errno != EINVAL)
                goto fail;
        errno = 0;
        if (copy_file_range(
                            source_fd,
                            &copy_input_offset,
                            copy_fd,
                            &copy_output_offset,
                            1,
                            1) >= 0 ||
            errno != EINVAL)
                goto fail;
        if (copy_file_range(
                            source_fd,
                            &copy_input_offset,
                            copy_fd,
                            &copy_output_offset,
                            4,
                            0) != 4 ||
            copy_input_offset != 6 || copy_output_offset != 5 ||
            sendfile(GUEST_ZERO_SOCKET_SEND_FD, source_fd, &send_offset, 4) != 4 || send_offset != 10)
                goto fail;
        errno = 0;
        if (sendfile(GUEST_ZERO_SOCKET_SEND_FD, source_fd, (off_t*) 1, 1) >= 0 || errno != EFAULT)
                goto fail;

        memory = mmap(NULL, (size_t) page_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (memory == MAP_FAILED)
                goto fail;
        memcpy(memory, guest_zero_vmsplice_payload, sizeof(guest_zero_vmsplice_payload) - 1);
        iov = (struct iovec) {
                .iov_base = memory,
                .iov_len = sizeof(guest_zero_vmsplice_payload) - 1,
        };
        if (vmsplice(GUEST_ZERO_PIPE_WRITE_FD, &iov, 1, SPLICE_F_GIFT | SPLICE_F_NONBLOCK) !=
                            (ssize_t) sizeof(guest_zero_vmsplice_payload) - 1 ||
            tee(
                            GUEST_ZERO_PIPE_READ_FD,
                            GUEST_ZERO_TEE_WRITE_FD,
                            sizeof(guest_zero_vmsplice_payload) - 1,
                            SPLICE_F_NONBLOCK) != (ssize_t) sizeof(guest_zero_vmsplice_payload) - 1 ||
            munmap(memory, (size_t) page_size) < 0)
                goto fail;
        memory = MAP_FAILED;
        if (splice(
                            source_fd,
                            &splice_offset,
                            GUEST_ZERO_PIPE_WRITE_FD,
                            NULL,
                            6,
                            SPLICE_F_NONBLOCK) != 6 ||
            splice_offset != 16 || lseek(source_fd, 0, SEEK_CUR) != 0 ||
            lseek(copy_fd, 0, SEEK_CUR) != 0 || check_guest_zero_copy_fds(false) < 0)
                goto fail;

        child = fork();
        if (child < 0)
                goto fail;
        if (child == 0) {
                void *child_memory = mmap(
                                NULL,
                                (size_t) page_size,
                                PROT_READ | PROT_WRITE,
                                MAP_PRIVATE | MAP_ANONYMOUS,
                                -1,
                                0);
                struct iovec child_iov;

                if (child_memory == MAP_FAILED || check_guest_zero_copy_fds(false) < 0)
                        _exit(172);
                memcpy(child_memory, guest_zero_fork_payload, sizeof(guest_zero_fork_payload) - 1);
                child_iov = (struct iovec) {
                        .iov_base = child_memory,
                        .iov_len = sizeof(guest_zero_fork_payload) - 1,
                };
                if (vmsplice(
                                    GUEST_ZERO_PIPE_WRITE_FD,
                                    &child_iov,
                                    1,
                                    SPLICE_F_GIFT | SPLICE_F_NONBLOCK) !=
                                    (ssize_t) sizeof(guest_zero_fork_payload) - 1 ||
                    munmap(child_memory, (size_t) page_size) < 0)
                        _exit(172);
                _exit(0);
        }
        int available;
        if (waitpid(child, &status, 0) != child ||
            !WIFEXITED(status) || WEXITSTATUS(status) != 0 ||
            ioctl(GUEST_ZERO_PIPE_READ_FD, FIONREAD, &available) < 0 ||
            available != (int) (sizeof(guest_zero_vmsplice_payload) - 1 + 6 +
                               sizeof(guest_zero_fork_payload) - 1))
                goto fail;

        execl(self, self, "--guest-exec-target", "--expect-zero-copy", NULL);
fail:
        if (memory != MAP_FAILED)
                munmap(memory, (size_t) page_size);
        if (!fixed_fds) {
                if (source_fd >= 0)
                        close(source_fd);
                if (output_fd >= 0)
                        close(output_fd);
                if (copy_fd >= 0)
                        close(copy_fd);
                for (size_t i = 0; i < 2; i++) {
                        if (pipe_fds[i] >= 0)
                                close(pipe_fds[i]);
                        if (tee_fds[i] >= 0)
                                close(tee_fds[i]);
                        if (socket_fds[i] >= 0)
                                close(socket_fds[i]);
                }
        }
        cleanup_guest_zero_copy();
        return -EPROTO;
}

static int test_guest_zero_copy_exec(const char *self) {
        int status;
        pid_t child;

        child = fork();
        if (child < 0)
                return EXIT_FAILURE;
        if (child == 0)
                _exit(run_guest_zero_copy_exec(self) < 0 ? 173 : 0);
        if (waitpid(child, &status, 0) != child ||
            !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                return EXIT_FAILURE;
        return EXIT_SUCCESS;
}

static int make_guest_extent_path(char path[static PATH_MAX], pid_t owner) {
        return snprintf(path, PATH_MAX, "/var/tmp/kvm-extent-%ld", (long) owner) < PATH_MAX ?
                0 : -EOVERFLOW;
}

static int move_guest_extent_fd(int fd, int target, bool cloexec) {
        int flags;

        if (fd < 0)
                return -EBADF;
        if (fd != target) {
                int r = cloexec ? dup3(fd, target, O_CLOEXEC) : dup2(fd, target);

                if (r != target)
                        return -errno;
                if (close(fd) < 0)
                        return -errno;
                return target;
        }

        flags = fcntl(fd, F_GETFD);
        if (flags < 0 || fcntl(fd, F_SETFD, cloexec ? flags | FD_CLOEXEC : flags & ~FD_CLOEXEC) < 0)
                return -errno;
        return target;
}

static int check_guest_extent_pages(int fd, long page_size, const uint8_t expected[static 4]) {
        uint8_t byte;

        for (size_t i = 0; i < 4; i++)
                if (pread(fd, &byte, 1, (off_t) i * page_size) != 1 || byte != expected[i])
                        return -EPROTO;
        return 0;
}

static int check_guest_extent_fds(bool exec_completed) {
        static const int persistent_fds[] = {
                GUEST_EXTENT_MEMFD_FD,
                GUEST_EXTENT_MEMFD_DUPLICATE_FD,
                GUEST_EXTENT_FILE_FD,
                GUEST_EXTENT_INDEPENDENT_FD,
        };
        struct stat expected, stat_buffer;
        int r;

        for (size_t i = 0; i < sizeof(persistent_fds) / sizeof(persistent_fds[0]); i++)
                if ((fcntl(persistent_fds[i], F_GETFD) & FD_CLOEXEC) != 0)
                        return -EPROTO;
        if (fstat(GUEST_EXTENT_FILE_FD, &expected) < 0 ||
            fstat(GUEST_EXTENT_INDEPENDENT_FD, &stat_buffer) < 0 || expected.st_dev != stat_buffer.st_dev ||
            expected.st_ino != stat_buffer.st_ino)
                return -EPROTO;
        errno = 0;
        r = fcntl(GUEST_EXTENT_CLOEXEC_FD, F_GETFD);
        if ((exec_completed && (r >= 0 || errno != EBADF)) ||
            (!exec_completed && (r < 0 || (r & FD_CLOEXEC) == 0)))
                return -EPROTO;
        return 0;
}

static int cleanup_guest_extent_state(void) {
        char path[PATH_MAX];
        int result = 0;

        for (int fd = GUEST_EXTENT_MEMFD_FD; fd <= GUEST_EXTENT_CLOEXEC_FD; fd++)
                if (close(fd) < 0 && errno != EBADF)
                        result = -errno;
        if (make_guest_extent_path(path, getpid()) < 0)
                result = -EOVERFLOW;
        else if (unlink(path) < 0 && errno != ENOENT)
                result = -errno;
        return result;
}

static int validate_guest_extent_state_exec(void) {
        const uint8_t memfd_expected[] = { 0x11, 0x00, 0x00, 0x44 };
        const uint8_t file_expected[] = { 0x51, 0x00, 0x53, 0x54 };
        void *file_mapping = MAP_FAILED, *memfd_mapping = MAP_FAILED;
        long page_size;
        int result = EXIT_FAILURE;

        page_size = sysconf(_SC_PAGESIZE);
        if (page_size <= 0 || check_guest_extent_fds(true) < 0 ||
            check_guest_extent_pages(GUEST_EXTENT_MEMFD_FD, page_size, memfd_expected) < 0 ||
            check_guest_extent_pages(GUEST_EXTENT_FILE_FD, page_size, file_expected) < 0)
                goto finish;
        memfd_mapping = mmap(
                        NULL,
                        (size_t) page_size * 4,
                        PROT_READ | PROT_WRITE,
                        MAP_SHARED,
                        GUEST_EXTENT_MEMFD_FD,
                        0);
        file_mapping = mmap(
                        NULL,
                        (size_t) page_size * 4,
                        PROT_READ | PROT_WRITE,
                        MAP_SHARED,
                        GUEST_EXTENT_INDEPENDENT_FD,
                        0);
        if (memfd_mapping == MAP_FAILED || file_mapping == MAP_FAILED ||
            ((uint8_t*) memfd_mapping)[0] != 0x11 || ((uint8_t*) memfd_mapping)[page_size] != 0 ||
            ((uint8_t*) memfd_mapping)[2 * page_size] != 0 || ((uint8_t*) memfd_mapping)[3 * page_size] != 0x44 ||
            ((uint8_t*) file_mapping)[0] != 0x51 || ((uint8_t*) file_mapping)[page_size] != 0 ||
            ((uint8_t*) file_mapping)[2 * page_size] != 0x53 || ((uint8_t*) file_mapping)[3 * page_size] != 0x54)
                goto finish;
        if (pwrite(GUEST_EXTENT_INDEPENDENT_FD, "\x55", 1, 3 * page_size) != 1 ||
            ((uint8_t*) file_mapping)[3 * page_size] != 0x55 ||
            posix_fadvise(GUEST_EXTENT_FILE_FD, 0, 0, POSIX_FADV_DONTNEED) != 0 ||
            readahead(GUEST_EXTENT_FILE_FD, 0, (size_t) page_size * 4) < 0 ||
            sync_file_range(
                            GUEST_EXTENT_FILE_FD,
                            0,
                            0,
                            SYNC_FILE_RANGE_WAIT_BEFORE | SYNC_FILE_RANGE_WRITE | SYNC_FILE_RANGE_WAIT_AFTER) < 0 ||
            fdatasync(GUEST_EXTENT_INDEPENDENT_FD) < 0 || fsync(GUEST_EXTENT_FILE_FD) < 0 ||
            syncfs(GUEST_EXTENT_FILE_FD) < 0)
                goto finish;
        result = EXIT_SUCCESS;

finish:
        if (file_mapping != MAP_FAILED && munmap(file_mapping, (size_t) page_size * 4) < 0)
                result = EXIT_FAILURE;
        if (memfd_mapping != MAP_FAILED && munmap(memfd_mapping, (size_t) page_size * 4) < 0)
                result = EXIT_FAILURE;
        if (cleanup_guest_extent_state() < 0)
                result = EXIT_FAILURE;
        if (result == EXIT_SUCCESS)
                printf("KVM_FILE_EXTENTS_OK\n");
        return result;
}

static int run_guest_extent_state_exec(const char *self) {
        char path[PATH_MAX] = {};
        void *file_mapping = MAP_FAILED, *memfd_mapping = MAP_FAILED;
        int file_fd = -1, independent_fd = -1, memfd_fd = -1, status;
        bool fixed_fds = false;
        long page_size;
        pid_t child;

        page_size = sysconf(_SC_PAGESIZE);
        if (page_size <= 0 || make_guest_extent_path(path, getpid()) < 0)
                goto fail;
        memfd_fd = memfd_create("kvm-extent-memfd", 0);
        file_fd = open(path, O_CREAT | O_EXCL | O_RDWR, 0600);
        if (memfd_fd < 0 || file_fd < 0 || ftruncate(memfd_fd, page_size * 4) < 0 ||
            ftruncate(file_fd, page_size * 4) < 0)
                goto fail;
        memfd_mapping = mmap(
                        NULL,
                        (size_t) page_size * 4,
                        PROT_READ | PROT_WRITE,
                        MAP_SHARED,
                        memfd_fd,
                        0);
        file_mapping = mmap(
                        NULL,
                        (size_t) page_size * 4,
                        PROT_READ | PROT_WRITE,
                        MAP_SHARED,
                        file_fd,
                        0);
        if (memfd_mapping == MAP_FAILED || file_mapping == MAP_FAILED)
                goto fail;
        for (size_t i = 0; i < 4; i++) {
                memset((uint8_t*) memfd_mapping + i * page_size, 0x11 * (i + 1), (size_t) page_size);
                memset((uint8_t*) file_mapping + i * page_size, 0x51 + i, (size_t) page_size);
        }
        if (msync(memfd_mapping, (size_t) page_size * 4, MS_SYNC) < 0 ||
            msync(file_mapping, (size_t) page_size * 4, MS_SYNC) < 0)
                goto fail;

        if (fallocate(memfd_fd, FALLOC_FL_KEEP_SIZE, page_size * 4, page_size) < 0)
                goto fail;
        struct stat stat_buffer;
        if (fstat(memfd_fd, &stat_buffer) < 0 || stat_buffer.st_size != page_size * 4 ||
            fallocate(memfd_fd, FALLOC_FL_PUNCH_HOLE | FALLOC_FL_KEEP_SIZE, page_size, page_size) < 0 ||
            ((uint8_t*) memfd_mapping)[page_size] != 0)
                goto fail;
        errno = 0;
        if (fallocate(memfd_fd, FALLOC_FL_ZERO_RANGE, 2 * page_size, page_size) >= 0 || errno != EOPNOTSUPP)
                goto fail;
        errno = 0;
        if (fallocate(memfd_fd, FALLOC_FL_PUNCH_HOLE, page_size, page_size) >= 0 || errno != EOPNOTSUPP)
                goto fail;

        if (fallocate(file_fd, FALLOC_FL_ZERO_RANGE, page_size, page_size) < 0 ||
            ((uint8_t*) file_mapping)[page_size] != 0)
                goto fail;
        errno = 0;
        if (fallocate(file_fd, FALLOC_FL_COLLAPSE_RANGE, page_size, page_size) >= 0 || errno != EOPNOTSUPP)
                goto fail;
        errno = 0;
        if (fallocate(file_fd, FALLOC_FL_INSERT_RANGE, page_size, page_size) >= 0 || errno != EOPNOTSUPP)
                goto fail;
        errno = 0;
        if (fallocate(file_fd, FALLOC_FL_UNSHARE_RANGE, 0, page_size) >= 0 || errno != EOPNOTSUPP)
                goto fail;
        errno = 0;
        if (fallocate(file_fd, 0, -1, page_size) >= 0 || errno != EINVAL ||
            posix_fadvise(file_fd, 0, 0, INT_MAX) != EINVAL)
                goto fail;
        errno = 0;
        if (readahead(-1, 0, page_size) >= 0 || errno != EBADF)
                goto fail;
        errno = 0;
        if (sync_file_range(file_fd, 0, page_size, UINT_MAX) >= 0 || errno != EINVAL)
                goto fail;
        errno = 0;
        if (syncfs(-1) >= 0 || errno != EBADF)
                goto fail;

        if (posix_fadvise(file_fd, 0, page_size * 4, POSIX_FADV_SEQUENTIAL) != 0 ||
            posix_fadvise(file_fd, 0, page_size * 4, POSIX_FADV_RANDOM) != 0 ||
            posix_fadvise(file_fd, 0, page_size * 4, POSIX_FADV_WILLNEED) != 0 ||
            readahead(file_fd, 0, (size_t) page_size * 4) < 0 ||
            sync_file_range(file_fd, 0, page_size * 4, SYNC_FILE_RANGE_WRITE) < 0 ||
            fdatasync(file_fd) < 0 || fsync(file_fd) < 0 || syncfs(file_fd) < 0)
                goto fail;

        independent_fd = open(path, O_RDWR);
        if (independent_fd < 0 || move_guest_extent_fd(memfd_fd, GUEST_EXTENT_MEMFD_FD, false) < 0 ||
            dup2(GUEST_EXTENT_MEMFD_FD, GUEST_EXTENT_MEMFD_DUPLICATE_FD) != GUEST_EXTENT_MEMFD_DUPLICATE_FD ||
            move_guest_extent_fd(file_fd, GUEST_EXTENT_FILE_FD, false) < 0 ||
            move_guest_extent_fd(independent_fd, GUEST_EXTENT_INDEPENDENT_FD, false) < 0 ||
            dup3(GUEST_EXTENT_FILE_FD, GUEST_EXTENT_CLOEXEC_FD, O_CLOEXEC) != GUEST_EXTENT_CLOEXEC_FD)
                goto fail;
        memfd_fd = GUEST_EXTENT_MEMFD_FD;
        file_fd = GUEST_EXTENT_FILE_FD;
        independent_fd = GUEST_EXTENT_INDEPENDENT_FD;
        fixed_fds = true;
        if (check_guest_extent_fds(false) < 0)
                goto fail;

        child = fork();
        if (child < 0)
                goto fail;
        if (child == 0) {
                if (check_guest_extent_fds(false) < 0 ||
                    fallocate(
                                    GUEST_EXTENT_MEMFD_DUPLICATE_FD,
                                    FALLOC_FL_PUNCH_HOLE | FALLOC_FL_KEEP_SIZE,
                                    2 * page_size,
                                    page_size) < 0)
                        _exit(174);
                _exit(0);
        }
        if (waitpid(child, &status, 0) != child ||
            !WIFEXITED(status) || WEXITSTATUS(status) != 0 ||
            ((uint8_t*) memfd_mapping)[2 * page_size] != 0)
                goto fail;

        execl(self, self, "--guest-exec-target", "--expect-file-extents", NULL);
fail:
        if (file_mapping != MAP_FAILED)
                munmap(file_mapping, (size_t) page_size * 4);
        if (memfd_mapping != MAP_FAILED)
                munmap(memfd_mapping, (size_t) page_size * 4);
        if (!fixed_fds) {
                if (file_fd >= 0)
                        close(file_fd);
                if (independent_fd >= 0)
                        close(independent_fd);
                if (memfd_fd >= 0)
                        close(memfd_fd);
        }
        cleanup_guest_extent_state();
        if (path[0] != 0)
                unlink(path);
        return -EPROTO;
}

static int test_guest_extent_state_exec(const char *self) {
        int status;
        pid_t child;

        child = fork();
        if (child < 0)
                return EXIT_FAILURE;
        if (child == 0)
                _exit(run_guest_extent_state_exec(self) < 0 ? 175 : 0);
        if (waitpid(child, &status, 0) != child ||
            !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                return EXIT_FAILURE;
        return EXIT_SUCCESS;
}

#define GUEST_XATTR_PATH "user.kvm.path"
#define GUEST_XATTR_FD "user.kvm.fd"
#define GUEST_XATTR_LINK "user.kvm.link"
#define GUEST_XATTR_CHILD "user.kvm.child"
#define GUEST_XATTR_HANDLE "user.kvm.handle"

typedef struct GuestXattrArgs {
        uint64_t value;
        uint32_t size;
        uint32_t flags;
} GuestXattrArgs;

typedef struct GuestFileHandleState {
        uint32_t handle_bytes;
        int32_t handle_type;
        int32_t mount_id;
        uint32_t reserved;
        uint64_t unique_mount_id;
        uint8_t handle[MAX_HANDLE_SZ];
} GuestFileHandleState;

static int make_guest_metadata_paths(
                char path[static PATH_MAX],
                char link_path[static PATH_MAX],
                pid_t owner) {

        if (snprintf(path, PATH_MAX, "/var/tmp/kvm-metadata-%ld", (long) owner) >= PATH_MAX ||
            snprintf(link_path, PATH_MAX, "/var/tmp/kvm-metadata-link-%ld", (long) owner) >= PATH_MAX)
                return -EOVERFLOW;
        return 0;
}

static int move_guest_metadata_fd(int fd, int target, bool cloexec) {
        int flags;

        if (fd < 0)
                return -EBADF;
        if (fd != target) {
                int r = cloexec ? dup3(fd, target, O_CLOEXEC) : dup2(fd, target);

                if (r != target)
                        return -errno;
                if (close(fd) < 0)
                        return -errno;
                return target;
        }

        flags = fcntl(fd, F_GETFD);
        if (flags < 0 || fcntl(fd, F_SETFD, cloexec ? flags | FD_CLOEXEC : flags & ~FD_CLOEXEC) < 0)
                return -errno;
        return target;
}

static int guest_xattr_list_has(const char *list, size_t size, const char *name) {
        size_t offset = 0;

        while (offset < size) {
                size_t length = strnlen(list + offset, size - offset);

                if (length == size - offset)
                        return -EPROTO;
                if (strcmp(list + offset, name) == 0)
                        return 1;
                offset += length + 1;
        }
        return 0;
}

static int guest_flistxattr_has(int fd, const char *name) {
        char *list = NULL;
        ssize_t size, n;
        int result;

        size = flistxattr(fd, NULL, 0);
        if (size < 0)
                return -errno;
        if (size == 0)
                return 0;
        list = malloc((size_t) size);
        if (!list)
                return -ENOMEM;
        n = flistxattr(fd, list, (size_t) size);
        if (n != size) {
                result = n < 0 ? -errno : -EPROTO;
                free(list);
                return result;
        }
        result = guest_xattr_list_has(list, (size_t) n, name);
        free(list);
        return result;
}

static int guest_llistxattr_has(const char *path, const char *name) {
        char *list = NULL;
        ssize_t size, n;
        int result;

        size = llistxattr(path, NULL, 0);
        if (size < 0)
                return -errno;
        if (size == 0)
                return 0;
        list = malloc((size_t) size);
        if (!list)
                return -ENOMEM;
        n = llistxattr(path, list, (size_t) size);
        if (n != size) {
                result = n < 0 ? -errno : -EPROTO;
                free(list);
                return result;
        }
        result = guest_xattr_list_has(list, (size_t) n, name);
        free(list);
        return result;
}

static int check_guest_xattr_value(int fd, const char *name, const void *expected, size_t expected_size) {
        void *value;
        ssize_t size, n;
        int result = 0;

        size = fgetxattr(fd, name, NULL, 0);
        if (size != (ssize_t) expected_size)
                return -EPROTO;
        value = malloc(expected_size);
        if (!value)
                return -ENOMEM;
        n = fgetxattr(fd, name, value, expected_size);
        if (n != size || memcmp(value, expected, expected_size) != 0)
                result = -EPROTO;
        free(value);
        return result;
}

static int check_guest_xattrat(int fd, const char *link_path) {
        static const char fd_name[] = "user.kvm.xattrat-fd";
        static const char link_name[] = "user.kvm.xattrat-link";
        static const char fd_value[] = "xattrat-fd";
        static const char link_value[] = "xattrat-link";
        GuestXattrArgs arguments = {
                .value = (uint64_t) (uintptr_t) fd_value,
                .size = sizeof(fd_value),
                .flags = XATTR_CREATE,
        };
        char list[512], value[sizeof(link_value)];
        long r;

        errno = 0;
        r = syscall(SYS_setxattrat, fd, "", AT_EMPTY_PATH, fd_name, &arguments, sizeof(arguments));
        if (r < 0 && errno == ENOSYS) {
                errno = 0;
                if (syscall(SYS_getxattrat, fd, "", AT_EMPTY_PATH, fd_name, &arguments, sizeof(arguments)) >= 0 ||
                    errno != ENOSYS)
                        return -EPROTO;
                errno = 0;
                if (syscall(SYS_listxattrat, fd, "", AT_EMPTY_PATH, list, sizeof(list)) >= 0 || errno != ENOSYS)
                        return -EPROTO;
                errno = 0;
                if (syscall(SYS_removexattrat, fd, "", AT_EMPTY_PATH, fd_name) >= 0 || errno != ENOSYS)
                        return -EPROTO;
                return 0;
        }
        if (r < 0)
                return -errno;

        arguments = (GuestXattrArgs) {
                .value = (uint64_t) (uintptr_t) value,
                .size = sizeof(value),
        };
        if (syscall(SYS_getxattrat, fd, "", AT_EMPTY_PATH, fd_name, &arguments, sizeof(arguments)) !=
            (long) sizeof(fd_value) || memcmp(value, fd_value, sizeof(fd_value)) != 0)
                return -EPROTO;
        r = syscall(SYS_listxattrat, fd, "", AT_EMPTY_PATH, list, sizeof(list));
        if (r <= 0 || guest_xattr_list_has(list, (size_t) r, fd_name) != 1)
                return -EPROTO;
        errno = 0;
        if (syscall(SYS_getxattrat, fd, "", UINT_MAX, fd_name, &arguments, sizeof(arguments)) >= 0 ||
            errno != EINVAL)
                return -EPROTO;

        arguments = (GuestXattrArgs) {
                .value = (uint64_t) (uintptr_t) link_value,
                .size = sizeof(link_value),
                .flags = XATTR_CREATE,
        };
        if (syscall(
                            SYS_setxattrat,
                            AT_FDCWD,
                            link_path,
                            0,
                            link_name,
                            &arguments,
                            sizeof(arguments)) < 0 ||
            getxattr(link_path, link_name, value, sizeof(value)) != (ssize_t) sizeof(link_value) ||
            memcmp(value, link_value, sizeof(link_value)) != 0)
                return -EPROTO;
        arguments = (GuestXattrArgs) {
                .value = (uint64_t) (uintptr_t) value,
                .size = sizeof(value),
        };
        errno = 0;
        if (syscall(
                            SYS_getxattrat,
                            AT_FDCWD,
                            link_path,
                            AT_SYMLINK_NOFOLLOW,
                            link_name,
                            &arguments,
                            sizeof(arguments)) >= 0 ||
            errno != ENODATA)
                return -EPROTO;
        if (syscall(SYS_removexattrat, AT_FDCWD, link_path, 0, link_name) < 0 ||
            syscall(SYS_removexattrat, fd, "", AT_EMPTY_PATH, fd_name) < 0)
                return -errno;
        return 0;
}

static int prepare_guest_metadata_xattrs(const char *path, const char *link_path, int fd) {
        static const char path_initial[] = "path-initial";
        static const char path_replaced[] = "path-replaced";
        static const char fd_value[] = "fd-value";
        static const char link_value[] = "link-value";
        static const char temporary_name[] = "user.kvm.temporary";
        char byte, value[sizeof(path_replaced)];
        ssize_t size;

        if (setxattr(path, GUEST_XATTR_PATH, path_initial, sizeof(path_initial), XATTR_CREATE) < 0)
                return -errno;
        errno = 0;
        if (setxattr(path, GUEST_XATTR_PATH, path_initial, sizeof(path_initial), XATTR_CREATE) >= 0 ||
            errno != EEXIST)
                return -EPROTO;
        errno = 0;
        if (setxattr(path, "user.kvm.missing", path_initial, sizeof(path_initial), XATTR_REPLACE) >= 0 ||
            errno != ENODATA)
                return -EPROTO;
        if (setxattr(path, GUEST_XATTR_PATH, path_replaced, sizeof(path_replaced), XATTR_REPLACE) < 0 ||
            getxattr(path, GUEST_XATTR_PATH, value, sizeof(value)) != (ssize_t) sizeof(path_replaced) ||
            memcmp(value, path_replaced, sizeof(path_replaced)) != 0)
                return -EPROTO;

        if (fsetxattr(fd, GUEST_XATTR_FD, fd_value, sizeof(fd_value), XATTR_CREATE) < 0)
                return -errno;
        size = fgetxattr(fd, GUEST_XATTR_FD, NULL, 0);
        if (size != (ssize_t) sizeof(fd_value))
                return -EPROTO;
        errno = 0;
        if (fgetxattr(fd, GUEST_XATTR_FD, &byte, 1) >= 0 || errno != ERANGE)
                return -EPROTO;
        errno = 0;
        if (fgetxattr(fd, "user.kvm.missing", value, sizeof(value)) >= 0 || errno != ENODATA)
                return -EPROTO;
        errno = 0;
        if (fsetxattr(fd, GUEST_XATTR_FD, fd_value, sizeof(fd_value), XATTR_CREATE | XATTR_REPLACE) >= 0 ||
                        errno != EEXIST)
                return -EPROTO;

        if (setxattr(link_path, GUEST_XATTR_LINK, link_value, sizeof(link_value), XATTR_CREATE) < 0 ||
            getxattr(link_path, GUEST_XATTR_LINK, value, sizeof(value)) != (ssize_t) sizeof(link_value) ||
            memcmp(value, link_value, sizeof(link_value)) != 0)
                return -EPROTO;
        errno = 0;
        if (lgetxattr(link_path, GUEST_XATTR_LINK, value, sizeof(value)) >= 0 || errno != ENODATA)
                return -EPROTO;
        errno = 0;
        if (lsetxattr(link_path, GUEST_XATTR_LINK, link_value, sizeof(link_value), XATTR_CREATE) >= 0 ||
            errno != EPERM)
                return -EPROTO;
        errno = 0;
        if (lremovexattr(link_path, GUEST_XATTR_LINK) >= 0 || errno != EPERM ||
            guest_llistxattr_has(link_path, GUEST_XATTR_LINK) != 0)
                return -EPROTO;

        if (setxattr(link_path, temporary_name, link_value, sizeof(link_value), XATTR_CREATE) < 0 ||
            removexattr(link_path, temporary_name) < 0 ||
            fsetxattr(fd, temporary_name, fd_value, sizeof(fd_value), XATTR_CREATE) < 0 ||
            fremovexattr(fd, temporary_name) < 0)
                return -errno;
        errno = 0;
        if (fgetxattr(fd, temporary_name, value, sizeof(value)) >= 0 || errno != ENODATA)
                return -EPROTO;
        if (guest_flistxattr_has(fd, GUEST_XATTR_PATH) != 1 ||
            guest_flistxattr_has(fd, GUEST_XATTR_FD) != 1 ||
            guest_flistxattr_has(fd, GUEST_XATTR_LINK) != 1)
                return -EPROTO;
        errno = 0;
        if (flistxattr(fd, &byte, 1) >= 0 || errno != ERANGE)
                return -EPROTO;
        return 0;
}

static bool guest_file_handles_equal(const GuestFileHandleState *a, const GuestFileHandleState *b) {
        return a->handle_bytes == b->handle_bytes && a->handle_type == b->handle_type &&
               a->mount_id == b->mount_id && memcmp(a->handle, b->handle, a->handle_bytes) == 0;
}

static int guest_name_to_handle(
                int dfd,
                const char *path,
                int flags,
                GuestFileHandleState *ret_state) {

        struct file_handle *handle;
        int mount_id = -1, result;
        uint32_t required;

        handle = calloc(1, sizeof(*handle) + MAX_HANDLE_SZ);
        if (!handle)
                return -ENOMEM;
        errno = 0;
        result = syscall(SYS_name_to_handle_at, dfd, path, handle, &mount_id, flags);
        if (result < 0 && errno == EOPNOTSUPP) {
                free(handle);
                *ret_state = (GuestFileHandleState) {};
                return 0;
        }
        if (result >= 0 || errno != EOVERFLOW || handle->handle_bytes == 0 ||
            handle->handle_bytes > MAX_HANDLE_SZ) {
                free(handle);
                return -EPROTO;
        }
        required = handle->handle_bytes;
        memset(handle, 0, sizeof(*handle) + MAX_HANDLE_SZ);
        handle->handle_bytes = required;
        mount_id = -1;
        if (syscall(SYS_name_to_handle_at, dfd, path, handle, &mount_id, flags) < 0) {
                result = -errno;
                free(handle);
                return result;
        }
        *ret_state = (GuestFileHandleState) {
                .handle_bytes = handle->handle_bytes,
                .handle_type = handle->handle_type,
                .mount_id = mount_id,
        };
        memcpy(ret_state->handle, handle->f_handle, handle->handle_bytes);
        free(handle);
        return 1;
}

static int guest_name_to_handle_unique(
                const char *path,
                int flags,
                GuestFileHandleState *state) {

        struct file_handle *handle;
        uint64_t mount_id = 0, statx_mount_id;
        int result;

        handle = calloc(1, sizeof(*handle) + state->handle_bytes);
        if (!handle)
                return -ENOMEM;
        handle->handle_bytes = state->handle_bytes;
        errno = 0;
        result = syscall(
                        SYS_name_to_handle_at,
                        AT_FDCWD,
                        path,
                        handle,
                        &mount_id,
                        flags | AT_HANDLE_MNT_ID_UNIQUE);
        if (result < 0 && errno == EINVAL) {
                free(handle);
                state->unique_mount_id = 0;
                return 0;
        }
        if (result < 0 || handle->handle_bytes != state->handle_bytes ||
            handle->handle_type != state->handle_type ||
            memcmp(handle->f_handle, state->handle, state->handle_bytes) != 0 ||
            guest_mount_unique_id(path, &statx_mount_id) < 0 || mount_id != statx_mount_id) {
                free(handle);
                return -EPROTO;
        }
        state->unique_mount_id = mount_id;
        free(handle);
        return 1;
}

static int check_guest_file_handle_identity(
                const char *path,
                const char *link_path,
                int fd,
                GuestFileHandleState *ret_state) {

        GuestFileHandleState fd_state, fid_state, link_state, symlink_state;
        struct file_handle *handle;
        int result;

        result = guest_name_to_handle(AT_FDCWD, path, 0, ret_state);
        if (result <= 0)
                return result;
        if (guest_name_to_handle(fd, "", AT_EMPTY_PATH, &fd_state) != 1 ||
            !guest_file_handles_equal(ret_state, &fd_state) ||
            guest_name_to_handle(AT_FDCWD, link_path, AT_SYMLINK_FOLLOW, &link_state) != 1 ||
            !guest_file_handles_equal(ret_state, &link_state) ||
            guest_name_to_handle(AT_FDCWD, link_path, 0, &symlink_state) != 1 ||
            guest_file_handles_equal(ret_state, &symlink_state) ||
            guest_name_to_handle(AT_FDCWD, path, AT_HANDLE_FID, &fid_state) != 1 ||
            fid_state.handle_bytes == 0 || fid_state.mount_id != ret_state->mount_id)
                return -EPROTO;
        result = guest_name_to_handle_unique(path, 0, ret_state);
        if (result < 0)
                return result;

        handle = calloc(1, sizeof(*handle) + MAX_HANDLE_SZ);
        if (!handle)
                return -ENOMEM;
        handle->handle_bytes = MAX_HANDLE_SZ;
        errno = 0;
        result = syscall(SYS_name_to_handle_at, AT_FDCWD, path, handle, &fd_state.mount_id, 0x40000000U);
        free(handle);
        if (result >= 0 || errno != EINVAL)
                return -EPROTO;
        return 1;
}

static struct file_handle *guest_file_handle_from_state(const GuestFileHandleState *state) {
        struct file_handle *handle;

        handle = malloc(sizeof(*handle) + state->handle_bytes);
        if (!handle)
                return NULL;
        handle->handle_bytes = state->handle_bytes;
        handle->handle_type = state->handle_type;
        memcpy(handle->f_handle, state->handle, state->handle_bytes);
        return handle;
}

static int check_guest_open_by_handle(
                const GuestFileHandleState *state,
                int expected_fd,
                bool *ret_decode_allowed) {

        struct file_handle *handle;
        struct stat expected, opened;
        bool permission_first;
        int fd, malformed_error, result = 0;

        *ret_decode_allowed = false;
        if (state->handle_bytes == 0)
                return 0;
        handle = guest_file_handle_from_state(state);
        if (!handle)
                return -ENOMEM;

        fd = open_by_handle_at(GUEST_METADATA_MOUNT_FD, handle, O_RDONLY | O_CLOEXEC);
        if (fd < 0) {
                if (errno != EPERM) {
                        result = -EPROTO;
                        goto finish;
                }
        } else {
                *ret_decode_allowed = true;
                if (fstat(expected_fd, &expected) < 0 || fstat(fd, &opened) < 0 ||
                    expected.st_dev != opened.st_dev || expected.st_ino != opened.st_ino ||
                    (fcntl(fd, F_GETFD) & FD_CLOEXEC) == 0)
                        result = -EPROTO;
                if (close(fd) < 0 && result >= 0)
                        result = -errno;
                if (result < 0)
                        goto finish;
        }

        handle->handle_bytes = 0;
        errno = 0;
        if (open_by_handle_at(GUEST_METADATA_MOUNT_FD, handle, O_RDONLY | O_CLOEXEC) >= 0 ||
            (errno != EINVAL && (!*ret_decode_allowed && errno != EPERM))) {
                result = -EPROTO;
                goto finish;
        }
        malformed_error = errno;
        permission_first = malformed_error == EPERM;
        handle->handle_bytes = MAX_HANDLE_SZ + 1;
        errno = 0;
        if (open_by_handle_at(GUEST_METADATA_MOUNT_FD, handle, O_RDONLY | O_CLOEXEC) >= 0 ||
            errno != malformed_error) {
                result = -EPROTO;
                goto finish;
        }
        handle->handle_bytes = state->handle_bytes;
        handle->handle_type = -1;
        errno = 0;
        if (open_by_handle_at(GUEST_METADATA_MOUNT_FD, handle, O_RDONLY | O_CLOEXEC) >= 0 ||
            errno != (permission_first ? EPERM : EINVAL)) {
                result = -EPROTO;
                goto finish;
        }
        handle->handle_type = state->handle_type;
        errno = 0;
        if (open_by_handle_at(-1, handle, O_RDONLY | O_CLOEXEC) >= 0 || errno != EBADF) {
                result = -EPROTO;
                goto finish;
        }

finish:
        free(handle);
        return result;
}

static int check_guest_stale_file_handle(const GuestFileHandleState *state, bool decode_allowed) {
        struct file_handle *handle;
        int fd;

        if (state->handle_bytes == 0)
                return 0;
        handle = guest_file_handle_from_state(state);
        if (!handle)
                return -ENOMEM;
        errno = 0;
        fd = open_by_handle_at(GUEST_METADATA_MOUNT_FD, handle, O_RDONLY | O_CLOEXEC);
        free(handle);
        if (fd >= 0) {
                close(fd);
                return -EPROTO;
        }
        if ((decode_allowed && errno != ESTALE) || (!decode_allowed && errno != EPERM))
                return -EPROTO;
        return 0;
}

static int check_guest_metadata_fds(bool exec_completed) {
        static const int persistent_fds[] = {
                GUEST_METADATA_FILE_FD,
                GUEST_METADATA_DUPLICATE_FD,
                GUEST_METADATA_INDEPENDENT_FD,
                GUEST_METADATA_MOUNT_FD,
        };
        struct stat expected, stat_buffer;
        int flags, r;

        for (size_t i = 0; i < sizeof(persistent_fds) / sizeof(persistent_fds[0]); i++) {
                flags = fcntl(persistent_fds[i], F_GETFD);
                if (flags < 0 || (flags & FD_CLOEXEC) != 0)
                        return -EPROTO;
        }
        if (fstat(GUEST_METADATA_FILE_FD, &expected) < 0 ||
            fstat(GUEST_METADATA_DUPLICATE_FD, &stat_buffer) < 0 || expected.st_dev != stat_buffer.st_dev ||
            expected.st_ino != stat_buffer.st_ino ||
            fstat(GUEST_METADATA_INDEPENDENT_FD, &stat_buffer) < 0 || expected.st_dev != stat_buffer.st_dev ||
            expected.st_ino != stat_buffer.st_ino ||
            fstat(GUEST_METADATA_MOUNT_FD, &stat_buffer) < 0 || !S_ISDIR(stat_buffer.st_mode))
                return -EPROTO;
        errno = 0;
        r = fcntl(GUEST_METADATA_CLOEXEC_FD, F_GETFD);
        if ((exec_completed && (r >= 0 || errno != EBADF)) ||
            (!exec_completed && (r < 0 || (r & FD_CLOEXEC) == 0)))
                return -EPROTO;
        return 0;
}

static int cleanup_guest_metadata_state(void) {
        char link_path[PATH_MAX], path[PATH_MAX];
        int result = 0;

        for (int fd = GUEST_METADATA_FILE_FD; fd <= GUEST_METADATA_CLOEXEC_FD; fd++)
                if (close(fd) < 0 && errno != EBADF)
                        result = -errno;
        if (make_guest_metadata_paths(path, link_path, getpid()) < 0)
                return -EOVERFLOW;
        if (unlink(link_path) < 0 && errno != ENOENT)
                result = -errno;
        if (unlink(path) < 0 && errno != ENOENT)
                result = -errno;
        return result;
}

static int validate_guest_metadata_exec(void) {
        static const char path_value[] = "child-path";
        static const char fd_value[] = "fd-value";
        static const char link_value[] = "link-value";
        static const char child_value[] = "child-value";
        GuestFileHandleState current_state, saved_state;
        char link_path[PATH_MAX], path[PATH_MAX];
        bool decode_allowed = false;
        int result = EXIT_FAILURE;

        if (make_guest_metadata_paths(path, link_path, getpid()) < 0 || check_guest_metadata_fds(true) < 0 ||
            check_guest_xattr_value(GUEST_METADATA_FILE_FD, GUEST_XATTR_PATH, path_value, sizeof(path_value)) < 0 ||
            check_guest_xattr_value(GUEST_METADATA_DUPLICATE_FD, GUEST_XATTR_FD, fd_value, sizeof(fd_value)) < 0 ||
            check_guest_xattr_value(GUEST_METADATA_INDEPENDENT_FD, GUEST_XATTR_LINK, link_value, sizeof(link_value)) < 0 ||
            check_guest_xattr_value(GUEST_METADATA_FILE_FD, GUEST_XATTR_CHILD, child_value, sizeof(child_value)) < 0 ||
            fgetxattr(
                            GUEST_METADATA_FILE_FD,
                            GUEST_XATTR_HANDLE,
                            &saved_state,
                            sizeof(saved_state)) != (ssize_t) sizeof(saved_state) ||
            check_guest_xattrat(GUEST_METADATA_INDEPENDENT_FD, link_path) < 0)
                goto finish;
        if (check_guest_file_handle_identity(path, link_path, GUEST_METADATA_FILE_FD, &current_state) < 0 ||
            !guest_file_handles_equal(&saved_state, &current_state) ||
            saved_state.unique_mount_id != current_state.unique_mount_id ||
            check_guest_open_by_handle(&saved_state, GUEST_METADATA_FILE_FD, &decode_allowed) < 0)
                goto finish;
        if (guest_flistxattr_has(GUEST_METADATA_FILE_FD, GUEST_XATTR_PATH) != 1 ||
            guest_flistxattr_has(GUEST_METADATA_FILE_FD, GUEST_XATTR_FD) != 1 ||
            guest_flistxattr_has(GUEST_METADATA_FILE_FD, GUEST_XATTR_LINK) != 1 ||
            guest_flistxattr_has(GUEST_METADATA_FILE_FD, GUEST_XATTR_CHILD) != 1 ||
            guest_flistxattr_has(GUEST_METADATA_FILE_FD, GUEST_XATTR_HANDLE) != 1)
                goto finish;
        if (removexattr(path, GUEST_XATTR_PATH) < 0 ||
            fremovexattr(GUEST_METADATA_DUPLICATE_FD, GUEST_XATTR_FD) < 0 ||
            removexattr(link_path, GUEST_XATTR_LINK) < 0 ||
            fremovexattr(GUEST_METADATA_INDEPENDENT_FD, GUEST_XATTR_CHILD) < 0 ||
            fremovexattr(GUEST_METADATA_FILE_FD, GUEST_XATTR_HANDLE) < 0 ||
            unlink(link_path) < 0 || unlink(path) < 0)
                goto finish;
        for (int fd = GUEST_METADATA_FILE_FD; fd <= GUEST_METADATA_INDEPENDENT_FD; fd++)
                if (close(fd) < 0)
                        goto finish;
        if (syncfs(GUEST_METADATA_MOUNT_FD) < 0 ||
            check_guest_stale_file_handle(&saved_state, decode_allowed) < 0 ||
            close(GUEST_METADATA_MOUNT_FD) < 0)
                goto finish;
        result = EXIT_SUCCESS;

finish:
        if (cleanup_guest_metadata_state() < 0)
                result = EXIT_FAILURE;
        if (result == EXIT_SUCCESS)
                printf("KVM_FILE_METADATA_OK\n");
        return result;
}

static int run_guest_metadata_exec(const char *self) {
        static const char child_path_value[] = "child-path";
        static const char child_value[] = "child-value";
        GuestFileHandleState handle_state;
        char link_path[PATH_MAX] = {}, path[PATH_MAX] = {};
        bool decode_allowed;
        int file_fd = -1, independent_fd = -1, mount_fd = -1, status;
        pid_t child;

        if (make_guest_metadata_paths(path, link_path, getpid()) < 0)
                goto fail;
        file_fd = open(path, O_CREAT | O_EXCL | O_RDWR, 0600);
        if (file_fd < 0 || symlink(path, link_path) < 0 ||
            prepare_guest_metadata_xattrs(path, link_path, file_fd) < 0)
                goto fail;
        independent_fd = open(path, O_RDWR);
        mount_fd = open("/var/tmp", O_RDONLY | O_DIRECTORY);
        if (independent_fd < 0 || mount_fd < 0 ||
            move_guest_metadata_fd(file_fd, GUEST_METADATA_FILE_FD, false) < 0 ||
            dup2(GUEST_METADATA_FILE_FD, GUEST_METADATA_DUPLICATE_FD) != GUEST_METADATA_DUPLICATE_FD ||
            move_guest_metadata_fd(independent_fd, GUEST_METADATA_INDEPENDENT_FD, false) < 0 ||
            move_guest_metadata_fd(mount_fd, GUEST_METADATA_MOUNT_FD, false) < 0 ||
            dup3(GUEST_METADATA_FILE_FD, GUEST_METADATA_CLOEXEC_FD, O_CLOEXEC) != GUEST_METADATA_CLOEXEC_FD)
                goto fail;
        file_fd = GUEST_METADATA_FILE_FD;
        independent_fd = GUEST_METADATA_INDEPENDENT_FD;
        mount_fd = GUEST_METADATA_MOUNT_FD;
        if (check_guest_metadata_fds(false) < 0 ||
            check_guest_xattrat(GUEST_METADATA_FILE_FD, link_path) < 0 ||
            check_guest_file_handle_identity(path, link_path, GUEST_METADATA_FILE_FD, &handle_state) < 0 ||
            fsetxattr(
                            GUEST_METADATA_FILE_FD,
                            GUEST_XATTR_HANDLE,
                            &handle_state,
                            sizeof(handle_state),
                            XATTR_CREATE) < 0 ||
            check_guest_open_by_handle(&handle_state, GUEST_METADATA_FILE_FD, &decode_allowed) < 0)
                goto fail;

        child = fork();
        if (child < 0)
                goto fail;
        if (child == 0) {
                if (check_guest_metadata_fds(false) < 0 ||
                    fsetxattr(
                                    GUEST_METADATA_DUPLICATE_FD,
                                    GUEST_XATTR_CHILD,
                                    child_value,
                                    sizeof(child_value),
                                    XATTR_CREATE) < 0 ||
                    fsetxattr(
                                    GUEST_METADATA_DUPLICATE_FD,
                                    GUEST_XATTR_PATH,
                                    child_path_value,
                                    sizeof(child_path_value),
                                    XATTR_REPLACE) < 0 ||
                    check_guest_xattr_value(
                                    GUEST_METADATA_INDEPENDENT_FD,
                                    GUEST_XATTR_CHILD,
                                    child_value,
                                    sizeof(child_value)) < 0)
                        _exit(176);
                _exit(0);
        }
        if (waitpid(child, &status, 0) != child || !WIFEXITED(status) || WEXITSTATUS(status) != 0 ||
            check_guest_xattr_value(
                            GUEST_METADATA_FILE_FD,
                            GUEST_XATTR_PATH,
                            child_path_value,
                            sizeof(child_path_value)) < 0)
                goto fail;

        execl(self, self, "--guest-exec-target", "--expect-file-metadata", NULL);
fail:
        if (file_fd >= 0 && file_fd != GUEST_METADATA_FILE_FD)
                close(file_fd);
        if (independent_fd >= 0 && independent_fd != GUEST_METADATA_INDEPENDENT_FD)
                close(independent_fd);
        if (mount_fd >= 0 && mount_fd != GUEST_METADATA_MOUNT_FD)
                close(mount_fd);
        cleanup_guest_metadata_state();
        if (link_path[0] != 0)
                unlink(link_path);
        if (path[0] != 0)
                unlink(path);
        return -EPROTO;
}

static int test_guest_metadata_exec(const char *self) {
        int status;
        pid_t child;

        child = fork();
        if (child < 0)
                return EXIT_FAILURE;
        if (child == 0)
                _exit(run_guest_metadata_exec(self) < 0 ? 177 : 0);
        if (waitpid(child, &status, 0) != child || !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                return EXIT_FAILURE;
        return EXIT_SUCCESS;
}

static volatile sig_atomic_t guest_orphan_hup_seen;
static int guest_orphan_hup_fd = -1;

static void guest_orphan_hup_handler(int signal_number) {
        int saved_errno = errno;

        guest_orphan_hup_seen = signal_number == SIGHUP;
        if (guest_orphan_hup_fd >= 0)
                (void) write(guest_orphan_hup_fd, "h", 1);
        errno = saved_errno;
}

static int move_guest_job_fd(int fd, int target, bool cloexec) {
        int flags;

        if (fd < 0)
                return -EBADF;
        if (fd != target) {
                int duplicate = cloexec ? dup3(fd, target, O_CLOEXEC) : dup2(fd, target);

                if (duplicate != target)
                        return -errno;
                if (close(fd) < 0)
                        return -errno;
                return target;
        }

        flags = fcntl(fd, F_GETFD);
        if (flags < 0 || fcntl(fd, F_SETFD, cloexec ? flags | FD_CLOEXEC : flags & ~FD_CLOEXEC) < 0)
                return -errno;
        return target;
}

static int check_guest_job_fds(bool exec_completed) {
        static const int persistent_fds[] = {
                GUEST_JOB_MASTER_FD,
                GUEST_JOB_SLAVE_FD,
        };
        struct stat stat_buffer;
        int flags, result;

        for (size_t index = 0; index < sizeof(persistent_fds) / sizeof(persistent_fds[0]); index++) {
                flags = fcntl(persistent_fds[index], F_GETFD);
                if (flags < 0 || (flags & FD_CLOEXEC) != 0 || !isatty(persistent_fds[index]) ||
                    fstat(persistent_fds[index], &stat_buffer) < 0 || !S_ISCHR(stat_buffer.st_mode))
                        return -EPROTO;
        }

        errno = 0;
        result = fcntl(GUEST_JOB_CLOEXEC_FD, F_GETFD);
        if ((exec_completed && (result >= 0 || errno != EBADF)) ||
            (!exec_completed && (result < 0 || (result & FD_CLOEXEC) == 0)))
                return -EPROTO;
        return 0;
}

static int run_guest_process_group_signal(void) {
        int ready_pipe[2] = { -1, -1 }, status;
        pid_t child, parent = getpid();
        char ready;

        if (pipe2(ready_pipe, O_CLOEXEC) < 0)
                return -errno;
        child = fork();
        if (child < 0)
                return -errno;
        if (child == 0) {
                siginfo_t information;
                sigset_t mask;

                close(ready_pipe[0]);
                if (sigemptyset(&mask) < 0 || sigaddset(&mask, SIGUSR1) < 0 ||
                    sigprocmask(SIG_BLOCK, &mask, NULL) < 0 || setpgid(0, 0) < 0 ||
                    write(ready_pipe[1], "r", 1) != 1)
                        _exit(180);
                if (sigwaitinfo(&mask, &information) != SIGUSR1 || information.si_code != SI_USER ||
                    information.si_pid != parent || setpgid(0, parent) < 0 || getpgrp() != parent ||
                    getsid(0) != parent)
                        _exit(181);
                _exit(0);
        }

        close(ready_pipe[1]);
        ready_pipe[1] = -1;
        if (read(ready_pipe[0], &ready, 1) != 1 || ready != 'r' || setpgid(child, child) < 0 ||
            getpgid(child) != child || getsid(child) != parent || kill(-child, SIGUSR1) < 0 ||
            waitpid(child, &status, 0) != child || !WIFEXITED(status) || WEXITSTATUS(status) != 0) {
                kill(child, SIGKILL);
                (void) waitpid(child, NULL, 0);
                close(ready_pipe[0]);
                return -EPROTO;
        }
        close(ready_pipe[0]);
        errno = 0;
        if (getpgid(child) >= 0 || errno != ESRCH)
                return -EPROTO;
        return 0;
}

static int run_guest_tty_job_control(int master_fd, int slave_fd) {
        int control_pipe[2] = { -1, -1 }, stage_pipe[2] = { -1, -1 }, status;
        pid_t child, parent = getpid();
        char byte;

        if (pipe2(control_pipe, O_CLOEXEC) < 0 || pipe2(stage_pipe, O_CLOEXEC) < 0)
                return -errno;
        child = fork();
        if (child < 0)
                return -errno;
        if (child == 0) {
                struct sigaction action = {
                        .sa_handler = SIG_DFL,
                };
                sigset_t mask;
                int result;

                close(control_pipe[1]);
                close(stage_pipe[0]);
                if (sigemptyset(&action.sa_mask) < 0 || sigaction(SIGTTIN, &action, NULL) < 0 ||
                    sigaction(SIGTTOU, &action, NULL) < 0 || sigemptyset(&mask) < 0 ||
                    sigaddset(&mask, SIGTTIN) < 0 || sigaddset(&mask, SIGTTOU) < 0 ||
                    sigprocmask(SIG_UNBLOCK, &mask, NULL) < 0 || setpgid(0, 0) < 0 ||
                    write(stage_pipe[1], "s", 1) != 1)
                        _exit(182);
                if (read(slave_fd, &byte, 1) != 1 || byte != 'j' ||
                    write(stage_pipe[1], "r", 1) != 1 ||
                    read(control_pipe[0], &byte, 1) != 1 || byte != 'g')
                        _exit(183);
                do
                        result = tcsetpgrp(slave_fd, getpid());
                while (result < 0 && errno == EINTR);
                if (result < 0 || tcgetpgrp(slave_fd) != getpid() ||
                    write(stage_pipe[1], "t", 1) != 1)
                        _exit(184);
                _exit(0);
        }

        close(control_pipe[0]);
        control_pipe[0] = -1;
        close(stage_pipe[1]);
        stage_pipe[1] = -1;
        if (read(stage_pipe[0], &byte, 1) != 1 || byte != 's' || setpgid(child, child) < 0 ||
            waitpid(child, &status, WUNTRACED) != child || !WIFSTOPPED(status) || WSTOPSIG(status) != SIGTTIN ||
            tcsetpgrp(slave_fd, child) < 0 || kill(child, SIGCONT) < 0 ||
            write(master_fd, "j", 1) != 1 || read(stage_pipe[0], &byte, 1) != 1 || byte != 'r' ||
            tcsetpgrp(slave_fd, parent) < 0 || write(control_pipe[1], "g", 1) != 1 ||
            waitpid(child, &status, WUNTRACED) != child || !WIFSTOPPED(status) || WSTOPSIG(status) != SIGTTOU ||
            tcsetpgrp(slave_fd, child) < 0 || kill(child, SIGCONT) < 0 ||
            read(stage_pipe[0], &byte, 1) != 1 || byte != 't' ||
            waitpid(child, &status, 0) != child || !WIFEXITED(status) || WEXITSTATUS(status) != 0 ||
            tcsetpgrp(slave_fd, parent) < 0) {
                kill(child, SIGKILL);
                (void) waitpid(child, NULL, 0);
                (void) tcsetpgrp(slave_fd, parent);
                close(control_pipe[1]);
                close(stage_pipe[0]);
                return -EPROTO;
        }

        close(control_pipe[1]);
        close(stage_pipe[0]);
        return 0;
}

static int run_guest_orphaned_group(void) {
        int acknowledge_pipe[2] = { -1, -1 }, event_pipe[2] = { -1, -1 }, report_pipe[2] = { -1, -1 };
        int member_pidfd = -1, result = -EPROTO, status;
        pid_t manager = -1, member = -1;
        char byte;

        if (pipe2(acknowledge_pipe, O_CLOEXEC) < 0 || pipe2(event_pipe, O_CLOEXEC) < 0 ||
            pipe2(report_pipe, O_CLOEXEC) < 0)
                return -errno;
        manager = fork();
        if (manager < 0)
                goto finish;
        if (manager == 0) {
                close(acknowledge_pipe[1]);
                close(event_pipe[0]);
                close(report_pipe[0]);
                member = fork();
                if (member < 0)
                        _exit(185);
                if (member == 0) {
                        struct sigaction action = {
                                .sa_handler = guest_orphan_hup_handler,
                        };
                        sigset_t mask;

                        close(acknowledge_pipe[0]);
                        close(report_pipe[1]);
                        guest_orphan_hup_seen = 0;
                        guest_orphan_hup_fd = event_pipe[1];
                        if (sigemptyset(&action.sa_mask) < 0 || sigaction(SIGHUP, &action, NULL) < 0 ||
                            sigemptyset(&mask) < 0 || sigaddset(&mask, SIGHUP) < 0 ||
                            sigprocmask(SIG_UNBLOCK, &mask, NULL) < 0 || setpgid(0, 0) < 0 ||
                            raise(SIGSTOP) < 0)
                                _exit(186);
                        _exit(guest_orphan_hup_seen ? 0 : 187);
                }

                close(event_pipe[1]);
                if (waitpid(member, &status, WUNTRACED) != member || !WIFSTOPPED(status) ||
                    WSTOPSIG(status) != SIGSTOP || write(report_pipe[1], &member, sizeof(member)) != sizeof(member) ||
                    read(acknowledge_pipe[0], &byte, 1) != 1 || byte != 'a')
                        _exit(188);
                _exit(0);
        }

        close(acknowledge_pipe[0]);
        acknowledge_pipe[0] = -1;
        close(event_pipe[1]);
        event_pipe[1] = -1;
        close(report_pipe[1]);
        report_pipe[1] = -1;
        if (read(report_pipe[0], &member, sizeof(member)) != sizeof(member) || member <= 0)
                goto finish;
        member_pidfd = syscall(SYS_pidfd_open, member, 0);
        if (member_pidfd < 0 || write(acknowledge_pipe[1], "a", 1) != 1 ||
            waitpid(manager, &status, 0) != manager || !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                goto finish;
        manager = -1;

        struct pollfd poll_fd = {
                .fd = event_pipe[0],
                .events = POLLIN,
        };
        if (poll(&poll_fd, 1, 5000) != 1 || poll_fd.revents != POLLIN ||
            read(event_pipe[0], &byte, 1) != 1 || byte != 'h')
                goto finish;
        poll_fd = (struct pollfd) {
                .fd = member_pidfd,
                .events = POLLIN,
        };
        if (poll(&poll_fd, 1, 5000) != 1 || (poll_fd.revents & POLLIN) == 0)
                goto finish;
        result = 0;

finish:
        if (result < 0 && member > 0)
                (void) kill(member, SIGKILL);
        if (manager > 0) {
                (void) kill(manager, SIGKILL);
                (void) waitpid(manager, NULL, 0);
        }
        if (member_pidfd >= 0)
                close(member_pidfd);
        for (size_t index = 0; index < 2; index++) {
                if (acknowledge_pipe[index] >= 0)
                        close(acknowledge_pipe[index]);
                if (event_pipe[index] >= 0)
                        close(event_pipe[index]);
                if (report_pipe[index] >= 0)
                        close(report_pipe[index]);
        }
        return result;
}

static int cleanup_guest_job_control(void) {
        int result = 0;

        if (fcntl(GUEST_JOB_SLAVE_FD, F_GETFD) >= 0 && ioctl(GUEST_JOB_SLAVE_FD, TIOCNOTTY) < 0 &&
            errno != ENOTTY)
                result = -errno;
        for (int fd = GUEST_JOB_MASTER_FD; fd <= GUEST_JOB_CLOEXEC_FD; fd++)
                if (close(fd) < 0 && errno != EBADF)
                        result = -errno;
        return result;
}

static int validate_guest_job_control_exec(void) {
        const struct timespec timeout = {
                .tv_sec = 1,
        };
        bool saw_hangup = false, saw_tty_output = false;
        siginfo_t information;
        sigset_t mask, pending;
        pid_t session = getpid();
        int result = EXIT_FAILURE, tty_session;

        if (check_guest_job_fds(true) < 0 || getpgrp() != session || getpgid(0) != session ||
            getsid(0) != session || tcgetpgrp(GUEST_JOB_SLAVE_FD) != session ||
            ioctl(GUEST_JOB_SLAVE_FD, TIOCGSID, &tty_session) < 0 || tty_session != session ||
            sigemptyset(&mask) < 0 || sigaddset(&mask, SIGHUP) < 0 || sigaddset(&mask, SIGTTOU) < 0 ||
            sigpending(&pending) < 0 || sigismember(&pending, SIGHUP) != 1 ||
            sigismember(&pending, SIGTTOU) != 1)
                goto finish;
        for (size_t index = 0; index < 2; index++) {
                int signal_number = sigtimedwait(&mask, &information, &timeout);

                if (signal_number == SIGHUP)
                        saw_hangup = true;
                else if (signal_number == SIGTTOU)
                        saw_tty_output = true;
                else
                        goto finish;
        }
        if (!saw_hangup || !saw_tty_output)
                goto finish;
        errno = 0;
        if (setsid() >= 0 || errno != EPERM || ioctl(GUEST_JOB_SLAVE_FD, TIOCNOTTY) < 0)
                goto finish;
        tty_session = 0;
        errno = 0;
        if (ioctl(GUEST_JOB_SLAVE_FD, TIOCGSID, &tty_session) >= 0 || errno != ENOTTY)
                goto finish;
        errno = 0;
        if (tcgetpgrp(GUEST_JOB_SLAVE_FD) >= 0 || errno != ENOTTY ||
            sigpending(&pending) < 0 || sigismember(&pending, SIGHUP) != 1 ||
            sigtimedwait(&mask, &information, &timeout) != SIGHUP ||
            close(GUEST_JOB_MASTER_FD) < 0 || close(GUEST_JOB_SLAVE_FD) < 0 ||
            sigprocmask(SIG_UNBLOCK, &mask, NULL) < 0)
                goto finish;
        result = EXIT_SUCCESS;

finish:
        if (cleanup_guest_job_control() < 0)
                result = EXIT_FAILURE;
        if (result == EXIT_SUCCESS)
                printf("KVM_JOB_CONTROL_OK\n");
        return result;
}

static int run_guest_job_control_exec(const char *self) {
        struct termios attributes;
        sigset_t blocked;
        char *slave_path;
        pid_t foreign_group, session;
        int master_fd = -1, slave_fd = -1, tty_session;

        errno = 0;
        if (setpgid(0, -1) >= 0 || errno != EINVAL)
                goto fail;
        errno = 0;
        if (getpgid(INT_MAX) >= 0 || errno != ESRCH)
                goto fail;
        errno = 0;
        if (getsid(INT_MAX) >= 0 || errno != ESRCH)
                goto fail;
        session = setsid();
        if (session != getpid() || getpgrp() != session || getpgid(0) != session || getsid(0) != session)
                goto fail;
        errno = 0;
        if (setsid() >= 0 || errno != EPERM || setpgid(0, 0) >= 0 || errno != EPERM ||
            sigemptyset(&blocked) < 0 || sigaddset(&blocked, SIGHUP) < 0 ||
            sigaddset(&blocked, SIGTTOU) < 0 || sigprocmask(SIG_BLOCK, &blocked, NULL) < 0)
                goto fail;

        master_fd = posix_openpt(O_RDWR | O_NOCTTY | O_CLOEXEC);
        if (master_fd < 0 || grantpt(master_fd) < 0 || unlockpt(master_fd) < 0)
                goto fail;
        slave_path = ptsname(master_fd);
        if (!slave_path)
                goto fail;
        slave_fd = open(slave_path, O_RDWR | O_NOCTTY | O_CLOEXEC);
        tty_session = 0;
        errno = 0;
        if (slave_fd < 0 || ioctl(slave_fd, TIOCGSID, &tty_session) >= 0 || errno != ENOTTY ||
            ioctl(slave_fd, TIOCSCTTY, 0) < 0 || ioctl(slave_fd, TIOCGSID, &tty_session) < 0 ||
            tty_session != session || tcgetpgrp(slave_fd) != session || tcgetattr(slave_fd, &attributes) < 0)
                goto fail;
        cfmakeraw(&attributes);
        if (tcsetattr(slave_fd, TCSANOW, &attributes) < 0)
                goto fail;

        foreign_group = getpgid(getppid());
        errno = 0;
        if (foreign_group <= 0 || tcsetpgrp(slave_fd, foreign_group) >= 0 || errno != EPERM)
                goto fail;
        errno = 0;
        if (tcsetpgrp(slave_fd, INT_MAX) >= 0 || errno != ESRCH ||
            run_guest_process_group_signal() < 0 || run_guest_tty_job_control(master_fd, slave_fd) < 0 ||
            run_guest_orphaned_group() < 0 || tcsetpgrp(slave_fd, session) < 0 ||
            kill(getpid(), SIGHUP) < 0 || kill(getpid(), SIGTTOU) < 0 ||
            move_guest_job_fd(master_fd, GUEST_JOB_MASTER_FD, false) < 0 ||
            move_guest_job_fd(slave_fd, GUEST_JOB_SLAVE_FD, false) < 0 ||
            dup3(GUEST_JOB_SLAVE_FD, GUEST_JOB_CLOEXEC_FD, O_CLOEXEC) != GUEST_JOB_CLOEXEC_FD ||
            check_guest_job_fds(false) < 0)
                goto fail;
        master_fd = GUEST_JOB_MASTER_FD;
        slave_fd = GUEST_JOB_SLAVE_FD;
        execl(self, self, "--guest-exec-target", "--expect-job-control", NULL);

fail:
        if (slave_fd >= 0)
                (void) ioctl(slave_fd, TIOCNOTTY);
        if (master_fd >= 0 && master_fd != GUEST_JOB_MASTER_FD)
                close(master_fd);
        if (slave_fd >= 0 && slave_fd != GUEST_JOB_SLAVE_FD)
                close(slave_fd);
        cleanup_guest_job_control();
        return -EPROTO;
}

static int test_guest_job_control_exec(const char *self) {
        int status;
        pid_t child;

        child = fork();
        if (child < 0)
                return EXIT_FAILURE;
        if (child == 0)
                _exit(run_guest_job_control_exec(self) < 0 ? 189 : 0);
        if (waitpid(child, &status, 0) != child || !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                return EXIT_FAILURE;
        return EXIT_SUCCESS;
}

typedef struct GuestLinuxDirent {
        unsigned long inode;
        unsigned long offset;
        unsigned short record_length;
        char name[];
} GuestLinuxDirent;

typedef struct GuestLinuxDirent64 {
        uint64_t inode;
        int64_t offset;
        unsigned short record_length;
        unsigned char type;
        char name[];
} GuestLinuxDirent64;

typedef struct GuestDirectoryState {
        int64_t shared_offset;
        uint64_t device;
        uint64_t inode;
        char path[PATH_MAX];
} GuestDirectoryState;

typedef struct GuestDirectoryForkState {
        int64_t offset;
        int64_t bytes;
} GuestDirectoryForkState;

enum {
        GUEST_DIRECTORY_ENTRY_COUNT = 12,
        GUEST_DIRECTORY_REMOVED_INDEX = 3,
};

static int make_guest_directory_entry_name(char name[static 32], unsigned index) {
        return snprintf(name, 32, "entry-%02u", index) < 32 ? 0 : -EOVERFLOW;
}

static int create_guest_directory_entry(int directory_fd, const char *name) {
        int fd;
        ssize_t written;

        fd = openat(directory_fd, name, O_CREAT | O_EXCL | O_WRONLY | O_CLOEXEC, 0600);
        if (fd < 0)
                return -errno;
        written = write(fd, name, strlen(name));
        if (written != (ssize_t) strlen(name)) {
                int error = written < 0 ? -errno : -EIO;

                close(fd);
                return error;
        }
        if (close(fd) < 0)
                return -errno;
        return 0;
}

static int validate_guest_dirents64(
                const void *buffer,
                size_t size,
                const char *target,
                bool *ret_found,
                int64_t *ret_last_offset) {

        size_t position = 0;
        bool found = false;
        int64_t last_offset = 0;

        while (position < size) {
                const GuestLinuxDirent64 *entry;
                size_t name_capacity, name_length;

                if (size - position < offsetof(GuestLinuxDirent64, name) + 1)
                        return -EPROTO;
                entry = (const GuestLinuxDirent64*) ((const uint8_t*) buffer + position);
                if (entry->record_length < offsetof(GuestLinuxDirent64, name) + 1 ||
                    entry->record_length > size - position || entry->record_length % sizeof(uint64_t) != 0)
                        return -EPROTO;
                name_capacity = entry->record_length - offsetof(GuestLinuxDirent64, name);
                name_length = strnlen(entry->name, name_capacity);
                if (name_length == name_capacity)
                        return -EPROTO;
                if (target && strcmp(entry->name, target) == 0)
                        found = true;
                last_offset = entry->offset;
                position += entry->record_length;
        }
        if (position != size)
                return -EPROTO;
        if (ret_found)
                *ret_found = found;
        if (ret_last_offset)
                *ret_last_offset = last_offset;
        return 0;
}

static bool guest_dirents64_equal(const void *first, size_t first_size, const void *second, size_t second_size) {
        size_t first_position = 0, second_position = 0;

        if (first_size != second_size)
                return false;
        while (first_position < first_size && second_position < second_size) {
                const GuestLinuxDirent64 *first_entry =
                        (const GuestLinuxDirent64*) ((const uint8_t*) first + first_position);
                const GuestLinuxDirent64 *second_entry =
                        (const GuestLinuxDirent64*) ((const uint8_t*) second + second_position);

                if (first_entry->record_length != second_entry->record_length ||
                    first_entry->inode != second_entry->inode || first_entry->offset != second_entry->offset ||
                    first_entry->type != second_entry->type || strcmp(first_entry->name, second_entry->name) != 0)
                        return false;
                first_position += first_entry->record_length;
                second_position += second_entry->record_length;
        }
        return first_position == first_size && second_position == second_size;
}

static int validate_guest_dirents(
                const void *buffer,
                size_t size,
                int64_t *ret_last_offset) {

        size_t position = 0;
        int64_t last_offset = 0;

        while (position < size) {
                const GuestLinuxDirent *entry;
                size_t name_capacity, name_length;

                if (size - position < offsetof(GuestLinuxDirent, name) + 2)
                        return -EPROTO;
                entry = (const GuestLinuxDirent*) ((const uint8_t*) buffer + position);
                if (entry->record_length < offsetof(GuestLinuxDirent, name) + 2 ||
                    entry->record_length > size - position || entry->record_length % sizeof(long) != 0)
                        return -EPROTO;
                name_capacity = entry->record_length - offsetof(GuestLinuxDirent, name) - 1;
                name_length = strnlen(entry->name, name_capacity);
                if (name_length == name_capacity)
                        return -EPROTO;
                last_offset = (int64_t) entry->offset;
                position += entry->record_length;
        }
        if (position != size)
                return -EPROTO;
        if (ret_last_offset)
                *ret_last_offset = last_offset;
        return 0;
}

static ssize_t read_guest_dirents64(int fd, void *buffer, size_t size) {
        int64_t last_offset;
        ssize_t bytes;
        off_t current;

        bytes = syscall(SYS_getdents64, fd, buffer, size);
        if (bytes <= 0)
                return bytes < 0 ? -errno : 0;
        if (validate_guest_dirents64(buffer, (size_t) bytes, NULL, NULL, &last_offset) < 0)
                return -EPROTO;
        current = lseek(fd, 0, SEEK_CUR);
        if (current < 0 || current != (off_t) last_offset)
                return -EPROTO;
        return bytes;
}

static int validate_guest_old_directory_stream(int fd) {
        uint8_t buffer[128];
        size_t records = 0;

        if (lseek(fd, 0, SEEK_SET) != 0)
                return -errno;
        for (;;) {
                int64_t last_offset;
                ssize_t bytes;
                off_t current;

                bytes = syscall(SYS_getdents, fd, buffer, sizeof(buffer));
                if (bytes < 0)
                        return -errno;
                if (bytes == 0)
                        break;
                if (validate_guest_dirents(buffer, (size_t) bytes, &last_offset) < 0)
                        return -EPROTO;
                current = lseek(fd, 0, SEEK_CUR);
                if (current < 0 || current != (off_t) last_offset)
                        return -EPROTO;
                records++;
        }
        return records > 0 ? 0 : -EPROTO;
}

static int guest_directory_has_name(int fd, const char *name) {
        uint8_t buffer[256];
        bool found = false;

        if (lseek(fd, 0, SEEK_SET) != 0)
                return -errno;
        for (;;) {
                bool found_in_buffer;
                int64_t last_offset;
                off_t current;
                ssize_t bytes = syscall(SYS_getdents64, fd, buffer, sizeof(buffer));

                if (bytes < 0)
                        return -errno;
                if (bytes == 0)
                        return found;
                if (validate_guest_dirents64(
                                    buffer,
                                    (size_t) bytes,
                                    name,
                                    &found_in_buffer,
                                    &last_offset) < 0)
                        return -EPROTO;
                current = lseek(fd, 0, SEEK_CUR);
                if (current < 0 || current != (off_t) last_offset)
                        return -EPROTO;
                found = found || found_in_buffer;
        }
}

static int move_guest_directory_fd(int fd, int target, bool cloexec) {
        int flags;

        if (fd < 0)
                return -EBADF;
        if (fd != target) {
                int duplicate = cloexec ? dup3(fd, target, O_CLOEXEC) : dup2(fd, target);

                if (duplicate != target)
                        return -errno;
                if (close(fd) < 0)
                        return -errno;
                return target;
        }

        flags = fcntl(fd, F_GETFD);
        if (flags < 0 || fcntl(fd, F_SETFD, cloexec ? flags | FD_CLOEXEC : flags & ~FD_CLOEXEC) < 0)
                return -errno;
        return target;
}

static int remove_guest_directory_path(const char *path) {
        static const char *const extra_entries[] = {
                "late-entry",
                "target-entry",
        };
        int directory_fd = -1, result = 0;

        if (!path || path[0] == 0)
                return 0;
        directory_fd = open(path, O_RDONLY | O_DIRECTORY | O_CLOEXEC);
        if (directory_fd >= 0) {
                for (unsigned index = 0; index < GUEST_DIRECTORY_ENTRY_COUNT; index++) {
                        char name[32];

                        if (make_guest_directory_entry_name(name, index) < 0)
                                result = -EOVERFLOW;
                        else if (unlinkat(directory_fd, name, 0) < 0 && errno != ENOENT)
                                result = -errno;
                }
                for (size_t index = 0; index < sizeof(extra_entries) / sizeof(extra_entries[0]); index++)
                        if (unlinkat(directory_fd, extra_entries[index], 0) < 0 && errno != ENOENT)
                                result = -errno;
                if (close(directory_fd) < 0)
                        result = -errno;
        } else if (errno != ENOENT)
                result = -errno;
        if (rmdir(path) < 0 && errno != ENOENT)
                result = -errno;
        return result;
}

static int cleanup_guest_directory_state(const char *path) {
        int path_result, result = 0;

        for (int fd = GUEST_DIRECTORY_FD; fd <= GUEST_DIRECTORY_CLOEXEC_FD; fd++)
                if (close(fd) < 0 && errno != EBADF)
                        result = -errno;
        path_result = remove_guest_directory_path(path);
        if (path_result < 0)
                result = path_result;
        return result;
}

static int check_guest_directory_fds(bool exec_completed, const GuestDirectoryState *state) {
        static const int directory_fds[] = {
                GUEST_DIRECTORY_FD,
                GUEST_DIRECTORY_DUPLICATE_FD,
                GUEST_DIRECTORY_INDEPENDENT_FD,
        };
        struct stat stat_buffer;
        int flags, result;

        for (size_t index = 0; index < sizeof(directory_fds) / sizeof(directory_fds[0]); index++) {
                flags = fcntl(directory_fds[index], F_GETFD);
                if (flags < 0 || (flags & FD_CLOEXEC) != 0 ||
                    fstat(directory_fds[index], &stat_buffer) < 0 || !S_ISDIR(stat_buffer.st_mode) ||
                    (uint64_t) stat_buffer.st_dev != state->device || (uint64_t) stat_buffer.st_ino != state->inode)
                        return -EPROTO;
        }
        flags = fcntl(GUEST_DIRECTORY_STATE_FD, F_GETFD);
        if (flags < 0 || (flags & FD_CLOEXEC) != 0 || fstat(GUEST_DIRECTORY_STATE_FD, &stat_buffer) < 0 ||
            !S_ISREG(stat_buffer.st_mode))
                return -EPROTO;
        errno = 0;
        result = fcntl(GUEST_DIRECTORY_CLOEXEC_FD, F_GETFD);
        if ((exec_completed && (result >= 0 || errno != EBADF)) ||
            (!exec_completed && (result < 0 || (result & FD_CLOEXEC) == 0)))
                return -EPROTO;
        return 0;
}

static int advance_guest_directory_in_child(int fd, GuestDirectoryForkState *ret_state) {
        int state_pipe[2] = { -1, -1 }, status;
        pid_t child;

        if (pipe2(state_pipe, O_CLOEXEC) < 0)
                return -errno;
        child = fork();
        if (child < 0)
                return -errno;
        if (child == 0) {
                GuestDirectoryForkState state;
                uint8_t buffer[64];

                close(state_pipe[0]);
                state.bytes = read_guest_dirents64(fd, buffer, sizeof(buffer));
                state.offset = lseek(fd, 0, SEEK_CUR);
                if (state.bytes <= 0 || state.offset < 0 ||
                    write(state_pipe[1], &state, sizeof(state)) != sizeof(state))
                        _exit(190);
                _exit(0);
        }

        close(state_pipe[1]);
        state_pipe[1] = -1;
        if (read(state_pipe[0], ret_state, sizeof(*ret_state)) != sizeof(*ret_state) ||
            waitpid(child, &status, 0) != child || !WIFEXITED(status) || WEXITSTATUS(status) != 0) {
                kill(child, SIGKILL);
                (void) waitpid(child, NULL, 0);
                close(state_pipe[0]);
                return -EPROTO;
        }
        close(state_pipe[0]);
        return 0;
}

static int validate_guest_directory_exec(void) {
        GuestDirectoryState state = {};
        uint8_t expected[96], replay[96], independent[64];
        struct stat stat_buffer;
        ssize_t expected_bytes, replay_bytes;
        off_t shared_offset;
        int result = EXIT_FAILURE;

        if (pread(GUEST_DIRECTORY_STATE_FD, &state, sizeof(state), 0) != (ssize_t) sizeof(state) ||
            state.path[0] == 0 || check_guest_directory_fds(true, &state) < 0 ||
            stat(state.path, &stat_buffer) < 0 || (uint64_t) stat_buffer.st_dev != state.device ||
            (uint64_t) stat_buffer.st_ino != state.inode ||
            lseek(GUEST_DIRECTORY_FD, 0, SEEK_CUR) != (off_t) state.shared_offset ||
            lseek(GUEST_DIRECTORY_DUPLICATE_FD, 0, SEEK_CUR) != (off_t) state.shared_offset ||
            lseek(GUEST_DIRECTORY_INDEPENDENT_FD, 0, SEEK_CUR) != 0)
                goto finish;

        if (read_guest_dirents64(GUEST_DIRECTORY_INDEPENDENT_FD, independent, sizeof(independent)) <= 0 ||
            lseek(GUEST_DIRECTORY_FD, 0, SEEK_CUR) != (off_t) state.shared_offset)
                goto finish;
        expected_bytes = read_guest_dirents64(GUEST_DIRECTORY_DUPLICATE_FD, expected, sizeof(expected));
        if (expected_bytes <= 0 || lseek(GUEST_DIRECTORY_FD, state.shared_offset, SEEK_SET) != state.shared_offset)
                goto finish;
        replay_bytes = read_guest_dirents64(GUEST_DIRECTORY_FD, replay, sizeof(replay));
        if (replay_bytes != expected_bytes ||
            !guest_dirents64_equal(expected, (size_t) expected_bytes, replay, (size_t) replay_bytes))
                goto finish;
        shared_offset = lseek(GUEST_DIRECTORY_DUPLICATE_FD, 0, SEEK_CUR);
        if (shared_offset < 0 || shared_offset == (off_t) state.shared_offset)
                goto finish;

        for (unsigned index = 0; index < GUEST_DIRECTORY_ENTRY_COUNT; index++) {
                char name[32];
                int found;

                if (make_guest_directory_entry_name(name, index) < 0)
                        goto finish;
                found = guest_directory_has_name(GUEST_DIRECTORY_INDEPENDENT_FD, name);
                if (found != (index == GUEST_DIRECTORY_REMOVED_INDEX ? 0 : 1))
                        goto finish;
        }
        if (guest_directory_has_name(GUEST_DIRECTORY_INDEPENDENT_FD, "late-entry") != 1 ||
            create_guest_directory_entry(GUEST_DIRECTORY_FD, "target-entry") < 0 ||
            guest_directory_has_name(GUEST_DIRECTORY_INDEPENDENT_FD, "target-entry") != 1)
                goto finish;
        result = EXIT_SUCCESS;

finish:
        if (cleanup_guest_directory_state(state.path) < 0)
                result = EXIT_FAILURE;
        if (result == EXIT_SUCCESS)
                printf("KVM_DIRECTORY_CURSOR_OK\n");
        return result;
}

static int run_guest_directory_exec(const char *self) {
        GuestDirectoryForkState child_state;
        GuestDirectoryState state = {};
        char path[] = "/tmp/kvm-directory-cursor-XXXXXX";
        uint8_t expected[96], replay[96], small_buffer[64];
        int directory_fd = -1, duplicate_fd = -1, independent_fd = -1, regular_fd = -1, state_fd = -1;
        ssize_t expected_bytes, replay_bytes;
        struct stat stat_buffer;
        off_t first_offset;

        if (!mkdtemp(path))
                goto fail;
        directory_fd = open(path, O_RDONLY | O_DIRECTORY | O_CLOEXEC);
        if (directory_fd < 0)
                goto fail;
        for (unsigned index = 0; index < GUEST_DIRECTORY_ENTRY_COUNT; index++) {
                char name[32];

                if (make_guest_directory_entry_name(name, index) < 0 ||
                    create_guest_directory_entry(directory_fd, name) < 0)
                        goto fail;
        }
        duplicate_fd = dup(directory_fd);
        independent_fd = open(path, O_RDONLY | O_DIRECTORY | O_CLOEXEC);
        regular_fd = openat(directory_fd, "entry-00", O_RDONLY | O_CLOEXEC);
        errno = 0;
        if (duplicate_fd < 0 || independent_fd < 0 || regular_fd < 0 ||
            syscall(SYS_getdents64, -1, small_buffer, sizeof(small_buffer)) >= 0 || errno != EBADF)
                goto fail;
        errno = 0;
        if (syscall(SYS_getdents64, regular_fd, small_buffer, sizeof(small_buffer)) >= 0 || errno != ENOTDIR)
                goto fail;
        errno = 0;
        if (syscall(SYS_getdents, -1, small_buffer, sizeof(small_buffer)) >= 0 || errno != EBADF)
                goto fail;
        errno = 0;
        if (syscall(SYS_getdents, regular_fd, small_buffer, sizeof(small_buffer)) >= 0 || errno != ENOTDIR)
                goto fail;
        errno = 0;
        if (syscall(SYS_getdents64, directory_fd, (void*) (uintptr_t) 1, sizeof(small_buffer)) >= 0 ||
            errno != EFAULT)
                goto fail;
        errno = 0;
        if (syscall(SYS_getdents64, directory_fd, small_buffer, 1) >= 0 || errno != EINVAL)
                goto fail;
        errno = 0;
        if (syscall(SYS_getdents, directory_fd, small_buffer, 1) >= 0 || errno != EINVAL)
                goto fail;
        errno = 0;
        if (lseek(directory_fd, 0, INT_MAX) >= 0 || errno != EINVAL)
                goto fail;
        if (close(regular_fd) < 0)
                goto fail;
        regular_fd = -1;

        if (lseek(directory_fd, 0, SEEK_SET) != 0 ||
            read_guest_dirents64(directory_fd, small_buffer, sizeof(small_buffer)) <= 0 ||
            create_guest_directory_entry(directory_fd, "late-entry") < 0 ||
            unlinkat(directory_fd, "entry-03", 0) < 0 ||
            guest_directory_has_name(directory_fd, "late-entry") != 1 ||
            guest_directory_has_name(directory_fd, "entry-03") != 0 ||
            validate_guest_old_directory_stream(independent_fd) < 0 ||
            lseek(directory_fd, 0, SEEK_SET) != 0 ||
            read_guest_dirents64(directory_fd, small_buffer, sizeof(small_buffer)) <= 0)
                goto fail;
        first_offset = lseek(directory_fd, 0, SEEK_CUR);
        if (first_offset <= 0 || advance_guest_directory_in_child(duplicate_fd, &child_state) < 0 ||
            child_state.bytes <= 0 || child_state.offset == first_offset ||
            lseek(directory_fd, 0, SEEK_CUR) != child_state.offset)
                goto fail;
        state.shared_offset = child_state.offset;

        expected_bytes = read_guest_dirents64(duplicate_fd, expected, sizeof(expected));
        if (expected_bytes <= 0 || lseek(directory_fd, state.shared_offset, SEEK_SET) != state.shared_offset)
                goto fail;
        replay_bytes = read_guest_dirents64(directory_fd, replay, sizeof(replay));
        if (replay_bytes != expected_bytes ||
            !guest_dirents64_equal(expected, (size_t) expected_bytes, replay, (size_t) replay_bytes) ||
            lseek(directory_fd, state.shared_offset, SEEK_SET) != state.shared_offset ||
            lseek(independent_fd, 0, SEEK_SET) != 0 || fstat(directory_fd, &stat_buffer) < 0 ||
            snprintf(state.path, sizeof(state.path), "%s", path) >= (int) sizeof(state.path))
                goto fail;
        state.device = stat_buffer.st_dev;
        state.inode = stat_buffer.st_ino;
        state_fd = memfd_create("kvm-directory-state", MFD_CLOEXEC);
        if (state_fd < 0 || pwrite(state_fd, &state, sizeof(state), 0) != (ssize_t) sizeof(state) ||
            move_guest_directory_fd(directory_fd, GUEST_DIRECTORY_FD, false) < 0 ||
            move_guest_directory_fd(duplicate_fd, GUEST_DIRECTORY_DUPLICATE_FD, false) < 0 ||
            move_guest_directory_fd(independent_fd, GUEST_DIRECTORY_INDEPENDENT_FD, false) < 0 ||
            move_guest_directory_fd(state_fd, GUEST_DIRECTORY_STATE_FD, false) < 0 ||
            dup3(GUEST_DIRECTORY_FD, GUEST_DIRECTORY_CLOEXEC_FD, O_CLOEXEC) != GUEST_DIRECTORY_CLOEXEC_FD ||
            check_guest_directory_fds(false, &state) < 0)
                goto fail;
        directory_fd = GUEST_DIRECTORY_FD;
        duplicate_fd = GUEST_DIRECTORY_DUPLICATE_FD;
        independent_fd = GUEST_DIRECTORY_INDEPENDENT_FD;
        state_fd = GUEST_DIRECTORY_STATE_FD;
        execl(self, self, "--guest-exec-target", "--expect-directory-cursor", NULL);

fail:
        if (regular_fd >= 0)
                close(regular_fd);
        if (directory_fd >= 0 && directory_fd != GUEST_DIRECTORY_FD)
                close(directory_fd);
        if (duplicate_fd >= 0 && duplicate_fd != GUEST_DIRECTORY_DUPLICATE_FD)
                close(duplicate_fd);
        if (independent_fd >= 0 && independent_fd != GUEST_DIRECTORY_INDEPENDENT_FD)
                close(independent_fd);
        if (state_fd >= 0 && state_fd != GUEST_DIRECTORY_STATE_FD)
                close(state_fd);
        cleanup_guest_directory_state(path);
        return -EPROTO;
}

static int test_guest_directory_exec(const char *self) {
        int status;
        pid_t child;

        child = fork();
        if (child < 0)
                return EXIT_FAILURE;
        if (child == 0)
                _exit(run_guest_directory_exec(self) < 0 ? 191 : 0);
        if (waitpid(child, &status, 0) != child || !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                return EXIT_FAILURE;
        return EXIT_SUCCESS;
}

typedef struct GuestNamespaceState {
        uint64_t directory_device;
        uint64_t directory_inode;
        uint64_t left_device;
        uint64_t left_inode;
        uint64_t right_device;
        uint64_t right_inode;
        uint64_t tmpfile_device;
        uint64_t tmpfile_inode;
        int32_t tmpfs_whiteout;
        int32_t btrfs_whiteout;
        char path[PATH_MAX];
} GuestNamespaceState;

static const char guest_namespace_left_payload[] = "namespace-left";
static const char guest_namespace_right_payload[] = "namespace-right";
static const char guest_namespace_tmpfile_payload[] = "namespace-tmpfile";

static int create_guest_namespace_file(int directory_fd, const char *name, const char *payload) {
        size_t size = strlen(payload);
        int fd;
        ssize_t written;

        fd = openat(directory_fd, name, O_CREAT | O_EXCL | O_RDWR | O_CLOEXEC, 0600);
        if (fd < 0)
                return -errno;
        written = pwrite(fd, payload, size, 0);
        if (written != (ssize_t) size) {
                int error = written < 0 ? -errno : -EIO;

                close(fd);
                return error;
        }
        return fd;
}

static int check_guest_namespace_payload(int fd, const char *payload) {
        char buffer[64] = {};
        size_t size = strlen(payload);
        struct stat stat_buffer;

        if (size > sizeof(buffer) || fstat(fd, &stat_buffer) < 0 || stat_buffer.st_size != (off_t) size ||
            pread(fd, buffer, size, 0) != (ssize_t) size || memcmp(buffer, payload, size) != 0)
                return -EPROTO;
        return 0;
}

static bool guest_namespace_same_inode(const struct stat *first, const struct stat *second) {
        return first->st_dev == second->st_dev && first->st_ino == second->st_ino;
}

static int remove_guest_namespace_path(const char *path) {
        static const char *const entries[] = {
                "left",
                "right",
                "moved",
                "published",
                "hard-entry",
                "symlink-entry",
                "bad-link",
                "source",
                "target",
                "missing",
                "whiteout-source",
                "whiteout-destination",
        };
        int directory_fd, result = 0;

        if (!path || path[0] == 0)
                return 0;
        directory_fd = open(path, O_RDONLY | O_DIRECTORY | O_CLOEXEC);
        if (directory_fd >= 0) {
                for (size_t index = 0; index < sizeof(entries) / sizeof(entries[0]); index++)
                        if (unlinkat(directory_fd, entries[index], 0) < 0 && errno != ENOENT)
                                result = -errno;
                if (close(directory_fd) < 0)
                        result = -errno;
        } else if (errno != ENOENT)
                result = -errno;
        if (rmdir(path) < 0 && errno != ENOENT)
                result = -errno;
        return result;
}

static int run_guest_rename_matrix(const char *parent) {
        char path[PATH_MAX];
        struct stat source_stat, target_stat, path_stat, whiteout_stat;
        int directory_fd = -1, path_length, result = -EPROTO, source_fd = -1, target_fd = -1, whiteout_fd = -1;

        path_length = snprintf(path, sizeof(path), "%s/kvm-rename-matrix-XXXXXX", parent);
        if (path_length < 0)
                return -EIO;
        if (path_length >= (int) sizeof(path))
                return -EOVERFLOW;
        if (!mkdtemp(path))
                return -errno;
        directory_fd = open(path, O_RDONLY | O_DIRECTORY | O_CLOEXEC);
        if (directory_fd < 0)
                goto finish;
        source_fd = create_guest_namespace_file(directory_fd, "source", "source");
        target_fd = create_guest_namespace_file(directory_fd, "target", "target");
        if (source_fd < 0 || target_fd < 0 || fstat(source_fd, &source_stat) < 0 ||
            fstat(target_fd, &target_stat) < 0)
                goto finish;

        errno = 0;
        if (syscall(SYS_renameat2, directory_fd, "source", directory_fd, "target", UINT_MAX) >= 0 ||
            errno != EINVAL)
                goto finish;
        errno = 0;
        if (syscall(
                            SYS_renameat2,
                            directory_fd,
                            "source",
                            directory_fd,
                            "target",
                            RENAME_NOREPLACE | RENAME_EXCHANGE) >= 0 ||
            errno != EINVAL)
                goto finish;
        errno = 0;
        if (syscall(
                            SYS_renameat2,
                            directory_fd,
                            "source",
                            directory_fd,
                            "target",
                            RENAME_WHITEOUT | RENAME_EXCHANGE) >= 0 ||
            errno != EINVAL)
                goto finish;
        errno = 0;
        if (syscall(SYS_renameat2, directory_fd, "source", directory_fd, "target", RENAME_NOREPLACE) >= 0 ||
            errno != EEXIST)
                goto finish;
        errno = 0;
        if (syscall(SYS_renameat2, directory_fd, "source", directory_fd, "missing", RENAME_EXCHANGE) >= 0 ||
            errno != ENOENT)
                goto finish;
        if (syscall(SYS_renameat2, directory_fd, "source", directory_fd, "target", RENAME_EXCHANGE) < 0 ||
            fstatat(directory_fd, "source", &path_stat, 0) < 0 ||
            !guest_namespace_same_inode(&path_stat, &target_stat) ||
            fstatat(directory_fd, "target", &path_stat, 0) < 0 ||
            !guest_namespace_same_inode(&path_stat, &source_stat) ||
            syscall(SYS_renameat2, directory_fd, "source", directory_fd, "target", RENAME_EXCHANGE) < 0)
                goto finish;

        whiteout_fd = create_guest_namespace_file(directory_fd, "whiteout-source", "whiteout");
        if (whiteout_fd < 0 || fstat(whiteout_fd, &whiteout_stat) < 0)
                goto finish;
        errno = 0;
        if (syscall(
                            SYS_renameat2,
                            directory_fd,
                            "whiteout-source",
                            directory_fd,
                            "whiteout-destination",
                            RENAME_WHITEOUT) < 0) {
                if (errno != EPERM && errno != EOPNOTSUPP && errno != EINVAL)
                        goto finish;
                result = 0;
        } else {
                if (fstatat(directory_fd, "whiteout-destination", &path_stat, 0) < 0 ||
                    !guest_namespace_same_inode(&path_stat, &whiteout_stat) ||
                    fstatat(directory_fd, "whiteout-source", &path_stat, AT_SYMLINK_NOFOLLOW) < 0 ||
                    !S_ISCHR(path_stat.st_mode) || path_stat.st_rdev != 0)
                        goto finish;
                result = 1;
        }

finish:
        if (source_fd >= 0)
                close(source_fd);
        if (target_fd >= 0)
                close(target_fd);
        if (whiteout_fd >= 0)
                close(whiteout_fd);
        if (directory_fd >= 0)
                close(directory_fd);
        if (remove_guest_namespace_path(path) < 0)
                result = -EPROTO;
        return result;
}

static int move_guest_namespace_fd(int fd, int target, bool cloexec) {
        int flags;

        if (fd < 0)
                return -EBADF;
        if (fd != target) {
                int duplicate = cloexec ? dup3(fd, target, O_CLOEXEC) : dup2(fd, target);

                if (duplicate != target)
                        return -errno;
                if (close(fd) < 0)
                        return -errno;
                return target;
        }

        flags = fcntl(fd, F_GETFD);
        if (flags < 0 || fcntl(fd, F_SETFD, cloexec ? flags | FD_CLOEXEC : flags & ~FD_CLOEXEC) < 0)
                return -errno;
        return target;
}

static int check_guest_namespace_fds(bool exec_completed, const GuestNamespaceState *state) {
        static const struct {
                int fd;
                mode_t type;
        } files[] = {
                { GUEST_NAMESPACE_LEFT_FD, S_IFREG },
                { GUEST_NAMESPACE_RIGHT_FD, S_IFREG },
                { GUEST_NAMESPACE_TMPFILE_FD, S_IFREG },
                { GUEST_NAMESPACE_DIRECTORY_FD, S_IFDIR },
        };
        struct stat stat_buffer;
        int flags, result;

        for (size_t index = 0; index < sizeof(files) / sizeof(files[0]); index++) {
                uint64_t expected_device = index == 0 ? state->left_device :
                        index == 1 ? state->right_device :
                        index == 2 ? state->tmpfile_device : state->directory_device;
                uint64_t expected_inode = index == 0 ? state->left_inode :
                        index == 1 ? state->right_inode :
                        index == 2 ? state->tmpfile_inode : state->directory_inode;

                flags = fcntl(files[index].fd, F_GETFD);
                if (flags < 0 || (flags & FD_CLOEXEC) != 0 || fstat(files[index].fd, &stat_buffer) < 0 ||
                    (stat_buffer.st_mode & S_IFMT) != files[index].type ||
                    (uint64_t) stat_buffer.st_dev != expected_device ||
                    (uint64_t) stat_buffer.st_ino != expected_inode)
                        return -EPROTO;
        }
        flags = fcntl(GUEST_NAMESPACE_STATE_FD, F_GETFD);
        if (flags < 0 || (flags & FD_CLOEXEC) != 0 || fstat(GUEST_NAMESPACE_STATE_FD, &stat_buffer) < 0 ||
            !S_ISREG(stat_buffer.st_mode))
                return -EPROTO;
        errno = 0;
        result = fcntl(GUEST_NAMESPACE_CLOEXEC_FD, F_GETFD);
        if ((exec_completed && (result >= 0 || errno != EBADF)) ||
            (!exec_completed && (result < 0 || (result & FD_CLOEXEC) == 0)))
                return -EPROTO;
        return 0;
}

static int cleanup_guest_namespace_state(const char *path) {
        int path_result, result = 0;

        for (int fd = GUEST_NAMESPACE_LEFT_FD; fd <= GUEST_NAMESPACE_CLOEXEC_FD; fd++)
                if (close(fd) < 0 && errno != EBADF)
                        result = -errno;
        path_result = remove_guest_namespace_path(path);
        if (path_result < 0)
                result = path_result;
        return result;
}

static int validate_guest_namespace_exec(void) {
        GuestNamespaceState state = {};
        char link_target[32];
        struct stat left_stat, right_stat, tmpfile_stat, path_stat, link_stat;
        int link_fd = -1, result = EXIT_FAILURE;
        ssize_t link_size;

        if (pread(GUEST_NAMESPACE_STATE_FD, &state, sizeof(state), 0) != (ssize_t) sizeof(state) ||
            state.path[0] == 0 || check_guest_namespace_fds(true, &state) < 0 ||
            check_guest_namespace_payload(GUEST_NAMESPACE_LEFT_FD, guest_namespace_left_payload) < 0 ||
            check_guest_namespace_payload(GUEST_NAMESPACE_RIGHT_FD, guest_namespace_right_payload) < 0 ||
            check_guest_namespace_payload(GUEST_NAMESPACE_TMPFILE_FD, guest_namespace_tmpfile_payload) < 0 ||
            fstat(GUEST_NAMESPACE_LEFT_FD, &left_stat) < 0 ||
            fstat(GUEST_NAMESPACE_RIGHT_FD, &right_stat) < 0 ||
            fstat(GUEST_NAMESPACE_TMPFILE_FD, &tmpfile_stat) < 0 ||
            fstatat(GUEST_NAMESPACE_DIRECTORY_FD, "moved", &path_stat, 0) < 0 ||
            !guest_namespace_same_inode(&path_stat, &left_stat) ||
            fstatat(GUEST_NAMESPACE_DIRECTORY_FD, "right", &path_stat, 0) < 0 ||
            !guest_namespace_same_inode(&path_stat, &right_stat) ||
            fstatat(GUEST_NAMESPACE_DIRECTORY_FD, "hard-entry", &path_stat, 0) < 0 ||
            !guest_namespace_same_inode(&path_stat, &tmpfile_stat) ||
            fstatat(GUEST_NAMESPACE_DIRECTORY_FD, "symlink-entry", &link_stat, AT_SYMLINK_NOFOLLOW) < 0 ||
            !S_ISLNK(link_stat.st_mode))
                goto finish;
        link_size = readlinkat(
                        GUEST_NAMESPACE_DIRECTORY_FD,
                        "symlink-entry",
                        link_target,
                        sizeof(link_target));
        if (link_size != (ssize_t) strlen("hard-entry") ||
            memcmp(link_target, "hard-entry", (size_t) link_size) != 0)
                goto finish;
        link_fd = openat(GUEST_NAMESPACE_DIRECTORY_FD, "symlink-entry", O_RDONLY | O_CLOEXEC);
        if (link_fd < 0 || fstat(link_fd, &path_stat) < 0 ||
            !guest_namespace_same_inode(&path_stat, &tmpfile_stat) || close(link_fd) < 0)
                goto finish;
        link_fd = -1;
        errno = 0;
        if (fstatat(GUEST_NAMESPACE_DIRECTORY_FD, "published", &path_stat, 0) >= 0 || errno != ENOENT ||
            syscall(
                            SYS_renameat2,
                            GUEST_NAMESPACE_DIRECTORY_FD,
                            "moved",
                            GUEST_NAMESPACE_DIRECTORY_FD,
                            "right",
                            RENAME_EXCHANGE) < 0 ||
            fstatat(GUEST_NAMESPACE_DIRECTORY_FD, "moved", &path_stat, 0) < 0 ||
            !guest_namespace_same_inode(&path_stat, &right_stat) ||
            fstatat(GUEST_NAMESPACE_DIRECTORY_FD, "right", &path_stat, 0) < 0 ||
            !guest_namespace_same_inode(&path_stat, &left_stat) ||
            unlinkat(GUEST_NAMESPACE_DIRECTORY_FD, "symlink-entry", 0) < 0 ||
            unlinkat(GUEST_NAMESPACE_DIRECTORY_FD, "hard-entry", 0) < 0 ||
            unlinkat(GUEST_NAMESPACE_DIRECTORY_FD, "moved", 0) < 0 ||
            unlinkat(GUEST_NAMESPACE_DIRECTORY_FD, "right", 0) < 0 ||
            fstat(GUEST_NAMESPACE_LEFT_FD, &left_stat) < 0 || left_stat.st_nlink != 0 ||
            fstat(GUEST_NAMESPACE_RIGHT_FD, &right_stat) < 0 || right_stat.st_nlink != 0 ||
            fstat(GUEST_NAMESPACE_TMPFILE_FD, &tmpfile_stat) < 0 || tmpfile_stat.st_nlink != 0 ||
            check_guest_namespace_payload(GUEST_NAMESPACE_LEFT_FD, guest_namespace_left_payload) < 0 ||
            check_guest_namespace_payload(GUEST_NAMESPACE_RIGHT_FD, guest_namespace_right_payload) < 0 ||
            check_guest_namespace_payload(GUEST_NAMESPACE_TMPFILE_FD, guest_namespace_tmpfile_payload) < 0)
                goto finish;
        result = EXIT_SUCCESS;

finish:
        if (link_fd >= 0)
                close(link_fd);
        if (cleanup_guest_namespace_state(state.path) < 0)
                result = EXIT_FAILURE;
        if (result == EXIT_SUCCESS)
                printf(
                                "KVM_NAMESPACE_MUTATION_OK tmpfs_whiteout=%d btrfs_whiteout=%d\n",
                                state.tmpfs_whiteout,
                                state.btrfs_whiteout);
        return result;
}

static int run_guest_namespace_exec(const char *self) {
        GuestNamespaceState state = {};
        char path[] = "/tmp/kvm-namespace-mutation-XXXXXX";
        char link_target[32];
        struct stat left_stat, right_stat, tmpfile_stat, path_stat;
        int directory_fd = -1, left_fd = -1, link_fd = -1, right_fd = -1, state_fd = -1, tmpfile_fd = -1;
        int status;
        pid_t child;
        ssize_t link_size, tmpfile_written;

        state.tmpfs_whiteout = run_guest_rename_matrix("/tmp");
        state.btrfs_whiteout = run_guest_rename_matrix("/var/tmp");
        if (state.tmpfs_whiteout < 0 || state.btrfs_whiteout < 0 || !mkdtemp(path))
                goto fail;
        directory_fd = open(path, O_RDONLY | O_DIRECTORY | O_CLOEXEC);
        if (directory_fd < 0)
                goto fail;
        left_fd = create_guest_namespace_file(directory_fd, "left", guest_namespace_left_payload);
        right_fd = create_guest_namespace_file(directory_fd, "right", guest_namespace_right_payload);
        if (left_fd < 0 || right_fd < 0 || fstat(left_fd, &left_stat) < 0 || fstat(right_fd, &right_stat) < 0)
                goto fail;
        errno = 0;
        if (syscall(SYS_renameat2, directory_fd, "left", directory_fd, "right", RENAME_NOREPLACE) >= 0 ||
            errno != EEXIST ||
            syscall(SYS_renameat2, directory_fd, "left", directory_fd, "moved", RENAME_NOREPLACE) < 0 ||
            syscall(SYS_renameat2, directory_fd, "moved", directory_fd, "right", RENAME_EXCHANGE) < 0 ||
            fstatat(directory_fd, "moved", &path_stat, 0) < 0 ||
            !guest_namespace_same_inode(&path_stat, &right_stat) ||
            fstatat(directory_fd, "right", &path_stat, 0) < 0 ||
            !guest_namespace_same_inode(&path_stat, &left_stat))
                goto fail;

        child = fork();
        if (child < 0)
                goto fail;
        if (child == 0) {
                if (syscall(SYS_renameat2, directory_fd, "moved", directory_fd, "right", RENAME_EXCHANGE) < 0)
                        _exit(192);
                _exit(0);
        }
        if (waitpid(child, &status, 0) != child || !WIFEXITED(status) || WEXITSTATUS(status) != 0 ||
            fstatat(directory_fd, "moved", &path_stat, 0) < 0 ||
            !guest_namespace_same_inode(&path_stat, &left_stat) ||
            fstatat(directory_fd, "right", &path_stat, 0) < 0 ||
            !guest_namespace_same_inode(&path_stat, &right_stat))
                goto fail;

        tmpfile_fd = openat(directory_fd, ".", O_TMPFILE | O_RDWR | O_CLOEXEC, 0600);
                if (tmpfile_fd < 0)
                goto fail;
                tmpfile_written = pwrite(
                                                tmpfile_fd,
                                                guest_namespace_tmpfile_payload,
                                                strlen(guest_namespace_tmpfile_payload),
                                                0);
                if (tmpfile_written != (ssize_t) strlen(guest_namespace_tmpfile_payload) ||
                        fstat(tmpfile_fd, &tmpfile_stat) < 0 || tmpfile_stat.st_nlink != 0)
                                goto fail;
        errno = 0;
        if (linkat(tmpfile_fd, "", directory_fd, "published", 0) >= 0 || errno != ENOENT)
                goto fail;
        errno = 0;
        if (linkat(tmpfile_fd, "", directory_fd, "bad-link", UINT_MAX) >= 0 || errno != EINVAL ||
            linkat(tmpfile_fd, "", directory_fd, "published", AT_EMPTY_PATH) < 0)
                goto fail;
        errno = 0;
        if (linkat(tmpfile_fd, "", directory_fd, "published", AT_EMPTY_PATH) >= 0 || errno != EEXIST ||
            linkat(directory_fd, "published", directory_fd, "hard-entry", 0) < 0 ||
            symlinkat("hard-entry", directory_fd, "symlink-entry") < 0 ||
            fstatat(directory_fd, "published", &path_stat, 0) < 0 ||
            !guest_namespace_same_inode(&path_stat, &tmpfile_stat) ||
            fstatat(directory_fd, "hard-entry", &path_stat, 0) < 0 ||
            !guest_namespace_same_inode(&path_stat, &tmpfile_stat) ||
            fstat(tmpfile_fd, &path_stat) < 0 || path_stat.st_nlink != 2)
                goto fail;
        link_size = readlinkat(directory_fd, "symlink-entry", link_target, sizeof(link_target));
        if (link_size != (ssize_t) strlen("hard-entry") ||
            memcmp(link_target, "hard-entry", (size_t) link_size) != 0)
                goto fail;
        link_fd = openat(directory_fd, "symlink-entry", O_RDONLY | O_CLOEXEC);
        if (link_fd < 0 || fstat(link_fd, &path_stat) < 0 ||
            !guest_namespace_same_inode(&path_stat, &tmpfile_stat) || close(link_fd) < 0 ||
            unlinkat(directory_fd, "published", 0) < 0 || fstat(tmpfile_fd, &path_stat) < 0 ||
            path_stat.st_nlink != 1)
                goto fail;
        link_fd = -1;

        if (fstat(directory_fd, &path_stat) < 0 ||
            snprintf(state.path, sizeof(state.path), "%s", path) >= (int) sizeof(state.path))
                goto fail;
        state.directory_device = path_stat.st_dev;
        state.directory_inode = path_stat.st_ino;
        state.left_device = left_stat.st_dev;
        state.left_inode = left_stat.st_ino;
        state.right_device = right_stat.st_dev;
        state.right_inode = right_stat.st_ino;
        state.tmpfile_device = tmpfile_stat.st_dev;
        state.tmpfile_inode = tmpfile_stat.st_ino;
        state_fd = memfd_create("kvm-namespace-state", MFD_CLOEXEC);
        if (state_fd < 0 || pwrite(state_fd, &state, sizeof(state), 0) != (ssize_t) sizeof(state) ||
            move_guest_namespace_fd(left_fd, GUEST_NAMESPACE_LEFT_FD, false) < 0 ||
            move_guest_namespace_fd(right_fd, GUEST_NAMESPACE_RIGHT_FD, false) < 0 ||
            move_guest_namespace_fd(tmpfile_fd, GUEST_NAMESPACE_TMPFILE_FD, false) < 0 ||
            move_guest_namespace_fd(directory_fd, GUEST_NAMESPACE_DIRECTORY_FD, false) < 0 ||
            move_guest_namespace_fd(state_fd, GUEST_NAMESPACE_STATE_FD, false) < 0 ||
            dup3(GUEST_NAMESPACE_LEFT_FD, GUEST_NAMESPACE_CLOEXEC_FD, O_CLOEXEC) != GUEST_NAMESPACE_CLOEXEC_FD ||
            check_guest_namespace_fds(false, &state) < 0)
                goto fail;
        left_fd = GUEST_NAMESPACE_LEFT_FD;
        right_fd = GUEST_NAMESPACE_RIGHT_FD;
        tmpfile_fd = GUEST_NAMESPACE_TMPFILE_FD;
        directory_fd = GUEST_NAMESPACE_DIRECTORY_FD;
        state_fd = GUEST_NAMESPACE_STATE_FD;
        execl(self, self, "--guest-exec-target", "--expect-namespace-mutation", NULL);

fail:
        if (link_fd >= 0)
                close(link_fd);
        if (left_fd >= 0 && left_fd != GUEST_NAMESPACE_LEFT_FD)
                close(left_fd);
        if (right_fd >= 0 && right_fd != GUEST_NAMESPACE_RIGHT_FD)
                close(right_fd);
        if (tmpfile_fd >= 0 && tmpfile_fd != GUEST_NAMESPACE_TMPFILE_FD)
                close(tmpfile_fd);
        if (directory_fd >= 0 && directory_fd != GUEST_NAMESPACE_DIRECTORY_FD)
                close(directory_fd);
        if (state_fd >= 0 && state_fd != GUEST_NAMESPACE_STATE_FD)
                close(state_fd);
        cleanup_guest_namespace_state(path);
        return -EPROTO;
}

static int test_guest_namespace_exec(const char *self) {
        int status;
        pid_t child;

        child = fork();
        if (child < 0)
                return EXIT_FAILURE;
        if (child == 0)
                _exit(run_guest_namespace_exec(self) < 0 ? 193 : 0);
        if (waitpid(child, &status, 0) != child || !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                return EXIT_FAILURE;
        return EXIT_SUCCESS;
}

typedef struct GuestResourceUsageState {
        uint64_t magic;
        struct rusage self;
        struct rusage thread;
        struct rusage children;
        struct rusage waited_child;
        struct tms times;
        clock_t elapsed;
} GuestResourceUsageState;

typedef struct GuestResourceThreadState {
        int notify_fd;
        int result;
        struct rusage before;
        struct rusage after;
} GuestResourceThreadState;

static const uint64_t guest_resource_usage_magic = UINT64_C(0x5255534147453031);
static const uint64_t guest_timeval_delta_rounding_usec = UINT64_C(4);

static int guest_timeval_to_usec(const struct timeval *value, uint64_t *ret_usec) {
        uint64_t seconds;

        if (value->tv_sec < 0 || value->tv_usec < 0 || value->tv_usec >= 1000000)
                return -ERANGE;
        seconds = (uint64_t) value->tv_sec;
        if (seconds > (UINT64_MAX - (uint64_t) value->tv_usec) / UINT64_C(1000000))
                return -EOVERFLOW;
        *ret_usec = seconds * UINT64_C(1000000) + (uint64_t) value->tv_usec;
        return 0;
}

static bool guest_rusage_monotonic(const struct rusage *before, const struct rusage *after) {
        uint64_t after_system, after_user, before_system, before_user;

        if (guest_timeval_to_usec(&before->ru_utime, &before_user) < 0 ||
            guest_timeval_to_usec(&before->ru_stime, &before_system) < 0 ||
            guest_timeval_to_usec(&after->ru_utime, &after_user) < 0 ||
            guest_timeval_to_usec(&after->ru_stime, &after_system) < 0)
                return false;
        return after_user >= before_user && after_system >= before_system &&
               after->ru_maxrss >= before->ru_maxrss && after->ru_minflt >= before->ru_minflt &&
               after->ru_majflt >= before->ru_majflt && after->ru_inblock >= before->ru_inblock &&
               after->ru_oublock >= before->ru_oublock && after->ru_nvcsw >= before->ru_nvcsw &&
               after->ru_nivcsw >= before->ru_nivcsw;
}

static bool guest_rusage_accounting_equal(const struct rusage *first, const struct rusage *second) {
        return first->ru_utime.tv_sec == second->ru_utime.tv_sec &&
               first->ru_utime.tv_usec == second->ru_utime.tv_usec &&
               first->ru_stime.tv_sec == second->ru_stime.tv_sec &&
               first->ru_stime.tv_usec == second->ru_stime.tv_usec &&
               first->ru_maxrss == second->ru_maxrss && first->ru_minflt == second->ru_minflt &&
               first->ru_majflt == second->ru_majflt && first->ru_inblock == second->ru_inblock &&
               first->ru_oublock == second->ru_oublock && first->ru_nvcsw == second->ru_nvcsw &&
               first->ru_nivcsw == second->ru_nivcsw;
}

static bool guest_rusage_delta_contains(
                const struct rusage *before,
                const struct rusage *after,
                const struct rusage *contribution_before,
                const struct rusage *contribution_after) {

        uint64_t after_system, after_user, before_system, before_user;
        uint64_t contribution_after_system, contribution_after_user;
        uint64_t contribution_before_system, contribution_before_user;

        if (!guest_rusage_monotonic(before, after) ||
            !guest_rusage_monotonic(contribution_before, contribution_after) ||
            guest_timeval_to_usec(&before->ru_utime, &before_user) < 0 ||
            guest_timeval_to_usec(&before->ru_stime, &before_system) < 0 ||
            guest_timeval_to_usec(&after->ru_utime, &after_user) < 0 ||
            guest_timeval_to_usec(&after->ru_stime, &after_system) < 0 ||
            guest_timeval_to_usec(&contribution_before->ru_utime, &contribution_before_user) < 0 ||
            guest_timeval_to_usec(&contribution_before->ru_stime, &contribution_before_system) < 0 ||
            guest_timeval_to_usec(&contribution_after->ru_utime, &contribution_after_user) < 0 ||
            guest_timeval_to_usec(&contribution_after->ru_stime, &contribution_after_system) < 0)
                return false;

        return after_user - before_user + after_system - before_system + guest_timeval_delta_rounding_usec >=
                       contribution_after_user - contribution_before_user +
                               contribution_after_system - contribution_before_system &&
               after->ru_minflt - before->ru_minflt >=
                       contribution_after->ru_minflt - contribution_before->ru_minflt &&
               after->ru_majflt - before->ru_majflt >=
                       contribution_after->ru_majflt - contribution_before->ru_majflt &&
               after->ru_inblock - before->ru_inblock >=
                       contribution_after->ru_inblock - contribution_before->ru_inblock &&
               after->ru_oublock - before->ru_oublock >=
                       contribution_after->ru_oublock - contribution_before->ru_oublock &&
               after->ru_nvcsw - before->ru_nvcsw >=
                       contribution_after->ru_nvcsw - contribution_before->ru_nvcsw &&
               after->ru_nivcsw - before->ru_nivcsw >=
                       contribution_after->ru_nivcsw - contribution_before->ru_nivcsw;
}

static bool guest_times_monotonic(const struct tms *before, const struct tms *after) {
        return after->tms_utime >= before->tms_utime && after->tms_stime >= before->tms_stime &&
               after->tms_cutime >= before->tms_cutime && after->tms_cstime >= before->tms_cstime;
}

static int exercise_guest_processor_usage(
                int who,
                const struct rusage *before,
                struct rusage *ret_after) {

        struct rusage current, fault_before;
        volatile uint64_t accumulator = UINT64_C(0x123456789abcdef);
        uint64_t before_user, current_system, current_user, system_start;
        size_t mapping_size;
        long page_size;
        void *mapping;
        bool advanced = false;

                if (guest_timeval_to_usec(&before->ru_utime, &before_user) < 0)
                return -ERANGE;

        for (unsigned batch = 0; batch < 1024; batch++) {
                for (unsigned iteration = 0; iteration < 65536; iteration++)
                        accumulator = accumulator * UINT64_C(6364136223846793005) + UINT64_C(1442695040888963407);
                if (getrusage(who, &current) < 0)
                        return -errno;
                if (guest_timeval_to_usec(&current.ru_utime, &current_user) < 0)
                        return -ERANGE;
                if (current_user < before_user)
                        return -EPROTO;
                if (current_user - before_user >= UINT64_C(20000)) {
                        advanced = true;
                        break;
                }
        }
        (void) accumulator;
        if (!advanced)
                return -ETIMEDOUT;
        if (guest_timeval_to_usec(&current.ru_stime, &system_start) < 0)
                return -ERANGE;

        advanced = false;
        for (unsigned batch = 0; batch < 4096; batch++) {
                for (unsigned iteration = 0; iteration < 256; iteration++)
                        (void) syscall(SYS_getpid);
                if (getrusage(who, &current) < 0)
                        return -errno;
                if (guest_timeval_to_usec(&current.ru_stime, &current_system) < 0)
                        return -ERANGE;
                if (current_system < system_start)
                        return -EPROTO;
                if (current_system - system_start >= UINT64_C(20000)) {
                        advanced = true;
                        break;
                }
        }
        if (!advanced)
                return -ETIMEDOUT;

        page_size = sysconf(_SC_PAGESIZE);
        if (page_size <= 0 || (size_t) page_size > SIZE_MAX / 64)
                return -EOVERFLOW;
        mapping_size = (size_t) page_size * 64;
        mapping = mmap(NULL, mapping_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (mapping == MAP_FAILED)
                return -errno;
        if (getrusage(who, &fault_before) < 0) {
                int error = -errno;

                munmap(mapping, mapping_size);
                return error;
        }
        for (size_t offset = 0; offset < mapping_size; offset += (size_t) page_size)
                ((volatile uint8_t*) mapping)[offset] = (uint8_t) offset;
        if (getrusage(who, &current) < 0) {
                int error = -errno;

                munmap(mapping, mapping_size);
                return error;
        }
        if (!guest_rusage_monotonic(before, &current) || current.ru_minflt <= fault_before.ru_minflt) {
                munmap(mapping, mapping_size);
                return -EPROTO;
        }
        if (munmap(mapping, mapping_size) < 0)
                return -errno;
        *ret_after = current;
        return 0;
}

static void *run_guest_resource_thread(void *userdata) {
        GuestResourceThreadState *state = userdata;
        struct timespec delay = {
                .tv_nsec = 20000000,
        };
        uint8_t notification = 1;

        state->result = getrusage(RUSAGE_THREAD, &state->before) < 0 ? -errno : 0;
        while (state->result >= 0 && nanosleep(&delay, &delay) < 0)
                if (errno != EINTR) {
                        state->result = -errno;
                        break;
                }
        if (state->result >= 0)
                state->result = exercise_guest_processor_usage(RUSAGE_THREAD, &state->before, &state->after);
        if (write(state->notify_fd, &notification, sizeof(notification)) != sizeof(notification) &&
            state->result >= 0)
                state->result = -errno;
        return NULL;
}

static int exercise_guest_thread_accounting(void) {
        GuestResourceThreadState thread_state = {};
        struct rusage main_before, main_after, self_before, self_after;
        struct timespec main_delay = {
                .tv_nsec = 20000000,
        };
        struct tms times_before, times_after;
        uint8_t notification;
        pthread_t thread;
        clock_t elapsed_before, elapsed_after;
        const char *failure = NULL;
        int pipe_fds[2], r;
        ssize_t bytes;

        if (pipe2(pipe_fds, O_CLOEXEC) < 0)
                return -errno;
        elapsed_before = times(&times_before);
        if (elapsed_before == (clock_t) -1 || getrusage(RUSAGE_SELF, &self_before) < 0 ||
            getrusage(RUSAGE_THREAD, &main_before) < 0) {
                close(pipe_fds[0]);
                close(pipe_fds[1]);
                return -errno;
        }
        thread_state.notify_fd = pipe_fds[1];
        r = pthread_create(&thread, NULL, run_guest_resource_thread, &thread_state);
        if (r != 0) {
                close(pipe_fds[0]);
                close(pipe_fds[1]);
                return -r;
        }
        while (nanosleep(&main_delay, &main_delay) < 0)
                if (errno != EINTR)
                        break;
        do
                bytes = read(pipe_fds[0], &notification, sizeof(notification));
        while (bytes < 0 && errno == EINTR);
        if (getrusage(RUSAGE_THREAD, &main_after) < 0)
                bytes = -1;
        r = pthread_join(thread, NULL);
        close(pipe_fds[0]);
        close(pipe_fds[1]);
        if (bytes != sizeof(notification) || notification != 1 || r != 0 || thread_state.result < 0)
                return -EPROTO;
        elapsed_after = times(&times_after);
        if (elapsed_after == (clock_t) -1 || getrusage(RUSAGE_SELF, &self_after) < 0)
                return -errno;
        if (!guest_rusage_monotonic(&main_before, &main_after))
                failure = "main counters regressed";
        else if (main_after.ru_nvcsw <= main_before.ru_nvcsw)
                failure = "main voluntary switch did not advance";
        else if (!guest_rusage_delta_contains(
                         &self_before,
                         &self_after,
                         &thread_state.before,
                         &thread_state.after))
                failure = "worker contribution missing from process";
        else if (!guest_times_monotonic(&times_before, &times_after))
                failure = "times counters regressed";
        else if (elapsed_after < elapsed_before)
                failure = "times elapsed value regressed";
        else if (times_after.tms_utime + times_after.tms_stime <=
                 times_before.tms_utime + times_before.tms_stime)
                failure = "times process ticks did not advance";
        else if (times_after.tms_cutime != times_before.tms_cutime ||
                 times_after.tms_cstime != times_before.tms_cstime)
                failure = "thread changed child ticks";
        if (failure) {
                fprintf(
                                stderr,
                                "Guest resource thread invariant failed: %s, nvcsw=%ld->%ld,"
                                " self_minflt=%ld->%ld worker_minflt=%ld->%ld,"
                                " ticks=%ld/%ld->%ld/%ld child_ticks=%ld/%ld->%ld/%ld\n",
                                failure,
                                main_before.ru_nvcsw,
                                main_after.ru_nvcsw,
                                self_before.ru_minflt,
                                self_after.ru_minflt,
                                thread_state.before.ru_minflt,
                                thread_state.after.ru_minflt,
                                (long) times_before.tms_utime,
                                (long) times_before.tms_stime,
                                (long) times_after.tms_utime,
                                (long) times_after.tms_stime,
                                (long) times_before.tms_cutime,
                                (long) times_before.tms_cstime,
                                (long) times_after.tms_cutime,
                                (long) times_after.tms_cstime);
                return -EPROTO;
        }
        return 0;
}

static int exercise_guest_block_io(void) {
        char path[] = "/var/tmp/kvm-resource-usage-XXXXXX";
        struct rusage read_after, read_before, write_after, write_before;
        void *buffer = NULL;
        int fd = -1, result = -EPROTO, temporary_fd;
        size_t io_size = 4096;

        temporary_fd = mkstemp(path);
        if (temporary_fd < 0)
                return -errno;
        if (close(temporary_fd) < 0)
                goto finish;
        fd = open(path, O_RDWR | O_DIRECT | O_CLOEXEC);
        if (fd < 0)
                goto finish;
        if (posix_memalign(&buffer, io_size, io_size) != 0)
                goto finish;
        memset(buffer, 0x5a, io_size);
        if (getrusage(RUSAGE_THREAD, &write_before) < 0 ||
            pwrite(fd, buffer, io_size, 0) != (ssize_t) io_size || fdatasync(fd) < 0 ||
            getrusage(RUSAGE_THREAD, &write_after) < 0 ||
            !guest_rusage_monotonic(&write_before, &write_after) ||
            write_after.ru_oublock <= write_before.ru_oublock)
                goto finish;

        memset(buffer, 0, io_size);
        if (getrusage(RUSAGE_THREAD, &read_before) < 0 ||
            pread(fd, buffer, io_size, 0) != (ssize_t) io_size ||
            getrusage(RUSAGE_THREAD, &read_after) < 0 ||
            !guest_rusage_monotonic(&read_before, &read_after) ||
            read_after.ru_inblock <= read_before.ru_inblock || ((uint8_t*) buffer)[0] != 0x5a)
                goto finish;
        result = 0;

finish:
        free(buffer);
        if (fd >= 0 && close(fd) < 0)
                result = -errno;
        if (unlink(path) < 0 && errno != ENOENT)
                result = -errno;
        return result;
}

static int check_guest_resource_scalar_errors(void) {
        pid_t child;
        long result;

        errno = 0;
        result = syscall(SYS_getrusage, INT_MAX, (void*) (uintptr_t) 1);
        if (result >= 0 || errno != EINVAL)
                return -EPROTO;
        errno = 0;
        result = syscall(SYS_getrusage, RUSAGE_SELF, (void*) (uintptr_t) 1);
        if (result >= 0 || errno != EFAULT)
                return -EPROTO;
        errno = 0;
        result = syscall(SYS_times, (void*) (uintptr_t) 1);
        if (result >= 0 || errno != EFAULT || syscall(SYS_times, NULL) < 0)
                return -EPROTO;
        errno = 0;
        result = syscall(SYS_wait4, -1, NULL, UINT_MAX, NULL);
        if (result >= 0 || errno != EINVAL)
                return -EPROTO;

        child = fork();
        if (child < 0)
                return -errno;
        if (child == 0)
                _exit(0);
        do {
                errno = 0;
                result = syscall(SYS_wait4, child, NULL, 0, (void*) (uintptr_t) 1);
        } while (result < 0 && errno == EINTR);
        if (result >= 0 || errno != EFAULT) {
                (void) waitpid(child, NULL, 0);
                return -EPROTO;
        }
        errno = 0;
        if (waitpid(child, NULL, 0) >= 0 || errno != ECHILD)
                return -EPROTO;
        return 0;
}

static int exercise_guest_child_accounting(struct rusage *ret_waited_child) {
        const struct rusage zero = {};
        struct rusage child_before, child_after, children_before, children_after, children_zombie;
        struct rusage self_before, self_after, waited_child = {};
        struct tms times_before, times_after;
        siginfo_t info = {};
        clock_t elapsed_before, elapsed_after;
        int r, status;
        pid_t child, waited;

        elapsed_before = times(&times_before);
        if (elapsed_before == (clock_t) -1 || getrusage(RUSAGE_CHILDREN, &children_before) < 0 ||
            getrusage(RUSAGE_SELF, &self_before) < 0)
                return -errno;
        child = fork();
        if (child < 0)
                return -errno;
        if (child == 0) {
                struct rusage inherited_children;

                if (getrusage(RUSAGE_CHILDREN, &inherited_children) < 0 ||
                    !guest_rusage_accounting_equal(&zero, &inherited_children) ||
                    getrusage(RUSAGE_SELF, &child_before) < 0 ||
                    exercise_guest_processor_usage(RUSAGE_SELF, &child_before, &child_after) < 0)
                        _exit(196);
                _exit(0);
        }

        do
                r = waitid(P_PID, child, &info, WEXITED | WNOWAIT);
        while (r < 0 && errno == EINTR);
        if (r < 0 || info.si_pid != child ||
            info.si_code != CLD_EXITED || info.si_status != 0 ||
            getrusage(RUSAGE_CHILDREN, &children_zombie) < 0 ||
            !guest_rusage_accounting_equal(&children_before, &children_zombie)) {
                kill(child, SIGKILL);
                (void) waitpid(child, NULL, 0);
                return -EPROTO;
        }
        do
                waited = wait4(child, &status, 0, &waited_child);
        while (waited < 0 && errno == EINTR);
        if (waited != child || !WIFEXITED(status) || WEXITSTATUS(status) != 0 ||
            getrusage(RUSAGE_CHILDREN, &children_after) < 0 || getrusage(RUSAGE_SELF, &self_after) < 0)
                return -EPROTO;
        elapsed_after = times(&times_after);
        if (elapsed_after == (clock_t) -1 || !guest_rusage_monotonic(&self_before, &self_after) ||
            !guest_rusage_delta_contains(&children_before, &children_after, &zero, &waited_child) ||
            !guest_times_monotonic(&times_before, &times_after) || elapsed_after < elapsed_before ||
            times_after.tms_cutime <= times_before.tms_cutime ||
            times_after.tms_cstime <= times_before.tms_cstime || waited_child.ru_minflt <= 0)
                return -EPROTO;
        *ret_waited_child = waited_child;
        return 0;
}

static int move_guest_resource_state_fd(int fd) {
        int flags;

        if (fd != GUEST_RESOURCE_STATE_FD) {
                if (dup2(fd, GUEST_RESOURCE_STATE_FD) != GUEST_RESOURCE_STATE_FD)
                        return -errno;
                if (close(fd) < 0)
                        return -errno;
                return GUEST_RESOURCE_STATE_FD;
        }
        flags = fcntl(fd, F_GETFD);
        if (flags < 0 || fcntl(fd, F_SETFD, flags & ~FD_CLOEXEC) < 0)
                return -errno;
        return fd;
}

static int validate_guest_resource_usage_exec(void) {
        const struct rusage zero = {};
        GuestResourceUsageState state = {};
        struct rusage after, before, children, self, thread;
        struct tms times_before, times_after;
        uint64_t child_system, child_user, self_system, self_user;
        clock_t elapsed_before, elapsed_after;
        const char *failure = "read state";
        int result = EXIT_FAILURE;

        if (pread(GUEST_RESOURCE_STATE_FD, &state, sizeof(state), 0) != (ssize_t) sizeof(state) ||
            state.magic != guest_resource_usage_magic || getrusage(RUSAGE_SELF, &self) < 0 ||
            getrusage(RUSAGE_THREAD, &thread) < 0 || getrusage(RUSAGE_CHILDREN, &children) < 0)
                goto finish;
        failure = "exec continuity";
        elapsed_before = times(&times_before);
        if (elapsed_before == (clock_t) -1 || elapsed_before < state.elapsed ||
            !guest_rusage_monotonic(&state.self, &self) || !guest_rusage_monotonic(&state.thread, &thread) ||
            !guest_rusage_accounting_equal(&state.children, &children) ||
            !guest_rusage_delta_contains(&zero, &state.children, &zero, &state.waited_child) ||
            !guest_times_monotonic(&state.times, &times_before) ||
            times_before.tms_cutime != state.times.tms_cutime ||
            times_before.tms_cstime != state.times.tms_cstime)
                goto finish;

        failure = "post-exec workload";
        before = thread;
        if (exercise_guest_processor_usage(RUSAGE_THREAD, &before, &after) < 0 ||
            getrusage(RUSAGE_SELF, &self) < 0 || !guest_rusage_monotonic(&state.self, &self) ||
            !guest_rusage_delta_contains(&state.thread, &after, &before, &after))
                goto finish;
        elapsed_after = times(&times_after);
        if (elapsed_after == (clock_t) -1 || elapsed_after < elapsed_before ||
            !guest_times_monotonic(&times_before, &times_after) ||
            times_after.tms_utime + times_after.tms_stime <= times_before.tms_utime + times_before.tms_stime ||
            guest_timeval_to_usec(&self.ru_utime, &self_user) < 0 ||
            guest_timeval_to_usec(&self.ru_stime, &self_system) < 0 ||
            guest_timeval_to_usec(&children.ru_utime, &child_user) < 0 ||
            guest_timeval_to_usec(&children.ru_stime, &child_system) < 0)
                goto finish;
        result = EXIT_SUCCESS;

finish:
        if (close(GUEST_RESOURCE_STATE_FD) < 0)
                result = EXIT_FAILURE;
        if (result == EXIT_SUCCESS)
                printf(
                                "KVM_RESOURCE_USAGE_OK self_user_us=%" PRIu64
                                " self_system_us=%" PRIu64 " child_user_us=%" PRIu64
                                " child_system_us=%" PRIu64 " minflt=%ld nvcsw=%ld inblock=%ld oublock=%ld"
                                " accounting=host-task runtime_overhead=included\n",
                                self_user,
                                self_system,
                                child_user,
                                child_system,
                                self.ru_minflt,
                                self.ru_nvcsw,
                                self.ru_inblock,
                                self.ru_oublock);
        else
                fprintf(stderr, "Guest resource usage target failed at %s\n", failure);
        return result;
}

static int run_guest_resource_usage_exec(const char *self) {
        GuestResourceUsageState state = {
                .magic = guest_resource_usage_magic,
        };
        int r, state_fd = -1;

        r = check_guest_resource_scalar_errors();
        if (r < 0) {
                fprintf(stderr, "Guest resource usage scalar checks failed: %s\n", strerror(-r));
                goto fail;
        }
        r = exercise_guest_thread_accounting();
        if (r < 0) {
                fprintf(stderr, "Guest resource usage thread checks failed: %s\n", strerror(-r));
                goto fail;
        }
        r = exercise_guest_block_io();
        if (r < 0) {
                fprintf(stderr, "Guest resource usage I/O checks failed: %s\n", strerror(-r));
                goto fail;
        }
        r = exercise_guest_child_accounting(&state.waited_child);
        if (r < 0) {
                fprintf(stderr, "Guest resource usage child checks failed: %s\n", strerror(-r));
                goto fail;
        }
        if (getrusage(RUSAGE_SELF, &state.self) < 0 || getrusage(RUSAGE_THREAD, &state.thread) < 0 ||
            getrusage(RUSAGE_CHILDREN, &state.children) < 0) {
                fprintf(stderr, "Guest resource usage snapshot failed: %m\n");
                goto fail;
        }
        state.elapsed = times(&state.times);
        if (state.elapsed == (clock_t) -1)
                goto fail;
        state_fd = memfd_create("kvm-resource-usage-state", MFD_CLOEXEC);
        if (state_fd < 0 || pwrite(state_fd, &state, sizeof(state), 0) != (ssize_t) sizeof(state) ||
            move_guest_resource_state_fd(state_fd) < 0)
                goto fail;
        state_fd = GUEST_RESOURCE_STATE_FD;
        execl(self, self, "--guest-exec-target", "--expect-resource-usage", NULL);

fail:
        if (state_fd >= 0)
                close(state_fd);
        return -EPROTO;
}

static int test_guest_resource_usage_exec(const char *self) {
        int status;
        pid_t child;

        child = fork();
        if (child < 0)
                return EXIT_FAILURE;
        if (child == 0)
                _exit(run_guest_resource_usage_exec(self) < 0 ? 197 : 0);
        if (waitpid(child, &status, 0) != child || !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                return EXIT_FAILURE;
        return EXIT_SUCCESS;
}

typedef struct GuestProcessObjectState {
        uint64_t magic;
        uint64_t device;
        uint64_t inode;
        pid_t child;
        int32_t semid;
        int32_t mrelease_observed;
        char path[PATH_MAX];
} GuestProcessObjectState;

typedef struct GuestKcmpThreadContext {
        int ready_fd;
        int release_fd;
        pid_t tid;
        int result;
} GuestKcmpThreadContext;

static const uint64_t guest_process_object_magic = UINT64_C(0x4b434d504f424a31);

static long guest_kcmp(
                pid_t first,
                pid_t second,
                int type,
                unsigned long first_index,
                unsigned long second_index) {

        return syscall(SYS_kcmp, first, second, type, first_index, second_index);
}

static int move_guest_process_object_fd(int fd, int target) {
        int flags;

        if (fd < 0)
                return -EBADF;
        if (fd != target) {
                if (dup2(fd, target) != target)
                        return -errno;
                if (close(fd) < 0)
                        return -errno;
                return target;
        }
        flags = fcntl(fd, F_GETFD);
        if (flags < 0 || fcntl(fd, F_SETFD, flags & ~FD_CLOEXEC) < 0)
                return -errno;
        return target;
}

static int check_guest_kcmp_self(void) {
        static const int process_types[] = {
                KCMP_VM,
                KCMP_FILES,
                KCMP_FS,
                KCMP_SIGHAND,
                KCMP_IO,
                KCMP_SYSVSEM,
        };
        struct kcmp_epoll_slot slot = {
                .efd = GUEST_KCMP_EPOLL_FD,
                .tfd = GUEST_KCMP_TARGET_FD,
        };
        pid_t self = getpid();
        long result;

        for (size_t i = 0; i < sizeof(process_types) / sizeof(process_types[0]); i++)
                if (guest_kcmp(self, self, process_types[i], 0, 0) != 0)
                        return -EPROTO;
        if (guest_kcmp(self, self, KCMP_FILE, GUEST_KCMP_FILE_FD, GUEST_KCMP_DUPLICATE_FD) != 0 ||
            guest_kcmp(self, self, KCMP_FILE, GUEST_KCMP_FILE_FD, GUEST_KCMP_INDEPENDENT_FD) <= 0 ||
            guest_kcmp(
                            self,
                            self,
                            KCMP_EPOLL_TFD,
                            GUEST_KCMP_TARGET_FD,
                            (unsigned long) (uintptr_t) &slot) != 0)
                return -EPROTO;

        errno = 0;
        result = guest_kcmp(self, self, KCMP_TYPES, 0, 0);
        if (result >= 0 || errno != EINVAL)
                return -EPROTO;
        errno = 0;
        result = guest_kcmp(self, self, KCMP_FILE, INT_MAX, GUEST_KCMP_FILE_FD);
        if (result >= 0 || errno != EBADF)
                return -EPROTO;
        errno = 0;
        result = guest_kcmp(self, self, KCMP_EPOLL_TFD, GUEST_KCMP_TARGET_FD, 1);
        if (result >= 0 || errno != EFAULT)
                return -EPROTO;
        errno = 0;
        result = guest_kcmp(INT_MAX, self, KCMP_VM, 0, 0);
        if (result >= 0 || errno != ESRCH)
                return -EPROTO;
        return 0;
}

static int check_guest_kcmp_process(pid_t child, uint32_t shared_types) {
        static const int process_types[] = {
                KCMP_VM,
                KCMP_FILES,
                KCMP_FS,
                KCMP_SIGHAND,
                KCMP_IO,
                KCMP_SYSVSEM,
        };
        struct kcmp_epoll_slot slot = {
                .efd = GUEST_KCMP_EPOLL_FD,
                .tfd = GUEST_KCMP_TARGET_FD,
        };
        pid_t self = getpid();
        long result;

        for (size_t i = 0; i < sizeof(process_types) / sizeof(process_types[0]); i++) {
                bool shared = (shared_types & (UINT32_C(1) << process_types[i])) != 0;

                result = guest_kcmp(self, child, process_types[i], 0, 0);
                if ((shared && result != 0) || (!shared && result <= 0))
                        return -EPROTO;
        }
        if (guest_kcmp(self, child, KCMP_FILE, GUEST_KCMP_FILE_FD, GUEST_KCMP_FILE_FD) != 0 ||
            guest_kcmp(self, child, KCMP_FILE, GUEST_KCMP_FILE_FD, GUEST_KCMP_INDEPENDENT_FD) <= 0 ||
            guest_kcmp(
                            self,
                            child,
                            KCMP_EPOLL_TFD,
                            GUEST_KCMP_TARGET_FD,
                            (unsigned long) (uintptr_t) &slot) != 0)
                return -EPROTO;
        return 0;
}

static void *guest_kcmp_thread_main(void *userdata) {
        GuestKcmpThreadContext *context = userdata;
        uint8_t byte = 1;
        ssize_t n;

        context->tid = gettid();
        do
                n = write(context->ready_fd, &byte, sizeof(byte));
        while (n < 0 && errno == EINTR);
        if (n != sizeof(byte)) {
                context->result = n < 0 ? -errno : -EPROTO;
                return NULL;
        }
        do
                n = read(context->release_fd, &byte, sizeof(byte));
        while (n < 0 && errno == EINTR);
        if (n != sizeof(byte) || byte != 2)
                context->result = n < 0 ? -errno : -EPROTO;
        return NULL;
}

static int check_guest_kcmp_shared_thread(void) {
        const uint32_t shared_types =
                (UINT32_C(1) << KCMP_VM) |
                (UINT32_C(1) << KCMP_FILES) |
                (UINT32_C(1) << KCMP_FS) |
                (UINT32_C(1) << KCMP_SIGHAND) |
                (UINT32_C(1) << KCMP_SYSVSEM);
        GuestKcmpThreadContext context = {};
        uint8_t byte;
        int ready_pipe[2] = { -1, -1 }, release_pipe[2] = { -1, -1 };
        int r, result = -EPROTO;
        pthread_t thread;
        bool created = false;
        ssize_t n;
        struct pollfd poll_fd = {
                .events = POLLIN,
        };

        if (pipe2(ready_pipe, O_CLOEXEC) < 0 || pipe2(release_pipe, O_CLOEXEC) < 0)
                goto finish;
        context.ready_fd = ready_pipe[1];
        context.release_fd = release_pipe[0];
        r = pthread_create(&thread, NULL, guest_kcmp_thread_main, &context);
        if (r != 0) {
                result = -r;
                goto finish;
        }
        created = true;
        poll_fd.fd = ready_pipe[0];
        do
                r = poll(&poll_fd, 1, 10000);
        while (r < 0 && errno == EINTR);
        if (r <= 0 || (poll_fd.revents & POLLIN) == 0)
                goto finish;
        do
                n = read(ready_pipe[0], &byte, sizeof(byte));
        while (n < 0 && errno == EINTR);
        if (n == sizeof(byte) && byte == 1 && context.tid > 0)
                result = check_guest_kcmp_process(context.tid, shared_types);
        byte = 2;
        do
                n = write(release_pipe[1], &byte, sizeof(byte));
        while (n < 0 && errno == EINTR);
        if (n != sizeof(byte)) {
                result = -EPROTO;
                (void) close(release_pipe[1]);
                release_pipe[1] = -1;
        }
        if (pthread_join(thread, NULL) != 0 || context.result < 0)
                result = -EPROTO;
        created = false;

finish:
        if (created) {
                byte = 2;
                do
                        n = write(release_pipe[1], &byte, sizeof(byte));
                while (n < 0 && errno == EINTR);
                if (n != sizeof(byte)) {
                        (void) close(release_pipe[1]);
                        release_pipe[1] = -1;
                }
                (void) pthread_join(thread, NULL);
        }
        for (size_t i = 0; i < 2; i++) {
                if (ready_pipe[i] >= 0)
                        close(ready_pipe[i]);
                if (release_pipe[i] >= 0)
                        close(release_pipe[i]);
        }
        return result;
}

static int check_guest_kcmp_permission(void) {
        int sockets[2] = { -1, -1 }, status;
        pid_t child, waited;
        uint8_t byte;
        int result = -EPROTO;

        if (socketpair(AF_UNIX, SOCK_SEQPACKET | SOCK_CLOEXEC, 0, sockets) < 0)
                return -errno;
        child = fork();
        if (child < 0)
                goto finish;
        if (child == 0) {
                pid_t parent = getppid();

                close(sockets[0]);
                if (prctl(PR_SET_PDEATHSIG, SIGKILL) < 0 || getppid() != parent ||
                    prctl(PR_SET_DUMPABLE, 0) < 0 || send(sockets[1], "R", 1, 0) != 1 ||
                    recv(sockets[1], &byte, sizeof(byte), 0) != sizeof(byte) || byte != 'X')
                        _exit(200);
                _exit(0);
        }

        close(sockets[1]);
        sockets[1] = -1;
        if (recv(sockets[0], &byte, sizeof(byte), 0) != sizeof(byte) || byte != 'R')
                goto reap;
        errno = 0;
        if (guest_kcmp(getpid(), child, KCMP_VM, 0, 0) >= 0 || errno != EPERM)
                goto reap;
        if (send(sockets[0], "X", 1, 0) != 1)
                goto reap;
        result = 0;

reap:
        if (result < 0)
                kill(child, SIGKILL);
        do
                waited = waitpid(child, &status, 0);
        while (waited < 0 && errno == EINTR);
        if (waited != child || (result >= 0 && (!WIFEXITED(status) || WEXITSTATUS(status) != 0)))
                result = -EPROTO;

finish:
        if (sockets[0] >= 0)
                close(sockets[0]);
        if (sockets[1] >= 0)
                close(sockets[1]);
        return result;
}

static int run_guest_process_mrelease_attempt(size_t size, bool negative_checks, bool *ret_observed) {
        int pipe_fds[2] = { -1, -1 }, pidfd = -1, status;
        pid_t child, waited;
        uint8_t byte;
        long release_result;
        int release_errno, result = -EPROTO;

        if (pipe2(pipe_fds, O_CLOEXEC) < 0)
                return -errno;
        child = fork();
        if (child < 0)
                goto finish;
        if (child == 0) {
                long page_size = sysconf(_SC_PAGESIZE);
                uint8_t *mapping;

                close(pipe_fds[0]);
                if (page_size <= 0)
                        _exit(201);
                mapping = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
                if (mapping == MAP_FAILED)
                        _exit(202);
                for (size_t offset = 0; offset < size; offset += (size_t) page_size)
                        mapping[offset] = (uint8_t) (offset / (size_t) page_size);
                if (write(pipe_fds[1], "R", 1) != 1)
                        _exit(203);
                for (;;)
                        pause();
        }

        close(pipe_fds[1]);
        pipe_fds[1] = -1;
        do
                release_result = read(pipe_fds[0], &byte, sizeof(byte));
        while (release_result < 0 && errno == EINTR);
        if (release_result != sizeof(byte) || byte != 'R')
                goto reap;
        pidfd = syscall(SYS_pidfd_open, child, 0);
        if (pidfd < 0)
                goto reap;
        if (negative_checks) {
                errno = 0;
                release_result = syscall(SYS_process_mrelease, pidfd, UINT_MAX);
                if (release_result >= 0 || errno != EINVAL)
                        goto reap;
                errno = 0;
                release_result = syscall(SYS_process_mrelease, pidfd, 0);
                if (release_result >= 0 || errno != EINVAL)
                        goto reap;
        }
        if (kill(child, SIGKILL) < 0)
                goto reap;
        errno = 0;
        release_result = syscall(SYS_process_mrelease, pidfd, 0);
        release_errno = errno;
        if (release_result == 0)
                *ret_observed = true;
        else if (release_errno != ESRCH)
                goto reap;
        result = 0;

reap:
        if (result < 0)
                kill(child, SIGKILL);
        do
                waited = waitpid(child, &status, 0);
        while (waited < 0 && errno == EINTR);
        if (waited != child || !WIFSIGNALED(status) || WTERMSIG(status) != SIGKILL)
                result = -EPROTO;
        if (pidfd >= 0) {
                errno = 0;
                if (syscall(SYS_process_mrelease, pidfd, 0) >= 0 || errno != ESRCH)
                        result = -EPROTO;
        }

finish:
        if (pidfd >= 0)
                close(pidfd);
        if (pipe_fds[0] >= 0)
                close(pipe_fds[0]);
        if (pipe_fds[1] >= 0)
                close(pipe_fds[1]);
        return result;
}

static int check_guest_process_mrelease(void) {
        bool observed = false;
        int fd, r;

        errno = 0;
        if (syscall(SYS_process_mrelease, -1, UINT_MAX) >= 0 || errno != EINVAL)
                return -EPROTO;
        errno = 0;
        if (syscall(SYS_process_mrelease, -1, 0) >= 0 || errno != EBADF)
                return -EPROTO;
        fd = open("/dev/null", O_RDONLY | O_CLOEXEC);
        if (fd < 0)
                return -errno;
        errno = 0;
        r = syscall(SYS_process_mrelease, fd, 0);
        close(fd);
        if (r >= 0 || errno != EBADF)
                return -EPROTO;

        for (size_t size_mb = 1; size_mb <= 64 && !observed; size_mb *= 2) {
                r = run_guest_process_mrelease_attempt(
                                size_mb * UINT64_C(1024) * UINT64_C(1024),
                                size_mb == 1,
                                &observed);
                if (r < 0)
                        return r;
        }
        return observed;
}

static int start_guest_kcmp_retained_child(GuestProcessObjectState *state) {
        int sockets[2] = { -1, -1 };
        pid_t child;
        uint8_t byte;

        if (socketpair(AF_UNIX, SOCK_SEQPACKET | SOCK_CLOEXEC, 0, sockets) < 0)
                return -errno;
        child = fork();
        if (child < 0)
                goto fail;
        if (child == 0) {
                pid_t parent = getppid();

                close(sockets[0]);
                if (prctl(PR_SET_PDEATHSIG, SIGKILL) < 0 || getppid() != parent ||
                    move_guest_process_object_fd(sockets[1], GUEST_KCMP_CONTROL_FD) < 0 ||
                    send(GUEST_KCMP_CONTROL_FD, "R", 1, 0) != 1 ||
                    recv(GUEST_KCMP_CONTROL_FD, &byte, sizeof(byte), 0) != sizeof(byte) || byte != 'X')
                        _exit(204);
                _exit(0);
        }

        state->child = child;
        close(sockets[1]);
        sockets[1] = -1;
        if (move_guest_process_object_fd(sockets[0], GUEST_KCMP_CONTROL_FD) < 0)
                goto fail;
        sockets[0] = -1;
        if (recv(GUEST_KCMP_CONTROL_FD, &byte, sizeof(byte), 0) != sizeof(byte) || byte != 'R')
                goto fail;
        return 0;

fail:
        if (state->child > 0) {
                kill(state->child, SIGKILL);
                (void) waitpid(state->child, NULL, 0);
                state->child = -1;
        }
        if (sockets[0] >= 0)
                close(sockets[0]);
        if (sockets[1] >= 0)
                close(sockets[1]);
        return -EPROTO;
}

static int cleanup_guest_process_object_state(GuestProcessObjectState *state) {
        int result = 0, status;
        pid_t waited;

        if (state->child > 0) {
                if (send(GUEST_KCMP_CONTROL_FD, "X", 1, MSG_NOSIGNAL) != 1)
                        kill(state->child, SIGKILL);
                do
                        waited = waitpid(state->child, &status, 0);
                while (waited < 0 && errno == EINTR);
                if (waited != state->child ||
                    (!WIFEXITED(status) && !WIFSIGNALED(status)) ||
                    (WIFEXITED(status) && WEXITSTATUS(status) != 0))
                        result = -EPROTO;
                state->child = -1;
        }
        if (state->semid >= 0 && semctl(state->semid, 0, IPC_RMID) < 0 && errno != EINVAL)
                result = -errno;
        state->semid = -1;
        for (int fd = GUEST_KCMP_FILE_FD; fd <= GUEST_KCMP_STATE_FD; fd++)
                if (close(fd) < 0 && errno != EBADF)
                        result = -errno;
        if (state->path[0] != 0 && unlink(state->path) < 0 && errno != ENOENT)
                result = -errno;
        return result;
}

static int check_guest_process_object_fds(const GuestProcessObjectState *state) {
        struct stat file_stat, duplicate_stat, independent_stat, path_stat, target_stat, control_stat, state_stat;

        for (int fd = GUEST_KCMP_FILE_FD; fd <= GUEST_KCMP_STATE_FD; fd++) {
                int flags = fcntl(fd, F_GETFD);

                if (flags < 0 || (flags & FD_CLOEXEC) != 0)
                        return -EPROTO;
        }
        if (fstat(GUEST_KCMP_FILE_FD, &file_stat) < 0 ||
            fstat(GUEST_KCMP_DUPLICATE_FD, &duplicate_stat) < 0 ||
            fstat(GUEST_KCMP_INDEPENDENT_FD, &independent_stat) < 0 ||
            stat(state->path, &path_stat) < 0 || fstat(GUEST_KCMP_TARGET_FD, &target_stat) < 0 ||
            fstat(GUEST_KCMP_CONTROL_FD, &control_stat) < 0 || fstat(GUEST_KCMP_STATE_FD, &state_stat) < 0 ||
            !S_ISREG(file_stat.st_mode) || !S_ISREG(duplicate_stat.st_mode) ||
            !S_ISREG(independent_stat.st_mode) || !S_ISREG(path_stat.st_mode) ||
            !S_ISFIFO(target_stat.st_mode) || !S_ISSOCK(control_stat.st_mode) || !S_ISREG(state_stat.st_mode) ||
            file_stat.st_dev != duplicate_stat.st_dev || file_stat.st_ino != duplicate_stat.st_ino ||
            file_stat.st_dev != independent_stat.st_dev || file_stat.st_ino != independent_stat.st_ino ||
            file_stat.st_dev != path_stat.st_dev || file_stat.st_ino != path_stat.st_ino ||
            (uint64_t) file_stat.st_dev != state->device || (uint64_t) file_stat.st_ino != state->inode)
                return -EPROTO;
        return 0;
}

static int validate_guest_process_object_exec(void) {
        GuestProcessObjectState state = {
                .child = -1,
                .semid = -1,
        };
        const char *failure = "read state";
        int result = EXIT_FAILURE;

        if (pread(GUEST_KCMP_STATE_FD, &state, sizeof(state), 0) != (ssize_t) sizeof(state) ||
            state.magic != guest_process_object_magic || state.child <= 0 || state.semid < 0)
                goto finish;
        failure = "retained descriptors";
        if (check_guest_process_object_fds(&state) < 0)
                goto finish;
        failure = "self comparisons";
        if (check_guest_kcmp_self() < 0)
                goto finish;
        failure = "retained child comparisons";
        if (check_guest_kcmp_process(state.child, 0) < 0)
                goto finish;
        failure = "SysV semaphore state";
        if (semctl(state.semid, 0, GETVAL) != 1)
                goto finish;
        result = EXIT_SUCCESS;

finish:
        if (result != EXIT_SUCCESS)
                fprintf(stderr, "Guest process-object target failed at %s\n", failure);
        if (cleanup_guest_process_object_state(&state) < 0)
                result = EXIT_FAILURE;
        if (result == EXIT_SUCCESS)
                printf(
                                "KVM_PROCESS_OBJECTS_OK kcmp_types=%d mrelease_window=%s\n",
                                KCMP_TYPES,
                                state.mrelease_observed ? "observed" : "unobserved");
        return result;
}

static int run_guest_process_object_exec(const char *self) {
        GuestProcessObjectState state = {
                .magic = guest_process_object_magic,
                .child = -1,
                .semid = -1,
                .path = "/tmp/kvm-process-objects-XXXXXX",
        };
        struct epoll_event event = {
                .events = EPOLLIN,
        };
        struct sembuf operation = {
                .sem_num = 0,
                .sem_op = 1,
                .sem_flg = SEM_UNDO,
        };
        struct stat file_stat;
        int duplicate_fd = -1, epoll_fd = -1, file_fd = -1, independent_fd = -1;
        int pipe_fds[2] = { -1, -1 }, r, state_fd = -1;

        r = check_guest_process_mrelease();
        if (r < 0) {
                fprintf(stderr, "Guest process_mrelease checks failed: %s\n", strerror(-r));
                goto fail;
        }
        state.mrelease_observed = r;

        file_fd = mkstemp(state.path);
        if (file_fd < 0)
                goto fail;
        duplicate_fd = dup(file_fd);
        independent_fd = open(state.path, O_RDWR | O_CLOEXEC);
        if (duplicate_fd < 0 || independent_fd < 0 ||
            move_guest_process_object_fd(file_fd, GUEST_KCMP_FILE_FD) < 0 ||
            move_guest_process_object_fd(duplicate_fd, GUEST_KCMP_DUPLICATE_FD) < 0 ||
            move_guest_process_object_fd(independent_fd, GUEST_KCMP_INDEPENDENT_FD) < 0)
                goto fail;
        file_fd = GUEST_KCMP_FILE_FD;
        duplicate_fd = GUEST_KCMP_DUPLICATE_FD;
        independent_fd = GUEST_KCMP_INDEPENDENT_FD;

        if (pipe2(pipe_fds, O_CLOEXEC) < 0)
                goto fail;
        if (move_guest_process_object_fd(pipe_fds[0], GUEST_KCMP_TARGET_FD) < 0)
                goto fail;
        pipe_fds[0] = GUEST_KCMP_TARGET_FD;
        epoll_fd = epoll_create1(EPOLL_CLOEXEC);
        if (epoll_fd < 0 || move_guest_process_object_fd(epoll_fd, GUEST_KCMP_EPOLL_FD) < 0)
                goto fail;
        epoll_fd = GUEST_KCMP_EPOLL_FD;
        if (epoll_ctl(epoll_fd, EPOLL_CTL_ADD, GUEST_KCMP_TARGET_FD, &event) < 0 ||
            close(pipe_fds[1]) < 0)
                goto fail;
        pipe_fds[1] = -1;

        if (syscall(
                            SYS_ioprio_set,
                            IOPRIO_WHO_PROCESS,
                            0,
                            IOPRIO_PRIO_VALUE(IOPRIO_CLASS_BE, 4)) < 0)
                goto fail;
        state.semid = semget(IPC_PRIVATE, 1, IPC_CREAT | 0600);
        if (state.semid < 0 || semop(state.semid, &operation, 1) < 0)
                goto fail;
        r = check_guest_kcmp_self();
        if (r < 0) {
                fprintf(stderr, "Guest kcmp self checks failed: %s\n", strerror(-r));
                goto fail;
        }
        r = check_guest_kcmp_shared_thread();
        if (r < 0) {
                fprintf(stderr, "Guest kcmp shared-thread checks failed: %s\n", strerror(-r));
                goto fail;
        }
        r = check_guest_kcmp_permission();
        if (r < 0) {
                fprintf(stderr, "Guest kcmp permission checks failed: %s\n", strerror(-r));
                goto fail;
        }
        r = start_guest_kcmp_retained_child(&state);
        if (r < 0) {
                fprintf(stderr, "Guest kcmp retained child setup failed: %s\n", strerror(-r));
                goto fail;
        }
        r = check_guest_kcmp_process(state.child, 0);
        if (r < 0) {
                fprintf(stderr, "Guest kcmp retained-child checks failed: %s\n", strerror(-r));
                goto fail;
        }
        if (fstat(GUEST_KCMP_FILE_FD, &file_stat) < 0)
                goto fail;
        state.device = file_stat.st_dev;
        state.inode = file_stat.st_ino;

        state_fd = memfd_create("kvm-process-object-state", MFD_CLOEXEC);
        if (state_fd < 0 || pwrite(state_fd, &state, sizeof(state), 0) != (ssize_t) sizeof(state) ||
            move_guest_process_object_fd(state_fd, GUEST_KCMP_STATE_FD) < 0 ||
            check_guest_process_object_fds(&state) < 0)
                goto fail;
        state_fd = GUEST_KCMP_STATE_FD;
        execl(self, self, "--guest-exec-target", "--expect-process-objects", NULL);

fail:
        if (file_fd >= 0 && file_fd != GUEST_KCMP_FILE_FD)
                close(file_fd);
        if (duplicate_fd >= 0 && duplicate_fd != GUEST_KCMP_DUPLICATE_FD)
                close(duplicate_fd);
        if (independent_fd >= 0 && independent_fd != GUEST_KCMP_INDEPENDENT_FD)
                close(independent_fd);
        if (epoll_fd >= 0 && epoll_fd != GUEST_KCMP_EPOLL_FD)
                close(epoll_fd);
        if (pipe_fds[0] >= 0 && pipe_fds[0] != GUEST_KCMP_TARGET_FD)
                close(pipe_fds[0]);
        if (pipe_fds[1] >= 0)
                close(pipe_fds[1]);
        if (state_fd >= 0 && state_fd != GUEST_KCMP_STATE_FD)
                close(state_fd);
        cleanup_guest_process_object_state(&state);
        return -EPROTO;
}

static int test_guest_process_object_exec(const char *self) {
        int status;
        pid_t child;

        child = fork();
        if (child < 0)
                return EXIT_FAILURE;
        if (child == 0)
                _exit(run_guest_process_object_exec(self) < 0 ? 205 : 0);
        if (waitpid(child, &status, 0) != child || !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                return EXIT_FAILURE;
        return EXIT_SUCCESS;
}

typedef struct GuestUtsState {
        uint64_t magic;
        uint64_t original_device;
        uint64_t original_inode;
        uint64_t joined_device;
        uint64_t joined_inode;
        uint64_t user_device;
        uint64_t user_inode;
        struct utsname original_name;
        struct utsname joined_name;
} GuestUtsState;

static const uint64_t guest_uts_magic = UINT64_C(0x5554534e414d4531);
static const char guest_uts_primary_hostname[] = "kvm-uts-primary";
static const char guest_uts_primary_domain[] = "primary.invalid";
static const char guest_uts_inherited_hostname[] = "kvm-uts-inherited";
static const char guest_uts_inherited_domain[] = "inherited.invalid";
static const char guest_uts_joined_hostname[] = "kvm-uts-joined";
static const char guest_uts_joined_domain[] = "joined.invalid";
static const char guest_uts_target_hostname[] = "kvm-uts-target";
static const char guest_uts_target_domain[] = "target.invalid";

static bool guest_uts_names_equal(const struct utsname *first, const struct utsname *second) {
        return strcmp(first->sysname, second->sysname) == 0 &&
               strcmp(first->nodename, second->nodename) == 0 &&
               strcmp(first->release, second->release) == 0 &&
               strcmp(first->version, second->version) == 0 &&
               strcmp(first->machine, second->machine) == 0 &&
               strcmp(first->domainname, second->domainname) == 0;
}

static bool guest_uts_base_names_equal(const struct utsname *first, const struct utsname *second) {
        return strcmp(first->sysname, second->sysname) == 0 &&
               strcmp(first->release, second->release) == 0 &&
               strcmp(first->version, second->version) == 0 &&
               strcmp(first->machine, second->machine) == 0;
}

static int move_guest_uts_fd(int fd, int target, bool cloexec) {
        int flags;

        if (fd < 0)
                return -EBADF;
        if (fd != target) {
                int moved = cloexec ? dup3(fd, target, O_CLOEXEC) : dup2(fd, target);

                if (moved != target)
                        return -errno;
                if (close(fd) < 0) {
                        int error = -errno;

                        (void) close(target);
                        return error;
                }
                return target;
        }
        flags = fcntl(fd, F_GETFD);
        if (flags < 0 || fcntl(fd, F_SETFD, cloexec ? flags | FD_CLOEXEC : flags & ~FD_CLOEXEC) < 0)
                return -errno;
        return target;
}

static int check_guest_uts_namespace_owner(int namespace_fd, const struct stat *expected_user) {
        struct stat owner;
        int owner_fd;

        owner_fd = ioctl(namespace_fd, NS_GET_USERNS);
        if (owner_fd < 0)
                return -errno;
        if (fstat(owner_fd, &owner) < 0) {
                int error = -errno;

                close(owner_fd);
                return error;
        }
        if (close(owner_fd) < 0)
                return -errno;
        return owner.st_dev == expected_user->st_dev && owner.st_ino == expected_user->st_ino ? 0 : -EPROTO;
}

static int check_guest_uts_fds(bool exec_completed, const GuestUtsState *state) {
        struct stat original, joined, user, current_uts, current_user, state_stat;
        int flags, result;

        for (int fd = GUEST_UTS_ORIGINAL_FD; fd <= GUEST_UTS_STATE_FD; fd++) {
                flags = fcntl(fd, F_GETFD);
                if (flags < 0 || (flags & FD_CLOEXEC) != 0)
                        return -EPROTO;
        }
        if (fstat(GUEST_UTS_ORIGINAL_FD, &original) < 0 ||
            fstat(GUEST_UTS_JOINED_FD, &joined) < 0 ||
            fstat(GUEST_UTS_USER_FD, &user) < 0 || fstat(GUEST_UTS_STATE_FD, &state_stat) < 0 ||
            stat("/proc/self/ns/uts", &current_uts) < 0 || stat("/proc/self/ns/user", &current_user) < 0 ||
            !S_ISREG(original.st_mode) || !S_ISREG(joined.st_mode) || !S_ISREG(user.st_mode) ||
            !S_ISREG(state_stat.st_mode) ||
            (uint64_t) original.st_dev != state->original_device ||
            (uint64_t) original.st_ino != state->original_inode ||
            (uint64_t) joined.st_dev != state->joined_device ||
            (uint64_t) joined.st_ino != state->joined_inode ||
            (uint64_t) user.st_dev != state->user_device || (uint64_t) user.st_ino != state->user_inode ||
            original.st_dev != joined.st_dev || original.st_ino == joined.st_ino ||
            current_uts.st_dev != joined.st_dev || current_uts.st_ino != joined.st_ino ||
            current_user.st_dev != user.st_dev || current_user.st_ino != user.st_ino ||
            ioctl(GUEST_UTS_ORIGINAL_FD, NS_GET_NSTYPE) != CLONE_NEWUTS ||
            ioctl(GUEST_UTS_JOINED_FD, NS_GET_NSTYPE) != CLONE_NEWUTS ||
            ioctl(GUEST_UTS_USER_FD, NS_GET_NSTYPE) != CLONE_NEWUSER ||
            check_guest_uts_namespace_owner(GUEST_UTS_ORIGINAL_FD, &user) < 0 ||
            check_guest_uts_namespace_owner(GUEST_UTS_JOINED_FD, &user) < 0)
                return -EPROTO;

        errno = 0;
        result = fcntl(GUEST_UTS_CLOEXEC_FD, F_GETFD);
        if ((exec_completed && (result >= 0 || errno != EBADF)) ||
            (!exec_completed && (result < 0 || (result & FD_CLOEXEC) == 0)))
                return -EPROTO;
        return 0;
}

static int check_guest_uts_permission(void) {
        int status;
        pid_t child, waited;

        child = syscall(SYS_clone, CLONE_NEWUSER | SIGCHLD, NULL, NULL, NULL, 0);
        if (child < 0)
                return -errno;
        if (child == 0) {
                errno = 0;
                if (syscall(SYS_sethostname, "forbidden", strlen("forbidden")) >= 0 || errno != EPERM)
                        _exit(206);
                errno = 0;
                if (syscall(SYS_setdomainname, "forbidden", strlen("forbidden")) >= 0 || errno != EPERM)
                        _exit(207);
                _exit(0);
        }
        do
                waited = waitpid(child, &status, 0);
        while (waited < 0 && errno == EINTR);
        return waited == child && WIFEXITED(status) && WEXITSTATUS(status) == 0 ? 0 : -EPROTO;
}

static int check_guest_uts_scalar_errors(void) {
        struct utsname names;
        char maximum_name[sizeof(names.nodename) - 1];
        long result;

        memset(maximum_name, 'n', sizeof(maximum_name));
        errno = 0;
        result = syscall(SYS_uname, (void*) (uintptr_t) 1);
        if (result >= 0 || errno != EFAULT)
                return -EPROTO;
        errno = 0;
        result = syscall(SYS_sethostname, maximum_name, -1);
        if (result >= 0 || errno != EINVAL)
                return -EPROTO;
        errno = 0;
        result = syscall(SYS_sethostname, maximum_name, sizeof(names.nodename));
        if (result >= 0 || errno != EINVAL)
                return -EPROTO;
        errno = 0;
        result = syscall(SYS_sethostname, (void*) (uintptr_t) 1, 1);
        if (result >= 0 || errno != EFAULT)
                return -EPROTO;
        errno = 0;
        result = syscall(SYS_setdomainname, maximum_name, -1);
        if (result >= 0 || errno != EINVAL)
                return -EPROTO;
        errno = 0;
        result = syscall(SYS_setdomainname, maximum_name, sizeof(names.domainname));
        if (result >= 0 || errno != EINVAL)
                return -EPROTO;
        errno = 0;
        result = syscall(SYS_setdomainname, (void*) (uintptr_t) 1, 1);
        if (result >= 0 || errno != EFAULT)
                return -EPROTO;

        if (syscall(SYS_sethostname, (void*) (uintptr_t) 1, 0) < 0 ||
            syscall(SYS_setdomainname, (void*) (uintptr_t) 1, 0) < 0 || uname(&names) < 0 ||
            names.nodename[0] != 0 || names.domainname[0] != 0 ||
            syscall(SYS_sethostname, maximum_name, sizeof(maximum_name)) < 0 ||
            syscall(SYS_setdomainname, maximum_name, sizeof(maximum_name)) < 0 || uname(&names) < 0 ||
            memcmp(names.nodename, maximum_name, sizeof(maximum_name)) != 0 ||
            names.nodename[sizeof(maximum_name)] != 0 ||
            memcmp(names.domainname, maximum_name, sizeof(maximum_name)) != 0 ||
            names.domainname[sizeof(maximum_name)] != 0 ||
            sethostname(guest_uts_primary_hostname, strlen(guest_uts_primary_hostname)) < 0 ||
            setdomainname(guest_uts_primary_domain, strlen(guest_uts_primary_domain)) < 0)
                return -EPROTO;
        return 0;
}

static int exercise_guest_uts_fork_inheritance(struct utsname *ret_name) {
        int status;
        pid_t child, waited;

        child = fork();
        if (child < 0)
                return -errno;
        if (child == 0) {
                struct utsname names;

                if (sethostname(guest_uts_inherited_hostname, strlen(guest_uts_inherited_hostname)) < 0 ||
                    setdomainname(guest_uts_inherited_domain, strlen(guest_uts_inherited_domain)) < 0 ||
                    uname(&names) < 0 || strcmp(names.nodename, guest_uts_inherited_hostname) != 0 ||
                    strcmp(names.domainname, guest_uts_inherited_domain) != 0)
                        _exit(208);
                _exit(0);
        }
        do
                waited = waitpid(child, &status, 0);
        while (waited < 0 && errno == EINTR);
        if (waited != child || !WIFEXITED(status) || WEXITSTATUS(status) != 0 || uname(ret_name) < 0 ||
            strcmp(ret_name->nodename, guest_uts_inherited_hostname) != 0 ||
            strcmp(ret_name->domainname, guest_uts_inherited_domain) != 0)
                return -EPROTO;
        return 0;
}

static int start_guest_uts_joined_namespace(pid_t *ret_child, int *ret_control_fd, int *ret_namespace_fd) {
        int sockets[2] = { -1, -1 }, status;
        char path[PATH_MAX], byte;
        pid_t child, waited;
        int namespace_fd = -1;

        if (socketpair(AF_UNIX, SOCK_SEQPACKET | SOCK_CLOEXEC, 0, sockets) < 0)
                return -errno;
        child = fork();
        if (child < 0)
                goto fail;
        if (child == 0) {
                struct utsname names;

                close(sockets[0]);
                if (prctl(PR_SET_PDEATHSIG, SIGKILL) < 0 ||
                    unshare(CLONE_NEWUTS) < 0 ||
                    sethostname(guest_uts_joined_hostname, strlen(guest_uts_joined_hostname)) < 0 ||
                    setdomainname(guest_uts_joined_domain, strlen(guest_uts_joined_domain)) < 0 ||
                    uname(&names) < 0 || strcmp(names.nodename, guest_uts_joined_hostname) != 0 ||
                    strcmp(names.domainname, guest_uts_joined_domain) != 0 || send(sockets[1], "R", 1, 0) != 1 ||
                    recv(sockets[1], &byte, sizeof(byte), 0) != sizeof(byte) || byte != 'X')
                        _exit(209);
                _exit(0);
        }

        close(sockets[1]);
        sockets[1] = -1;
        if (recv(sockets[0], &byte, sizeof(byte), 0) != sizeof(byte) || byte != 'R' ||
            snprintf(path, sizeof(path), "/proc/%ld/ns/uts", (long) child) >= (int) sizeof(path))
                goto fail_child;
        namespace_fd = open(path, O_RDONLY | O_CLOEXEC);
        if (namespace_fd < 0)
                goto fail_child;

        *ret_child = child;
        *ret_control_fd = sockets[0];
        *ret_namespace_fd = namespace_fd;
        return 0;

fail_child:
        kill(child, SIGKILL);
        do
                waited = waitpid(child, &status, 0);
        while (waited < 0 && errno == EINTR);
fail:
        if (namespace_fd >= 0)
                close(namespace_fd);
        if (sockets[0] >= 0)
                close(sockets[0]);
        if (sockets[1] >= 0)
                close(sockets[1]);
        return -EPROTO;
}

static int finish_guest_uts_joined_namespace(pid_t child, int control_fd) {
        int status, result = 0;
        pid_t waited;

        if (send(control_fd, "X", 1, MSG_NOSIGNAL) != 1) {
                kill(child, SIGKILL);
                result = -EPROTO;
        }
        if (close(control_fd) < 0)
                result = -errno;
        do
                waited = waitpid(child, &status, 0);
        while (waited < 0 && errno == EINTR);
        if (waited != child || !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                result = -EPROTO;
        return result;
}

static int cleanup_guest_uts_fds(void) {
        int result = 0;

        for (int fd = GUEST_UTS_ORIGINAL_FD; fd <= GUEST_UTS_CLOEXEC_FD; fd++)
                if (close(fd) < 0 && errno != EBADF)
                        result = -errno;
        return result;
}

static int validate_guest_uts_exec(void) {
        GuestUtsState state = {};
        struct stat current;
        struct utsname names;
        const char *failure = "read state";
        int result = EXIT_FAILURE;

        if (pread(GUEST_UTS_STATE_FD, &state, sizeof(state), 0) != (ssize_t) sizeof(state) ||
            state.magic != guest_uts_magic)
                goto finish;
        failure = "retained namespace identity";
        if (check_guest_uts_fds(true, &state) < 0 || uname(&names) < 0 ||
            !guest_uts_names_equal(&names, &state.joined_name))
                goto finish;

        failure = "setns errors";
        errno = 0;
        if (setns(-1, CLONE_NEWUTS) >= 0 || errno != EBADF)
                goto finish;
        errno = 0;
        if (setns(GUEST_UTS_USER_FD, CLONE_NEWUTS) >= 0 || errno != EINVAL)
                goto finish;

        failure = "original namespace round trip";
        if (setns(GUEST_UTS_ORIGINAL_FD, CLONE_NEWUTS) < 0 || uname(&names) < 0 ||
            !guest_uts_names_equal(&names, &state.original_name) || stat("/proc/self/ns/uts", &current) < 0 ||
            (uint64_t) current.st_dev != state.original_device ||
            (uint64_t) current.st_ino != state.original_inode ||
            sethostname(guest_uts_target_hostname, strlen(guest_uts_target_hostname)) < 0 ||
            setdomainname(guest_uts_target_domain, strlen(guest_uts_target_domain)) < 0)
                goto finish;

        failure = "joined namespace round trip";
        if (setns(GUEST_UTS_JOINED_FD, 0) < 0 || uname(&names) < 0 ||
            !guest_uts_names_equal(&names, &state.joined_name) || stat("/proc/self/ns/uts", &current) < 0 ||
            (uint64_t) current.st_dev != state.joined_device || (uint64_t) current.st_ino != state.joined_inode)
                goto finish;
        result = EXIT_SUCCESS;

finish:
        if (result != EXIT_SUCCESS)
                fprintf(stderr, "Guest UTS namespace target failed at %s\n", failure);
        if (cleanup_guest_uts_fds() < 0)
                result = EXIT_FAILURE;
        if (result == EXIT_SUCCESS)
                printf("KVM_UTS_NAMESPACE_OK setns=1 owner=1\n");
        return result;
}

static int run_guest_uts_exec(const char *self) {
        GuestUtsState state = {
                .magic = guest_uts_magic,
        };
        struct stat original_stat, joined_stat, user_stat;
        struct utsname names;
        int cloexec_fd = -1, control_fd = -1, joined_fd = -1, original_fd = -1, state_fd = -1;
        int result = -EPROTO, user_fd = -1;
        pid_t helper = -1;

        if (check_guest_uts_scalar_errors() < 0)
                goto finish;
        original_fd = open("/proc/self/ns/uts", O_RDONLY | O_CLOEXEC);
        user_fd = open("/proc/self/ns/user", O_RDONLY | O_CLOEXEC);
        if (original_fd < 0 || user_fd < 0 ||
            move_guest_uts_fd(original_fd, GUEST_UTS_ORIGINAL_FD, false) < 0 ||
            move_guest_uts_fd(user_fd, GUEST_UTS_USER_FD, false) < 0 ||
            dup3(GUEST_UTS_ORIGINAL_FD, GUEST_UTS_CLOEXEC_FD, O_CLOEXEC) != GUEST_UTS_CLOEXEC_FD)
                goto finish;
        original_fd = GUEST_UTS_ORIGINAL_FD;
        user_fd = GUEST_UTS_USER_FD;
        cloexec_fd = GUEST_UTS_CLOEXEC_FD;

        if (exercise_guest_uts_fork_inheritance(&state.original_name) < 0 ||
            start_guest_uts_joined_namespace(&helper, &control_fd, &joined_fd) < 0 ||
            uname(&names) < 0 || !guest_uts_names_equal(&names, &state.original_name) ||
            move_guest_uts_fd(joined_fd, GUEST_UTS_JOINED_FD, false) < 0)
                goto finish;
        joined_fd = GUEST_UTS_JOINED_FD;
        if (fstat(original_fd, &original_stat) < 0 || fstat(joined_fd, &joined_stat) < 0 ||
            fstat(user_fd, &user_stat) < 0 || original_stat.st_ino == joined_stat.st_ino ||
            check_guest_uts_namespace_owner(original_fd, &user_stat) < 0 ||
            check_guest_uts_namespace_owner(joined_fd, &user_stat) < 0)
                goto finish;

        errno = 0;
        if (setns(joined_fd, CLONE_NEWNS) >= 0 || errno != EINVAL ||
            setns(joined_fd, CLONE_NEWUTS) < 0 || uname(&state.joined_name) < 0 ||
            strcmp(state.joined_name.nodename, guest_uts_joined_hostname) != 0 ||
            strcmp(state.joined_name.domainname, guest_uts_joined_domain) != 0 ||
            !guest_uts_base_names_equal(&state.original_name, &state.joined_name))
                goto finish;
        if (finish_guest_uts_joined_namespace(helper, control_fd) < 0)
                goto finish;
        helper = -1;
        control_fd = -1;

        state.original_device = original_stat.st_dev;
        state.original_inode = original_stat.st_ino;
        state.joined_device = joined_stat.st_dev;
        state.joined_inode = joined_stat.st_ino;
        state.user_device = user_stat.st_dev;
        state.user_inode = user_stat.st_ino;
        state_fd = memfd_create("kvm-uts-state", MFD_CLOEXEC);
        if (state_fd < 0 || pwrite(state_fd, &state, sizeof(state), 0) != (ssize_t) sizeof(state) ||
            move_guest_uts_fd(state_fd, GUEST_UTS_STATE_FD, false) < 0 || check_guest_uts_fds(false, &state) < 0)
                goto finish;
        state_fd = GUEST_UTS_STATE_FD;
        execl(self, self, "--guest-exec-target", "--expect-uts-namespace", NULL);

finish:
        if (helper > 0) {
                if (control_fd >= 0)
                        (void) finish_guest_uts_joined_namespace(helper, control_fd);
                else {
                        kill(helper, SIGKILL);
                        (void) waitpid(helper, NULL, 0);
                }
                control_fd = -1;
        } else if (control_fd >= 0)
                close(control_fd);
        if (original_fd >= 0)
                close(original_fd);
        if (joined_fd >= 0)
                close(joined_fd);
        if (user_fd >= 0)
                close(user_fd);
        if (state_fd >= 0)
                close(state_fd);
        if (cloexec_fd >= 0)
                close(cloexec_fd);
        return result;
}

static int test_guest_uts_exec(const char *self) {
        struct utsname parent_before, parent_after;
        struct stat namespace_before, namespace_after;
        int go_pipe[2] = { -1, -1 }, ready_pipe[2] = { -1, -1 }, status;
        uid_t uid = getuid();
        gid_t gid = getgid();
        pid_t child, waited;
        char byte;
        int result = EXIT_FAILURE;

        if (uname(&parent_before) < 0 || stat("/proc/self/ns/uts", &namespace_before) < 0 ||
            check_guest_uts_permission() < 0 ||
            pipe2(ready_pipe, O_CLOEXEC) < 0 || pipe2(go_pipe, O_CLOEXEC) < 0)
                goto finish;
        child = syscall(SYS_clone, CLONE_NEWUSER | CLONE_NEWUTS | SIGCHLD, NULL, NULL, NULL, 0);
        if (child < 0)
                goto finish;
        if (child == 0) {
                close(ready_pipe[0]);
                close(go_pipe[1]);
                if (write(ready_pipe[1], "r", 1) != 1 || read(go_pipe[0], &byte, 1) != 1 || byte != 'g' ||
                    setresgid(0, 0, 0) < 0 || setresuid(0, 0, 0) < 0)
                        _exit(210);
                close(ready_pipe[1]);
                close(go_pipe[0]);
                _exit(run_guest_uts_exec(self) < 0 ? 211 : 0);
        }

        close(ready_pipe[1]);
        ready_pipe[1] = -1;
        close(go_pipe[0]);
        go_pipe[0] = -1;
        if (read(ready_pipe[0], &byte, 1) != 1 || byte != 'r' ||
            map_guest_user_namespace(child, uid, gid) < 0 || write(go_pipe[1], "g", 1) != 1)
                goto fail_child;
        close(ready_pipe[0]);
        ready_pipe[0] = -1;
        close(go_pipe[1]);
        go_pipe[1] = -1;
        do
                waited = waitpid(child, &status, 0);
        while (waited < 0 && errno == EINTR);
        if (waited != child || !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                goto finish;
        if (uname(&parent_after) < 0 || stat("/proc/self/ns/uts", &namespace_after) < 0 ||
            !guest_uts_names_equal(&parent_before, &parent_after) ||
            namespace_before.st_dev != namespace_after.st_dev || namespace_before.st_ino != namespace_after.st_ino)
                goto finish;
        result = EXIT_SUCCESS;
        goto finish;

fail_child:
        close(go_pipe[1]);
        go_pipe[1] = -1;
        kill(child, SIGKILL);
        (void) waitpid(child, NULL, 0);
finish:
        for (size_t i = 0; i < 2; i++) {
                if (ready_pipe[i] >= 0)
                        close(ready_pipe[i]);
                if (go_pipe[i] >= 0)
                        close(go_pipe[i]);
        }
        return result;
}

typedef struct GuestQuotaState {
        uint64_t magic;
        uint64_t directory_device;
        uint64_t directory_inode;
        uint64_t file_device;
        uint64_t file_inode;
        int32_t positive;
        int32_t mount_errno;
        uint32_t format;
        struct if_dqblk quota;
        char path[PATH_MAX];
} GuestQuotaState;

static const uint64_t guest_quota_magic = UINT64_C(0x51554f5441535431);

static long guest_quotactl_fd(int fd, unsigned int command, uint32_t id, void *address) {
        return syscall(SYS_quotactl_fd, fd, command, id, address);
}

static int move_guest_quota_fd(int fd, int target, bool cloexec) {
        int flags;

        if (fd < 0)
                return -EBADF;
        if (fd != target) {
                int moved = cloexec ? dup3(fd, target, O_CLOEXEC) : dup2(fd, target);

                if (moved != target)
                        return -errno;
                if (close(fd) < 0) {
                        int error = -errno;

                        (void) close(target);
                        return error;
                }
                return target;
        }
        flags = fcntl(fd, F_GETFD);
        if (flags < 0 || fcntl(fd, F_SETFD, cloexec ? flags | FD_CLOEXEC : flags & ~FD_CLOEXEC) < 0)
                return -errno;
        return target;
}

static int check_guest_quota_scalar_errors(void) {
        struct if_dqinfo info = {};
        int btrfs_fd = -1, result = -EPROTO, tmpfs_fd = -1;
        long syscall_result;

        errno = 0;
        syscall_result = syscall(
                        SYS_quotactl,
                        QCMD(Q_GETINFO, MAXQUOTAS),
                        (void*) (uintptr_t) 1,
                        0,
                        &info);
        if (syscall_result >= 0 || errno != EINVAL)
                goto finish;
        errno = 0;
        syscall_result = syscall(SYS_quotactl, QCMD(Q_GETINFO, USRQUOTA), NULL, 0, &info);
        if (syscall_result >= 0 || errno != ENODEV)
                goto finish;
        errno = 0;
        syscall_result = syscall(
                        SYS_quotactl,
                        QCMD(Q_GETINFO, USRQUOTA),
                        (void*) (uintptr_t) 1,
                        0,
                        &info);
        if (syscall_result >= 0 || errno != EFAULT)
                goto finish;
        errno = 0;
        syscall_result = syscall(SYS_quotactl, QCMD(Q_GETINFO, USRQUOTA), "/does-not-exist", 0, &info);
        if (syscall_result >= 0 || errno != ENOENT)
                goto finish;
        errno = 0;
        syscall_result = syscall(SYS_quotactl, QCMD(Q_GETINFO, USRQUOTA), "/tmp", 0, &info);
        if (syscall_result >= 0 || errno != ENOTBLK)
                goto finish;
        if (syscall(SYS_quotactl, QCMD(Q_SYNC, USRQUOTA), NULL, 0, NULL) < 0)
                goto finish;

        errno = 0;
        syscall_result = guest_quotactl_fd(-1, QCMD(Q_GETINFO, MAXQUOTAS), 0, &info);
        if (syscall_result >= 0 || errno != EBADF)
                goto finish;
        tmpfs_fd = open("/tmp", O_RDONLY | O_DIRECTORY | O_CLOEXEC);
        btrfs_fd = open("/var/tmp", O_RDONLY | O_DIRECTORY | O_CLOEXEC);
        if (tmpfs_fd < 0 || btrfs_fd < 0)
                goto finish;
        errno = 0;
        syscall_result = guest_quotactl_fd(tmpfs_fd, QCMD(Q_GETINFO, MAXQUOTAS), 0, &info);
        if (syscall_result >= 0 || errno != EINVAL)
                goto finish;
        errno = 0;
        syscall_result = guest_quotactl_fd(tmpfs_fd, QCMD(Q_GETINFO, USRQUOTA), 0, &info);
        if (syscall_result >= 0 || errno != ENOSYS)
                goto finish;
        errno = 0;
        syscall_result = guest_quotactl_fd(btrfs_fd, QCMD(Q_GETINFO, USRQUOTA), 0, &info);
        if (syscall_result >= 0 || errno != ENOSYS)
                goto finish;
        errno = 0;
        syscall_result = guest_quotactl_fd(
                        tmpfs_fd,
                        QCMD(Q_GETINFO, USRQUOTA),
                        0,
                        (void*) (uintptr_t) 1);
        if (syscall_result >= 0 || errno != ENOSYS)
                goto finish;
        result = 0;

finish:
        if (tmpfs_fd >= 0)
                close(tmpfs_fd);
        if (btrfs_fd >= 0)
                close(btrfs_fd);
        return result;
}

static int check_guest_quota_unsupported(int fd) {
        static const unsigned int commands[] = {
                Q_GETFMT,
                Q_GETINFO,
                Q_GETQUOTA,
                Q_SETQUOTA,
                Q_QUOTAON,
                Q_QUOTAOFF,
        };
        union {
                uint32_t format;
                struct if_dqinfo info;
                struct if_dqblk quota;
        } data = {};

        for (size_t i = 0; i < sizeof(commands) / sizeof(commands[0]); i++) {
                errno = 0;
                if (guest_quotactl_fd(fd, QCMD(commands[i], USRQUOTA), 0, &data) >= 0 || errno != ENOSYS)
                        return -EPROTO;
        }
        return 0;
}

static bool guest_quota_limits_equal(const struct if_dqblk *first, const struct if_dqblk *second) {
        return first->dqb_bhardlimit == second->dqb_bhardlimit &&
               first->dqb_bsoftlimit == second->dqb_bsoftlimit &&
               first->dqb_ihardlimit == second->dqb_ihardlimit &&
               first->dqb_isoftlimit == second->dqb_isoftlimit;
}

static int initialize_guest_quota_positive(GuestQuotaState *state) {
        struct if_dqblk requested = {
                .dqb_bhardlimit = 8192,
                .dqb_bsoftlimit = 4096,
                .dqb_ihardlimit = 128,
                .dqb_isoftlimit = 64,
                .dqb_valid = QIF_BLIMITS | QIF_ILIMITS,
        };
        struct if_dqinfo info;
        uint32_t format;
        uint32_t id = geteuid();
        long result;

        if (guest_quotactl_fd(
                            GUEST_QUOTA_DIRECTORY_FD,
                            QCMD(Q_GETFMT, USRQUOTA),
                            0,
                            &format) < 0 ||
            format != QFMT_SHMEM ||
            guest_quotactl_fd(
                            GUEST_QUOTA_DIRECTORY_FD,
                            QCMD(Q_GETINFO, USRQUOTA),
                            0,
                            &info) < 0)
                return -EPROTO;
        errno = 0;
        result = guest_quotactl_fd(
                        GUEST_QUOTA_DIRECTORY_FD,
                        QCMD(Q_GETFMT, USRQUOTA),
                        0,
                        (void*) (uintptr_t) 1);
        if (result >= 0 || errno != EFAULT)
                return -EPROTO;
        errno = 0;
        result = guest_quotactl_fd(
                        GUEST_QUOTA_DIRECTORY_FD,
                        QCMD(Q_SETQUOTA, USRQUOTA),
                        id,
                        (void*) (uintptr_t) 1);
        if (result >= 0 || errno != EFAULT)
                return -EPROTO;
        errno = 0;
        result = guest_quotactl_fd(GUEST_QUOTA_DIRECTORY_FD, QCMD(UINT_MAX >> SUBCMDSHIFT, USRQUOTA), 0, NULL);
        if (result >= 0 || errno != EINVAL)
                return -EPROTO;
        if (guest_quotactl_fd(
                            GUEST_QUOTA_DIRECTORY_FD,
                            QCMD(Q_SETQUOTA, USRQUOTA),
                            id,
                            &requested) < 0 ||
            guest_quotactl_fd(
                            GUEST_QUOTA_DIRECTORY_FD,
                            QCMD(Q_GETQUOTA, USRQUOTA),
                            id,
                            &state->quota) < 0 ||
            !guest_quota_limits_equal(&requested, &state->quota) || state->quota.dqb_curspace == 0 ||
            state->quota.dqb_curinodes == 0)
                return -EPROTO;
        state->format = format;
        return 0;
}

static int check_guest_quota_fork(const GuestQuotaState *state) {
        int status;
        pid_t child, waited;

        child = fork();
        if (child < 0)
                return -errno;
        if (child == 0) {
                if (state->positive) {
                        struct if_dqblk quota;
                        uint32_t format;

                        if (guest_quotactl_fd(
                                            GUEST_QUOTA_FILE_FD,
                                            QCMD(Q_GETFMT, USRQUOTA),
                                            0,
                                            &format) < 0 ||
                            format != state->format ||
                            guest_quotactl_fd(
                                            GUEST_QUOTA_FILE_FD,
                                            QCMD(Q_GETQUOTA, USRQUOTA),
                                            geteuid(),
                                            &quota) < 0 ||
                            !guest_quota_limits_equal(&quota, &state->quota) || unshare(CLONE_NEWUSER) < 0)
                                _exit(212);
                        errno = 0;
                        if (guest_quotactl_fd(
                                            GUEST_QUOTA_FILE_FD,
                                            QCMD(Q_SETQUOTA, USRQUOTA),
                                            geteuid(),
                                            &quota) >= 0 ||
                            errno != EPERM)
                                _exit(213);
                } else if (check_guest_quota_unsupported(GUEST_QUOTA_FILE_FD) < 0)
                        _exit(214);
                _exit(0);
        }
        do
                waited = waitpid(child, &status, 0);
        while (waited < 0 && errno == EINTR);
        return waited == child && WIFEXITED(status) && WEXITSTATUS(status) == 0 ? 0 : -EPROTO;
}

static int check_guest_quota_fds(bool exec_completed, const GuestQuotaState *state) {
        struct stat directory, file, path, state_stat;
        char payload[32] = {};
        int flags, result;

        for (int fd = GUEST_QUOTA_DIRECTORY_FD; fd <= GUEST_QUOTA_STATE_FD; fd++) {
                flags = fcntl(fd, F_GETFD);
                if (flags < 0 || (flags & FD_CLOEXEC) != 0)
                        return -EPROTO;
        }
        if (fstat(GUEST_QUOTA_DIRECTORY_FD, &directory) < 0 || fstat(GUEST_QUOTA_FILE_FD, &file) < 0 ||
            fstat(GUEST_QUOTA_STATE_FD, &state_stat) < 0 || stat(state->path, &path) < 0 ||
            !S_ISDIR(directory.st_mode) || !S_ISDIR(path.st_mode) || !S_ISREG(file.st_mode) ||
            !S_ISREG(state_stat.st_mode) || (uint64_t) directory.st_dev != state->directory_device ||
            (uint64_t) directory.st_ino != state->directory_inode ||
            (uint64_t) file.st_dev != state->file_device || (uint64_t) file.st_ino != state->file_inode ||
            directory.st_dev != path.st_dev || directory.st_ino != path.st_ino ||
            pread(GUEST_QUOTA_FILE_FD, payload, strlen("quota-payload"), 0) != (ssize_t) strlen("quota-payload") ||
            memcmp(payload, "quota-payload", strlen("quota-payload")) != 0)
                return -EPROTO;

        errno = 0;
        result = fcntl(GUEST_QUOTA_CLOEXEC_FD, F_GETFD);
        if ((exec_completed && (result >= 0 || errno != EBADF)) ||
            (!exec_completed && (result < 0 || (result & FD_CLOEXEC) == 0)))
                return -EPROTO;
        return 0;
}

static int cleanup_guest_quota_state(const GuestQuotaState *state) {
        int result = 0;

        if (state->positive) {
                errno = 0;
                if (guest_quotactl_fd(
                                    GUEST_QUOTA_DIRECTORY_FD,
                                    QCMD(Q_QUOTAOFF, USRQUOTA),
                                    0,
                                    NULL) < 0 &&
                                        errno != ESRCH && errno != EBADF && errno != EEXIST)
                        result = -errno;
        }
        for (int fd = GUEST_QUOTA_DIRECTORY_FD; fd <= GUEST_QUOTA_CLOEXEC_FD; fd++)
                if (close(fd) < 0 && errno != EBADF && result >= 0)
                        result = -errno;
        if (state->path[0] != 0) {
                if (umount2(state->path, MNT_DETACH) < 0 && errno != EINVAL && errno != ENOENT && result >= 0)
                        result = -errno;
                if (rmdir(state->path) < 0 && errno != ENOENT && result >= 0)
                        result = -errno;
        }
        return result;
}

static int validate_guest_quota_exec(void) {
        GuestQuotaState state = {};
        struct if_dqblk quota;
        uint32_t format;
        const char *failure = "read state";
        int result = EXIT_FAILURE;

        if (pread(GUEST_QUOTA_STATE_FD, &state, sizeof(state), 0) != (ssize_t) sizeof(state) ||
            state.magic != guest_quota_magic)
                goto finish;
        failure = "retained descriptors";
        if (check_guest_quota_fds(true, &state) < 0)
                goto finish;
        if (state.positive) {
                failure = "positive quota state";
                if (guest_quotactl_fd(
                                    GUEST_QUOTA_DIRECTORY_FD,
                                    QCMD(Q_GETFMT, USRQUOTA),
                                    0,
                                    &format) < 0 ||
                    format != state.format ||
                    guest_quotactl_fd(
                                    GUEST_QUOTA_DIRECTORY_FD,
                                    QCMD(Q_GETQUOTA, USRQUOTA),
                                    geteuid(),
                                    &quota) < 0 ||
                    !guest_quota_limits_equal(&quota, &state.quota) ||
                    guest_quotactl_fd(
                                    GUEST_QUOTA_DIRECTORY_FD,
                                    QCMD(Q_QUOTAOFF, USRQUOTA),
                                    0,
                                    NULL) < 0)
                        goto finish;
                errno = 0;
                if (guest_quotactl_fd(
                                    GUEST_QUOTA_DIRECTORY_FD,
                                    QCMD(Q_QUOTAOFF, USRQUOTA),
                                    0,
                                    NULL) >= 0 ||
                    errno != EEXIST)
                        goto finish;
                if (guest_quotactl_fd(
                                    GUEST_QUOTA_DIRECTORY_FD,
                                    QCMD(Q_GETFMT, USRQUOTA),
                                    0,
                                    &format) < 0 ||
                    format != QFMT_SHMEM ||
                    guest_quotactl_fd(
                                    GUEST_QUOTA_DIRECTORY_FD,
                                    QCMD(Q_GETQUOTA, USRQUOTA),
                                    geteuid(),
                                    &quota) < 0 ||
                    !guest_quota_limits_equal(&quota, &state.quota) ||
                    guest_quotactl_fd(
                                    GUEST_QUOTA_DIRECTORY_FD,
                                    QCMD(Q_QUOTAON, USRQUOTA),
                                    QFMT_SHMEM,
                                    NULL) < 0)
                        goto finish;
                errno = 0;
                if (guest_quotactl_fd(
                                    GUEST_QUOTA_DIRECTORY_FD,
                                    QCMD(Q_QUOTAON, USRQUOTA),
                                    QFMT_SHMEM,
                                    NULL) >= 0 ||
                    errno != EEXIST)
                        goto finish;
                if (guest_quotactl_fd(
                                    GUEST_QUOTA_DIRECTORY_FD,
                                    QCMD(Q_GETFMT, USRQUOTA),
                                    0,
                                    &format) < 0 ||
                    format != QFMT_SHMEM ||
                    guest_quotactl_fd(
                                    GUEST_QUOTA_DIRECTORY_FD,
                                    QCMD(Q_GETQUOTA, USRQUOTA),
                                    geteuid(),
                                    &quota) < 0 ||
                    !guest_quota_limits_equal(&quota, &state.quota) ||
                    guest_quotactl_fd(
                                    GUEST_QUOTA_DIRECTORY_FD,
                                    QCMD(Q_QUOTAOFF, USRQUOTA),
                                    0,
                                    NULL) < 0)
                        goto finish;
        } else {
                failure = "unsupported quota state";
                if (state.mount_errno != EINVAL && state.mount_errno != EPERM && state.mount_errno != EOPNOTSUPP)
                        goto finish;
                if (check_guest_quota_unsupported(GUEST_QUOTA_DIRECTORY_FD) < 0)
                        goto finish;
        }
        result = EXIT_SUCCESS;

finish:
        if (result != EXIT_SUCCESS)
                fprintf(stderr, "Guest quota target failed at %s\n", failure);
        if (cleanup_guest_quota_state(&state) < 0)
                result = EXIT_FAILURE;
        if (result == EXIT_SUCCESS) {
                if (state.positive)
                        printf("KVM_QUOTA_OK format=%u\n", state.format);
                else
                        printf(
                                        "KVM_QUOTA_UNSUPPORTED quota_mount_errno=%d quotactl_fd=ENOSYS\n",
                                        state.mount_errno);
        }
        return result;
}

static int run_guest_quota_exec(const char *self) {
        GuestQuotaState state = {
                .magic = guest_quota_magic,
                .path = "/tmp/kvm-quota-state-XXXXXX",
        };
        char payload[4096] = "quota-payload";
        struct stat directory_stat, file_stat;
        int cloexec_fd = -1, directory_fd = -1, file_fd = -1, state_fd = -1;
        int result = -EPROTO;

        if (check_guest_quota_scalar_errors() < 0 || !mkdtemp(state.path))
                goto finish;
        if (mount(
                            "tmpfs",
                            state.path,
                            "tmpfs",
                            MS_NODEV | MS_NOSUID,
                            "size=16M,nr_inodes=1024,quota") < 0) {
                state.mount_errno = errno;
                if (state.mount_errno != EINVAL && state.mount_errno != EPERM &&
                    state.mount_errno != EOPNOTSUPP)
                        goto finish;
                if (mount(
                                    "tmpfs",
                                    state.path,
                                    "tmpfs",
                                    MS_NODEV | MS_NOSUID,
                                    "size=16M,nr_inodes=1024") < 0)
                        goto finish;
        } else
                state.positive = true;

        directory_fd = open(state.path, O_RDONLY | O_DIRECTORY | O_CLOEXEC);
        if (directory_fd < 0)
                goto finish;
        file_fd = openat(directory_fd, "payload", O_CREAT | O_EXCL | O_RDWR | O_CLOEXEC, 0600);
        if (file_fd < 0 || pwrite(file_fd, payload, sizeof(payload), 0) != (ssize_t) sizeof(payload) ||
            move_guest_quota_fd(directory_fd, GUEST_QUOTA_DIRECTORY_FD, false) < 0 ||
            move_guest_quota_fd(file_fd, GUEST_QUOTA_FILE_FD, false) < 0 ||
            dup3(GUEST_QUOTA_DIRECTORY_FD, GUEST_QUOTA_CLOEXEC_FD, O_CLOEXEC) != GUEST_QUOTA_CLOEXEC_FD)
                goto finish;
        directory_fd = GUEST_QUOTA_DIRECTORY_FD;
        file_fd = GUEST_QUOTA_FILE_FD;
        cloexec_fd = GUEST_QUOTA_CLOEXEC_FD;

        if ((state.positive && initialize_guest_quota_positive(&state) < 0) ||
            (!state.positive && check_guest_quota_unsupported(directory_fd) < 0) ||
            check_guest_quota_fork(&state) < 0 || fstat(directory_fd, &directory_stat) < 0 ||
            fstat(file_fd, &file_stat) < 0)
                goto finish;
        state.directory_device = directory_stat.st_dev;
        state.directory_inode = directory_stat.st_ino;
        state.file_device = file_stat.st_dev;
        state.file_inode = file_stat.st_ino;

        state_fd = memfd_create("kvm-quota-state", MFD_CLOEXEC);
        if (state_fd < 0 || pwrite(state_fd, &state, sizeof(state), 0) != (ssize_t) sizeof(state) ||
            move_guest_quota_fd(state_fd, GUEST_QUOTA_STATE_FD, false) < 0 ||
            check_guest_quota_fds(false, &state) < 0)
                goto finish;
        state_fd = GUEST_QUOTA_STATE_FD;
        execl(self, self, "--guest-exec-target", "--expect-quota-state", NULL);

finish:
        if (state.positive && directory_fd >= 0)
                (void) guest_quotactl_fd(directory_fd, QCMD(Q_QUOTAOFF, USRQUOTA), 0, NULL);
        if (directory_fd >= 0)
                close(directory_fd);
        if (file_fd >= 0)
                close(file_fd);
        if (state_fd >= 0)
                close(state_fd);
        if (cloexec_fd >= 0)
                close(cloexec_fd);
        if (state.path[0] != 0) {
                (void) umount2(state.path, MNT_DETACH);
                (void) rmdir(state.path);
        }
        return result;
}

static int test_guest_quota_exec(const char *self) {
        int go_pipe[2] = { -1, -1 }, ready_pipe[2] = { -1, -1 }, status;
        uid_t uid = getuid();
        gid_t gid = getgid();
        pid_t child, waited;
        char byte;
        int result = EXIT_FAILURE;

        child = fork();
        if (child < 0)
                return EXIT_FAILURE;
        if (child == 0) {
                if (unshare(CLONE_NEWNS) < 0)
                        _exit(errno == EPERM ? 215 : 216);
                if (mount(NULL, "/", NULL, MS_REC | MS_PRIVATE, NULL) < 0)
                        _exit(217);
                _exit(run_guest_quota_exec(self) < 0 ? 218 : 0);
        }
        do
                waited = waitpid(child, &status, 0);
        while (waited < 0 && errno == EINTR);
        if (waited != child || !WIFEXITED(status))
                return EXIT_FAILURE;
        if (WEXITSTATUS(status) == 0)
                return EXIT_SUCCESS;
        if (WEXITSTATUS(status) != 215)
                return EXIT_FAILURE;

        if (pipe2(ready_pipe, O_CLOEXEC) < 0 || pipe2(go_pipe, O_CLOEXEC) < 0)
                goto finish;
        child = syscall(SYS_clone, CLONE_NEWUSER | CLONE_NEWNS | SIGCHLD, NULL, NULL, NULL, 0);
        if (child < 0)
                goto finish;
        if (child == 0) {
                close(ready_pipe[0]);
                close(go_pipe[1]);
                if (write(ready_pipe[1], "r", 1) != 1 || read(go_pipe[0], &byte, 1) != 1 || byte != 'g' ||
                    setresgid(0, 0, 0) < 0 || setresuid(0, 0, 0) < 0 ||
                    mount(NULL, "/", NULL, MS_REC | MS_PRIVATE, NULL) < 0)
                        _exit(219);
                close(ready_pipe[1]);
                close(go_pipe[0]);
                _exit(run_guest_quota_exec(self) < 0 ? 220 : 0);
        }

        close(ready_pipe[1]);
        ready_pipe[1] = -1;
        close(go_pipe[0]);
        go_pipe[0] = -1;
        if (read(ready_pipe[0], &byte, 1) != 1 || byte != 'r' ||
            map_guest_user_namespace(child, uid, gid) < 0 || write(go_pipe[1], "g", 1) != 1)
                goto fail_child;
        close(ready_pipe[0]);
        ready_pipe[0] = -1;
        close(go_pipe[1]);
        go_pipe[1] = -1;
        do
                waited = waitpid(child, &status, 0);
        while (waited < 0 && errno == EINTR);
        if (waited == child && WIFEXITED(status) && WEXITSTATUS(status) == 0)
                result = EXIT_SUCCESS;
        goto finish;

fail_child:
        close(go_pipe[1]);
        go_pipe[1] = -1;
        kill(child, SIGKILL);
        (void) waitpid(child, NULL, 0);
finish:
        for (size_t i = 0; i < 2; i++) {
                if (ready_pipe[i] >= 0)
                        close(ready_pipe[i]);
                if (go_pipe[i] >= 0)
                        close(go_pipe[i]);
        }
        return result;
}

typedef struct GuestAcctExpectation {
        uint32_t pid;
        uint32_t ppid;
        uint32_t exitcode;
        uint32_t btime_min;
        uint32_t btime_max;
        char comm[ACCT_COMM];
} GuestAcctExpectation;

typedef struct GuestProcessAccountingState {
        uint64_t magic;
        uint64_t primary_device;
        uint64_t primary_inode;
        uint64_t replacement_device;
        uint64_t replacement_inode;
        uint32_t uid;
        uint32_t gid;
        uint32_t record_version;
        int32_t positive;
        int32_t cap_sys_pacct;
        int32_t isolation_errno;
        GuestAcctExpectation first;
        GuestAcctExpectation second;
        char primary_path[PATH_MAX];
        char replacement_path[PATH_MAX];
} GuestProcessAccountingState;

static const uint64_t guest_process_accounting_magic = UINT64_C(0x4143435453543031);
static const uint32_t guest_process_accounting_version = 3;

static int probe_guest_process_accounting_capability(bool *ret_capable) {
        long result;

        errno = 0;
        result = syscall(SYS_acct, (void*) (uintptr_t) 1);
        if (result >= 0)
                return -EPROTO;
        if (errno == EPERM) {
                *ret_capable = false;
                return 0;
        }
        if (errno == EFAULT) {
                *ret_capable = true;
                return 0;
        }
        return -errno;
}

static int check_guest_process_accounting_errors(bool capable, const char *valid_path) {
        bool observed_capable;
        long result;
        int expected, r;

        r = probe_guest_process_accounting_capability(&observed_capable);
        if (r < 0 || observed_capable != capable)
                return -EPROTO;
        expected = capable ? ENOENT : EPERM;
        errno = 0;
        result = syscall(SYS_acct, "/definitely/missing/kvm-process-accounting");
        if (result >= 0 || errno != expected)
                return -EPROTO;
        if (!capable) {
                errno = 0;
                result = syscall(SYS_acct, valid_path);
                if (result >= 0 || errno != EPERM)
                        return -EPROTO;
                errno = 0;
                result = syscall(SYS_acct, NULL);
                if (result >= 0 || errno != EPERM)
                        return -EPROTO;
        }
        return 0;
}

static int move_guest_process_accounting_fd(int fd, int target, bool cloexec) {
        int flags;

        if (fd < 0)
                return -EBADF;
        if (fd != target) {
                int moved = cloexec ? dup3(fd, target, O_CLOEXEC) : dup2(fd, target);

                if (moved != target)
                        return -errno;
                if (close(fd) < 0) {
                        int error = -errno;

                        (void) close(target);
                        return error;
                }
                return target;
        }
        flags = fcntl(fd, F_GETFD);
        if (flags < 0 || fcntl(fd, F_SETFD, cloexec ? flags | FD_CLOEXEC : flags & ~FD_CLOEXEC) < 0)
                return -errno;
        return target;
}

static uint64_t decode_guest_acct_comp(comp_t value) {
        return (uint64_t) (value & UINT16_C(0x1fff)) << (3 * (value >> 13));
}

static void run_guest_accounted_child(const char *comm, int status) {
        struct timespec cpu_start, cpu_now, delay = {
                .tv_nsec = 20000000,
        };
        volatile uint64_t accumulator = UINT64_C(0x123456789abcdef);
        uint8_t *mapping;
        long page_size;
        bool advanced = false;

        if (prctl(PR_SET_NAME, comm) < 0 || clock_gettime(CLOCK_PROCESS_CPUTIME_ID, &cpu_start) < 0)
                _exit(221);
        page_size = sysconf(_SC_PAGESIZE);
        if (page_size <= 0 || (size_t) page_size > SIZE_MAX / 64)
                _exit(222);
        mapping = mmap(
                        NULL,
                        (size_t) page_size * 64,
                        PROT_READ | PROT_WRITE,
                        MAP_PRIVATE | MAP_ANONYMOUS,
                        -1,
                        0);
        if (mapping == MAP_FAILED)
                _exit(223);
        for (size_t offset = 0; offset < (size_t) page_size * 64; offset += (size_t) page_size)
                mapping[offset] = (uint8_t) (offset / (size_t) page_size);

        for (unsigned batch = 0; batch < 2048; batch++) {
                for (unsigned iteration = 0; iteration < 65536; iteration++)
                        accumulator = accumulator * UINT64_C(6364136223846793005) + UINT64_C(1442695040888963407);
                if (clock_gettime(CLOCK_PROCESS_CPUTIME_ID, &cpu_now) < 0)
                        _exit(224);
                if ((cpu_now.tv_sec - cpu_start.tv_sec) * INT64_C(1000000000) +
                            cpu_now.tv_nsec - cpu_start.tv_nsec >= INT64_C(20000000)) {
                        advanced = true;
                        break;
                }
        }
        (void) accumulator;
        if (!advanced)
                _exit(225);
        while (nanosleep(&delay, &delay) < 0)
                if (errno != EINTR)
                        _exit(226);
        _exit(status);
}

static int spawn_guest_accounted_child(
                const char *comm,
                int status,
                GuestAcctExpectation *ret_expectation) {

        time_t before, after;
        pid_t child, waited;
        int wait_status;

        before = time(NULL);
        if (before == (time_t) -1)
                return -EIO;
        child = fork();
        if (child < 0)
                return -errno;
        if (child == 0)
                run_guest_accounted_child(comm, status);
        do
                waited = waitpid(child, &wait_status, 0);
        while (waited < 0 && errno == EINTR);
        after = time(NULL);
        if (waited != child || after == (time_t) -1 || !WIFEXITED(wait_status) ||
            WEXITSTATUS(wait_status) != status || before > UINT32_MAX || after > UINT32_MAX ||
            strlen(comm) >= sizeof(ret_expectation->comm))
                return -EPROTO;

        *ret_expectation = (GuestAcctExpectation) {
                .pid = child,
                .ppid = getpid(),
                .exitcode = (uint32_t) status << 8,
                .btime_min = (uint32_t) before,
                .btime_max = (uint32_t) after,
        };
        memcpy(ret_expectation->comm, comm, strlen(comm) + 1);
        return 0;
}

static bool guest_acct_record_identity_matches(
                const struct acct_v3 *record,
                const GuestAcctExpectation *expectation) {

        return record->ac_pid == expectation->pid && record->ac_ppid == expectation->ppid &&
               strncmp(record->ac_comm, expectation->comm, sizeof(record->ac_comm)) == 0;
}

static int validate_guest_acct_record(
                const struct acct_v3 *record,
                const GuestAcctExpectation *expectation,
                const GuestProcessAccountingState *state) {

        uint64_t cpu, faults, memory;

        cpu = decode_guest_acct_comp(record->ac_utime) + decode_guest_acct_comp(record->ac_stime);
        faults = decode_guest_acct_comp(record->ac_minflt) + decode_guest_acct_comp(record->ac_majflt);
        memory = decode_guest_acct_comp(record->ac_mem);
        if ((uint8_t) record->ac_version != (guest_process_accounting_version | ACCT_BYTEORDER) ||
            record->ac_exitcode != expectation->exitcode || record->ac_uid != state->uid ||
            record->ac_gid != state->gid || record->ac_btime < expectation->btime_min ||
            record->ac_btime > expectation->btime_max ||
            !(record->ac_etime > 0.0f && record->ac_etime < 60.0f * AHZ) ||
            cpu == 0 || cpu > UINT64_C(6000) || faults == 0 || faults > UINT64_C(1000000) ||
            memory == 0 || memory > UINT64_C(1073741824) || record->ac_io != 0 || record->ac_rw != 0 ||
            record->ac_swaps != 0 || (record->ac_flag & AFORK) == 0 ||
            (record->ac_flag & (ACORE | AXSIG)) != 0)
                return -EPROTO;
        return 0;
}

static int find_guest_acct_record(
                int fd,
                const GuestAcctExpectation *expectation,
                const GuestProcessAccountingState *state) {

        struct acct_v3 records[32];
        struct stat stat_buffer;
        size_t count, matches = 0;

        if (fstat(fd, &stat_buffer) < 0 || stat_buffer.st_size <= 0 ||
            stat_buffer.st_size % (off_t) sizeof(struct acct_v3) != 0 ||
            stat_buffer.st_size > (off_t) sizeof(records))
                return -EPROTO;
        if (pread(fd, records, (size_t) stat_buffer.st_size, 0) != (ssize_t) stat_buffer.st_size)
                return -EIO;
        count = (size_t) stat_buffer.st_size / sizeof(struct acct_v3);
        for (size_t i = 0; i < count; i++)
                if (guest_acct_record_identity_matches(records + i, expectation)) {
                        if (validate_guest_acct_record(records + i, expectation, state) < 0)
                                return -EPROTO;
                        matches++;
                }
        return matches == 1 ? 0 : -EPROTO;
}

static int check_guest_process_accounting_fds(
                bool exec_completed,
                const GuestProcessAccountingState *state) {

        struct stat primary, primary_path, replacement, replacement_path, state_stat;
        int flags, result;

        for (int fd = GUEST_ACCT_PRIMARY_FD; fd <= GUEST_ACCT_STATE_FD; fd++) {
                flags = fcntl(fd, F_GETFD);
                if (flags < 0 || (flags & FD_CLOEXEC) != 0)
                        return -EPROTO;
        }
        if (fstat(GUEST_ACCT_PRIMARY_FD, &primary) < 0 ||
            fstat(GUEST_ACCT_REPLACEMENT_FD, &replacement) < 0 ||
            fstat(GUEST_ACCT_STATE_FD, &state_stat) < 0 || stat(state->primary_path, &primary_path) < 0 ||
            stat(state->replacement_path, &replacement_path) < 0 || !S_ISREG(primary.st_mode) ||
            !S_ISREG(replacement.st_mode) || !S_ISREG(state_stat.st_mode) ||
            primary.st_dev != primary_path.st_dev || primary.st_ino != primary_path.st_ino ||
            replacement.st_dev != replacement_path.st_dev || replacement.st_ino != replacement_path.st_ino ||
            (uint64_t) primary.st_dev != state->primary_device ||
            (uint64_t) primary.st_ino != state->primary_inode ||
            (uint64_t) replacement.st_dev != state->replacement_device ||
            (uint64_t) replacement.st_ino != state->replacement_inode ||
            (!state->positive && (primary.st_size != 0 || replacement.st_size != 0)))
                return -EPROTO;

        errno = 0;
        result = fcntl(GUEST_ACCT_CLOEXEC_FD, F_GETFD);
        if ((exec_completed && (result >= 0 || errno != EBADF)) ||
            (!exec_completed && (result < 0 || (result & FD_CLOEXEC) == 0)))
                return -EPROTO;
        return 0;
}

static int cleanup_guest_process_accounting_state(const GuestProcessAccountingState *state) {
        int result = 0;

        for (int fd = GUEST_ACCT_PRIMARY_FD; fd <= GUEST_ACCT_CLOEXEC_FD; fd++)
                if (close(fd) < 0 && errno != EBADF && result >= 0)
                        result = -errno;
        if (state->primary_path[0] != 0 && unlink(state->primary_path) < 0 && errno != ENOENT && result >= 0)
                result = -errno;
        if (state->replacement_path[0] != 0 &&
            unlink(state->replacement_path) < 0 && errno != ENOENT && result >= 0)
                result = -errno;
        return result;
}

static int validate_guest_process_accounting_exec(void) {
        GuestProcessAccountingState state = {};
        GuestAcctExpectation target, unrecorded;
        struct stat before, after;
        const char *failure = "read state";
        bool accounting_active = false;
        int result = EXIT_FAILURE;

        if (pread(GUEST_ACCT_STATE_FD, &state, sizeof(state), 0) != (ssize_t) sizeof(state) ||
            state.magic != guest_process_accounting_magic || state.record_version != guest_process_accounting_version)
                goto finish;
        accounting_active = state.positive;
        failure = "retained descriptors";
        if (check_guest_process_accounting_fds(true, &state) < 0)
                goto finish;
        if (state.positive) {
                failure = "target record";
                if (spawn_guest_accounted_child("acct-target", 33, &target) < 0 || syscall(SYS_acct, NULL) < 0)
                        goto finish;
                accounting_active = false;
                if (fsync(GUEST_ACCT_PRIMARY_FD) < 0 || fsync(GUEST_ACCT_REPLACEMENT_FD) < 0 ||
                    find_guest_acct_record(GUEST_ACCT_PRIMARY_FD, &state.first, &state) < 0 ||
                    find_guest_acct_record(GUEST_ACCT_REPLACEMENT_FD, &state.second, &state) < 0 ||
                    find_guest_acct_record(GUEST_ACCT_REPLACEMENT_FD, &target, &state) < 0)
                        goto finish;

                failure = "disabled accounting";
                if (fstat(GUEST_ACCT_REPLACEMENT_FD, &before) < 0 ||
                    spawn_guest_accounted_child("acct-disabled", 34, &unrecorded) < 0 ||
                    fstat(GUEST_ACCT_REPLACEMENT_FD, &after) < 0 || before.st_size != after.st_size ||
                    syscall(SYS_acct, NULL) < 0)
                        goto finish;
        } else {
                failure = "permission boundary";
                if (check_guest_process_accounting_errors(state.cap_sys_pacct, state.primary_path) < 0)
                        goto finish;
        }
        result = EXIT_SUCCESS;

finish:
        if (accounting_active)
                (void) syscall(SYS_acct, NULL);
        if (result != EXIT_SUCCESS)
                fprintf(stderr, "Guest process-accounting target failed at %s\n", failure);
        if (cleanup_guest_process_accounting_state(&state) < 0)
                result = EXIT_FAILURE;
        if (result == EXIT_SUCCESS) {
                if (state.positive)
                        printf("KVM_PROCESS_ACCOUNTING_OK version=%u records=3\n", state.record_version);
                else
                        printf(
                                        "KVM_PROCESS_ACCOUNTING_UNSUPPORTED cap_sys_pacct=%d"
                                        " isolation_errno=%d record_version=%u\n",
                                        state.cap_sys_pacct,
                                        state.isolation_errno,
                                        state.record_version);
        }
        return result;
}

static int run_guest_process_accounting_exec(
                const char *self,
                bool positive_requested,
                int isolation_errno) {

        GuestProcessAccountingState state = {
                .magic = guest_process_accounting_magic,
                .record_version = guest_process_accounting_version,
                .isolation_errno = isolation_errno,
                .primary_path = "/tmp/kvm-process-accounting-primary-XXXXXX",
                .replacement_path = "/tmp/kvm-process-accounting-replacement-XXXXXX",
        };
        struct stat primary_stat, replacement_stat;
        bool accounting_active = false, capable;
        int cloexec_fd = -1, primary_fd = -1, replacement_fd = -1, state_fd = -1;
        int result = -EPROTO;

        primary_fd = mkstemp(state.primary_path);
        replacement_fd = mkstemp(state.replacement_path);
        if (primary_fd < 0 || replacement_fd < 0 ||
            probe_guest_process_accounting_capability(&capable) < 0)
                goto finish;
        state.cap_sys_pacct = capable;
        state.positive = positive_requested && capable;
        state.uid = getuid();
        state.gid = getgid();
        if (check_guest_process_accounting_errors(capable, state.primary_path) < 0)
                goto finish;
        if (state.positive) {
                if (getpid() != 1 || syscall(SYS_acct, state.primary_path) < 0)
                        goto finish;
                accounting_active = true;
                if (spawn_guest_accounted_child("acct-first", 31, &state.first) < 0 ||
                    syscall(SYS_acct, state.replacement_path) < 0 ||
                    spawn_guest_accounted_child("acct-second", 32, &state.second) < 0)
                        goto finish;
        }

        if (fstat(primary_fd, &primary_stat) < 0 || fstat(replacement_fd, &replacement_stat) < 0)
                goto finish;
        if (move_guest_process_accounting_fd(primary_fd, GUEST_ACCT_PRIMARY_FD, false) < 0)
                goto finish;
        primary_fd = GUEST_ACCT_PRIMARY_FD;
        if (move_guest_process_accounting_fd(replacement_fd, GUEST_ACCT_REPLACEMENT_FD, false) < 0)
                goto finish;
        replacement_fd = GUEST_ACCT_REPLACEMENT_FD;
        if (dup3(GUEST_ACCT_REPLACEMENT_FD, GUEST_ACCT_CLOEXEC_FD, O_CLOEXEC) != GUEST_ACCT_CLOEXEC_FD)
                goto finish;
        cloexec_fd = GUEST_ACCT_CLOEXEC_FD;
        state.primary_device = primary_stat.st_dev;
        state.primary_inode = primary_stat.st_ino;
        state.replacement_device = replacement_stat.st_dev;
        state.replacement_inode = replacement_stat.st_ino;

        state_fd = memfd_create("kvm-process-accounting-state", MFD_CLOEXEC);
        if (state_fd < 0 || pwrite(state_fd, &state, sizeof(state), 0) != (ssize_t) sizeof(state) ||
            move_guest_process_accounting_fd(state_fd, GUEST_ACCT_STATE_FD, false) < 0)
                goto finish;
        state_fd = GUEST_ACCT_STATE_FD;
        if (check_guest_process_accounting_fds(false, &state) < 0)
                goto finish;
        execl(self, self, "--guest-exec-target", "--expect-process-accounting", NULL);

finish:
        if (accounting_active)
                (void) syscall(SYS_acct, NULL);
        if (primary_fd >= 0)
                close(primary_fd);
        if (replacement_fd >= 0)
                close(replacement_fd);
        if (state_fd >= 0)
                close(state_fd);
        if (cloexec_fd >= 0)
                close(cloexec_fd);
        if (state.primary_path[0] != 0)
                (void) unlink(state.primary_path);
        if (state.replacement_path[0] != 0)
                (void) unlink(state.replacement_path);
        return result;
}

static int wait_guest_process_accounting_child(pid_t child) {
        int status;
        pid_t waited;

        do
                waited = waitpid(child, &status, 0);
        while (waited < 0 && errno == EINTR);
        return waited == child && WIFEXITED(status) && WEXITSTATUS(status) == 0 ? EXIT_SUCCESS : EXIT_FAILURE;
}

static int test_guest_process_accounting_exec(const char *self) {
        bool capable;
        pid_t child;
        int isolation_errno;

        if (probe_guest_process_accounting_capability(&capable) < 0)
                return EXIT_FAILURE;
        child = syscall(SYS_clone, CLONE_NEWPID | SIGCHLD, NULL, NULL, NULL, 0);
        if (child == 0)
                _exit(run_guest_process_accounting_exec(self, capable, 0) < 0 ? 227 : 0);
        if (child > 0)
                return wait_guest_process_accounting_child(child);
        isolation_errno = errno;
        if (isolation_errno != EPERM && isolation_errno != EINVAL && isolation_errno != ENOSPC)
                return EXIT_FAILURE;

        child = fork();
        if (child < 0)
                return EXIT_FAILURE;
        if (child == 0)
                _exit(run_guest_process_accounting_exec(self, false, isolation_errno) < 0 ? 228 : 0);
        return wait_guest_process_accounting_child(child);
}

typedef enum GuestMaskedWaitKind {
        GUEST_WAIT_PSELECT,
        GUEST_WAIT_PPOLL,
        GUEST_WAIT_EPOLL_PWAIT,
        GUEST_WAIT_EPOLL_PWAIT2,
        _GUEST_WAIT_MAX,
} GuestMaskedWaitKind;

typedef struct GuestPselectSigset {
        const uint64_t *mask;
        size_t size;
} GuestPselectSigset;

typedef struct GuestMaskedWaitState {
        uint64_t magic;
        uint64_t event_device;
        uint64_t event_inode;
        uint64_t epoll_device;
        uint64_t epoll_inode;
        uint64_t queued_value;
} GuestMaskedWaitState;

static const uint64_t guest_masked_wait_magic = UINT64_C(0x4d41534b57414954);
static const uint64_t guest_masked_wait_event_data = UINT64_C(0xfeedface04204242);
static volatile sig_atomic_t guest_masked_wait_signal_seen;
static volatile sig_atomic_t guest_masked_wait_handler_mask_ok;
static volatile sig_atomic_t guest_masked_wait_frame_mask_ok;

static void guest_masked_wait_signal_handler(int signo, siginfo_t *info, void *context) {
        ucontext_t *ucontext = context;
        sigset_t current;

        if (signo != SIGUSR1 || !info || !ucontext)
                return;
        guest_masked_wait_signal_seen++;
        if (sigprocmask(SIG_SETMASK, NULL, &current) >= 0 &&
            sigismember(&current, SIGUSR1) == 1 && sigismember(&current, SIGUSR2) == 1)
                guest_masked_wait_handler_mask_ok = 1;
        if (sigismember(&ucontext->uc_sigmask, SIGUSR1) == 1 &&
            sigismember(&ucontext->uc_sigmask, SIGUSR2) == 0)
                guest_masked_wait_frame_mask_ok = 1;
}

static bool guest_timespec_equal(const struct timespec *first, const struct timespec *second) {
        return first->tv_sec == second->tv_sec && first->tv_nsec == second->tv_nsec;
}

static bool guest_wait_timeout_matches(GuestMaskedWaitKind kind, const struct timespec *timeout) {
        const struct timespec initial = {
                .tv_sec = 1,
        };

        if (kind == GUEST_WAIT_PSELECT || kind == GUEST_WAIT_PPOLL)
                return timeout->tv_sec >= 0 && timeout->tv_nsec >= 0 && timeout->tv_nsec < 1000000000 &&
                       !guest_timespec_equal(timeout, &initial) &&
                       (timeout->tv_sec < initial.tv_sec ||
                        (timeout->tv_sec == initial.tv_sec && timeout->tv_nsec < initial.tv_nsec));
        return guest_timespec_equal(timeout, &initial);
}

static int guest_kernel_signal_mask(const sigset_t *mask, uint64_t *ret_mask) {
        uint64_t kernel_mask = 0;

        for (int signo = 1; signo <= 64; signo++) {
                int member = sigismember(mask, signo);

                if (member < 0)
                        return -errno;
                if (member > 0)
                        kernel_mask |= UINT64_C(1) << (signo - 1);
        }
        *ret_mask = kernel_mask;
        return 0;
}

static long guest_masked_wait(
                GuestMaskedWaitKind kind,
                int event_fd,
                int epoll_fd,
                struct timespec *timeout,
                int legacy_timeout_ms,
                const uint64_t *mask,
                size_t mask_size,
                bool *ret_ready) {

        struct epoll_event event = {};
        long result;

        *ret_ready = false;
        switch (kind) {
        case GUEST_WAIT_PSELECT: {
                GuestPselectSigset sigset = {
                        .mask = mask,
                        .size = mask_size,
                };
                fd_set read_fds;

                if (event_fd >= FD_SETSIZE) {
                        errno = EOVERFLOW;
                        return -1;
                }
                FD_ZERO(&read_fds);
                FD_SET(event_fd, &read_fds);
                result = syscall(
                                SYS_pselect6,
                                event_fd + 1,
                                &read_fds,
                                NULL,
                                NULL,
                                timeout,
                                mask ? &sigset : NULL);
                if (result > 0) {
                        if (result != 1 || !FD_ISSET(event_fd, &read_fds)) {
                                errno = EPROTO;
                                return -1;
                        }
                        *ret_ready = true;
                }
                return result;
        }
        case GUEST_WAIT_PPOLL: {
                struct pollfd poll_fd = {
                        .fd = event_fd,
                        .events = POLLIN,
                };

                result = syscall(SYS_ppoll, &poll_fd, 1, timeout, mask, mask_size);
                if (result > 0) {
                        if (result != 1 || poll_fd.revents != POLLIN) {
                                errno = EPROTO;
                                return -1;
                        }
                        *ret_ready = true;
                }
                return result;
        }
        case GUEST_WAIT_EPOLL_PWAIT:
                result = syscall(
                                SYS_epoll_pwait,
                                epoll_fd,
                                &event,
                                1,
                                legacy_timeout_ms,
                                mask,
                                mask_size);
                break;
        case GUEST_WAIT_EPOLL_PWAIT2:
                result = syscall(SYS_epoll_pwait2, epoll_fd, &event, 1, timeout, mask, mask_size);
                break;
        default:
                errno = EINVAL;
                return -1;
        }

        if (result > 0) {
                if (result != 1 || (event.events & EPOLLIN) == 0 ||
                    event.data.u64 != guest_masked_wait_event_data) {
                        errno = EPROTO;
                        return -1;
                }
                *ret_ready = true;
        }
        return result;
}

static int drain_guest_wait_event(uint64_t expected) {
        uint64_t value;
        ssize_t n;

        do
                n = read(GUEST_WAIT_EVENT_FD, &value, sizeof(value));
        while (n < 0 && errno == EINTR);
        return n == sizeof(value) && value == expected ? 0 : -EPROTO;
}

static int check_guest_masked_wait_errors(void) {
        GuestPselectSigset bad_pselect_size;
        struct epoll_event event;
        struct timespec zero = {}, negative = {
                .tv_sec = -1,
        }, invalid_nsec = {
                .tv_nsec = 1000000000,
        };
        uint64_t mask = 0;
        long result;

        bad_pselect_size = (GuestPselectSigset) {
                .mask = &mask,
                .size = sizeof(mask) - 1,
        };
        errno = 0;
        result = syscall(SYS_pselect6, 0, NULL, NULL, NULL, &zero, (void*) (uintptr_t) 1);
        if (result >= 0 || errno != EFAULT)
                return -EPROTO;
        errno = 0;
        result = syscall(SYS_pselect6, 0, NULL, NULL, NULL, &zero, &bad_pselect_size);
        if (result >= 0 || errno != EINVAL)
                return -EPROTO;
        errno = 0;
        result = syscall(SYS_pselect6, 0, NULL, NULL, NULL, (void*) (uintptr_t) 1, NULL);
        if (result >= 0 || errno != EFAULT)
                return -EPROTO;
        errno = 0;
        result = syscall(SYS_pselect6, 0, NULL, NULL, NULL, &negative, NULL);
        if (result >= 0 || errno != EINVAL)
                return -EPROTO;
        errno = 0;
        result = syscall(SYS_pselect6, 0, NULL, NULL, NULL, &invalid_nsec, NULL);
        if (result >= 0 || errno != EINVAL)
                return -EPROTO;

        errno = 0;
        result = syscall(SYS_ppoll, NULL, 0, &zero, &mask, sizeof(mask) - 1);
        if (result >= 0 || errno != EINVAL)
                return -EPROTO;
        errno = 0;
        result = syscall(SYS_ppoll, NULL, 0, (void*) (uintptr_t) 1, NULL, 0);
        if (result >= 0 || errno != EFAULT)
                return -EPROTO;
        errno = 0;
        result = syscall(SYS_ppoll, NULL, 0, &negative, NULL, 0);
        if (result >= 0 || errno != EINVAL)
                return -EPROTO;
        errno = 0;
        result = syscall(SYS_ppoll, NULL, 0, &invalid_nsec, NULL, 0);
        if (result >= 0 || errno != EINVAL)
                return -EPROTO;

        errno = 0;
        result = syscall(
                        SYS_epoll_pwait,
                        GUEST_WAIT_EPOLL_FD,
                        &event,
                        1,
                        0,
                        &mask,
                        sizeof(mask) - 1);
        if (result >= 0 || errno != EINVAL)
                return -EPROTO;
        errno = 0;
        result = syscall(SYS_epoll_pwait, GUEST_WAIT_EPOLL_FD, &event, 0, 0, NULL, 0);
        if (result >= 0 || errno != EINVAL)
                return -EPROTO;

        errno = 0;
        result = syscall(
                        SYS_epoll_pwait2,
                        GUEST_WAIT_EPOLL_FD,
                        &event,
                        1,
                        &zero,
                        &mask,
                        sizeof(mask) - 1);
        if (result >= 0 || errno != EINVAL)
                return -EPROTO;
        errno = 0;
        result = syscall(
                        SYS_epoll_pwait2,
                        GUEST_WAIT_EPOLL_FD,
                        &event,
                        1,
                        (void*) (uintptr_t) 1,
                        NULL,
                        0);
        if (result >= 0 || errno != EFAULT)
                return -EPROTO;
        errno = 0;
        result = syscall(SYS_epoll_pwait2, GUEST_WAIT_EPOLL_FD, &event, 1, &negative, NULL, 0);
        if (result >= 0 || errno != EINVAL)
                return -EPROTO;
        errno = 0;
        result = syscall(SYS_epoll_pwait2, GUEST_WAIT_EPOLL_FD, &event, 1, &invalid_nsec, NULL, 0);
        if (result >= 0 || errno != EINVAL)
                return -EPROTO;
        return 0;
}

static int check_guest_masked_wait_zero(void) {
        const struct timespec zero = {};
        uint64_t mask = 0;

        for (GuestMaskedWaitKind kind = 0; kind < _GUEST_WAIT_MAX; kind++) {
                struct timespec timeout = zero;
                bool ready;
                long result;

                result = guest_masked_wait(
                                kind,
                                GUEST_WAIT_EVENT_FD,
                                GUEST_WAIT_EPOLL_FD,
                                &timeout,
                                0,
                                &mask,
                                sizeof(mask),
                                &ready);
                if (result != 0 || ready || !guest_timespec_equal(&timeout, &zero))
                        return -EPROTO;
        }
        return 0;
}

static int run_guest_masked_wait_producer(GuestMaskedWaitKind kind) {
        const struct timespec delay = {
                .tv_nsec = 20000000,
        };
        struct timespec timeout = {
                .tv_sec = 1,
        };
        uint64_t mask = 0, value = 1;
        bool ready;
        int status;
        pid_t child, waited;
        long result;

        child = fork();
        if (child < 0)
                return -errno;
        if (child == 0) {
                (void) nanosleep(&delay, NULL);
                _exit(write(GUEST_WAIT_EVENT_FD, &value, sizeof(value)) == sizeof(value) ? 0 : 229);
        }
        result = guest_masked_wait(
                        kind,
                        GUEST_WAIT_EVENT_FD,
                        GUEST_WAIT_EPOLL_FD,
                        &timeout,
                        1000,
                        &mask,
                        sizeof(mask),
                        &ready);
        do
                waited = waitpid(child, &status, 0);
        while (waited < 0 && errno == EINTR);
        if (result != 1 || !ready || waited != child || !WIFEXITED(status) || WEXITSTATUS(status) != 0 ||
            !guest_wait_timeout_matches(kind, &timeout) || drain_guest_wait_event(1) < 0)
                return -EPROTO;
        return 0;
}

static void drain_guest_masked_wait_signal(void) {
        const struct timespec zero = {};
        sigset_t signal_set;

        if (sigemptyset(&signal_set) < 0 || sigaddset(&signal_set, SIGUSR1) < 0)
                return;
        while (sigtimedwait(&signal_set, NULL, &zero) == SIGUSR1)
                ;
}

static int run_guest_masked_wait_signal_round(
                GuestMaskedWaitKind kind,
                bool restart,
                bool simultaneous) {

        struct sigaction action = {
                .sa_sigaction = guest_masked_wait_signal_handler,
                .sa_flags = SA_SIGINFO | (restart ? SA_RESTART : 0),
        }, old_action;
        struct timespec timeout = {
                .tv_sec = 1,
        };
        sigset_t original, saved, pending, current, temporary;
        uint64_t kernel_mask, value = 1;
        bool action_set = false, mask_set = false, ready;
        long result;
        int saved_errno, test_result = -EPROTO;

        if (sigemptyset(&action.sa_mask) < 0 || sigaction(SIGUSR1, NULL, &old_action) < 0 ||
            sigprocmask(SIG_SETMASK, NULL, &saved) < 0)
                return -errno;
        original = saved;
        if (sigaddset(&original, SIGUSR1) < 0 || sigdelset(&original, SIGUSR2) < 0 ||
            sigprocmask(SIG_SETMASK, &original, NULL) < 0)
                goto finish;
        mask_set = true;
        if (sigaction(SIGUSR1, &action, NULL) < 0)
                goto finish;
        action_set = true;
        temporary = original;
        if (sigdelset(&temporary, SIGUSR1) < 0 || sigaddset(&temporary, SIGUSR2) < 0 ||
            guest_kernel_signal_mask(&temporary, &kernel_mask) < 0)
                goto finish;

        guest_masked_wait_signal_seen = 0;
        guest_masked_wait_handler_mask_ok = 0;
        guest_masked_wait_frame_mask_ok = 0;
        if ((simultaneous && write(GUEST_WAIT_EVENT_FD, &value, sizeof(value)) != sizeof(value)) ||
            kill(getpid(), SIGUSR1) < 0)
                goto finish;
        result = guest_masked_wait(
                        kind,
                        GUEST_WAIT_EVENT_FD,
                        GUEST_WAIT_EPOLL_FD,
                        &timeout,
                        1000,
                        &kernel_mask,
                        sizeof(kernel_mask),
                        &ready);
        saved_errno = errno;
        if (simultaneous) {
                if (result != 1 || !ready || guest_masked_wait_signal_seen != 0 ||
                    sigpending(&pending) < 0 || sigismember(&pending, SIGUSR1) != 1 ||
                    drain_guest_wait_event(1) < 0)
                        goto finish;
                timeout = (struct timespec) {
                        .tv_sec = 1,
                };
                result = guest_masked_wait(
                                kind,
                                GUEST_WAIT_EVENT_FD,
                                GUEST_WAIT_EPOLL_FD,
                                &timeout,
                                1000,
                                &kernel_mask,
                                sizeof(kernel_mask),
                                &ready);
                saved_errno = errno;
        }
        if (result >= 0 || saved_errno != EINTR || ready || !guest_wait_timeout_matches(kind, &timeout) ||
            guest_masked_wait_signal_seen != 1 || guest_masked_wait_handler_mask_ok != 1 ||
            guest_masked_wait_frame_mask_ok != 1 ||
            sigprocmask(SIG_SETMASK, NULL, &current) < 0 || sigismember(&current, SIGUSR1) != 1 ||
            sigismember(&current, SIGUSR2) != 0 || sigpending(&pending) < 0 ||
            sigismember(&pending, SIGUSR1) != 0)
                goto finish;
        test_result = 0;

finish:
        drain_guest_masked_wait_signal();
        if (action_set && sigaction(SIGUSR1, &old_action, NULL) < 0)
                test_result = -errno;
        if (mask_set && sigprocmask(SIG_SETMASK, &saved, NULL) < 0)
                test_result = -errno;
        return test_result;
}

static int move_guest_masked_wait_fd(int fd, int target, bool cloexec) {
        int flags;

        if (fd < 0)
                return -EBADF;
        if (fd != target) {
                int moved = cloexec ? dup3(fd, target, O_CLOEXEC) : dup2(fd, target);

                if (moved != target)
                        return -errno;
                if (close(fd) < 0) {
                        int error = -errno;

                        (void) close(target);
                        return error;
                }
                return target;
        }
        flags = fcntl(fd, F_GETFD);
        if (flags < 0 || fcntl(fd, F_SETFD, cloexec ? flags | FD_CLOEXEC : flags & ~FD_CLOEXEC) < 0)
                return -errno;
        return target;
}

static int check_guest_masked_wait_fds(bool exec_completed, const GuestMaskedWaitState *state) {
        struct stat event_stat, epoll_stat, state_stat;
        int flags, result;

        for (int fd = GUEST_WAIT_EVENT_FD; fd <= GUEST_WAIT_STATE_FD; fd++) {
                flags = fcntl(fd, F_GETFD);
                if (flags < 0 || (flags & FD_CLOEXEC) != 0)
                        return -EPROTO;
        }
        if (fstat(GUEST_WAIT_EVENT_FD, &event_stat) < 0 || fstat(GUEST_WAIT_EPOLL_FD, &epoll_stat) < 0 ||
            fstat(GUEST_WAIT_STATE_FD, &state_stat) < 0 || !S_ISREG(state_stat.st_mode) ||
            (uint64_t) event_stat.st_dev != state->event_device ||
            (uint64_t) event_stat.st_ino != state->event_inode ||
            (uint64_t) epoll_stat.st_dev != state->epoll_device ||
            (uint64_t) epoll_stat.st_ino != state->epoll_inode)
                return -EPROTO;

        errno = 0;
        result = fcntl(GUEST_WAIT_CLOEXEC_FD, F_GETFD);
        if ((exec_completed && (result >= 0 || errno != EBADF)) ||
            (!exec_completed && (result < 0 || (result & FD_CLOEXEC) == 0)))
                return -EPROTO;
        return 0;
}

static int cleanup_guest_masked_wait_state(void) {
        int result = 0;

        for (int fd = GUEST_WAIT_EVENT_FD; fd <= GUEST_WAIT_CLOEXEC_FD; fd++)
                if (close(fd) < 0 && errno != EBADF && result >= 0)
                        result = -errno;
        return result;
}

static int validate_guest_masked_wait_exec(void) {
        GuestMaskedWaitState state = {};
        const struct timespec zero = {};
        uint64_t mask = 0;
        const char *failure = "read state";
        int result = EXIT_FAILURE;

        if (pread(GUEST_WAIT_STATE_FD, &state, sizeof(state), 0) != (ssize_t) sizeof(state) ||
            state.magic != guest_masked_wait_magic)
                goto finish;
        failure = "retained descriptors";
        if (check_guest_masked_wait_fds(true, &state) < 0)
                goto finish;
        failure = "retained readiness";
        for (GuestMaskedWaitKind kind = 0; kind < _GUEST_WAIT_MAX; kind++) {
                struct timespec timeout = zero;
                bool ready;

                if (guest_masked_wait(
                                    kind,
                                    GUEST_WAIT_EVENT_FD,
                                    GUEST_WAIT_EPOLL_FD,
                                    &timeout,
                                    0,
                                    &mask,
                                    sizeof(mask),
                                    &ready) != 1 ||
                    !ready || !guest_timespec_equal(&timeout, &zero))
                        goto finish;
        }
        if (drain_guest_wait_event(state.queued_value) < 0)
                goto finish;
        failure = "post-exec signal mask";
        if (run_guest_masked_wait_signal_round(GUEST_WAIT_EPOLL_PWAIT2, true, false) < 0)
                goto finish;
        result = EXIT_SUCCESS;

finish:
        if (result != EXIT_SUCCESS)
                fprintf(stderr, "Guest masked-wait target failed at %s\n", failure);
        if (cleanup_guest_masked_wait_state() < 0)
                result = EXIT_FAILURE;
        if (result == EXIT_SUCCESS)
                printf("KVM_MASKED_WAITS_OK syscalls=4 restart=eintr retained_epoll=1\n");
        return result;
}

static int run_guest_masked_wait_exec(const char *self) {
        GuestMaskedWaitState state = {
                .magic = guest_masked_wait_magic,
                .queued_value = 7,
        };
        struct epoll_event event = {
                .events = EPOLLIN,
                .data.u64 = guest_masked_wait_event_data,
        };
        struct stat event_stat, epoll_stat;
        int cloexec_fd = -1, epoll_fd = -1, event_fd = -1, state_fd = -1;
        int result = -EPROTO;

        event_fd = eventfd(0, EFD_CLOEXEC | EFD_NONBLOCK);
        epoll_fd = epoll_create1(EPOLL_CLOEXEC);
        if (event_fd < 0 || epoll_fd < 0 || epoll_ctl(epoll_fd, EPOLL_CTL_ADD, event_fd, &event) < 0 ||
            move_guest_masked_wait_fd(event_fd, GUEST_WAIT_EVENT_FD, false) < 0)
                goto finish;
        event_fd = GUEST_WAIT_EVENT_FD;
        if (move_guest_masked_wait_fd(epoll_fd, GUEST_WAIT_EPOLL_FD, false) < 0)
                goto finish;
        epoll_fd = GUEST_WAIT_EPOLL_FD;
        if (dup3(GUEST_WAIT_EPOLL_FD, GUEST_WAIT_CLOEXEC_FD, O_CLOEXEC) != GUEST_WAIT_CLOEXEC_FD)
                goto finish;
        cloexec_fd = GUEST_WAIT_CLOEXEC_FD;

        if (check_guest_masked_wait_errors() < 0 || check_guest_masked_wait_zero() < 0)
                goto finish;
        for (GuestMaskedWaitKind kind = 0; kind < _GUEST_WAIT_MAX; kind++) {
                if (run_guest_masked_wait_producer(kind) < 0 ||
                    run_guest_masked_wait_signal_round(kind, false, false) < 0 ||
                    run_guest_masked_wait_signal_round(kind, true, false) < 0 ||
                    run_guest_masked_wait_signal_round(kind, true, true) < 0)
                        goto finish;
        }

        if (fstat(GUEST_WAIT_EVENT_FD, &event_stat) < 0 || fstat(GUEST_WAIT_EPOLL_FD, &epoll_stat) < 0)
                goto finish;
        state.event_device = event_stat.st_dev;
        state.event_inode = event_stat.st_ino;
        state.epoll_device = epoll_stat.st_dev;
        state.epoll_inode = epoll_stat.st_ino;
        state_fd = memfd_create("kvm-masked-wait-state", MFD_CLOEXEC);
        if (state_fd < 0 || pwrite(state_fd, &state, sizeof(state), 0) != (ssize_t) sizeof(state) ||
            move_guest_masked_wait_fd(state_fd, GUEST_WAIT_STATE_FD, false) < 0)
                goto finish;
        state_fd = GUEST_WAIT_STATE_FD;
        if (write(GUEST_WAIT_EVENT_FD, &state.queued_value, sizeof(state.queued_value)) !=
                    sizeof(state.queued_value) ||
            check_guest_masked_wait_fds(false, &state) < 0)
                goto finish;
        execl(self, self, "--guest-exec-target", "--expect-masked-waits", NULL);

finish:
        if (event_fd >= 0)
                close(event_fd);
        if (epoll_fd >= 0)
                close(epoll_fd);
        if (state_fd >= 0)
                close(state_fd);
        if (cloexec_fd >= 0)
                close(cloexec_fd);
        return result;
}

static int test_guest_masked_wait_exec(const char *self) {
        int status;
        pid_t child, waited;

        child = fork();
        if (child < 0)
                return EXIT_FAILURE;
        if (child == 0)
                _exit(run_guest_masked_wait_exec(self) < 0 ? 230 : 0);
        do
                waited = waitpid(child, &status, 0);
        while (waited < 0 && errno == EINTR);
        return waited == child && WIFEXITED(status) && WEXITSTATUS(status) == 0 ? EXIT_SUCCESS : EXIT_FAILURE;
}

typedef struct GuestSchedulerState {
        uint64_t magic;
        struct sched_attr attr;
} GuestSchedulerState;

typedef struct GuestSchedulerWorkerContext {
        const char *self;
        struct sched_attr requested;
        int ready_fd;
        int release_fd;
        pid_t tid;
        int error;
} GuestSchedulerWorkerContext;

static const uint64_t guest_scheduler_magic = UINT64_C(0x5343484544434c53);

static int guest_sched_getattr(pid_t pid, struct sched_attr *ret_attr) {
        *ret_attr = (struct sched_attr) {
                .size = sizeof(*ret_attr),
        };
        return syscall(SYS_sched_getattr, pid, ret_attr, sizeof(*ret_attr), 0) < 0 ? -errno : 0;
}

static int guest_sched_setattr(const struct sched_attr *attr) {
        return syscall(SYS_sched_setattr, 0, attr, 0) < 0 ? -errno : 0;
}

static int restore_guest_scheduler_other(void) {
        const struct sched_attr other = {
                .size = sizeof(other),
                .sched_policy = SCHED_OTHER,
        };

        return guest_sched_setattr(&other);
}

static bool guest_scheduler_matches(
                const struct sched_attr *actual,
                const struct sched_attr *expected) {

        if (actual->sched_policy != expected->sched_policy ||
            actual->sched_priority != expected->sched_priority ||
            ((actual->sched_flags ^ expected->sched_flags) & SCHED_FLAG_RESET_ON_FORK) != 0)
                return false;
        if (expected->sched_policy == SCHED_DEADLINE)
                return actual->sched_runtime == expected->sched_runtime &&
                       actual->sched_deadline == expected->sched_deadline &&
                       actual->sched_period == expected->sched_period;
        return true;
}

static int move_guest_scheduler_fd(int fd) {
        int flags;

        if (fd < 0)
                return -EBADF;
        if (fd != GUEST_SCHEDULER_STATE_FD) {
                if (dup2(fd, GUEST_SCHEDULER_STATE_FD) != GUEST_SCHEDULER_STATE_FD)
                        return -errno;
                if (close(fd) < 0) {
                        int error = -errno;

                        (void) close(GUEST_SCHEDULER_STATE_FD);
                        return error;
                }
                return GUEST_SCHEDULER_STATE_FD;
        }
        flags = fcntl(fd, F_GETFD);
        if (flags < 0 || fcntl(fd, F_SETFD, flags & ~FD_CLOEXEC) < 0)
                return -errno;
        return fd;
}

static void *guest_scheduler_exec_worker(void *userdata) {
        GuestSchedulerWorkerContext *context = userdata;
        GuestSchedulerState state = {
                .magic = guest_scheduler_magic,
        };
        char byte;

        context->tid = gettid();
        context->error = guest_sched_setattr(&context->requested);
        if (context->error >= 0)
                context->error = guest_sched_getattr(0, &state.attr);
        if (context->error >= 0 &&
            pwrite(GUEST_SCHEDULER_STATE_FD, &state, sizeof(state), 0) != (ssize_t) sizeof(state))
                context->error = -errno;
        byte = context->error < 0 ? 'e' : 'r';
        if (write(context->ready_fd, &byte, 1) != 1)
                return (void*) (uintptr_t) EIO;
        if (context->error < 0)
                return (void*) (uintptr_t) -context->error;
        if (read(context->release_fd, &byte, 1) != 1 || byte != 'x')
                return (void*) (uintptr_t) EIO;
        execl(context->self, context->self, "--guest-exec-target", "--expect-scheduler-class", NULL);
        return (void*) (uintptr_t) errno;
}

static int validate_guest_scheduler_exec(void) {
        GuestSchedulerState state = {};
        struct sched_attr actual;
        int result = EXIT_FAILURE, status;
        pid_t child, waited;

        if (pread(GUEST_SCHEDULER_STATE_FD, &state, sizeof(state), 0) != (ssize_t) sizeof(state) ||
            state.magic != guest_scheduler_magic || guest_sched_getattr(0, &actual) < 0 ||
            !guest_scheduler_matches(&actual, &state.attr))
                goto finish;
        if (actual.sched_policy == SCHED_RR) {
                struct timespec interval;

                if (sched_rr_get_interval(0, &interval) < 0 || interval.tv_sec < 0 || interval.tv_nsec < 0 ||
                    interval.tv_nsec >= 1000000000 || (interval.tv_sec == 0 && interval.tv_nsec == 0))
                        goto finish;
        }

        child = fork();
        if (child < 0)
                goto finish;
        if (child == 0) {
                struct sched_attr inherited;

                if (guest_sched_getattr(0, &inherited) < 0 || inherited.sched_policy != SCHED_OTHER ||
                    inherited.sched_priority != 0 ||
                    (inherited.sched_flags & SCHED_FLAG_RESET_ON_FORK) != 0)
                        _exit(243);
                _exit(0);
        }
        do
                waited = waitpid(child, &status, 0);
        while (waited < 0 && errno == EINTR);
        if (waited != child || !WIFEXITED(status) || WEXITSTATUS(status) != 0 ||
            restore_guest_scheduler_other() < 0)
                goto finish;
        result = EXIT_SUCCESS;

finish:
        if (result != EXIT_SUCCESS)
                (void) restore_guest_scheduler_other();
        if (close(GUEST_SCHEDULER_STATE_FD) < 0)
                result = EXIT_FAILURE;
        if (result == EXIT_SUCCESS)
                printf(
                                "KVM_SCHEDULER_EXEC_OK policy=%u priority=%u reset=1\n",
                                state.attr.sched_policy,
                                state.attr.sched_priority);
        return result;
}

static int run_guest_scheduler_worker_exec(const char *self, const struct sched_attr *attr) {
        GuestSchedulerWorkerContext context = {
                .self = self,
                .requested = *attr,
        };
        struct sched_attr leader, worker;
        int ready_pipe[2] = { -1, -1 }, release_pipe[2] = { -1, -1 }, state_fd = -1;
        pthread_t thread;
        void *thread_result;
        char byte;
        int r, result = -EPROTO;

        state_fd = memfd_create("kvm-scheduler-state", MFD_CLOEXEC);
        if (state_fd < 0 || move_guest_scheduler_fd(state_fd) < 0 ||
            pipe2(ready_pipe, O_CLOEXEC) < 0 || pipe2(release_pipe, O_CLOEXEC) < 0)
                goto finish;
        state_fd = GUEST_SCHEDULER_STATE_FD;
        context.ready_fd = ready_pipe[1];
        context.release_fd = release_pipe[0];
        r = pthread_create(&thread, NULL, guest_scheduler_exec_worker, &context);
        if (r != 0) {
                result = -r;
                goto finish;
        }
        if (read(ready_pipe[0], &byte, 1) != 1)
                goto join;
        if (byte == 'e') {
                result = context.error;
                goto join;
        }
        if (byte != 'r' || context.tid <= 0 || guest_sched_getattr(0, &leader) < 0 ||
            guest_sched_getattr(context.tid, &worker) < 0 || leader.sched_policy != SCHED_OTHER ||
            !guest_scheduler_matches(&worker, attr) || write(release_pipe[1], "x", 1) != 1)
                goto join;
        r = pthread_join(thread, &thread_result);
        if (r != 0)
                result = -r;
        else
                result = -(int) (uintptr_t) thread_result;
        goto finish;

join:
        (void) write(release_pipe[1], "x", 1);
        r = pthread_join(thread, &thread_result);
        if (r != 0 && result >= 0)
                result = -r;
finish:
        for (size_t i = 0; i < 2; i++) {
                if (ready_pipe[i] >= 0)
                        close(ready_pipe[i]);
                if (release_pipe[i] >= 0)
                        close(release_pipe[i]);
        }
        if (state_fd >= 0)
                close(state_fd);
        return result;
}

static int run_guest_scheduler_exec_profile(const char *self, const struct sched_attr *attr) {
        int status;
        pid_t child, waited;

        child = fork();
        if (child < 0)
                return -errno;
        if (child == 0) {
                int r = run_guest_scheduler_worker_exec(self, attr);

                _exit(r < 0 && -r < 255 ? -r : 244);
        }
        do
                waited = waitpid(child, &status, 0);
        while (waited < 0 && errno == EINTR);
        if (waited != child || !WIFEXITED(status))
                return -EPROTO;
        return WEXITSTATUS(status) == 0 ? 0 : -WEXITSTATUS(status);
}

static int check_guest_scheduler_scalar_errors(void) {
        struct sched_attr attr = {
                .size = sizeof(attr),
                .sched_policy = SCHED_OTHER,
        };
        struct sched_param parameter = {};

        errno = 0;
        if (syscall(SYS_sched_setattr, -1, &attr, 0) >= 0 || errno != EINVAL)
                return -EPROTO;
        errno = 0;
        if (syscall(SYS_sched_setattr, 0, NULL, 0) >= 0 || errno != EINVAL)
                return -EPROTO;
        errno = 0;
        if (syscall(SYS_sched_setattr, 0, &attr, 1) >= 0 || errno != EINVAL)
                return -EPROTO;
        attr.sched_policy = UINT32_MAX;
        errno = 0;
        if (guest_sched_setattr(&attr) >= 0 || errno != EINVAL)
                return -EPROTO;
        attr = (struct sched_attr) {
                .size = sizeof(attr),
                .sched_policy = SCHED_FIFO,
        };
        errno = 0;
        if (guest_sched_setattr(&attr) >= 0 || errno != EINVAL)
                return -EPROTO;
        parameter.sched_priority = 1;
        errno = 0;
        if (sched_setscheduler(-1, SCHED_FIFO, &parameter) >= 0 || errno != EINVAL)
                return -EPROTO;
        return 0;
}

static int guest_has_initial_cap_sys_nice(bool *ret) {
        struct sched_attr attr = {
                .size = sizeof(attr),
                .sched_policy = SCHED_BATCH,
                .sched_flags = SCHED_FLAG_RESET_ON_FORK,
        };
        int status;
        pid_t child, waited;

        child = fork();
        if (child < 0)
                return -errno;
        if (child == 0) {
                int r;

                if (guest_sched_setattr(&attr) < 0)
                        _exit(251);
                attr.sched_flags = 0;
                r = guest_sched_setattr(&attr);
                _exit(r >= 0 ? 252 : r == -EPERM ? 253 : 254);
        }
        do
                waited = waitpid(child, &status, 0);
        while (waited < 0 && errno == EINTR);
        if (waited != child || !WIFEXITED(status) ||
            (WEXITSTATUS(status) != 252 && WEXITSTATUS(status) != 253))
                return -EPROTO;
        *ret = WEXITSTATUS(status) == 252;
        return 0;
}

static int check_guest_scheduler_permission_errors(bool privileged) {
        static const struct sched_attr attrs[] = {
                {
                        .size = sizeof(struct sched_attr),
                        .sched_policy = SCHED_FIFO,
                        .sched_priority = 1,
                },
                {
                        .size = sizeof(struct sched_attr),
                        .sched_policy = SCHED_RR,
                        .sched_priority = 1,
                },
                {
                        .size = sizeof(struct sched_attr),
                        .sched_policy = SCHED_DEADLINE,
                        .sched_runtime = 1000000,
                        .sched_deadline = 20000000,
                        .sched_period = 20000000,
                },
        };
        int status;
        pid_t child, waited;

        if (privileged)
                return 0;
        child = fork();
        if (child < 0)
                return -errno;
        if (child == 0) {
                for (size_t i = 0; i < sizeof(attrs) / sizeof(attrs[0]); i++) {
                        errno = 0;
                        if (guest_sched_setattr(attrs + i) >= 0 || errno != EPERM)
                                _exit(245);
                }
                _exit(0);
        }
        do
                waited = waitpid(child, &status, 0);
        while (waited < 0 && errno == EINTR);
        return waited == child && WIFEXITED(status) && WEXITSTATUS(status) == 0 ? 0 : -EPROTO;
}

static int check_guest_fair_reset_on_fork(void) {
        struct sched_attr attr = {
                .size = sizeof(attr),
                .sched_policy = SCHED_BATCH,
                .sched_flags = SCHED_FLAG_RESET_ON_FORK,
        }, actual;
        int status;
        pid_t child, grandchild, waited;

        child = fork();
        if (child < 0)
                return -errno;
        if (child == 0) {
                if (guest_sched_setattr(&attr) < 0 || guest_sched_getattr(0, &actual) < 0 ||
                    !guest_scheduler_matches(&actual, &attr))
                        _exit(246);
                grandchild = fork();
                if (grandchild < 0)
                        _exit(247);
                if (grandchild == 0) {
                        if (guest_sched_getattr(0, &actual) < 0 || actual.sched_policy != SCHED_BATCH ||
                            (actual.sched_flags & SCHED_FLAG_RESET_ON_FORK) != 0)
                                _exit(248);
                        _exit(0);
                }
                if (waitpid(grandchild, &status, 0) != grandchild ||
                    !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                        _exit(249);
                _exit(0);
        }
        do
                waited = waitpid(child, &status, 0);
        while (waited < 0 && errno == EINTR);
        return waited == child && WIFEXITED(status) && WEXITSTATUS(status) == 0 ? 0 : -EPROTO;
}

static int check_guest_rt_scheduler_class(const char *self, uint32_t policy) {
        struct sched_attr attr = {
                .size = sizeof(attr),
                .sched_policy = policy,
                .sched_priority = 1,
        }, inherited;
        int status, result = -EPROTO;
        pid_t child, waited;

        int r = guest_sched_setattr(&attr);
        if (r < 0)
                return r;
        child = fork();
        if (child < 0)
                goto finish;
        if (child == 0) {
                if (guest_sched_getattr(0, &inherited) < 0 || !guest_scheduler_matches(&inherited, &attr))
                        _exit(247);
                _exit(0);
        }
        do
                waited = waitpid(child, &status, 0);
        while (waited < 0 && errno == EINTR);
        if (waited != child || !WIFEXITED(status) || WEXITSTATUS(status) != 0 ||
            run_guest_clone_thread_flags_one(false) != EXIT_SUCCESS ||
            run_guest_clone_thread_flags_one(true) != EXIT_SUCCESS)
                goto finish;
        result = 0;
finish:
        if (restore_guest_scheduler_other() < 0 && result >= 0)
                result = -errno;
        if (result < 0)
                return result;
        attr.sched_flags = SCHED_FLAG_RESET_ON_FORK;
        return run_guest_scheduler_exec_profile(self, &attr);
}

static int spawn_guest_scheduler_probe_thread(int *ret_policy) {
        const size_t stack_size = 1U << 20;
        const int flags = CLONE_VM | CLONE_FS | CLONE_FILES | CLONE_SIGHAND | CLONE_THREAD | CLONE_SYSVSEM |
                CLONE_CHILD_SETTID | CLONE_CHILD_CLEARTID;
        GuestThreadSharingContext context = {
                .child_tid = 1,
        };
        void *stack;
        pid_t child;

        stack = mmap(NULL, stack_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (stack == MAP_FAILED)
                return -errno;
        child = clone(
                        guest_thread_sharing_child,
                        (uint8_t*) stack + stack_size,
                        flags,
                        &context,
                        NULL,
                        NULL,
                        &context.child_tid);
        if (child < 0) {
                int error = -errno;

                (void) munmap(stack, stack_size);
                return error;
        }
        while (__atomic_load_n(&context.ready, __ATOMIC_ACQUIRE) == 0)
                if (syscall(SYS_futex, &context.ready, FUTEX_WAIT, 0, NULL, NULL, 0) < 0 &&
                    errno != EAGAIN && errno != EINTR)
                        goto fail;
        *ret_policy = sched_getscheduler(child);
        __atomic_store_n(&context.release, 1, __ATOMIC_RELEASE);
        (void) syscall(SYS_futex, &context.release, FUTEX_WAKE, INT_MAX, NULL, NULL, 0);
        if (*ret_policy < 0 || wait_guest_thread_sharing_child(&context) < 0 || munmap(stack, stack_size) < 0)
                return -EPROTO;
        return 0;

fail:
        __atomic_store_n(&context.release, 1, __ATOMIC_RELEASE);
        (void) syscall(SYS_futex, &context.release, FUTEX_WAKE, INT_MAX, NULL, NULL, 0);
        (void) wait_guest_thread_sharing_child(&context);
        (void) munmap(stack, stack_size);
        return -EPROTO;
}

static int check_guest_deadline_scheduler_class(const char *self) {
        struct sched_attr attr = {
                .size = sizeof(attr),
                .sched_policy = SCHED_DEADLINE,
                .sched_runtime = 100000,
                .sched_deadline = 100000000,
                .sched_period = 100000000,
        };
        int policy, result = -EPROTO;
        pid_t child;

        int r = guest_sched_setattr(&attr);
        if (r < 0)
                return r;
        errno = 0;
        child = fork();
        if (child >= 0 || errno != EAGAIN) {
                if (child == 0)
                        _exit(248);
                if (child > 0)
                        (void) waitpid(child, NULL, 0);
                goto finish;
        }
        errno = 0;
        r = spawn_guest_scheduler_probe_thread(&policy);
        if (r >= 0 || r != -EAGAIN)
                goto finish;
        if (restore_guest_scheduler_other() < 0)
                return -errno;

        attr.sched_flags = SCHED_FLAG_RESET_ON_FORK;
        if (guest_sched_setattr(&attr) < 0 || spawn_guest_scheduler_probe_thread(&policy) < 0 ||
            policy != SCHED_OTHER)
                goto finish;
        result = 0;
finish:
        if (restore_guest_scheduler_other() < 0 && result >= 0)
                result = -errno;
        if (result < 0)
                return result;
        return run_guest_scheduler_exec_profile(self, &attr);
}

static int run_guest_privileged_scheduler_classes(const char *self, bool privileged) {
        struct rlimit rtprio;
        int fair, fifo, rr, deadline;

        fair = check_guest_fair_reset_on_fork();
        if (fair < 0) {
                fprintf(stderr, "Guest fair scheduler reset failed: %s\n", strerror(-fair));
                return -EPROTO;
        }
        if (!privileged) {
                if (getrlimit(RLIMIT_RTPRIO, &rtprio) < 0)
                        return -errno;
                printf(
                                "KVM_SCHEDULER_CLASSES_UNSUPPORTED"
                                " cap_sys_nice=0 rlimit_rtprio=%" PRIu64
                                " fifo_errno=%d rr_errno=%d deadline_errno=%d fair_reset=1\n",
                                (uint64_t) rtprio.rlim_cur,
                                EPERM,
                                EPERM,
                                EPERM);
                return 0;
        }
        fifo = check_guest_rt_scheduler_class(self, SCHED_FIFO);
        rr = check_guest_rt_scheduler_class(self, SCHED_RR);
        deadline = check_guest_deadline_scheduler_class(self);
        if ((fifo < 0 && fifo != -EPERM) || (rr < 0 && rr != -EPERM) ||
            (deadline < 0 && deadline != -EPERM && deadline != -EBUSY)) {
                fprintf(
                                stderr,
                                "Guest scheduler class failure: fifo=%d rr=%d deadline=%d\n",
                                fifo,
                                rr,
                                deadline);
                return -EPROTO;
        }
        if (fifo < 0 || rr < 0 || deadline < 0) {
                printf(
                                "KVM_SCHEDULER_CLASSES_GATED"
                                " cap_sys_nice=1 fifo_errno=%d rr_errno=%d deadline_errno=%d fair_reset=1\n",
                                fifo < 0 ? -fifo : 0,
                                rr < 0 ? -rr : 0,
                                deadline < 0 ? -deadline : 0);
                return 0;
        }
        printf("KVM_SCHEDULER_CLASSES_OK fifo=1 rr=1 deadline=1 fair_reset=1\n");
        return 0;
}

static int test_guest_privileged_scheduler_classes(const char *self) {
        bool privileged = false;
        int status;
        pid_t child, waited;
        int result = EXIT_FAILURE, r;

        r = guest_has_initial_cap_sys_nice(&privileged);
        if (r < 0)
                return EXIT_FAILURE;
        r = check_guest_scheduler_scalar_errors();
        if (r < 0) {
                fprintf(stderr, "Guest scheduler scalar checks failed: %s\n", strerror(-r));
                return EXIT_FAILURE;
        }
        r = check_guest_scheduler_permission_errors(privileged);
        if (r < 0) {
                fprintf(stderr, "Guest scheduler permission checks failed: %s\n", strerror(-r));
                return EXIT_FAILURE;
        }
        child = fork();
        if (child < 0)
                return EXIT_FAILURE;
        if (child == 0)
                _exit(run_guest_privileged_scheduler_classes(self, privileged) < 0 ? 250 : 0);
        do
                waited = waitpid(child, &status, 0);
        while (waited < 0 && errno == EINTR);
        if (waited == child && WIFEXITED(status) && WEXITSTATUS(status) == 0)
                result = EXIT_SUCCESS;
        else
                fprintf(stderr, "Guest scheduler child failed: status=%#x\n", status);
        return result;
}

static int make_guest_lock_path(char path[static PATH_MAX], const char *name, pid_t owner) {
        return snprintf(path, PATH_MAX, "/tmp/kvm-%s-lock-%ld", name, (long) owner) < PATH_MAX ?
                0 : -EOVERFLOW;
}

static int open_guest_lock_file(const char *path, int target_fd) {
        int fd;

        fd = open(path, O_CREAT | O_EXCL | O_RDWR, 0600);
        if (fd < 0)
                return -errno;
        if (fd == target_fd)
                return fd;
        if (dup2(fd, target_fd) != target_fd) {
                int error = -errno;

                close(fd);
                return error;
        }
        if (close(fd) < 0)
                return -errno;
        return target_fd;
}

static bool guest_lock_conflict_errno(void) {
        return errno == EACCES || errno == EAGAIN || errno == EWOULDBLOCK;
}

static int check_guest_lock_contenders(pid_t owner) {
        static const struct {
                const char *name;
                int command;
        } locks[] = {
                { "posix", F_SETLK },
                { "ofd", F_OFD_SETLK },
        };
        struct flock lock = {
                .l_type = F_WRLCK,
                .l_whence = SEEK_SET,
        };

        for (size_t i = 0; i < sizeof(locks) / sizeof(locks[0]); i++) {
                char path[PATH_MAX];
                int fd;

                if (make_guest_lock_path(path, locks[i].name, owner) < 0)
                        return -EOVERFLOW;
                fd = open(path, O_RDWR);
                if (fd < 0)
                        return -errno;
                errno = 0;
                if (fcntl(fd, locks[i].command, &lock) >= 0 || !guest_lock_conflict_errno()) {
                        close(fd);
                        return -EPROTO;
                }
                close(fd);
        }

        char path[PATH_MAX];
        if (make_guest_lock_path(path, "flock", owner) < 0)
                return -EOVERFLOW;
        int fd = open(path, O_RDWR);
        if (fd < 0)
                return -errno;
        errno = 0;
        if (flock(fd, LOCK_EX | LOCK_NB) >= 0 || !guest_lock_conflict_errno()) {
                close(fd);
                return -EPROTO;
        }
        close(fd);
        return 0;
}

static int cleanup_guest_advisory_locks(void) {
        static const struct {
                const char *name;
                int fd;
        } files[] = {
                { "posix", GUEST_POSIX_LOCK_FD },
                { "ofd", GUEST_OFD_LOCK_FD },
                { "flock", GUEST_FLOCK_FD },
        };
        int result = 0;

        for (size_t i = 0; i < sizeof(files) / sizeof(files[0]); i++) {
                char path[PATH_MAX];

                if (close(files[i].fd) < 0 && errno != EBADF)
                        result = -errno;
                if (make_guest_lock_path(path, files[i].name, getpid()) < 0)
                        result = -EOVERFLOW;
                else if (unlink(path) < 0 && errno != ENOENT)
                        result = -errno;
        }
        return result;
}

static int validate_guest_advisory_locks_exec(void) {
        struct flock lock = {
                .l_type = F_WRLCK,
                .l_whence = SEEK_SET,
        };
        int status;
        pid_t child;

        if ((fcntl(GUEST_POSIX_LOCK_FD, F_GETFD) & FD_CLOEXEC) != 0 ||
            (fcntl(GUEST_OFD_LOCK_FD, F_GETFD) & FD_CLOEXEC) != 0 ||
            (fcntl(GUEST_FLOCK_FD, F_GETFD) & FD_CLOEXEC) != 0)
                goto fail;

        child = fork();
        if (child < 0)
                goto fail;
        if (child == 0)
                _exit(check_guest_lock_contenders(getppid()) < 0 ? 148 : 0);
        if (waitpid(child, &status, 0) != child ||
            !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                goto fail;

        lock.l_type = F_UNLCK;
        if (fcntl(GUEST_POSIX_LOCK_FD, F_SETLK, &lock) < 0 ||
            fcntl(GUEST_OFD_LOCK_FD, F_OFD_SETLK, &lock) < 0 ||
            flock(GUEST_FLOCK_FD, LOCK_UN) < 0 || cleanup_guest_advisory_locks() < 0)
                return EXIT_FAILURE;

        printf("KVM_ADVISORY_LOCKS_OK\n");
        return EXIT_SUCCESS;

fail:
        cleanup_guest_advisory_locks();
        return EXIT_FAILURE;
}

static int run_guest_advisory_locks_exec(const char *self) {
        static const struct {
                const char *name;
                int fd;
        } files[] = {
                { "posix", GUEST_POSIX_LOCK_FD },
                { "ofd", GUEST_OFD_LOCK_FD },
                { "flock", GUEST_FLOCK_FD },
        };
        struct flock lock = {
                .l_type = F_WRLCK,
                .l_whence = SEEK_SET,
        };
        int status;
        pid_t child;

        for (size_t i = 0; i < sizeof(files) / sizeof(files[0]); i++) {
                char path[PATH_MAX];

                if (make_guest_lock_path(path, files[i].name, getpid()) < 0 ||
                    open_guest_lock_file(path, files[i].fd) < 0)
                        goto fail;
        }

        struct flock invalid_ofd = lock;
        invalid_ofd.l_pid = 1;
        errno = 0;
        if (fcntl(GUEST_OFD_LOCK_FD, F_OFD_SETLK, &invalid_ofd) >= 0 || errno != EINVAL ||
            fcntl(GUEST_POSIX_LOCK_FD, F_SETLK, &lock) < 0 ||
            fcntl(GUEST_OFD_LOCK_FD, F_OFD_SETLK, &lock) < 0 ||
            flock(GUEST_FLOCK_FD, LOCK_EX | LOCK_NB) < 0)
                goto fail;

        child = fork();
        if (child < 0)
                goto fail;
        if (child == 0) {
                struct flock query = {
                        .l_type = F_WRLCK,
                        .l_whence = SEEK_SET,
                };

                if (fcntl(GUEST_POSIX_LOCK_FD, F_GETLK, &query) < 0 ||
                    query.l_type != F_WRLCK || query.l_pid != getppid())
                        _exit(149);
                query = (struct flock) {
                        .l_type = F_WRLCK,
                        .l_whence = SEEK_SET,
                };
                if (fcntl(GUEST_OFD_LOCK_FD, F_OFD_GETLK, &query) < 0 || query.l_type != F_UNLCK ||
                    flock(GUEST_FLOCK_FD, LOCK_EX | LOCK_NB) < 0 ||
                    check_guest_lock_contenders(getppid()) < 0)
                        _exit(150);
                _exit(0);
        }
        if (waitpid(child, &status, 0) != child ||
            !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                goto fail;

        execl(self, self, "--guest-exec-target", "--expect-advisory-locks", NULL);
fail:
        cleanup_guest_advisory_locks();
        return -EPROTO;
}

static int test_guest_advisory_locks_exec(const char *self) {
        int status;
        pid_t child;

        child = fork();
        if (child < 0)
                return EXIT_FAILURE;
        if (child == 0)
                _exit(run_guest_advisory_locks_exec(self) < 0 ? 151 : 0);
        if (waitpid(child, &status, 0) != child ||
            !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                return EXIT_FAILURE;
        return EXIT_SUCCESS;
}

static int validate_guest_amx_exec(void) {
        unsigned eax, ebx, ecx, edx;
        uint64_t permissions = 0, supported = 0;

        __cpuid_count(7, 0, eax, ebx, ecx, edx);
        if (!(edx & bit_AMX_TILE))
                return EXIT_SUCCESS;
        if (syscall(SYS_arch_prctl, ARCH_GET_XCOMP_SUPP, &supported) < 0 ||
            syscall(SYS_arch_prctl, ARCH_GET_XCOMP_PERM, &permissions) < 0 ||
            !(supported & (UINT64_C(1) << ARCH_XCOMP_TILEDATA)) ||
            (permissions & (UINT64_C(1) << ARCH_XCOMP_TILEDATA)) != 0 ||
            !guest_amx_state_works())
                return EXIT_FAILURE;

        printf("KVM_AMX_EXEC_RESET_OK\n");
        return EXIT_SUCCESS;
}

__attribute__((target("amx-tile"), noinline))
static int test_guest_amx_exec(const char *self) {
        _Alignas(64) GuestAmxTileConfig configuration = {
                .palette_id = 1,
                .columns[0] = 64,
                .rows[0] = 16,
        };
        _Alignas(64) uint8_t input[1024], output[1024] = {};
        unsigned eax, ebx, ecx, edx;
        int status;
        pid_t child;

        __cpuid_count(7, 0, eax, ebx, ecx, edx);
        if (!(edx & bit_AMX_TILE))
                return EXIT_SUCCESS;

        child = fork();
        if (child < 0)
                return EXIT_FAILURE;
        if (child == 0) {
                char *const invalid_argv[] = { (char*) "/definitely-missing-amx-exec", NULL };

                if (syscall(SYS_arch_prctl, ARCH_REQ_XCOMP_PERM, ARCH_XCOMP_TILEDATA) < 0)
                        _exit(120);
                for (size_t i = 0; i < sizeof(input); i++)
                        input[i] = (uint8_t) (i * 59U + 31U);
                _tile_loadconfig(&configuration);
                _tile_loadd(0, input, 64);
                execve(invalid_argv[0], invalid_argv, environ);
                if (errno != ENOENT)
                        _exit(121);
                _tile_stored(0, output, 64);
                _tile_release();
                if (memcmp(output, input, sizeof(output)) != 0)
                        _exit(122);
                execl(self, self, "--guest-exec-target", "--expect-amx-reset", NULL);
                _exit(123);
        }

        if (waitpid(child, &status, 0) != child || !WIFEXITED(status) || WEXITSTATUS(status) != 0)
                return EXIT_FAILURE;
        return EXIT_SUCCESS;
}

typedef enum GuestAmxTestCase {
        GUEST_AMX_TEST_PROFILE,
        GUEST_AMX_TEST_CONTEXT_THREAD,
        GUEST_AMX_TEST_SIGNAL,
        GUEST_AMX_TEST_SIGALTSTACK,
        GUEST_AMX_TEST_FORK,
        GUEST_AMX_TEST_VFORK,
        GUEST_AMX_TEST_EXEC,
        GUEST_AMX_TEST_THREAD_EXEC,
        _GUEST_AMX_TEST_MAX,
} GuestAmxTestCase;

static int validate_guest_amx_profile(void) {
        unsigned eax, ebx, ecx, edx, xcr0_high, xcr0_low;
        uint64_t permissions = 0, supported = 0;
        uint32_t tilecfg_end, tiledata_end, tiledata_size;

        __cpuid_count(7, 0, eax, ebx, ecx, edx);
        if (!(edx & bit_AMX_TILE))
                return 77;
        asm volatile ("xgetbv" : "=a" (xcr0_low), "=d" (xcr0_high) : "c" (0));
        if ((xcr0_low & ((1U << 17)|(1U << 18))) != ((1U << 17)|(1U << 18)) || xcr0_high != 0)
                return EXIT_FAILURE;

        __cpuid_count(0x0d, 17, eax, ebx, ecx, edx);
        tilecfg_end = ebx + eax;
        if (eax != 64 || tilecfg_end < ebx || (ecx & 1U) != 0 || edx != 0)
                return EXIT_FAILURE;
        __cpuid_count(0x0d, 18, eax, ebx, ecx, edx);
        tiledata_size = eax;
        tiledata_end = ebx + eax;
        if (eax == 0 || ebx < tilecfg_end || tiledata_end < ebx ||
            (ecx & (1U << 2)) == 0 || (ecx & 1U) != 0 || edx != 0)
                return EXIT_FAILURE;
        __cpuid_count(0x1d, 0, eax, ebx, ecx, edx);
        if (eax < 1 || ebx != 0 || ecx != 0 || edx != 0)
                return EXIT_FAILURE;
        __cpuid_count(0x1d, 1, eax, ebx, ecx, edx);
        if ((eax & UINT32_C(0xffff)) != tiledata_size || (eax >> 16) < 1024 ||
            (ebx & UINT32_C(0xffff)) < 64 || (ebx >> 16) < 8 ||
            (ecx & UINT32_C(0xffff)) < 16 || (ecx >> 16) != 0 || edx != 0)
                return EXIT_FAILURE;

        if (syscall(SYS_arch_prctl, ARCH_GET_XCOMP_SUPP, &supported) < 0 ||
            syscall(SYS_arch_prctl, ARCH_GET_XCOMP_PERM, &permissions) < 0 ||
            (supported & ((UINT64_C(1) << 17)|(UINT64_C(1) << 18))) !=
                    ((UINT64_C(1) << 17)|(UINT64_C(1) << 18)) ||
            !(permissions & (UINT64_C(1) << 17)) ||
            (permissions & (UINT64_C(1) << 18)) != 0)
                return EXIT_FAILURE;
        return EXIT_SUCCESS;
}

static int run_guest_amx_test_case(const char *self, GuestAmxTestCase test_case) {
        int status;
        pid_t child;

        child = fork();
        if (child < 0)
                return EXIT_FAILURE;
        if (child == 0) {
                int r;

                switch (test_case) {
                case GUEST_AMX_TEST_PROFILE:
                        r = validate_guest_amx_profile();
                        break;
                case GUEST_AMX_TEST_CONTEXT_THREAD:
                        r = guest_amx_state_works() && guest_amx_thread_state_works() ? EXIT_SUCCESS : EXIT_FAILURE;
                        break;
                case GUEST_AMX_TEST_SIGNAL:
                        r = test_guest_signal_amx() < 0 ? EXIT_FAILURE : EXIT_SUCCESS;
                        break;
                case GUEST_AMX_TEST_SIGALTSTACK:
                        r = test_guest_sigaltstack();
                        break;
                case GUEST_AMX_TEST_FORK:
                        r = test_guest_fork_amx();
                        break;
                case GUEST_AMX_TEST_VFORK:
                        r = test_guest_vfork_amx();
                        break;
                case GUEST_AMX_TEST_EXEC:
                        r = test_guest_amx_exec(self);
                        break;
                case GUEST_AMX_TEST_THREAD_EXEC:
                        r = test_guest_thread_amx_exec(self);
                        break;
                default:
                        r = EXIT_FAILURE;
                }
                _exit(r);
        }

        if (waitpid(child, &status, 0) != child || !WIFEXITED(status))
                return EXIT_FAILURE;
        return WEXITSTATUS(status);
}

static int test_guest_amx(const char *self) {
        unsigned eax, ebx, ecx, edx;
        int source_kvm;

        __cpuid_count(7, 0, eax, ebx, ecx, edx);
        source_kvm = guest_process_has_kvm_fd();
        if (source_kvm < 0)
                return EXIT_FAILURE;
        if (!(edx & bit_AMX_TILE)) {
                printf("KVM_AMX_UNAVAILABLE source_kvm=%d\n", source_kvm);
                return 77;
        }

        for (GuestAmxTestCase test_case = 0; test_case < _GUEST_AMX_TEST_MAX; test_case++)
                if (run_guest_amx_test_case(self, test_case) != EXIT_SUCCESS)
                        return EXIT_FAILURE;

        printf("KVM_AMX_OK source_kvm=%d\n", source_kvm);
        return EXIT_SUCCESS;
}

static int test_guest_cet(void) {
        long page_size;
        uint64_t expected_token, token;
        unsigned long address;
        void *guard_mapping, *moved, *occupied, *target;
        int source_kvm, status;
        pid_t child;

        page_size = sysconf(_SC_PAGESIZE);
        if (page_size <= 0)
                return EXIT_FAILURE;

        errno = 0;
        if (syscall(SYS_map_shadow_stack, 0, 0, 0) >= 0 || errno != EINVAL)
                return EXIT_FAILURE;
        errno = 0;
        if (syscall(SYS_map_shadow_stack, 0, SIZE_MAX, 0) >= 0 || errno != EOVERFLOW)
                return EXIT_FAILURE;
        errno = 0;
        if (syscall(SYS_map_shadow_stack, 0, SIZE_MAX, SHADOW_STACK_SET_TOKEN) >= 0 || errno != EOVERFLOW)
                return EXIT_FAILURE;
        errno = 0;
        if (syscall(SYS_map_shadow_stack, 0, page_size, UINT_MAX) >= 0 || errno != EINVAL)
                return EXIT_FAILURE;
        errno = 0;
        if (syscall(SYS_map_shadow_stack, 0, 4, SHADOW_STACK_SET_TOKEN) >= 0 || errno != ENOSPC)
                return EXIT_FAILURE;
        errno = 0;
        if (syscall(SYS_map_shadow_stack, page_size, page_size, 0) >= 0 || errno != ERANGE)
                return EXIT_FAILURE;

        occupied = mmap(NULL, page_size, PROT_NONE, MAP_PRIVATE|MAP_ANONYMOUS, -1, 0);
        if (occupied == MAP_FAILED || (uintptr_t) occupied < UINT64_C(0x100000000))
                return EXIT_FAILURE;
        errno = 0;
        if (syscall(SYS_map_shadow_stack, occupied, 3 * sizeof(uint32_t), SHADOW_STACK_SET_TOKEN) >= 0 ||
            errno != EEXIST)
                return EXIT_FAILURE;
        if (munmap(occupied, page_size) < 0)
                return EXIT_FAILURE;

        address = syscall(SYS_map_shadow_stack, 0, 3 * page_size, SHADOW_STACK_SET_TOKEN);
        if (address >= (unsigned long) -4095 || address < UINT64_C(0x100000000) || address % page_size != 0) {
                if (address >= (unsigned long) -4095 && errno == EOPNOTSUPP) {
                        printf("KVM_CET_UNAVAILABLE\n");
                        return 77;
                }
                return EXIT_FAILURE;
        }
        memcpy(&token, (void*) (address + 3 * page_size - sizeof(token)), sizeof(token));
        expected_token = (address + 3 * page_size) | UINT64_C(1);
        if (token != expected_token)
                return EXIT_FAILURE;

        errno = 0;
        guard_mapping = mmap(
                        (void*) (address - page_size),
                        page_size,
                        PROT_READ|PROT_WRITE,
                        MAP_PRIVATE|MAP_FIXED_NOREPLACE,
                        -1,
                        0);
        if (guard_mapping != MAP_FAILED || errno != EBADF)
                return EXIT_FAILURE;
        errno = 0;
        guard_mapping = mmap(
                        (void*) (address - page_size),
                        page_size,
                        PROT_READ|PROT_WRITE,
                        MAP_PRIVATE|MAP_FIXED_NOREPLACE,
                        INT_MAX,
                        0);
        if (guard_mapping != MAP_FAILED || errno != EBADF)
                return EXIT_FAILURE;
        guard_mapping = mmap(
                        (void*) (address - page_size),
                        page_size,
                        PROT_READ|PROT_WRITE,
                        MAP_PRIVATE|MAP_ANONYMOUS,
                        -1,
                        0);
        if (guard_mapping == MAP_FAILED || guard_mapping == (void*) (address - page_size))
                return EXIT_FAILURE;
        if (munmap(guard_mapping, page_size) < 0)
                return EXIT_FAILURE;

        guard_mapping = mmap(
                        (void*) (address - page_size),
                        page_size,
                        PROT_READ|PROT_WRITE,
                        MAP_PRIVATE|MAP_ANONYMOUS|MAP_FIXED_NOREPLACE,
                        -1,
                        0);
        if (guard_mapping != (void*) (address - page_size))
                return EXIT_FAILURE;
        if (munmap(guard_mapping, page_size) < 0)
                return EXIT_FAILURE;
        guard_mapping = mmap(
                        (void*) (address - page_size),
                        page_size,
                        PROT_READ|PROT_WRITE,
                        MAP_PRIVATE|MAP_ANONYMOUS,
                        -1,
                        0);
        if (guard_mapping == MAP_FAILED || guard_mapping == (void*) (address - page_size))
                return EXIT_FAILURE;
        if (munmap(guard_mapping, page_size) < 0)
                return EXIT_FAILURE;

        child = fork();
        if (child < 0)
                return EXIT_FAILURE;
        if (child == 0) {
                target = mmap(NULL, page_size, PROT_NONE, MAP_PRIVATE|MAP_ANONYMOUS, -1, 0);
                if (target == MAP_FAILED)
                        _exit(116);
                if (munmap(target, page_size) < 0)
                        _exit(115);
                guard_mapping = mmap(
                                (void*) (address - page_size),
                                page_size,
                                PROT_READ|PROT_WRITE,
                                MAP_PRIVATE|MAP_ANONYMOUS|MAP_FIXED_NOREPLACE,
                                -1,
                                0);
                if (guard_mapping != (void*) (address - page_size))
                        _exit(114);
                *(volatile uint8_t*) guard_mapping = 0x6b;
                moved = mremap(
                                guard_mapping,
                                page_size,
                                page_size,
                                MREMAP_MAYMOVE|MREMAP_FIXED,
                                target);
                if (moved != target || *(volatile uint8_t*) moved != 0x6b)
                        _exit(113);
                guard_mapping = mmap(
                                (void*) (address - page_size),
                                page_size,
                                PROT_READ|PROT_WRITE,
                                MAP_PRIVATE|MAP_ANONYMOUS,
                                -1,
                                0);
                if (guard_mapping == MAP_FAILED || guard_mapping == (void*) (address - page_size))
                        _exit(112);
                if (munmap(guard_mapping, page_size) < 0 || munmap(moved, page_size) < 0)
                        _exit(111);
                _exit(EXIT_SUCCESS);
        }
        if (waitpid(child, &status, 0) != child || !WIFEXITED(status) || WEXITSTATUS(status) != EXIT_SUCCESS)
                return EXIT_FAILURE;

        child = fork();
        if (child < 0)
                return EXIT_FAILURE;
        if (child == 0) {
                guard_mapping = mmap(
                                (void*) (address - page_size),
                                page_size,
                                PROT_READ|PROT_WRITE,
                                MAP_PRIVATE|MAP_ANONYMOUS|MAP_FIXED_NOREPLACE,
                                -1,
                                0);
                if (guard_mapping != (void*) (address - page_size))
                        _exit(120);
                *(volatile uint8_t*) guard_mapping = 0x5a;
                if (munmap((void*) address, 3 * page_size) < 0)
                        _exit(119);
                if (*(volatile uint8_t*) guard_mapping != 0x5a)
                        _exit(118);
                if (munmap(guard_mapping, page_size) < 0)
                        _exit(117);
                _exit(EXIT_SUCCESS);
        }
        if (waitpid(child, &status, 0) != child || !WIFEXITED(status) || WEXITSTATUS(status) != EXIT_SUCCESS)
                return EXIT_FAILURE;

        child = fork();
        if (child < 0)
                return EXIT_FAILURE;
        if (child == 0) {
                *(volatile uint64_t*) address = 0;
                _exit(126);
        }
        if (waitpid(child, &status, 0) != child || !WIFSIGNALED(status) || WTERMSIG(status) != SIGSEGV)
                return EXIT_FAILURE;

        child = fork();
        if (child < 0)
                return EXIT_FAILURE;
        if (child == 0) {
                if (mprotect((void*) (address + page_size), page_size, PROT_READ) < 0 ||
                    mprotect((void*) (address + page_size), page_size, PROT_READ|PROT_WRITE) < 0)
                        _exit(125);
                memcpy(&token, (void*) (address + 3 * page_size - sizeof(token)), sizeof(token));
                if (token != expected_token)
                        _exit(124);
                *(volatile uint64_t*) (address + page_size) = 0;
                _exit(126);
        }
        if (waitpid(child, &status, 0) != child || !WIFSIGNALED(status) || WTERMSIG(status) != SIGSEGV)
                return EXIT_FAILURE;

        child = fork();
        if (child < 0)
                return EXIT_FAILURE;
        if (child == 0) {
                unsigned char residency;

                if (mprotect((void*) (address + page_size), page_size, PROT_READ) < 0)
                        _exit(123);
                if (munmap((void*) address, 3 * page_size) < 0)
                        _exit(122);
                errno = 0;
                if (mincore((void*) address, page_size, &residency) >= 0 || errno != ENOMEM)
                        _exit(121);
                _exit(EXIT_SUCCESS);
        }
        if (waitpid(child, &status, 0) != child || !WIFEXITED(status) || WEXITSTATUS(status) != EXIT_SUCCESS)
                return EXIT_FAILURE;

        source_kvm = guest_process_has_kvm_fd();
        if (source_kvm < 0)
                return EXIT_FAILURE;
        if (munmap((void*) address, 3 * page_size) < 0)
                return EXIT_FAILURE;
        printf("KVM_CET_MAP_OK source_kvm=%d address=%#lx\n", source_kvm, address);
        return EXIT_SUCCESS;
}

